// Generated by scripts/build-data.mjs from arctracker.io (2026-10-14) and arcraiders-data@2a4abeb. Do not edit.
(window.ARC_DATA = window.ARC_DATA || {}).guides = {"advanced_camera_blueprint":{"verdict":{"en":"A low-priority gadget blueprint: you can buy the camera from Shani, so only learn this if you land a spare copy.","zh":"低优先级的道具蓝图：相机可直接找萨尼买，捡到多余的再学。"},"obtain":{"en":"The community wiki only lists scavenging, with no confirmed container or map. The camera itself sells at Shani and is a free Reward Pass item, so there is no reason to hunt the blueprint.","zh":"社区维基只标注了搜刮，未确认具体容器或地图。相机本身萨尼有售，奖励通行证也有免费版，不必专门去找蓝图。"},"tips":[{"en":"The blueprint cannot be researched at the Research Station and the wiki lists it as a requirement for an Outpost project, so keep it if you have the project open.","zh":"该蓝图不能在研究站研究，且维基把它列为某个前哨项目的需求，若项目在做就留着。"}],"sources":["https://arcraiders.wiki/wiki/Advanced_Camera_Blueprint","https://arcraiders.wiki/wiki/Advanced_Camera"],"version":"2.0"},"angled_grip_ii_blueprint":{"verdict":{"en":"Cheap early attachment: learn it if it drops, otherwise research it at the Research Station.","zh":"入门级配件蓝图：掉了就学，没掉就去研究站研究。"},"obtain":{"en":"It turns up in Residential loot on every map. Research Station 2 can also research it for Research Points, ARC Flex Rubber and Mechanical Components, so don't farm for it.","zh":"各地图的住宅类容器都可能出。研究站 2 级也能用研究点数、ARC弹性橡胶和机械元件研究出来，不值得专门刷。"},"tips":[{"en":"A duplicate sells for 5,000 coins, so sell extras instead of holding them.","zh":"重复的蓝图能卖 5000 钱币，多的直接卖。"}],"sources":["https://arcraiders.wiki/wiki/Angled_Grip_II_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"angled_grip_iii_blueprint":{"verdict":{"en":"Worth learning for recoil control, but it only rolls reliably in harder conditions.","zh":"压枪效果明显值得学，但只在高难度条件下比较稳定地出。"},"obtain":{"en":"Residential containers on any map, with a better chance during Electromagnetic Storm, Locked Gate and Night Raid. It cannot be researched at the Research Station, so scavenging is the only route.","zh":"各图居民区容器，电磁风暴、上锁的大门、夜间奇袭时机会更高。研究站研究不了，只能靠搜刮。"},"tips":[{"en":"Learning it needs Gunsmith 3, so check your bench level before spending a Night Raid on it.","zh":"学习需要武器工作台 3 级，刷夜袭前先看看工作台等级。"}],"sources":["https://arcraiders.wiki/wiki/Angled_Grip_III_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"anvil_blueprint":{"verdict":{"en":"A solid mid-game hand cannon to learn, but expect a slow chase: it is an epic, so it rolls less often than Bettina.","zh":"值得学的中期手炮，但属于史诗蓝图，出货比贝蒂娜慢，要有耐心。"},"obtain":{"en":"Raider containers on any map and condition; guides rank it behind Bettina in how often it appears. You can also research it at Research Station 2 using Research Points and Bully Fragmenter, which is the more reliable route.","zh":"各图奇袭者类容器都可能出，出货率比“贝蒂娜”低。也可在研究站 2 级用研究点数和恶霸破片弹研究，这条路更稳。"},"tips":[{"en":"Learning needs Gunsmith 2 and Heavy Gun Parts, so stock those before you run a lucky copy.","zh":"学习要武器工作台 2 级和重型枪械零件，先备好材料。"}],"sources":["https://arcraiders.wiki/wiki/Anvil_Blueprint","https://allthings.how/arc-raiders-bettina-blueprint-locations-and-farming-strategy/"],"version":"2.0"},"aphelion_blueprint":{"verdict":{"en":"A top-tier priority, but learning it is the easy part: the Matriarch Reactor needed to craft it is the real gate.","zh":"顶级优先级，但学会只是第一步，真正卡脖子的是制作所需的“族母”反应堆。"},"obtain":{"en":"It now drops from loot on Stella Montis, not from the Matriarch boss as it did before patch 1.7. Guides point to the top layer of Cultural Archives and Medical Research and the bottom layer of the Control Room. Night Raid doubles blueprint spawns.","zh":"现在掉在星辰山的搜刮物里，不再从“族母”身上拿（1.7 版本起）。攻略推荐文化档案馆、医学研究部上层以及控制室下层。夜间奇袭会让蓝图刷新翻倍。"},"tips":[{"en":"Start learning only when you can afford 3 Magnetic Accelerators, 3 Complex Gun Parts and a Matriarch Reactor.","zh":"备齐 3 个磁力加速器、3 个复杂枪械零件和一个“族母”反应堆再动手学。"}],"sources":["https://arcraiders.wiki/wiki/Aphelion_Blueprint","https://beebom.com/how-to-get-aphelion-blueprint-in-arc-raiders/amp/","https://insider-gaming.com/where-to-find-aphelion-arc-raiders-guide-blueprint/"],"version":"2.0"},"banjo_blueprint":{"verdict":{"en":"A novelty blueprint with no known source yet: ignore it unless you collect gadgets.","zh":"纯娱乐向的新蓝图，来源尚不明确，不收集道具就无视。"},"obtain":{"en":"The community wiki has no page for the blueprint and the Banjo page lists no sources. It is a Frozen Trail 2.0 gadget, so keep any copy you find until sources are known.","zh":"社区维基没有该蓝图页面，班卓琴页面也没列出来源。属于冰封小径 2.0 新增道具，捡到先留着，等来源明确。"},"tips":[{"en":"The Banjo only attracts attention and blocks two-handed actions while played, so it adds no combat value.","zh":"班卓琴只能吸引注意，演奏时无法做双手动作，没有战斗价值。"}],"sources":["https://arcraiders.wiki/wiki/Banjo_Blueprint","https://arcraiders.wiki/wiki/Banjo"],"version":"2.0"},"bantam_blueprint":{"verdict":{"en":"A cheap 2.0 revolver blueprint you can research yourself, so do not farm for it.","zh":"2.0 新增的廉价左轮蓝图，可以自己研究，不用专门刷。"},"obtain":{"en":"The wiki lists scavenging and the Research Station without specific containers. Research Station 1 can produce it for 3,000 Research Points and 8 Hornet Drivers, which is the realistic path.","zh":"维基只写了搜刮和研究站，没有具体容器。研究站 1 级用 3000 研究点数和 8 个“马蜂”引擎就能研究，这是现实路线。"},"tips":[{"en":"Hornet Drivers come from Hornets, so kill a few on the way before queuing the research.","zh":"“马蜂”引擎来自马蜂，顺路多打几只再排研究。"}],"sources":["https://arcraiders.wiki/wiki/Bantam_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"barricade_kit_blueprint":{"verdict":{"en":"Useful utility, easy to get: pick it up when electrical containers give it, no need to chase.","zh":"实用但好拿的工具蓝图，电气类容器出了就学，不必追。"},"obtain":{"en":"Look in Electrical containers; every map can roll it. Research is the easier route: 1,000 Research Points and Rusty ARC Steel at the Research Station.","zh":"电子类容器里找，各地图都可能出。研究站用 1000 研究点数加生锈的ARC钢材研究更省事，没必要刷。"},"tips":[{"en":"Learning needs Utility Station 2, so upgrade that first.","zh":"学习需要工具工作台 2 级，先升级。"}],"sources":["https://arcraiders.wiki/wiki/Barricade_Kit_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"bettina_blueprint":{"verdict":{"en":"The easiest epic weapon blueprint to land, and worth learning because the gun stays useful against armored ARC.","zh":"最容易刷到的史诗武器蓝图，对付装甲 ARC 依然好用，值得学。"},"obtain":{"en":"Raider containers on any map, and guides call it one of the most frequently rolled epics. Reported spots: Dam apartments (Ruby Residence, Pale Apartments, Pattern House), Research and Administration, and Stella Montis Loading Bay. Hurricane First Wave Caches also give it.","zh":"各图奇袭者类容器，攻略称它是出得比较多的史诗蓝图。常见点位：大坝公寓区、研究与管理楼、星辰山装卸区。飓风期间的第一波箱也能开出。"},"tips":[{"en":"Drop rate was cut after an early bug, so use short runs through many containers rather than long fights.","zh":"早期有 bug 导致爆率偏高，后来已下调，建议快进快出多开容器。"}],"sources":["https://arcraiders.wiki/wiki/Bettina_Blueprint","https://allthings.how/arc-raiders-bettina-blueprint-locations-and-farming-strategy/","https://www.keengamer.com/articles/guides/arc-raiders-all-blueprints-and-their-locations/"],"version":"2.0"},"blaze_grenade_blueprint":{"verdict":{"en":"Nice-to-have fire grenade; learn it when it shows up, but nothing else depends on it.","zh":"锦上添花的火焰手雷，出了就学，其他东西不依赖它。"},"obtain":{"en":"Only scavenging: it rolls from Industrial containers anywhere, and the wiki lists no Research Station recipe for it.","zh":"只能搜刮：任意地图的工业类容器都可能出，维基没有列出研究站配方。"},"tips":[{"en":"Crafting needs Explosives Station 3, Explosive Compound and Oil, so check those before you count on it.","zh":"制作需要爆炸物工作台 3 级、炸药混合物和油，别指望前期用上。"}],"sources":["https://arcraiders.wiki/wiki/Blaze_Grenade_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"blue_light_stick_blueprint":{"verdict":{"en":"Skip it unless you want cheap lighting: any copy is better sold for 5,000 coins.","zh":"除非想要廉价照明，否则直接卖掉换 5000 钱币。"},"obtain":{"en":"Any container on any map and condition can roll it. It cannot be researched at the Research Station.","zh":"任何地图、任何条件下的容器都可能出。无法在研究站研究。"},"tips":[{"en":"Learning it needs Utility Station 2 and Chemicals; for a throwable light that is a poor deal.","zh":"学习需要工具工作台 2 级和化学品，只为一根荧光棒不太划算。"}],"sources":["https://arcraiders.wiki/wiki/Blue_Light_Stick_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"bobcat_blueprint":{"verdict":{"en":"The most valuable blueprint here and also the hardest, so lock it in through the Trophy Display project.","zh":"这批里最值钱也最难拿的蓝图，优先走战利品展示架项目拿到手。"},"obtain":{"en":"Trophy Display project Stage 4 gives one, which is the dependable route. Otherwise it drops in Blue Gate Locked Gate loot or in First Wave Caches during Hurricane, and Trials reward it too. Wild spawns are extremely rare.","zh":"战利品展示架项目第 4 阶段给一张，这是最稳的路线。其他途径是蓝门上锁的大门事件、飓风期间的第一波箱，试炼也给奖励。野外自然刷新极少。"},"tips":[{"en":"Aim for 3 stars on weekly Trials, which players report as a Bobcat source.","zh":"每周试炼尽量拿满 3 星，玩家反馈能拿到山猫蓝图。"},{"en":"The base Bobcat is weak, so you craft it mainly to upgrade it, which needs Gunsmith 3.","zh":"基础款山猫较弱，学来主要是为了升级，需要武器工作台 3 级。"}],"sources":["https://arcraiders.wiki/wiki/Bobcat_Blueprint","https://nerdschalk.com/arc-raiders-bobcat-location-crafting-and-usage-guide/","https://www.pcgamesn.com/arc-raiders/blueprints"],"version":"2.0"},"burletta_blueprint":{"verdict":{"en":"Free early pistol blueprint: finish the Industrial Espionage quest and you never need to hunt it.","zh":"免费的早期手枪蓝图：完成“工业间谍”任务就有，别去刷。"},"obtain":{"en":"Quest reward for Industrial Espionage from Tian Wen in Buried City, after Eyes On The Prize. You can use any Burletta for the delivery step, but do not hand over your modded one. It can also be researched at Research Station 1.","zh":"掩埋废城天玟的任务“工业间谍”奖励，需先完成前置任务。交付时任何布尔莱塔都行，别交改装过的。研究站 1 级也能研究。"},"tips":[{"en":"A duplicate blueprint sells for 5,000 coins.","zh":"多出来的蓝图能卖 5000 钱币。"}],"sources":["https://arcraiders.wiki/wiki/Burletta_Blueprint","https://arcraiders.wiki/wiki/Industrial_Espionage"],"version":"2.0"},"canto_blueprint":{"verdict":{"en":"A good SMG blueprint, but only Hurricane First Wave Caches give it, so plan a long low-risk farm.","zh":"不错的冲锋枪蓝图，只有飓风的第一波箱出，适合安排一次长时间低风险刷取。"},"obtain":{"en":"Hurricane only, from First Wave Caches (small buried caches that hum when close) on every map except Stella Montis. Dam has the highest cache density, Blue Gate is a favorite, Buried City the lowest. One source claims Close Scrutiny weapon cases; it is unverified.","zh":"仅飓风期间，开第一波箱获得，除星辰山外各图都有。大坝箱子最密，蓝门也受欢迎，掩埋废城最少。有说法称严密排查的武器箱也出，未证实。"},"tips":[{"en":"Players farm it with an empty loadout and the blueprint in a safe pocket, then surrender so a death costs nothing.","zh":"常见刷法是空装备入场，蓝图放安全口袋，没找到就投降重来，损失为零。"},{"en":"Expect roughly 1 to 2 hours of farming per copy.","zh":"预计每张要刷一到两小时。"}],"sources":["https://arcraiders.wiki/wiki/Canto_Blueprint","https://www.destructoid.com/how-to-get-the-canto-blueprint-in-arc-raiders/","https://arcraidershub.com/guides/canto-blueprint-guide"],"version":"2.0"},"combat_mk3_aggressive_blueprint":{"verdict":{"en":"A late-game augment worth learning for the extra shield support if you can find it.","zh":"后期护甲增幅，若能刷到，值得学来获得更强护盾支持。"},"obtain":{"en":"Medical and security containers on Stella Montis and The Blue Gate, any condition. It cannot be researched at the Research Station, so you need a scavenged copy.","zh":"星辰山和蓝门的医疗与安保类容器，任何条件。研究站研究不了，必须搜刮到。"},"tips":[{"en":"Learning needs Gear Bench 3, Advanced Electrical Components and Processors.","zh":"学习要装备工作台 3 级、高级电子元件和处理器。"}],"sources":["https://arcraiders.wiki/wiki/Combat_Mk._3_(Aggressive)_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"combat_mk3_flanking_blueprint":{"verdict":{"en":"The mobility-focused Mk. 3 augment; learn it if you play fast, but it is optional.","zh":"偏机动的 Mk. 3 增幅，打法灵活的玩家可学，属于可选。"},"obtain":{"en":"Medical and security containers on Stella Montis and The Blue Gate. Unlike Aggressive, it can also be researched at Research Station 3 for 3,000 Research Points and ARC Circuitry.","zh":"星辰山和蓝门的医疗与安保类容器。与进攻型不同，它还可在研究站 3 级用 3000 研究点数和ARC线圈研究。"},"tips":[{"en":"Same Gear Bench 3 requirement as the other Mk. 3 augment.","zh":"学习条件和另一款 Mk. 3 一样，要装备工作台 3 级。"}],"sources":["https://arcraiders.wiki/wiki/Combat_Mk._3_(Flanking)_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"compensator_ii_blueprint":{"verdict":{"en":"Cheap and easy: research it or take it from residential containers, no farming needed.","zh":"便宜好拿：自己研究或从居民区容器捡，不用专门刷。"},"obtain":{"en":"Residential containers on any map and condition. Research Station 2 also makes it for 2,000 Research Points, Rusty ARC Steel and a Cooling Coil.","zh":"各图居民区容器都可能出。研究站 2 级用 2000 研究点数、生锈的ARC钢材和冷却管也能研究。"},"tips":[{"en":"Learning needs Gunsmith 2.","zh":"学习需要武器工作台 2 级。"}],"sources":["https://arcraiders.wiki/wiki/Compensator_II_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"compensator_iii_blueprint":{"verdict":{"en":"Worth learning for steadier shots, but it only drops in harder conditions, so be patient.","zh":"能让射击更稳值得学，但只在高难度条件下出，需要耐心。"},"obtain":{"en":"Residential containers during Electromagnetic Storm, Locked Gate and Night Raid. No Research Station route is listed, so it has to be scavenged.","zh":"电磁风暴、上锁的大门、夜间奇袭期间的居民区容器。没有研究站途径，只能搜刮。"},"tips":[{"en":"Learning needs Gunsmith 3 and 8 Wires.","zh":"学习需要武器工作台 3 级和 8 根导线。"}],"sources":["https://arcraiders.wiki/wiki/Compensator_III_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"complex_gun_parts_blueprint":{"verdict":{"en":"Strong long-term pick: it makes a material that late weapons keep asking for, so learn it early.","zh":"长期收益高：后期武器一直要用的材料，越早学越好。"},"obtain":{"en":"Security containers on any map and condition. Research Station 3 can also make it for 3,000 Research Points plus 2 Complex Gun Parts and Advanced Mechanical Components, so you need parts before you can research it.","zh":"各图各条件下的安保类容器。研究站 3 级也能研究，但要先交 2 个复杂枪械零件和高级机械元件。"},"tips":[{"en":"Aphelion and Bettina recipes use Complex Gun Parts.","zh":"“远日点”“贝蒂娜”等武器的配方都要复杂枪械零件。"}],"sources":["https://arcraiders.wiki/wiki/Complex_Gun_Parts_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"crash_mat_blueprint":{"verdict":{"en":"A minor utility blueprint; the Research Station makes it cheaply, so skip the hunt.","zh":"次要工具蓝图，研究站成本很低，不用专门找。"},"obtain":{"en":"Any container on Riven Tides, any condition. Research Station 1 can produce it for 1,000 Research Points and 5 Durable Cloth.","zh":"裂潮镇任何容器、任何条件。研究站 1 级用 1000 研究点数和 5 块耐磨布料即可研究。"},"tips":[{"en":"Only worth the bench slot if you often drop from high places.","zh":"只有常从高处跳的人才值得占位置。"}],"sources":["https://arcraiders.wiki/wiki/Crash_Mat_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"deadline_blueprint":{"verdict":{"en":"A strong trap blueprint that is fairly farmable if you run Stella Montis in a duo.","zh":"强力陷阱蓝图，双排跑星辰山相对好刷。"},"obtain":{"en":"Stella Montis, any condition. Guides name the Staff Room by the Loading Bay (stairs down, right, through the gate), then the red locker and corner bins. Player estimates: 2 to 3 per run for duos by day.","zh":"星辰山，任何条件。攻略指向装卸区旁的员工室（下楼右转过门），先搜红色柜子和角落垃圾桶。玩家估计白天双排每局 2 到 3 张。"},"tips":[{"en":"The room sits near the Loading Bay, which is contested, so expect other squads.","zh":"该房间靠近装卸区，人多，注意其他小队。"}],"sources":["https://arcraiders.wiki/wiki/Deadline_Blueprint","https://nerdschalk.com/how-to-get-deadline-blueprint-in-arc-raiders/"],"version":"2.0"},"defibrillator_blueprint":{"verdict":{"en":"A good team revive tool; learn it if you play with friends, otherwise it is optional.","zh":"团队复活利器，组队玩家建议学，单排可选。"},"obtain":{"en":"Medical containers on any map and condition. It can also drop in Buried City Night Raids, in the two main rooms on the left side of the second-highest floor. Research Station 2 needs Syringes and Adrenaline Shots.","zh":"各图各条件下的医疗类容器。掩埋废城夜间奇袭里，次高层左侧两个主要房间也可能出。研究站 2 级需要注射器和肾上腺素。"},"tips":[{"en":"Learning needs Medical Lab 2.","zh":"学习需要医疗实验室 2 级。"}],"sources":["https://arcraiders.wiki/wiki/Defibrillator_Blueprint","https://www.dexerto.com/wikis/arc-raiders/blueprints/"],"version":"2.0"},"dolabra_blueprint":{"verdict":{"en":"A top anti-ARC shotgun blueprint, but a long grind that only the Close Scrutiny event gives.","zh":"顶级的对 ARC 霰弹枪蓝图，但只有严密排查事件出，需要长期刷。"},"obtain":{"en":"Close Scrutiny only, from breaching ARC Assessors. Each has three chambers, so three rolls. It does not drop from raider caches. Drop rate is low; some players breach 10 or more without one.","zh":"仅严密排查事件，破开大型 ARC 目标的舱室获得。每个有三个舱室，三次机会。不会从奇袭者箱里出。爆率偏低，有玩家破开十多个都没拿到。"},"tips":[{"en":"Crafting needs Vaporizer Regulators, which only drop during Close Scrutiny, so farm them in the same runs.","zh":"制作要“汽化者”调节器，只在严密排查期间掉落，同一局顺手刷。"},{"en":"Bring Energy Clips: they are expensive to buy or craft.","zh":"带足能量弹匣，买和做都不便宜。"}],"sources":["https://arcraiders.wiki/wiki/Dolabra_Blueprint","https://www.keengamer.com/articles/guides/arc-raiders-guide-how-to-get-dolabra-blueprint/","https://arcraidershub.com/guides/dolabra-blueprint-guide","https://arcstatus.com/arc-raiders-blueprints"],"version":"2.0"},"emperor_gateway_conduit_blueprint":{"verdict":{"en":"Only worth chasing if you want into the Fallen Emperor; the blueprint is a one-time unlock with a repeatable craft.","zh":"只有想进“陨落帝王”才值得追，学一次永久可造。"},"obtain":{"en":"Farm the Redirection condition on Pendola Pass: harvest an Emperor Beacon from a Damaged Emperor Relay (red beam), deploy it in the open, then breach the Harvester Payload. The payload can hold the blueprint and the three couplers, but it is not guaranteed.","zh":"在彭多拉山口刷“航向重定向”：从受损的“帝王”中继器（红色光柱）取得“帝王”信标，在开阔处投放，再破开“收割者”空投搜刮。空投可能出蓝图和三种耦合器，但不保底。"},"tips":[{"en":"Craft needs one each of the Insulated, Conductive and Plated ARC Couplers, which come from the same payloads, so keep farming after you learn it.","zh":"合成需要绝缘、导电、装甲三种 ARC 耦合器各一个，同样出自空投，学会后还得继续刷。"},{"en":"One guide says the Conduit also sits at Frozen Trail Reward Pass level 60; the local data does not confirm it.","zh":"有攻略称“霜痕小径”奖励通行证 60 级也能直接拿到导管，本站数据未证实。"},{"en":"Bring a grappling or snap hook for the vertical sections inside.","zh":"里面有垂直地形，带上钩爪或安全钩。"}],"sources":["https://arcraiders.wiki/wiki/Emperor_Gateway_Conduit_Blueprint","https://insider-gaming.com/how-to-get-emperor-gateway-conduit-blueprint-in-arc-raiders-redirection-map-condition/"],"version":"2.0"},"equalizer_blueprint":{"verdict":{"en":"A Harvester-event prize: great if you can also farm a Queen Reactor, but the blueprint alone makes nothing.","zh":"“收割者”事件大奖，还得再打出“女王”反应堆才能造。"},"obtain":{"en":"Not in regular containers. Run the Harvester event (Dam Battlegrounds or Spaceport): finish the puzzle for the three reward containers, each reportedly holding one top-tier blueprint, Equalizer or Jupiter. The Queen Core is the other source. Learn it after extracting.","zh":"普通容器不出。参加“收割者”事件（大坝战场或太空港）：完成谜题后的三个奖励箱，据称各有一份顶级蓝图（制裁者或木星）；击败“女王”的核心也有机会。撤离后再学习。"},"tips":[{"en":"The Queen Reactor only comes from killing the Queen, so you must beat her at least once to craft it, even if you sneaked in for the blueprint.","zh":"“女王”反应堆只有击败“女王”才掉，即便偷进去拿了蓝图，造枪仍要打她一次。"},{"en":"Duplicate copies still sell for 5,000 coins.","zh":"重复的蓝图仍可卖 5000 钱币。"},{"en":"Event windows are reported at fixed UTC hours; check the in-game map icon rather than trusting guide times.","zh":"事件时段据报道固定在几个 UTC 整点，以游戏内地图图标为准。"}],"sources":["https://arcraiders.wiki/wiki/Equalizer_Blueprint","https://nerdschalk.com/arc-raiders-equalizer-blueprint-location-unlock-guide/"],"version":"2.0"},"jupiter_blueprint":{"verdict":{"en":"The better pick of the two Harvester rewards if you snipe, but it also needs a Queen Reactor.","zh":"喜欢狙击就选它，同样要“女王”反应堆。"},"obtain":{"en":"Harvester event only: sneak past the Queen when she faces away, solve the interior puzzle, and open the three reward containers. Each is reported to hold either Jupiter or Equalizer, so two runs may not give you both. Learn it after extracting.","zh":"仅出自“收割者”事件：趁“女王”背对时潜入，完成内部谜题后开三个奖励箱，据称每箱是木星或制裁者二选一，不一定一次拿齐。撤离后学习。"},"tips":[{"en":"The blueprint does not require killing the Queen, but crafting does because of the Queen Reactor.","zh":"拿蓝图不用打“女王”，造枪却要她掉的“女王”反应堆。"},{"en":"Do not recycle a duplicate; it sells for 5,000 coins.","zh":"多余的蓝图别拆，可卖 5000 钱币。"}],"sources":["https://arcraiders.wiki/wiki/Jupiter_Blueprint","https://nerdschalk.com/arc-raiders-jupiter-blueprint-location-unlock-guide/"],"version":"2.0"},"explosive_mine_blueprint":{"verdict":{"en":"Nice to have, not urgent; buy it with Research Points once you have Research Station 2.","zh":"不急；研究站 2 级后用研究点数换即可。"},"obtain":{"en":"Drops while scavenging; one guide points to industrial containers (green drawers and lockers, industrial cleaners). The sure route is the Research Station 2: 2,000 Research Points, 3 Comet Igniters and 2 Sensors.","zh":"搜刮可得，有攻略推荐工业类容器（绿色抽屉、柜子、工业清洁车）。稳妥的办法是研究站 2 级：2000 研究点数、3 个“彗星”点火器、2 个传感器。"},"tips":[{"en":"The mine itself is crafted at Explosives Station 3, so the blueprint is no use before that bench.","zh":"地雷本身要爆炸物工作台 3 级才能造，没升级前蓝图用不上。"}],"sources":["https://arcraiders.wiki/wiki/Explosive_Mine_Blueprint","https://www.pcgamesn.com/arc-raiders/blueprints","https://wzstats.gg/arc-raiders/wiki/items/blueprints/explosive-mine-blueprint"],"version":"2.0"},"gas_mine_blueprint":{"verdict":{"en":"The cheapest mine to unlock; fine for a stamina-drain trap, not a priority.","zh":"最便宜的地雷蓝图，当耐力陷阱用，不必优先。"},"obtain":{"en":"Scavenging, or the Research Station 1 for 1,000 Research Points and 3 Household Cleaner. The station route is cheap and early, so don't hunt for a drop.","zh":"搜刮或研究站 1 级：1000 研究点数加 3 个家用清洁剂。门槛低，不用专门刷掉落。"},"tips":[{"en":"The mine is made at Explosives Station 1 from Chemicals and Rubber Parts, so it is one of the earliest mines you can run.","zh":"地雷用化学品和橡胶零件在爆炸物工作台 1 级就能造，是最早能用上的地雷之一。"}],"sources":["https://arcraiders.wiki/wiki/Gas_Mine_Blueprint","https://wzstats.gg/arc-raiders/wiki/items/blueprints/gas-mine-blueprint"],"version":"2.0"},"jolt_mine_blueprint":{"verdict":{"en":"A stun trap that is handy for holding a door; learn it only if you like trap play.","zh":"能眩晕敌人的陷阱，适合守门，爱玩陷阱再学。"},"obtain":{"en":"Scavenging, or the Research Station 2: 2,000 Research Points, 3 Advanced ARC Powercells and 1 Industrial Battery. No quest hands it out.","zh":"搜刮或研究站 2 级：2000 研究点数、3 个高级ARC能量电池、1 个工业级电池。没有任务送。"},"tips":[{"en":"Powercells are the expensive part of the Research Station route, so check you can spare them first.","zh":"研究站路线最贵的是电池，先确认能匀出来。"}],"sources":["https://arcraiders.wiki/wiki/Jolt_Mine_Blueprint","https://wzstats.gg/arc-raiders/wiki/items/blueprints/jolt-mine-blueprint"],"version":"2.0"},"extended_barrel_ii_blueprint":{"verdict":{"en":"Low priority: a modest velocity boost for a few guns.","zh":"优先级低，只给少数枪小幅提速。"},"use":{"en":"The barrel adds about 20% bullet velocity and 10% more distance before falloff, and fits Tempest, Arpeggio, Bettina, Anvil and Torrente only.","zh":"枪管提高约 20% 弹速、衰减距离增加 10%，只适配“风暴”“三连奏”“贝蒂娜”“铁砧”和“奔流”。"},"obtain":{"en":"Scavenging, or the Research Station 2: 2,000 Research Points, 5 Rusty ARC Steel and 1 Steel Cable. Crafting the barrel also needs Gunsmith 2.","zh":"搜刮或研究站 2 级：2000 研究点数、5 个生锈的ARC钢材、1 根钢缆。造枪管还需武器工作台 2 级。"},"tips":[{"en":"Pass on it unless one of those guns is your main.","zh":"主力枪不在适配名单里就别学。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Barrel_II_Blueprint","https://arcraiders.wiki/wiki/Extended_Barrel_II"],"version":"2.0"},"extended_barrel_iii_blueprint":{"verdict":{"en":"Worth learning for a long-range build: the best barrel, but it can't be researched.","zh":"长距离配装值得学，但不能靠研究站获得。"},"use":{"en":"Gives about 30% bullet velocity and 15% more falloff distance at the cost of 15% extra vertical recoil, on thirteen weapons from Ferro to Tempest.","zh":"弹速约 +30%、衰减距离 +15%，代价是垂直后坐力 +15%，适配从“生铁”到“风暴”的十三把枪。"},"obtain":{"en":"Scavenging only; the page says it cannot be bought at the Research Station. The quest A Rising Tide hands out the barrel itself, not the blueprint.","zh":"只能搜刮，研究站不能换。任务“涨潮”送的是成品枪管，不是蓝图。"},"tips":[{"en":"Crafting needs Gunsmith 3, 2 Mod Components and 8 Wires.","zh":"合成需要武器工作台 3 级、2 个改装零件、8 根导线。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Barrel_III_Blueprint","https://arcraiders.wiki/wiki/Extended_Barrel_III"],"version":"2.0"},"extended_light_mag_ii_blueprint":{"verdict":{"en":"Skip it unless you craft in bulk: the mag is on sale from traders already.","zh":"不批量造就别学，商人那里就能买到弹匣。"},"obtain":{"en":"Scavenging or the Research Station 2: 2,000 Research Points, 5 Dried-Out ARC Resin, 5 Wires.","zh":"搜刮或研究站 2 级：2000 研究点数、5 个干涸的ARC树脂、5 根导线。"},"tips":[{"en":"The finished mag (+10 rounds, fits Hairpin, Kettle, Stitcher, Burletta, Bobcat) is sold by Shani for 100 Cred and by Tian Wen for 6,000 coins, and quests Market Correction and Snap and Salvage give one.","zh":"成品弹匣（+10 发，适配发夹、水壶、钉机、布尔莱塔、山猫）萨尼卖 100 信用点，天玟卖 6000 钱币；任务“矫正市场规则”“拍照并拆解回收”也各送一个。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Light_Mag_II_Blueprint","https://arcraiders.wiki/wiki/Extended_Light_Mag_II"],"version":"2.0"},"extended_light_mag_iii_blueprint":{"verdict":{"en":"Worth keeping if you run a light-ammo SMG; there is no other way to get the Mk. III mag.","zh":"常用轻型弹药冲锋枪就留着，别的渠道拿不到 III 级弹匣。"},"obtain":{"en":"Scavenging only; it is not available at the Research Station. Treat it as a lucky find.","zh":"只能搜刮，研究站没有，属于撞运气。"},"tips":[{"en":"Craft needs Gunsmith 3, 2 Mod Components and 5 Steel Springs.","zh":"合成需要武器工作台 3 级、2 个改装零件、5 个钢质弹簧。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Light_Mag_III_Blueprint"],"version":"2.0"},"extended_medium_mag_ii_blueprint":{"verdict":{"en":"Not needed: the mag is cheap from Shani and a quest gives one.","zh":"没必要学，萨尼有便宜成品，任务也送一个。"},"obtain":{"en":"Scavenging or the Research Station 2: 2,000 Research Points, 5 Dried-Out ARC Resin, 3 Canisters.","zh":"搜刮或研究站 2 级：2000 研究点数、5 个干涸的ARC树脂、3 个小罐。"},"tips":[{"en":"Shani sells the mag (+8 rounds) for 100 Cred, 2 a day, and the quest Eyes on the Prize gives one.","zh":"萨尼每天限 2 个、100 信用点 出售成品（+8 发）；任务“目光长远”也送一个。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Medium_Mag_II_Blueprint","https://arcraiders.wiki/wiki/Extended_Medium_Mag_II"],"version":"2.0"},"extended_medium_mag_iii_blueprint":{"verdict":{"en":"A good find for medium-ammo guns, but only found by scavenging.","zh":"中型弹药枪的好东西，但只能靠搜刮。"},"obtain":{"en":"Scavenging only; the Research Station does not offer it.","zh":"只能搜刮，研究站没有。"},"tips":[{"en":"If you only need one mag, quests Collision Course and Outstanding Balance reward a finished one, so the blueprint is for repeat crafting.","zh":"只要一个的话，任务“碰撞航线”和“未结债务”会送成品，蓝图是为了反复造。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Medium_Mag_III_Blueprint","https://arcraiders.wiki/wiki/Extended_Medium_Mag_III"],"version":"2.0"},"extended_shotgun_mag_ii_blueprint":{"verdict":{"en":"Only for Il Toro or Vulcano users, and one comes free from a quest.","zh":"只给“公牛”和“火山”用，任务还送一个。"},"obtain":{"en":"Scavenging or the Research Station 2: 2,000 Research Points, 5 Dried-Out ARC Resin, 1 Mechanical Components.","zh":"搜刮或研究站 2 级：2000 研究点数、5 个干涸的ARC树脂、1 个机械元件。"},"tips":[{"en":"The mag adds +4 shells; the quest Eyes on the Prize gives one, so skip the blueprint if you only run one gun.","zh":"弹匣 +4 发；任务“目光长远”送一个，只用一把枪就不必学。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Shotgun_Mag_II_Blueprint","https://arcraiders.wiki/wiki/Extended_Shotgun_Mag_II"],"version":"2.0"},"extended_shotgun_mag_iii_blueprint":{"verdict":{"en":"Keep it if you main a shotgun; it comes only from loot.","zh":"主玩霰弹枪就留着，只能靠搜刮。"},"obtain":{"en":"Scavenging only, with no Research Station option. Check containers while you farm; no specific spot is documented.","zh":"只能搜刮，研究站不能换。没有确切刷点记录，搜箱子时顺手找。"},"tips":[{"en":"Plan Gunsmith 3, 2 Mod Components and 5 Steel Springs ahead.","zh":"提前备好武器工作台 3 级、2 个改装零件、5 个钢质弹簧。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Shotgun_Mag_III_Blueprint"],"version":"2.0"},"fireworks_box_blueprint":{"verdict":{"en":"You get it free from a quest; it is a fun toy, not a priority.","zh":"任务白送，是个乐子道具，不用优先。"},"obtain":{"en":"Reward for the quest Test Case from Apollo (after The League). It also drops while scavenging, reportedly under the Cold Snap condition.","zh":"完成阿波罗的任务“测试案例”（在“球队”之后）获得；寒潮条件下搜刮也可能出。"},"tips":[{"en":"The finished box is sold by Shani for 60 Cred, 3 a day, so crafting is only worth it if you want many.","zh":"成品萨尼每天限 3 个、60 信用点 出售，想要很多才值得自己造。"}],"sources":["https://arcraiders.wiki/wiki/Fireworks_Box_Blueprint","https://arcraiders.wiki/wiki/Test_Case","https://arcraiders.wiki/wiki/Fireworks_Box"],"version":"2.0"},"grappling_hook_blueprint":{"verdict":{"en":"Cheap to unlock and useful in 2.0; get it at the Research Station.","zh":"解锁便宜，2.0 里实用，直接去研究站换。"},"obtain":{"en":"Research Station 1 for 2,000 Research Points and 10 Rope, or scavenging. The blueprint is new in 2.0.","zh":"研究站 1 级：2000 研究点数加 10 根绳子，或搜刮。蓝图为 2.0 新增。"},"tips":[{"en":"Quests Belly of the Beast, Boarding the Frigate, Ruins and Reverberations and Tracks of the Beast each give one hook, so you can try one before spending.","zh":"任务“兽腹深处”、登上“护卫者”、“废墟和回响”、“巨兽踪迹”各送一个钩爪，可先试用再决定。"},{"en":"Players also recommend a hook for the Fallen Emperor's vertical sections.","zh":"玩家也建议带钩子进“陨落帝王”。"}],"sources":["https://arcraiders.wiki/wiki/Grappling_Hook_Blueprint","https://arcraiders.wiki/wiki/Grappling_Hook","https://insider-gaming.com/how-to-get-emperor-gateway-conduit-blueprint-in-arc-raiders-redirection-map-condition/"],"version":"2.0"},"green_light_stick_blueprint":{"verdict":{"en":"Skip it: light sticks are bought for pennies and the blueprint is rarely worth the slot.","zh":"不必学，荧光棒本来就便宜。"},"obtain":{"en":"Scavenging only. A player report put light-stick blueprints in the Blue Gate breach room and Buried City pharmacies, but this is unverified.","zh":"只能搜刮。有玩家称蓝门破门房和掩埋废城药店较常见，未经验证。"},"tips":[{"en":"Apollo sells the stick for 450 coins and Shani for 10 Cred. The quest In My Image needs 5, so buy those.","zh":"阿波罗卖 450 钱币，萨尼卖 10 信用点；任务“与我同形”要 5 根，买就行。"}],"sources":["https://arcraiders.wiki/wiki/Green_Light_Stick_Blueprint","https://arcraiders.wiki/wiki/Green_Light_Stick","https://breakingac.com/news/2025/dec/05/arc-raiders-best-blueprint-farming-locations-and-routes/"],"version":"2.0"},"heavy_gun_parts_blueprint":{"verdict":{"en":"Worth learning if you upgrade Anvil, Rascal or Hullcracker; otherwise ignore.","zh":"要升级“铁砧”“无赖”“裂甲者”等重型枪才值得学。"},"use":{"en":"Heavy Gun Parts are the upgrade bottleneck for Anvil, Bettina, Hullcracker, Rascal and Vulcano.","zh":"重型枪械零件是“铁砧”“贝蒂娜”“裂甲者”“无赖”“火山”升级的瓶颈。"},"obtain":{"en":"Research Station 2: 2,000 Research Points, 5 Simple Gun Parts, 1 Unusable Weapon; or scavenging. The parts also drop from ARC Bombardiers and Rocketeers.","zh":"研究站 2 级：2000 研究点数、5 个简易枪械零件、1 把报废的武器；或搜刮。“投弹手”和“火箭手”也掉零件。"},"tips":[{"en":"Celeste sells parts for seeds, 3 a day, so the blueprint only helps if you need more than that.","zh":"塞莱斯特用种子卖，每天限 3 个，需求更大才需要蓝图。"}],"sources":["https://arcraiders.wiki/wiki/Heavy_Gun_Parts_Blueprint","https://arcraiders.wiki/wiki/Heavy_Gun_Parts"],"version":"2.0"},"light_gun_parts_blueprint":{"verdict":{"en":"Take the guaranteed copy from the Trophy Display project instead of buying it.","zh":"战利品展示架项目送一份，不必另花研究点数。"},"obtain":{"en":"Reward in Stage 1 (Roaming Threats) of the Trophy Display project. Also scavenging, or Research Station 2 for 2,000 Research Points, 5 Simple Gun Parts and 1 Unusable Weapon.","zh":"战利品展示架项目第 1 阶段“游荡的威胁”奖励；也可搜刮，或研究站 2 级换（2000 研究点数、5 个简易枪械零件、1 把报废的武器）。"},"tips":[{"en":"The same project pays out for Stage 4 Bobcat blueprint, so stage 1 is worth finishing anyway.","zh":"这个项目第 4 阶段还送“山猫”蓝图，第 1 阶段本来就值得做。"}],"sources":["https://arcraiders.wiki/wiki/Light_Gun_Parts_Blueprint","https://arcraiders.wiki/wiki/Trophy_Display","https://www.pcgamesn.com/arc-raiders/blueprints"],"version":"2.0"},"hullcracker_blueprint":{"verdict":{"en":"A must for ARC bosses, and it is a quest reward you should just finish.","zh":"打 ARC 首领必备，任务奖励，做完就有。"},"use":{"en":"The Hullcracker fires explosives that only detonate on ARC, so one source says it does no damage to players: bring a second gun for PvP.","zh":"“裂甲者”爆炸弹只对 ARC 起爆，有攻略称对玩家无伤害，PvP 要另带枪。"},"obtain":{"en":"Quest The Major's Footlocker from Tian Wen: recover Aiva's mementos from the top floor of the westmost Ruby Residence apartment on Dam Battlegrounds. Or Research Station 3 for 4,500 Research Points. Shani no longer sells it after 2.0.","zh":"完成天玟的任务“少校的储物柜”：到大坝战场红宝石宅邸最西侧公寓的顶层取回遗物。或研究站 3 级换（4500 研究点数）。2.0 后萨尼不再出售。"},"tips":[{"en":"Older guides say to buy it for 30,000 coins or Cred, which is out of date.","zh":"旧攻略说可花 30000 买，已过时。"}],"sources":["https://arcraiders.wiki/wiki/Hullcracker_Blueprint","https://allthings.how/arc-raiders-majors-footlocker-location-pickup-and-reward/","https://nerdschalk.com/arc-raiders-hullcracker-acquiring-crafting-usage-guide/"],"version":"2.0"},"il_toro_blueprint":{"verdict":{"en":"A strong early shotgun that costs little to build; research it rather than wait on a drop.","zh":"前期强力霰弹枪，造价低，直接研究别等掉落。"},"obtain":{"en":"Research Station 1 for 2,000 Research Points and 5 Shredder Gyros is the reliable way. Drops are low (guides say 1-2%) from Raider containers on all maps, Marano Station is a suggested spot, and the Uncovered Caches event raises odds.","zh":"研究站 1 级换：2000 研究点数加 5 个“粉碎者”陀螺仪，最稳。奇袭者容器掉率低（攻略称 1-2%），可去马拉诺车站，“揭开储藏点”事件几率更高。"},"tips":[{"en":"Build is Gunsmith 1 with Mechanical Components and Simple Gun Parts.","zh":"武器工作台 1 级，用机械元件和简易枪械零件造。"}],"sources":["https://arcraiders.wiki/wiki/Il_Toro_Blueprint","https://nerdschalk.com/arc-raiders-il-toro-shotgun-location-crafting-maintenance/","https://findingdulcinea.com/where-to-find-il-toro-blueprint-in-arc-raiders/"],"version":"2.0"},"lightweight_stock_blueprint":{"verdict":{"en":"Situational: faster aiming and draw, with a recoil penalty.","zh":"看情况：开镜和拔枪更快，后坐力变差。"},"use":{"en":"The stock speeds up aim-down-sights and draw but adds 50% vertical recoil, for fifteen weapons including Il Toro and Hullcracker.","zh":"枪托加快开镜和拔枪，垂直后坐力 +50%，适配约十五把枪，含“公牛”和“裂甲者”。"},"obtain":{"en":"Scavenging only; no Research Station route or quest is listed.","zh":"只能搜刮，没有研究站或任务途径。"},"tips":[{"en":"Craft needs Gunsmith 3, 2 Mod Components and 5 Duct Tape.","zh":"合成需武器工作台 3 级、2 个改装零件、5 卷胶带。"}],"sources":["https://arcraiders.wiki/wiki/Lightweight_Stock_Blueprint","https://arcraiders.wiki/wiki/Lightweight_Stock","https://wzstats.gg/arc-raiders/wiki/items/blueprints/lightweight-stock-blueprint"],"version":"2.0"},"looting_mk3_safekeeper_blueprint":{"verdict":{"en":"Good for dedicated looters: a safe pocket that holds any item, in exchange for weight.","zh":"适合专职搜刮：安全口袋可放任意物品，代价是负重。"},"obtain":{"en":"Research Station 3 for 3,000 Research Points, 5 ARC Circuitry and 5 Canisters, or scavenging.","zh":"研究站 3 级：3000 研究点数、5 个ARC线圈、5 个小罐；或搜刮。"},"tips":[{"en":"The augment is crafted at Gear Bench 3; the wiki lists no community review yet.","zh":"护甲在装备工作台 3 级制造；暂无社区评价。"}],"sources":["https://arcraiders.wiki/wiki/Looting_Mk._3_(Safekeeper)_Blueprint","https://arcraiders.wiki/wiki/Looting_Mk._3_(Safekeeper)"],"version":"2.0"},"looting_mk3_survivor_blueprint":{"verdict":{"en":"A pure scavenging find with no known fixed spot; learn it only if you want the big-pack Survivor build.","zh":"只能靠搜刮碰运气，没有固定刷新点，想要大背包流再学。"},"obtain":{"en":"No quest or project rewards it and the community pages name no container, so treat it as random blue-tier loot. It cannot be researched at the Research Station. Run Night Raids and locked rooms, and keep it in a Safe Pocket: it is only learned once you extract.","zh":"没有任务或项目奖励，社区资料也没写出具体容器，只能当作随机战利品。研究站无法研究它。多跑夜间奇袭和上锁房间，放进安全口袋，成功撤离后才算学会。"},"tips":[{"en":"Making the augment later needs a Gear Bench level 3 and Processors, so check your bench before you spend farming runs on it.","zh":"之后制作需要装备工作台 3 级和处理器，先确认工作台等级再专门去刷。"}],"sources":["https://arcraiders.wiki/wiki/Looting_Mk._3_(Survivor)_Blueprint","https://www.keengamer.com/articles/guides/arc-raiders-all-blueprints-and-their-locations/","https://www.pcgamesn.com/arc-raiders/blueprints"],"version":"2.0"},"lure_grenade_blueprint":{"verdict":{"en":"Free from a Celeste quest, so never pay Research Points for it.","zh":"塞莱斯特的任务白送，别花研究点数去买。"},"use":{"en":"The grenade sticks to a surface and pulls ARC attention and fire toward it, which is useful for slipping past a patrol or splitting a group.","zh":"手雷会粘在表面上吸引附近 ARC 的注意和火力，适合绕过巡逻或拆开一群敌人。"},"obtain":{"en":"Finish Greasing Her Palms from Celeste: visit the Locked Room in the Water Treatment Control building on Dam Battlegrounds, scope the rocket thrusters southwest of the Rocket Assembly at The Spaceport, and check the barricaded area on floor 6 of the Space Travel Building in Buried City.","zh":"完成塞莱斯特的任务“打通通路”：大坝战场水处理控制楼的上锁房间、太空港火箭组装楼西南的巨型推进器、掩埋废城太空旅行大楼 6 层的封锁区域。"},"tips":[{"en":"The three objectives are on three different maps, so combine them with other tasks and keep the loadout cheap.","zh":"三个目标分在三张地图，顺路和其他任务一起做，带便宜装备即可。"}],"sources":["https://arcraiders.wiki/wiki/Lure_Grenade_Blueprint","https://arcraiders.wiki/wiki/Greasing_Her_Palms","https://www.keengamer.com/articles/guides/arc-raiders-all-blueprints-and-their-locations/"],"version":"2.0"},"medium_gun_parts_blueprint":{"verdict":{"en":"Skip it unless you plan to craft the Osprey, which eats three Medium Gun Parts.","zh":"不打算造“鱼鹰”就别学，它要 3 个中型枪械零件。"},"obtain":{"en":"It is a scavenged drop with no named container, or you can research it at Research Station level 2 for Research Points and Simple Gun Parts. The wiki's two recipes disagree, so check the station screen before you commit.","zh":"靠搜刮随机掉落，容器不明；也可在研究站 2 级用研究点数和简易枪械零件研究。维基给出的两个配方不一致，投入前先看游戏内研究界面。"},"tips":[{"en":"Guides rank it below new weapons and gadgets; buy it after the Osprey blueprint, not before.","zh":"攻略把它排在新武器和小工具之后，先拿到“鱼鹰”蓝图再说。"}],"sources":["https://arcraiders.wiki/wiki/Medium_Gun_Parts_Blueprint","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first","https://www.pcgamesn.com/arc-raiders/blueprints"],"version":"2.0"},"muzzle_brake_ii_blueprint":{"verdict":{"en":"Cheap recoil control that is nice to have, not urgent.","zh":"便宜的后坐力改善，有当然好，但不急。"},"obtain":{"en":"Random scavenged loot, or research it at Research Station level 2 for 2,000 Research Points plus Rusty ARC Steel and a Steel Cable. Players ranking research spend put tier-II attachments after new weapons and gadgets, so wait until those are done.","zh":"随机搜刮，或在研究站 2 级花 2000 研究点数加生锈的ARC钢材和钢缆研究。玩家的研究顺序里二级配件排在新武器和小工具之后，先放一放。"},"tips":[{"en":"Crafting the attachment needs Gunsmith level 2, so it fits mid-game.","zh":"制作配件需要武器工作台 2 级，适合中期。"}],"sources":["https://arcraiders.wiki/wiki/Muzzle_Brake_II_Blueprint","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first"],"version":"2.0"},"muzzle_brake_iii_blueprint":{"verdict":{"en":"Only worth chasing for a main gun with heavy recoil; it cannot be bought with Research Points.","zh":"只有主力枪后坐力很大时才值得追，研究站里买不到。"},"obtain":{"en":"Scavenging is the only listed source and no spawn spot is documented, so it is a lucky find. Run high-risk zones, locked rooms and Night Raids, and extract with it before it counts.","zh":"资料只列了搜刮一个来源，也没记载刷新点，全看运气。多跑高风险区、上锁房间和夜间奇袭，撤离成功才算学会。"},"tips":[{"en":"Making it needs Gunsmith level 3 and Mod Components, so a tier-II brake is the practical stopgap.","zh":"制作需要武器工作台 3 级和改装零件，在此之前用二级制退器过渡。"}],"sources":["https://arcraiders.wiki/wiki/Muzzle_Brake_III_Blueprint","https://www.pcgamesn.com/arc-raiders/blueprints"],"version":"2.0"},"osprey_blueprint":{"verdict":{"en":"A top-priority Research Station buy: a solid sniper blueprint that is hard to find in loot.","zh":"研究站里值得优先买的蓝图，狙击枪实用，掉落又难碰。"},"use":{"en":"The Osprey is a bolt-action medium-ammo sniper, so the blueprint matters if you want a long-range PvP or ARC option.","zh":"“鱼鹰”是中口径栓动狙击枪，想要远距离对枪或打 ARC 就该学。"},"obtain":{"en":"Weapon cases and locked rooms on Dam Battlegrounds and The Spaceport are the usual farming spots, with Night Raid and Hurricane raising loot quality. The faster route is Research Station level 2: 3,000 Research Points, 3 Sentinel Firing Cores and a Camera Lens.","zh":"常见刷法是大坝战场和太空港的武器箱与上锁房间，夜间奇袭和飓风会提升战利品质量。更稳的路线是研究站 2 级：3000 研究点数、3 个“哨卫”发射核心和 1 个相机镜头。"},"tips":[{"en":"Crafting the gun later needs Gunsmith 2 and three Medium Gun Parts, so learn that blueprint too.","zh":"之后造枪需要武器工作台 2 级和 3 个中型枪械零件，记得也学那张蓝图。"},{"en":"Drops are RNG; do not spend many raids hunting it when Research Points can buy it.","zh":"掉落看运气，能用研究点数换就别靠连跑几局去刷。"}],"sources":["https://arcraiders.wiki/wiki/Osprey_Blueprint","https://nerdschalk.com/arc-raiders-osprey-i-sniper-rifle-locations-where-to-find-and-unlock-it/","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first"],"version":"2.0"},"padded_stock_blueprint":{"verdict":{"en":"A random-drop stability mod with no research shortcut; pick it up if it shows, do not hunt it.","zh":"稳定性配件，只能随机掉落，碰到就学，不用专门刷。"},"obtain":{"en":"Scavenging is the only listed source, with no quest, project or Research Station route. Loot weapon cases, locked rooms and other high-value containers, and put the blueprint in a Safe Pocket before extracting.","zh":"只有搜刮一个来源，没有任务、项目或研究站途径。翻武器箱、上锁房间等高价值容器，拿到后放进安全口袋再撤离。"},"tips":[{"en":"Crafting it needs Gunsmith 3, Mod Components and Duct Tape, so it is a late-mid unlock.","zh":"制作需要武器工作台 3 级、改装零件和胶带，算中后期解锁。"}],"sources":["https://arcraiders.wiki/wiki/Padded_Stock_Blueprint","https://www.pcgamesn.com/arc-raiders/blueprints"],"version":"2.0"},"powered_descender_blueprint":{"verdict":{"en":"Worth learning if you run Riven Tides a lot: it removes lethal falls from the vertical map.","zh":"常跑裂潮镇就值得学，能让你从高处安全落地。"},"use":{"en":"It slows your fall in the air, with a short wind-up and a power limit, so it works as a quick shortcut and an escape from rooftops.","zh":"它在空中减缓下落速度，有启动延迟且能量有限，适合当近路和屋顶逃生。"},"obtain":{"en":"Search Riven Tides: Hotel Panorama Azzurro south of Azzurro Beach (lockers and dressers) is the most reported spot, plus Port Authority and its locked rooms. Night Raid improves the odds. Or research it at Research Station level 3 for 3,000 Research Points, 2 Cooling Fans and Advanced Electrical Components.","zh":"去裂潮镇找：阿祖罗海滩南边的蔚蓝全景酒店（储物柜、梳妆台）报告最多，港务局和上锁房间也行，夜间奇袭概率更高。也可在研究站 3 级用 3000 研究点数、2 个冷却风扇和高级电子元件研究。"},"tips":[{"en":"The device needs Utility Station 3, a Power Rod and a Turbine Compressor from Riven Tides turbines, which is a lot of prep.","zh":"制作需要工具工作台 3 级、能量管和裂潮镇涡轮上的“涡轮”压缩机，前置准备不少。"}],"sources":["https://arcraiders.wiki/wiki/Powered_Descender_Blueprint","https://allthings.how/powered-descender-blueprint-location-in-arc-raiders/","https://beebom.com/arc-raiders-powered-descender-blueprint-guide/amp/","https://keengamer.com/articles/guides/arc-raiders-all-new-riven-tides-blueprints-location/"],"version":"2.0"},"pulse_mine_blueprint":{"verdict":{"en":"A cheap early Research Station pick if you like trap play, otherwise skip.","zh":"喜欢布陷阱的话，是研究站里便宜的早期选择，不然可以跳过。"},"obtain":{"en":"It is a scavenged drop; one source points at Stella Montis, another lists several maps with Night Raid as the best condition, so the spawn data conflicts. The sure route is Research Station level 1: 1,000 Research Points and 3 Industrial Batteries.","zh":"靠搜刮掉落；有资料说在星辰山，另一处列了多张地图并推荐夜间奇袭，说法不一。稳妥的是研究站 1 级：1000 研究点数和 3 个工业电池。"},"tips":[{"en":"The mine itself only needs Explosives Station 1, so it unlocks very early once you own the blueprint.","zh":"地雷本身只要爆炸物工作台 1 级，拿到蓝图后很早就能造。"}],"sources":["https://arcraiders.wiki/wiki/Pulse_Mine_Blueprint","https://breakingac.com/news/2025/dec/05/arc-raiders-best-blueprint-farming-locations-and-routes/","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first"],"version":"2.0"},"rascal_blueprint":{"verdict":{"en":"A good anti-ARC backup launcher; buy it with Research Points rather than farming for it.","zh":"不错的对 ARC 副武器，直接用研究点数换，别去刷。"},"use":{"en":"It is lighter than the Hullcracker and handles armored ARC, but it only damages ARC, loads one round at a time and is inaccurate past about 14 m.","zh":"比“裂甲者”轻，能对付装甲 ARC，但只伤 ARC、一次装一发，14 米外准头差。"},"obtain":{"en":"No fixed spawn. Reported spots: Security Breach cabinets, Hurricane First Wave Caches, locked key rooms and weapon crates, and Ermal's weekly trader rotation may stock it. Research Station level 2 costs 3,000 Research Points, 2 Bombardier Cells and 15 ARC Alloy.","zh":"没有固定刷新点。报告较多的是安防突破柜、飓风“第一波”箱、上锁钥匙房和武器箱，商人埃尔马尔的每周轮换也可能上架。研究站 2 级需要 3000 研究点数、2 个“投弹手”电池和 15 个ARC合金。"},"tips":[{"en":"Crafting it needs 5 Canisters and 3 Heavy Gun Parts, which players call steep for a blue weapon.","zh":"制作要 5 个罐体和 3 个重型枪械零件，玩家觉得对蓝色武器来说偏贵。"},{"en":"Its blasts are loud and can draw other raiders.","zh":"爆炸声很大，会引来其他奇袭者。"}],"sources":["https://arcraiders.wiki/wiki/Rascal_Blueprint","https://arcraidershub.com/guides/rascal-blueprint-guide","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first"],"version":"2.0"},"red_light_stick_blueprint":{"verdict":{"en":"You get it for free during the Outpost unlock, so there is nothing to hunt.","zh":"解锁哨站的过程中白送，不用特意找。"},"obtain":{"en":"It is the stage 2 reward (Gather Building Materials) of the Sheltered Retreat Outpost project, which opens at level 18. The wiki also lists scavenging, but the project is the dependable way.","zh":"它是哨站解锁项目“掩护撤退”第 2 阶段（收集建筑材料）的奖励，18 级开启。维基也列了搜刮，但走项目最稳。"},"tips":[{"en":"Making the stick needs only Utility Station 2 and a few Chemicals, so it is cheap light for dark interiors and Night Raids.","zh":"制作只要工具工作台 2 级和少量化学品，夜间奇袭和黑暗室内用很划算。"}],"sources":["https://arcraiders.wiki/wiki/Red_Light_Stick_Blueprint","https://arcraiders.wiki/wiki/Outpost","https://allthings.how/arc-raiders-outpost-how-to-unlock-upgrade-and-use-the-research-workstation/"],"version":"2.0"},"remote_raider_flare_blueprint":{"verdict":{"en":"Cheap but niche: it is a signaling tool, so it is a low-priority research buy.","zh":"便宜但用途窄，只是信号工具，研究优先级低。"},"use":{"en":"You place it and trigger it by hand to launch a distress flare, which fits baiting or marking, not combat.","zh":"放置后手动触发发射求救信号弹，适合引诱或标记，不是战斗道具。"},"obtain":{"en":"Scavenging or Research Station level 1 at 500 Research Points and 25 Chemicals, the cheapest RP price among my batch. No container or quest is documented, so research is the practical route if you want it.","zh":"靠搜刮，或在研究站 1 级花 500 研究点数和 25 个化学品研究，是这批里最便宜的。没有记载容器或任务，想要的话研究最实际。"},"sources":["https://arcraiders.wiki/wiki/Remote_Raider_Flare_Blueprint","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first"],"version":"2.0"},"seeker_grenade_blueprint":{"verdict":{"en":"A handy anti-ARC grenade at a cheap price; a good early research choice.","zh":"便宜好用的反 ARC 手雷，适合早期研究。"},"use":{"en":"It homes in on one nearby ARC and explodes on contact, so it is good for finishing a damaged machine.","zh":"会追踪附近一台 ARC 并撞击爆炸，适合补刀残血机器。"},"obtain":{"en":"No documented container or quest; it drops as scavenged loot. Research it at Research Station level 1 for 1,000 Research Points and a Rocketeer Driver, which beats farming.","zh":"没有记载容器或任务，属于随机搜刮。可在研究站 1 级用 1000 研究点数和 1 个“火箭手”引擎研究，比刷划算。"},"tips":[{"en":"The grenade itself needs Explosives Station 1, Crude Explosives and ARC Alloy.","zh":"手雷本身需要爆炸物工作台 1 级、粗制炸药和ARC合金。"}],"sources":["https://arcraiders.wiki/wiki/Seeker_Grenade_Blueprint","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first"],"version":"2.0"},"shotgun_choke_ii_blueprint":{"verdict":{"en":"Worth it only if you run shotguns; the research cost is steep for a modest spread tweak.","zh":"只有常用霰弹枪才值，散布小幅改善，研究价格偏高。"},"obtain":{"en":"Random scavenged loot, or Research Station level 2 for 2,000 Research Points, 5 Rusty ARC Steel and a Heavy Gun Parts. No container is named, so research is more predictable.","zh":"随机搜刮，或在研究站 2 级用 2000 研究点数、5 个生锈的ARC钢材和 1 个重型枪械零件研究。没有指明容器，研究更可控。"},"tips":[{"en":"Attachment blueprints rank below weapons and gadgets for Research Points, so spend on those first.","zh":"研究点数先买武器和小工具，配件蓝图靠后。"}],"sources":["https://arcraiders.wiki/wiki/Shotgun_Choke_II_Blueprint","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first"],"version":"2.0"},"shotgun_choke_iii_blueprint":{"verdict":{"en":"A late pick-up for dedicated shotgun users; no research route, so it is luck only.","zh":"给专精霰弹枪的玩家的后期蓝图，不能研究，纯看运气。"},"obtain":{"en":"Only scavenging is listed; there is no quest, project or Research Station recipe. Check weapon cases, locked rooms and high-risk zones, and secure it in a Safe Pocket.","zh":"只列了搜刮，没有任务、项目或研究站配方。翻武器箱、上锁房间和高风险区，并放入安全口袋。"},"tips":[{"en":"Do not hold a run for it; tier II gives much of the same effect for less.","zh":"别为它专门耗一局，二级收束器效果相近，成本更低。"}],"sources":["https://arcraiders.wiki/wiki/Shotgun_Choke_III_Blueprint","https://www.pcgamesn.com/arc-raiders/blueprints"],"version":"2.0"},"shotgun_silencer_blueprint":{"verdict":{"en":"Take it from the Trophy Display project instead of farming it.","zh":"走战利品展示架项目拿，别去刷。"},"obtain":{"en":"It is the Trophy Display project stage 3 (Ferocious Foes) reward. That stage asks for ARC Performance Steel, Kinetic Converter, Shredder Gyros, Anvil Splitters, Leaper Pulse Units, Raider Tokens and Bastion Cells. The wiki lists scavenging too, but with no named spot.","zh":"它是战利品展示架项目第 3 阶段（凶暴的敌兽）的奖励，阶段要求ARC高性能钢、动能转换器、“粉碎者”陀螺仪、“铁砧”分流器、“跳跃者”脉冲单元、奇袭者代币和“堡垒”电池等。维基也列了搜刮，但没有具体地点。"},"tips":[{"en":"That stage is expensive; check whether you need the silencer before pouring materials into it.","zh":"这一阶段材料开销大，先想清楚是否真需要消音器再投入。"}],"sources":["https://arcraiders.wiki/wiki/Shotgun_Silencer_Blueprint","https://arcraiders.wiki/wiki/Trophy_Display"],"version":"2.0"},"showstopper_blueprint":{"verdict":{"en":"A late utility grenade; stun is nice but the unlock chain is long.","zh":"后期功能手雷，眩晕不错，但解锁链条太长。"},"use":{"en":"It detonates after a short delay and stuns everything in its radius, handy for pushing a room or stopping a charging ARC.","zh":"延迟引爆并眩晕范围内的目标，适合攻房或打断冲锋的 ARC。"},"obtain":{"en":"It is scavenged loot with no named container, or Research Station level 2 for 2,000 Research Points, 3 Industrial Batteries and 5 Hornet Drivers. Making it requires Explosives Station 3, so it is a late-mid goal.","zh":"随机搜刮，容器不明；或在研究站 2 级用 2000 研究点数、3 个工业级电池和 5 个“马蜂”引擎研究。制作需要爆炸物工作台 3 级，属于中后期目标。"},"sources":["https://arcraiders.wiki/wiki/Showstopper_Blueprint","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first"],"version":"2.0"},"silencer_i_blueprint":{"verdict":{"en":"Worth grabbing early if you play quietly; one known farm spot makes it reachable.","zh":"喜欢潜行的话早点拿，有一个已知刷点。"},"obtain":{"en":"Search the containers in the Arbusto Tower Pharmacy in Buried City; the front door is barricaded, so breach it or take the back stairwell up. It can also be researched at Research Station level 2 for 2,000 Research Points, 5 Rusty ARC Steel and a Cooling Coil.","zh":"去掩埋废城阿布斯托塔楼的药房翻容器；正门被封，可炸开或走后楼梯上去。也可在研究站 2 级用 2000 研究点数、5 个生锈的ARC钢材和 1 个冷却管研究。"},"tips":[{"en":"It only slightly dampens noise, so do not expect stealth from it alone.","zh":"只是小幅降噪，别指望单靠它实现潜行。"}],"sources":["https://arcraiders.wiki/wiki/Silencer_I_Blueprint","https://www.keengamer.com/articles/guides/arc-raiders-all-blueprints-and-their-locations/"],"version":"2.0"},"silencer_ii_blueprint":{"verdict":{"en":"A mid-priority upgrade for stealth builds; research it once you have the Level 3 station.","zh":"潜行流的中等优先升级，研究站升到 3 级再考虑。"},"obtain":{"en":"Random loot without a named container, or Research Station level 3 for 3,000 Research Points, 5 ARC Performance Steel and Advanced Mechanical Components. Learning Silencer I first costs less and covers the same slot.","zh":"随机掉落，容器不明；或在研究站 3 级用 3000 研究点数、5 个ARC高性能钢和高级机械元件研究。先学消音器 I 成本更低，占同一格位。"},"tips":[{"en":"Crafting needs Gunsmith 3, Mod Components and 8 Wires.","zh":"制作需要武器工作台 3 级、改装零件和 8 根导线。"}],"sources":["https://arcraiders.wiki/wiki/Silencer_II_Blueprint","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first"],"version":"2.0"},"smoke_grenade_blueprint":{"verdict":{"en":"A useful escape tool; a solid research buy once you hit station level 2.","zh":"实用的逃生道具，研究站到 2 级后值得买。"},"use":{"en":"The cloud blocks sight for ARC and other raiders, so use it to cover a revive, a crossing or a retreat.","zh":"烟幕遮挡 ARC 和其他奇袭者的视线，用来掩护救人、过空地或撤退。"},"obtain":{"en":"Scavenged loot with no named spot, or Research Station level 2 for 2,000 Research Points, 3 Gas Grenades and Household Cleaner. The wiki's workbench recipe differs, so confirm in the game.","zh":"随机搜刮，地点不明；或在研究站 2 级用 2000 研究点数、3 个毒气手雷和家用清洁剂研究。维基工作台配方不同，请以游戏内为准。"},"sources":["https://arcraiders.wiki/wiki/Smoke_Grenade_Blueprint","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first","https://www.pcgamesn.com/arc-raiders/blueprints"],"version":"2.0"},"snap_hook_blueprint":{"verdict":{"en":"A late project reward, not a farm target; only chase it if you want the Trophy Display chain.","zh":"后期项目奖励，不是刷取目标，只有做展示架项目时才会拿到。"},"obtain":{"en":"It is the final stage 5 (Imposing Behemoths) reward of Trophy Display. That stage wants Exodus Modules, 2 Snap Hooks, Geiger Counters, an Aphelion, Bombardier Cells, Raider Tokens and Matriarch Reactors. No Research Station route.","zh":"它是战利品展示架第 5 阶段（巍峨的巨兽）的奖励，阶段要求离巢模块、2 个安全钩、盖革计数器、“远日点”、“投弹手”电池、奇袭者代币和“族母”反应堆等。研究站里没有。"},"tips":[{"en":"The stage asks for 2 finished Snap Hooks, so you must have crafted the item once before the blueprint even arrives.","zh":"阶段要求交 2 个成品安全钩，意味着蓝图到手前你得已经造过它。"}],"sources":["https://arcraiders.wiki/wiki/Snap_Hook_Blueprint","https://arcraiders.wiki/wiki/Trophy_Display"],"version":"2.0"},"stable_stock_ii_blueprint":{"verdict":{"en":"A modest handling upgrade; research it late, after weapons and gadgets.","zh":"小幅操控提升，放到武器和小工具之后再研究。"},"obtain":{"en":"Scavenged loot with no documented container, or Research Station level 2 for 2,000 Research Points, 5 ARC Flex Rubber and a Rubber Pad. The wiki's infobox lists a different recipe, so check in the game before spending.","zh":"随机搜刮，容器不明；或在研究站 2 级用 2000 研究点数、5 个ARC弹性橡胶和橡胶垫研究。维基信息框的配方不同，花费前先在游戏里确认。"},"sources":["https://arcraiders.wiki/wiki/Stable_Stock_II_Blueprint","https://timesaver.gg/blog/arc-raiders-research-points-what-to-unlock-first"],"version":"2.0"},"stable_stock_iii_blueprint":{"verdict":{"en":"A luck-only attachment blueprint; use tier II meanwhile.","zh":"只能靠运气的配件蓝图，先用二级顶着。"},"obtain":{"en":"Scavenging is the sole listed source, with no Research Station recipe and no named container. Loot weapon cases and locked rooms, and extract with it to learn it.","zh":"只列了搜刮，没有研究站配方，也没有指明容器。翻武器箱和上锁房间，撤离成功后才能学会。"},"tips":[{"en":"Making it needs Gunsmith 3, Mod Components and Duct Tape.","zh":"制作需要武器工作台 3 级、改装零件和胶带。"}],"sources":["https://arcraiders.wiki/wiki/Stable_Stock_III_Blueprint","https://www.pcgamesn.com/arc-raiders/blueprints"],"version":"2.0"},"stiletto_blueprint":{"verdict":{"en":"No fixed drop spot, so unlock it at the Research Station if you want the entry-level Stiletto.","zh":"没有固定掉点，想要入门级“细剑”就去研究站解锁。"},"obtain":{"en":"It is random loot from containers and weapon cases, with no map condition needed. The wiki also lists the Research Station as a source, and one guide says most blueprints can be unlocked there with enough Research Points. The wiki's two unlock recipes disagree, so read the in-game price first.","zh":"属随机战利品，来自容器和武器箱，不需要地图条件。百科同时把研究站列为来源，有攻略称多数蓝图只要研究点数够就能解锁。百科给出的两套解锁条件互相矛盾，先看游戏内实际价格。"},"tips":[{"en":"Rated an uncommon, early-game rifle, so don't burn a long farming session on this blueprint.","zh":"这是定位偏入门的非稀有步枪，不值得为它专门长时间刷图。"}],"sources":["https://arcraiders.wiki/wiki/Stiletto_Blueprint","https://insider-gaming.com/how-to-get-uncommon-stiletto-battle-rifle-in-arc-raiders-blueprint-location/"],"version":"2.0"},"surge_coil_blueprint":{"verdict":{"en":"Only drops during an Electromagnetic Storm; check containers if you are there anyway, don't build runs around it.","zh":"只在电磁风暴期间掉落；赶上了就顺手搜，不必专门为它出击。"},"obtain":{"en":"Load into a map with Electromagnetic Storm active, which is mostly Dam Battlegrounds. It can sit in almost any container: lockers, drawers, crates. Guides suggest the Control Tower and nearby admin buildings on Dam. Not a quest reward.","zh":"进入有电磁风暴的地图，主要是大坝战场。几乎任何容器都可能出：储物柜、抽屉、板条箱。攻略推荐大坝的控制塔及周边行政楼。没有任务奖励。"},"tips":[{"en":"Do short loops of one or two buildings rather than clearing the whole map, and extract as soon as you find it.","zh":"在一两栋楼之间短线循环，别清全图；拿到后尽快撤离。"},{"en":"The unlock also needs an Explosives Station level 3 and a Hornet Driver, so plan the parts first.","zh":"制作要爆炸物工作台3级和一个“马蜂”引擎，先备好材料。"}],"sources":["https://arcraiders.wiki/wiki/Surge_Coil_Blueprint","https://www.keengamer.com/articles/guides/arc-raiders-guide-how-to-get-surge-coil-blueprint/","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"tactical_mk3_defensive_blueprint":{"verdict":{"en":"A random augment blueprint; worth taking if you find it, not worth a dedicated hunt.","zh":"随机出的增幅器蓝图，遇到就拿，不必专门去刷。"},"obtain":{"en":"The wiki's blueprint table lists Stella Montis and The Blue Gate, in Medical and Security containers, and it can also drop from a killed ARC Surveyor. Reinforced Reception on Blue Gate is the best-known augment room, though crowded. Night Raids give better loot.","zh":"百科蓝图表列出星辰山和蓝门，来自医疗类和安保类容器，击杀ARC勘测师也可能掉。蓝门的加固前台是最知名的增幅器房间，但人多。夜间奇袭的战利品更好。"},"tips":[{"en":"The wiki lists two different unlock costs, one at the Research Station; confirm in-game before gathering parts.","zh":"百科给出两套解锁条件，其中一套在研究站；备料前先在游戏里确认。"}],"sources":["https://arcraiders.wiki/wiki/Tactical_Mk._3_(Defensive)_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"tactical_mk3_healing_blueprint":{"verdict":{"en":"Pure support augment, and only luck finds the blueprint; farm it only if your squad runs a medic.","zh":"纯辅助向增幅器，蓝图全凭运气；队里有医疗位再去刷。"},"obtain":{"en":"Stella Montis and The Blue Gate, from Medical and Security containers. Reinforced Reception on Blue Gate is the usual pick: breach the room, open every locker and medical drawer. One guide lists White Medical Drawers, Medical Bags and Blue Cabinets as the useful medical containers.","zh":"星辰山和蓝门，来自医疗类和安保类容器。常见选择是蓝门加固前台：破门进房，开光所有储物柜和医疗抽屉。有攻略点名白色医疗抽屉、医疗包和蓝色柜子。"},"tips":[{"en":"Bring a cheap kit with a free Safe Pocket slot, because the room is contested and the drop is pure RNG.","zh":"带便宜的装备并空出安全口袋，那里抢的人多，掉落全看运气。"}],"sources":["https://arcraiders.wiki/wiki/Tactical_Mk._3_(Healing)_Blueprint","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-new-epic-augment-blueprints/"],"version":"2.0"},"tactical_mk3_revival_blueprint":{"verdict":{"en":"Worth grabbing if you play in a squad: the augment is a built-in revive, but the drop is pure luck.","zh":"组队玩值得拿：这个增幅器自带复活能力，但掉落全看运气。"},"obtain":{"en":"Best known from Reinforced Reception on Blue Gate: run the tunnels from spawn, breach in, and open lockers, augment cases and medical drawers. Stella Montis augment rooms (Lobby, Business Center, Archives keyroom) also work. Players carrying it can drop it too.","zh":"最知名的是蓝门加固前台：出生后跑隧道破门，开储物柜、增幅器箱和医疗抽屉。星辰山的增幅器房间（大厅、商务中心、档案馆钥匙房）也行。带着它的玩家也可能掉落。"},"tips":[{"en":"Expect heavy competition at Reinforced Reception; extract right after you find it.","zh":"加固前台竞争激烈，拿到就尽快撤离。"}],"sources":["https://arcraiders.wiki/wiki/Tactical_Mk._3_(Revival)_Blueprint","https://allthings.how/arc-raiders-how-to-get-the-tactical-mk-3-revival-blueprint/"],"version":"2.0"},"tactical_mk3_smoke_blueprint":{"verdict":{"en":"A niche epic augment blueprint added late; take it if it drops, but nothing in the wiki says it is a priority.","zh":"后加入的小众史诗增幅器蓝图；掉了就拿，但没有资料说它值得优先。"},"obtain":{"en":"One Riven Tides guide points to Security containers first, with Medical containers as a weaker backup. On Riven Tides try the Port Authority Buildings and Hotel Panorama Azzurro; backups are the Buried City Hospital and Blue Gate Reinforced Reception lockers. Locked rooms and offices are favoured.","zh":"一篇裂潮镇攻略首推安保类容器，医疗类容器次之。裂潮镇可去港务局大楼和蔚蓝全景酒店；备选是掩埋废城医院和蓝门加固前台的储物柜。上锁的房间和办公室更值得搜。"},"tips":[{"en":"The wiki shows no Research Station route for this one, so it has to be found as loot.","zh":"百科没有列出研究站途径，只能靠搜刮获得。"}],"sources":["https://arcraiders.wiki/wiki/Tactical_Mk._3_(Smoke)_Blueprint","https://keengamer.com/articles/guides/arc-raiders-all-new-riven-tides-blueprints-location/"],"version":"2.0"},"tagging_grenade_blueprint":{"verdict":{"en":"One of the easier blueprints to find, and a cheap scouting tool; learn it when it shows up.","zh":"属于较容易找到的蓝图，是便宜的侦察工具；见到就学。"},"obtain":{"en":"Any map, any condition, from Electrical containers, so check those as you pass. The Research Station can also unlock it at level 2 for a modest cost.","zh":"所有地图、任意条件都有机会，出自电类容器，路过时顺手开。研究站2级也能以较低成本解锁。"},"tips":[{"en":"Not worth a detour; if you can't find it, the Research Station route is the fallback.","zh":"不值得绕路；找不到就走研究站这条路。"}],"sources":["https://arcraiders.wiki/wiki/Tagging_Grenade_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"tempest_blueprint":{"verdict":{"en":"One of the rarest weapon blueprints: don't plan around it, grab it if you spot it.","zh":"最稀有的武器蓝图之一：别指望，见到就拿。"},"obtain":{"en":"Epic drop that needs a Night Raid or Hurricane. Buried City's Space Travel building (second-highest floor, left rooms) is the best-known spot; Residential containers and First Wave Caches also roll it. Daytime odds are very low.","zh":"史诗级掉落，需要夜间奇袭或飓风。最知名的点位是掩埋废城航天大楼次高层左侧房间；住宅类容器和第一波补给也可能掉。白天掉率极低。"},"tips":[{"en":"Hurricane puts Tempest and Vulcano in the pool together, so it is the best condition to hunt in.","zh":"飓风会同时把风暴和火山放进掉落池，是最值得刷的条件。"},{"en":"Unlocking needs Gunsmith level 3 and a Magnetic Accelerator; it cannot be done at the Research Station.","zh":"解锁要武器工作台3级和磁力加速器，研究站不能解锁。"}],"sources":["https://arcraiders.wiki/wiki/Tempest_Blueprint","https://www.keengamer.com/articles/guides/arc-raiders-all-blueprints-and-their-locations/","https://allthings.how/arc-raiders-where-the-rarest-blueprints-drop/"],"version":"2.0"},"tether_launcher_blueprint":{"verdict":{"en":"New in 2.0 with no mapped drop yet; the Research Station is the realistic way to get it.","zh":"2.0新增，还没人整理出掉点；研究站是现实的获取途径。"},"obtain":{"en":"The wiki lists only Scavenging and the Research Station, with no maps or containers, and no quest or project gives it. Plan on the Research Station and check the exact price in-game, because the page shows two conflicting recipes.","zh":"百科只列出搜刮和研究站，没有地图和容器信息，也没有任务或项目奖励。以研究站为主，价格先在游戏内确认，页面上有两套互相矛盾的配方。"},"tips":[{"en":"Ignore sellers offering it for real money; it can be unlocked in-game.","zh":"别理会卖蓝图的代练，游戏内就能解锁。"}],"sources":["https://arcraiders.wiki/wiki/Tether_Launcher_Blueprint"],"version":"2.0"},"torrente_blueprint":{"verdict":{"en":"Findable in Raider containers on any map; learn it if you want the weapon, no need for a special route.","zh":"任何地图的奇袭者容器都可能出；想要这把武器就学，不用特别规划路线。"},"obtain":{"en":"The wiki lists all maps and any condition, in Raider containers. That means weapon cases and Raider caches. Night Raids and locked rooms should help, as with other weapon blueprints.  Or take the Research Station 2 route.","zh":"百科列为所有地图、任意条件，出自奇袭者类容器，即武器箱和奇袭者补给。夜间奇袭和上锁房间应当更有利，和其他武器蓝图一样。研究站2级也可解锁。"},"tips":[{"en":"Unlocking via workshop needs Gunsmith level 2 or 3 depending on which wiki recipe is right; check first.","zh":"工坊解锁需要武器工作台2级或3级，取决于百科哪套配方正确，先确认。"}],"sources":["https://arcraiders.wiki/wiki/Torrente_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"trailblazer_blueprint":{"verdict":{"en":"Stella Montis loot only, so learn it only if you already run that map.","zh":"只在星辰山出，平时就跑那张图再去找。"},"obtain":{"en":"The wiki's blueprint table lists Stella Montis, any condition, any container. No room is named. Sources agree it is high-tier loot, so favour locked rooms and the augment-rich Security Checkpoint area.  Or take the Research Station 2 route.","zh":"百科蓝图表列为星辰山、任意条件、任意容器，没有指明房间。多方说法一致认为属高阶战利品，所以优先搜上锁房间和增幅器密集的安全检查站。研究站2级也可解锁。"},"tips":[{"en":"Don't trust guides that give exact coordinates for it; none could be verified.","zh":"别信给出具体坐标的攻略，目前没有可验证的。"}],"sources":["https://arcraiders.wiki/wiki/Trailblazer_Blueprint","https://techstory.in/how-to-get-trailblazer-blueprint-in-arc-raiders/"],"version":"2.0"},"trigger_nade_blueprint":{"verdict":{"en":"Take the guaranteed quest reward from Sparks Fly instead of hoping for a drop.","zh":"直接做任务“灭蜂大计”拿保底奖励，别等掉落。"},"obtain":{"en":"Sparks Fly gives one copy, and it can also be scavenged on any map. Trading it from Shani was removed in 2.0.  Or take the Research Station 2 route.","zh":"“灭蜂大计”任务奖励1份，也可在任意地图搜刮。2.0起不能再向萨尼购买。研究站2级也可解锁。"},"tips":[{"en":"Do the quest first; every other route costs more time.","zh":"先做任务，其他途径都更费时间。"}],"sources":["https://arcraiders.wiki/wiki/Trigger_Nade_Blueprint","https://www.keengamer.com/articles/guides/arc-raiders-all-blueprints-and-their-locations/"],"version":"2.0"},"venator_blueprint":{"verdict":{"en":"A weapon-case blueprint with no fixed spot; worth learning if you like close-range PvP pistols.","zh":"武器箱里出的蓝图，没有固定位置；喜欢近距离PvP手枪就值得学。"},"obtain":{"en":"Raider containers on any map. Weapon crates and Raider caches have the best odds, then Security Lockers, with locked rooms and Night Raids raising them. Dam Battlegrounds' Control Tower is a frequent suggestion.  Or take the Research Station 2 route.","zh":"所有地图的奇袭者容器。武器箱和奇袭者补给概率最高，其次是安保储物柜，上锁房间和夜间奇袭会更好。大坝战场控制塔常被推荐。研究站2级也可解锁。"},"tips":[{"en":"Put it in your Safe Pocket right away, then learn it back at base.","zh":"拿到后立刻放进安全口袋，回基地再学习。"},{"en":"A claimed locked hospital room on Buried City is unconfirmed; don't count on it.","zh":"掩埋废城医院上锁房间的说法未证实，别指望。"}],"sources":["https://arcraiders.wiki/wiki/Venator_Blueprint","https://allthings.how/arc-raiders-venator-blueprint-locations-and-best-farming-routes/","https://1v9.gg/blog/arc-raiders-venator-blueprint-location-guide"],"version":"2.0"},"vertical_grip_ii_blueprint":{"verdict":{"en":"A cheap, common attachment blueprint; check Residential containers or buy time at the Research Station.","zh":"便宜常见的配件蓝图；搜住宅类容器，或走研究站。"},"obtain":{"en":"All maps, any condition, from Residential containers such as wardrobes and dressers.  Or take the Research Station 2 route.","zh":"所有地图、任意条件，出自衣柜、梳妆台等住宅类容器。研究站2级也可解锁。"},"tips":[{"en":"Recoil gains are moderate, so learn it only if you build rifles.","zh":"后坐力削减幅度一般，玩步枪再学。"}],"sources":["https://arcraiders.wiki/wiki/Vertical_Grip_II_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"vertical_grip_iii_blueprint":{"verdict":{"en":"Better recoil control but rarer than Grip II; condition raids are the best bet.","zh":"后坐力控制更好，但比二级握把稀有；条件对局最有机会。"},"obtain":{"en":"Residential containers during Electromagnetic Storm, Locked Gate or Night Raid. Research Station 3 also lists it; check the price in-game.","zh":"电磁风暴、上锁的大门或夜间奇袭期间的住宅类容器。研究站3级也列有它，价格先在游戏内确认。"},"tips":[{"en":"Learn Grip II first and only chase this one if you use a high-recoil weapon.","zh":"先学二级握把，用高后坐力武器再追这个。"}],"sources":["https://arcraiders.wiki/wiki/Vertical_Grip_III_Blueprint","https://arcraiders.wiki/wiki/Blueprints"],"version":"2.0"},"vita_shot_blueprint":{"verdict":{"en":"Reasonable heal blueprint from Medical containers; learn it, there's no reason to sell it.","zh":"医疗容器里能找到的治疗蓝图；学掉，不必卖。"},"obtain":{"en":"All maps, Medical containers and ARC Surveyor kills. The Buried City Hospital and Dam Testing Annex are good medical farm spots. It is also a Trials reward and an item in the Trophy Display project (stage 2 part 1).","zh":"所有地图，来自医疗类容器和ARC勘测师。掩埋废城医院和大坝测试附楼是不错的医疗区。也是试炼奖励，并与展示柜项目第一阶段第2步有关。"},"tips":[{"en":"The wiki shows a Research Station route, so you don't need to rely on drops.","zh":"百科列出研究站途径，不必只靠掉落。"}],"sources":["https://arcraiders.wiki/wiki/Vita_Shot_Blueprint","https://wzstats.gg/arc-raiders/wiki/items/blueprints/vita-shot-blueprint"],"version":"2.0"},"vita_spray_blueprint":{"verdict":{"en":"Notoriously rare as a drop; finishing Worth Your Salt is the sure way to get it.","zh":"掉落极稀有；完成电池的“盐”伸是稳拿的办法。"},"obtain":{"en":"The quest Worth Your Salt gives one, but it sits late in Celeste's chain. Otherwise try Medical containers and ARC Surveyors (Testing Annex on Dam, Hospital on Buried City) or First Wave Caches in Hurricane.","zh":"任务电池的“盐”伸奖励1份，但在塞莱斯特任务链靠后。否则可搜医疗类容器和ARC勘测师（大坝测试附楼、掩埋废城医院），或飓风中的第一波补给。"},"tips":[{"en":"If you are deep in Celeste's quests, do it; if not, don't restart the chain just for this.","zh":"已经推进到塞莱斯特的后期任务就做；否则别为它从头打任务链。"}],"sources":["https://arcraiders.wiki/wiki/Vita_Spray_Blueprint","https://www.keengamer.com/articles/guides/arc-raiders-worth-your-salt-quest-walkthrough/","https://allthings.how/arc-raiders-where-the-rarest-blueprints-drop/"],"version":"2.0"},"vulcano_blueprint":{"verdict":{"en":"Epic shotgun blueprint tied to the Spaceport Hidden Bunker and Hurricane; farm only while one is active.","zh":"史诗霰弹枪蓝图，与太空港隐藏地堡和飓风绑定；只在条件开启时刷。"},"obtain":{"en":"Hidden Bunker event on The Spaceport: download the four antennas, open the bunker and every container, or search the Launch Towers' tops. In Hurricane it can come from First Wave Caches anywhere. Not craftable at the Research Station.","zh":"太空港隐藏地堡事件：下载四个天线数据，开启地堡并搜遍容器，或搜发射塔顶部。飓风期间任何地图的第一波补给也可能出。研究站不能解锁。"},"tips":[{"en":"Put it in the Safe Pocket right away; unlock needs Gunsmith level 3.","zh":"立即放进安全口袋；解锁需要武器工作台3级。"}],"sources":["https://arcraiders.wiki/wiki/Vulcano_Blueprint","https://allthings.how/how-to-get-the-vulcano-blueprint-in-arc-raiders/","https://www.keengamer.com/articles/guides/arc-raiders-all-blueprints-and-their-locations/"],"version":"2.0"},"white_flag_blueprint":{"verdict":{"en":"A common Riven Tides novelty blueprint; learn it cheaply, it is no priority.","zh":"裂潮镇上常见的趣味蓝图；便宜学掉，不算优先。"},"obtain":{"en":"Riven Tides, any container: cabinets, desks, lockers, suitcases. Hotel Panorama Azzurro first, then the Port Authority Buildings and docks. Backups: Buried City residences, Dam Research and Administration. The Research Station level 1 unlocks it cheaply.","zh":"裂潮镇任意容器：柜子、办公桌、储物柜、手提箱。先去蔚蓝全景酒店，再去港务局大楼和码头。备选：掩埋废城公寓、大坝研究与行政区。研究站1级即可低价解锁。"},"tips":[{"en":"The Research Station route is the cheapest of this batch, so just buy it.","zh":"研究站途径在本批蓝图中最便宜，直接解锁即可。"}],"sources":["https://arcraiders.wiki/wiki/White_Flag_Blueprint","https://keengamer.com/articles/guides/arc-raiders-all-new-riven-tides-blueprints-location/"],"version":"2.0"},"wolfpack_blueprint":{"verdict":{"en":"Night Raid residential loot; a good anti-ARC grenade blueprint, worth farming in Buried City.","zh":"夜间奇袭的住宅类战利品；优秀的反ARC手雷蓝图，值得去掩埋废城刷。"},"obtain":{"en":"Night Raid, in Residential containers on Buried City, Dam Battlegrounds or Stella Montis. Ruby Residences, Pale Apartments and Grandioso Apartments get named. Community data shows most finds outside keyed rooms. It also rolls in the Space Travel rooms alongside Tempest.","zh":"夜间奇袭，掩埋废城、大坝战场或星辰山的住宅类容器。红宝石公寓、苍白公寓和奢华公寓被点名。社区数据显示多数在非钥匙房间找到。航天大楼的房间也与风暴一同出。"},"tips":[{"en":"Open every locker, safe deposit box and drawer; unlock needs Explosives Station level 3.","zh":"柜子、保险箱和抽屉都开；解锁需要爆炸物工作台3级。"}],"sources":["https://arcraiders.wiki/wiki/Wolfpack_Blueprint","https://www.shacknews.com/article/147719/how-to-get-the-wolfpack-blueprint-in-arc-raiders","https://www.keengamer.com/articles/guides/arc-raiders-all-blueprints-and-their-locations/"],"version":"2.0"},"yank_grenade_blueprint":{"verdict":{"en":"New in 2.0 with no mapped drop; use the cheap Research Station route.","zh":"2.0新增，没有已知掉点；走便宜的研究站途径。"},"obtain":{"en":"The wiki lists only Scavenging and the Research Station (level 1 recipe), and no quest or project. I found no drop guides yet, so unlock it there and check the price in-game.","zh":"百科只列出搜刮和研究站（1级配方），没有任务或项目奖励。尚未找到掉落攻略，建议在研究站解锁，价格先在游戏内确认。"},"tips":[{"en":"The page shows two different recipes; trust the in-game price.","zh":"页面有两套配方，以游戏内价格为准。"}],"sources":["https://arcraiders.wiki/wiki/Yank_Grenade_Blueprint"],"version":"2.0"},"yellow_light_stick_blueprint":{"verdict":{"en":"Take the quest copy from Last Entry; the stick is cheap and the blueprint is easy.","zh":"拿“最后条目”的任务奖励；荧光棒便宜，蓝图也容易。"},"obtain":{"en":"Last Entry gives one copy. Otherwise it is found on all maps in any container. The workshop route needs Utility Station level 2 and a few Chemicals, per the wiki.","zh":"“最后条目”任务奖励1份。其他情况下所有地图任意容器都可能出。据百科，工坊解锁需要工具工作台2级和少量化学品。"},"tips":[{"en":"Not a priority; skip hunting if you don't need to mark routes.","zh":"不是优先项；不用标记路线就不必特意找。"}],"sources":["https://arcraiders.wiki/wiki/Yellow_Light_Stick_Blueprint","https://arcraiders.wiki/wiki/Last_Entry"],"version":"2.0"},"free_loadout_augment":{"verdict":{"en":"A throwaway starter bag: use it for free runs, then trade it to Lance for a Mk. 1 augment.","zh":"免费的起步背包：跑完免费局，再找兰斯换成 Mk. 1 强化。"},"use":{"en":"It only takes a Light Shield, has no Safe Pocket and a small weight limit, so treat it as a way to learn the maps without risking gear. Anything you can't afford to lose should not ride in this bag.","zh":"只能装轻型护盾，没有安全口袋，负重也低。适合零风险熟悉地图，贵重物品别放进来。"},"obtain":{"en":"You get it by deploying with a Free Loadout. Lance will swap one for a Combat, Looting or Tactical Mk. 1 at no cost, which is the best use of a spare. It also recycles into plastic and rubber parts, which is why it is worth keeping rather than dropping.","zh":"选择免费配装出战即可获得。兰斯可免费把它换成战斗、搜刮或战术 Mk. 1，这是多余一件时的最佳去处；也可回收出塑料零件和橡胶零件。"},"tips":[{"en":"Swap it for a Mk. 1 at Lance before you spend coins; the exchange costs nothing and the Mk. 1 lines hold more.","zh":"先找兰斯免费换 Mk. 1 再考虑花钱，Mk. 1 的容量更大。"}],"sources":["https://arcraiders.wiki/wiki/Free_Loadout_Augment","https://allthings.how/arc-raiders-augment-tier-list-best-picks-for-pve-and-pvp/"],"version":"2.0"},"combat_mk1_mk2":{"verdict":{"en":"Mk. 1 is a learner bag; Mk. 2 is the cheapest way into Heavy Shields and a solid budget fighter.","zh":"Mk. 1 是入门背包；Mk. 2 是最便宜的重型护盾入口，预算战斗首选。"},"use":{"en":"Combat Mk. 1 only matters because it allows a Medium Shield early. Combat Mk. 2 adds a grenade slot, slow health regeneration and Heavy Shield support, so a Mk. 2 plus a Heavy Shield is the budget way to get 52.5% damage reduction. Tier lists rank it mid-pack: strong value, but outclassed once you can craft Epic augments.","zh":"战斗 Mk. 1 的价值就是早早能用中型护盾。战斗 Mk. 2 多一个手雷位、缓慢回血，并支持重型护盾，搭重型护盾是预算最低的 52.5% 减伤方案。榜单评价中游：性价比高，但能做史诗强化后就被超越。"},"obtain":{"en":"Mk. 1: Lance sells it, or trade a Free Loadout Augment for it; the quest Down to Earth also rewards one. Mk. 2: craftable at Gear Bench 2, sold by Lance once a day, and Out of the Shadows rewards one. The wiki also lists Shani for Cred.","zh":"Mk. 1：兰斯出售，或用免费配装强化兑换；任务“踏实补给”也给一件。Mk. 2：装备工作台 2 级可制作，兰斯每日限购 1 件，任务“走出阴影”也有奖励；维基还提到萨尼可用信用点购买。"},"tips":[{"en":"Mk. 2 repairs with just one Electrical Components and one Magnet, so it is cheap to keep running even after deaths.","zh":"Mk. 2 修理只要 1 个电子元件加 1 块磁铁，死几次也不心疼。"},{"en":"Skip crafting Mk. 1 if you have a spare Free Loadout Augment; the exchange is free.","zh":"有多余的免费配装强化就别做 Mk. 1，直接免费兑换。"}],"sources":["https://arcraiders.wiki/wiki/Combat_Mk._1","https://arcraiders.wiki/wiki/Combat_Mk._2","https://allthings.how/arc-raiders-augment-tier-list-best-picks-for-pve-and-pvp/"],"version":"2.0"},"combat_mk3_aggressive":{"verdict":{"en":"The Heavy Shield fighter's bag: more regen than Mk. 2, a second grenade slot, and a big weight limit.","zh":"重型护盾玩家的背包：回血比 Mk. 2 更强，两个手雷位，负重高。"},"use":{"en":"It is the combat augment to take if you want Heavy Shield tankiness, since it also takes Light and Medium. The 2 health every 5 seconds is slow and stops for 30 seconds after any hit, so it rewards disengaging between fights rather than winning fights alone. Players rank it a solid A-tier for mixed PvE/PvP, and the pick over Flanking for sustained fights.","zh":"想要重型护盾的肉度就用它，轻、中型护盾也都能装。每 5 秒回 2 点血很慢，受伤后暂停 30 秒，适合打完脱战恢复，别指望靠它赢团战。多数榜单评 A 级，持久战比侧翼突击更稳。"},"obtain":{"en":"Craft it at Gear Bench 3 after learning the blueprint, which drops from augment and medical containers. Nerdschalk's farming list for blueprints: Stella Montis (Lobby Checkpoint Security, Sandbox, Archives), The Blue Gate (Confiscation), Buried City (Hospital), Dam Battlegrounds (Testing Addicts). It is not a quest reward.","zh":"学会蓝图后在装备工作台 3 级制作，蓝图出自强化和医疗类容器。蓝图推荐点：星辰山（大厅安检、沙盒、档案室）、蓝门（没收区）、掩埋废城（医院）、大坝战场（测试瘾君子）。没有任务奖励。"},"tips":[{"en":"Repair costs 1 Advanced Electrical Components and 2 Processors; don't take it into a raid you expect to lose.","zh":"修理要 1 个高级电子元件和 2 个处理器，没把握就别带进必输的局。"}],"sources":["https://arcraiders.wiki/wiki/Combat_Mk._3_(Aggressive)","https://allthings.how/arc-raiders-augment-tier-list-best-picks-for-pve-and-pvp/","https://nerdschalk.com/every-new-augment-in-arc-raiders-and-how-to-get-them/"],"version":"2.0"},"combat_mk3_flanking":{"verdict":{"en":"A niche pistol pick: great space, but no Heavy Shield and a perk most builds never use.","zh":"小众手枪流选择：空间大，但没法装重型护盾，核心词条多数配置用不上。"},"use":{"en":"The 33% faster equip only helps stowed Pistols and Hand Cannons, so it suits you if you swap to a sidearm for close fights. You also get the most Utility slots and 20 backpack slots, plus a Medium Shield since patch 1.29. Most rankings put it near the bottom of the Mk. 3 tier; Aggressive is better for general play.","zh":"加速只对收起的手枪和手炮有效，适合近身换手枪的打法。另有 20 格背包、更多功能位，1.29 起也能用中型护盾。多数榜单把它放在 Mk. 3 中下游，常规打法选进攻型更好。"},"obtain":{"en":"Lance sells it, limited to one at a time, and you can also craft it at Gear Bench 3 once the blueprint is learned. Buying avoids hunting the blueprint, but check your coin first.","zh":"兰斯有售（限购 1 件），学会蓝图后也可在装备工作台 3 级制作。买最省事，不用刷蓝图。"},"tips":[{"en":"If you never carry a Hand Cannon or pistol, take Aggressive or Survivor instead.","zh":"不带手枪或手炮就换进攻型或生存型。"}],"sources":["https://arcraiders.wiki/wiki/Combat_Mk._3_(Flanking)","https://allthings.how/arc-raiders-augment-tier-list-best-picks-for-pve-and-pvp/"],"version":"2.0"},"looting_mk1_mk2":{"verdict":{"en":"Mk. 1 is a cheap bag upgrade; Mk. 2 is the best budget looter, with trinket slots and tick protection.","zh":"Mk. 1 是便宜的背包升级；Mk. 2 是最好的预算搜刮包，带饰品位和防蜱虫。"},"use":{"en":"Both only take Light Shields, so you trade defense for room. Mk. 2 has the highest weight limit and the most backpack slots of the Rare augments, three Trinket slots and a second Safe Pocket, and it flicks Ticks off after 1 second. Reviewers call it a strong budget looting choice that is easy to afford.","zh":"两者都只能装轻型护盾，用防御换空间。Mk. 2 在稀有强化里负重和背包格最多，有 3 个饰品位和第二个安全口袋，蜱虫 1 秒就甩掉。评测普遍说它是很好上手的预算搜刮包。"},"obtain":{"en":"Mk. 1: Lance sells it, or swap in a Free Loadout Augment. Mk. 2: Lance sells one per day, it can be crafted at Gear Bench 2, and quests Celeste's Teenage Rebellion, In My Image and With A Trace give one. Shani also sells it for Cred.","zh":"Mk. 1：兰斯出售，或用免费配装强化兑换。Mk. 2：兰斯每日限购，装备工作台 2 级可制作，任务“塞莱斯特的少年叛逆”“与我同形”“蛛丝马迹”有奖励；萨尼也可用信用点购买。"},"tips":[{"en":"A Light Shield plus Mk. 2 costs little to repair, so this is a good kit for running places with ticks.","zh":"轻型护盾配 Mk. 2 修理很便宜，适合去蜱虫多的地方。"}],"sources":["https://arcraiders.wiki/wiki/Looting_Mk._1","https://arcraiders.wiki/wiki/Looting_Mk._2","https://allthings.how/arc-raiders-augment-tier-list-best-picks-for-pve-and-pvp/"],"version":"2.0"},"looting_mk3_cautious":{"verdict":{"en":"The biggest bag in the game at 24 slots, but Survivor beats it in most situations.","zh":"背包最大（24 格），但多数情况下生存型更强。"},"use":{"en":"It takes Light Shields only. The Adrenaline Shot fires when your shield breaks on a fixed cooldown, and the built-in binoculars cannot be dropped. It works for solo scouts who avoid fights and want maximum space. Rankings put it in the B tier, behind Survivor.","zh":"只能装轻型护盾。护盾破裂时自动打一针弱效肾上腺素针剂（固定冷却），内置望远镜不可丢弃。适合躲战的单人侦察型玩家。榜单评 B 级，不如生存型。"},"obtain":{"en":"Lance sells it, limited to one, and you can craft it at Gear Bench 3. It is not tied to a quest.","zh":"兰斯有售（限购 1 件），也可在装备工作台 3 级制作，没有任务奖励。"},"tips":[{"en":"The binoculars occupy a slot permanently, so factor that into your Quick Use layout.","zh":"望远镜占用固定栏位，规划快速使用栏时要算进去。"}],"sources":["https://arcraiders.wiki/wiki/Looting_Mk._3_(Cautious)","https://allthings.how/arc-raiders-augment-tier-list-best-picks-for-pve-and-pvp/"],"version":"2.0"},"looting_mk3_safekeeper":{"verdict":{"en":"Pick it when you must protect a weapon: its Safe Pocket takes any item and it supports all shields.","zh":"要保住一把武器时选它：安全口袋可放任何物品，三种护盾都能装。"},"use":{"en":"The standout is a Safe Pocket that can hold a full weapon, so a good gun survives a death. Reviewers call it powerful but specialised; it doesn't beat Survivor for general looting. Good for dangerous events and high-risk PvP with a prized weapon.","zh":"亮点是安全口袋能放整把武器，阵亡后好枪也保得住。评测说它强但很专精，普通搜刮不如生存型。适合高风险事件和带着心爱武器的 PvP。"},"obtain":{"en":"Reward for the quest Ruins and Reverberations; otherwise craft it at Gear Bench 3 after learning its blueprint. Blueprints come from augment and medical containers.","zh":"任务“废墟和回响”奖励；也可学会蓝图后在装备工作台 3 级制作，蓝图出自强化和医疗类容器。"},"tips":[{"en":"Only 18 backpack slots; keep loot light when you run it.","zh":"背包只有 18 格，带它时少拿杂物。"}],"sources":["https://arcraiders.wiki/wiki/Looting_Mk._3_(Safekeeper)","https://nerdschalk.com/every-new-augment-in-arc-raiders-and-how-to-get-them/"],"version":"2.0"},"looting_mk3_survivor":{"verdict":{"en":"The default Mk. 3 pick: the highest weight limit, three Safe Pockets and a downed-regen perk.","zh":"Mk. 3 的默认之选：负重最高，3 个安全口袋，倒地可回血。"},"use":{"en":"Almost every ranking lists it first: 80 weight, a Utility slot, and health that regenerates up to 75% while you are downed and stationary, which turns clutch revives into real chances. It handles Light and Medium Shields. One source mentions it may get a balance pass, so don't build your plans on it never changing.","zh":"几乎所有榜单都把它排第一：负重 80、有功能位，倒地静止时血量可回到 75%，让绝境救起更有机会。支持轻、中型护盾。有来源提到它可能被调整，别指望它永远不变。"},"obtain":{"en":"Reward for the quest Bait, Fetch, Blast. The wiki lists the Black Crate as a source, and the blueprint lets you craft it at Gear Bench 3.","zh":"任务“诱饵、搜寻、爆破”奖励；维基列出黑色板条箱为来源，学会蓝图后可在装备工作台 3 级制作。"},"tips":[{"en":"Great for farming ARC bosses and for solo extractions with a full bag.","zh":"适合刷 ARC 头目和单人满包撤离。"}],"sources":["https://arcraiders.wiki/wiki/Looting_Mk._3_(Survivor)","https://allthings.how/arc-raiders-augment-tier-list-best-picks-for-pve-and-pvp/"],"version":"2.0"},"tactical_mk1_mk2":{"verdict":{"en":"Mk. 1 is a learner bag; Mk. 2 is a favorite for PvP escapes thanks to its auto-smoke.","zh":"Mk. 1 入门用；Mk. 2 的自动烟雾让它成为 PvP 逃生热门。"},"use":{"en":"Tactical Mk. 1 is outclassed fast, but it gives five Quick Use slots and a Medium Shield. Mk. 2 drops a small smoke grenade whenever your shield breaks, which gives you a free break in line of sight, and one tier list puts it at S. The weight limit is the lowest of the Rare augments.","zh":"战术 Mk. 1 很快会被淘汰，但有 5 个快速使用位并可装中型护盾。Mk. 2 在护盾破裂时自动放出小烟雾，免费切断视线，有榜单评为 S 级。负重是稀有强化里最低的。"},"obtain":{"en":"Mk. 1: Lance sells it, or swap a Free Loadout Augment; quest Trash Into Treasure also gives one. Mk. 2: Lance sells one per day, craftable at Gear Bench 2, and quests With a View and A Toxic Trail reward it.","zh":"Mk. 1：兰斯出售或用免费配装强化兑换，任务“变废为宝”也给一件。Mk. 2：兰斯每日限购，装备工作台 2 级可制作，任务“风景如画”“有毒的踪迹”有奖励。"},"tips":[{"en":"Mk. 2 repair is one Electrical Components and one Magnet, so it is cheap insurance for PvP-heavy maps.","zh":"Mk. 2 修理只要 1 电子元件和 1 磁铁，PvP 多的地图很划算。"}],"sources":["https://arcraiders.wiki/wiki/Tactical_Mk._1","https://arcraiders.wiki/wiki/Tactical_Mk._2","https://allthings.how/arc-raiders-augment-tier-list-best-picks-for-pve-and-pvp/"],"version":"2.0"},"tactical_mk3_defensive":{"verdict":{"en":"The sustain pick for Heavy Shield players: a built-in recharger that works while running.","zh":"重型护盾玩家的续航之选：内置充能器，边跑边用。"},"use":{"en":"It comes with a reusable Shield Recharger on a cooldown and lets you use any Shield Recharger while sprinting. That makes a Heavy Shield much less painful in long fights and boss farms. Reviewers rate it A-tier and the pick for PvE and heavy-shield play.","zh":"自带可复用的护盾充能器（有冷却），还允许边跑边用任意充能器，重型护盾的持久战和刷头目更轻松。评测评为 A 级，PvE 和重盾首选。"},"obtain":{"en":"No quest gives it and Lance doesn't list it. Learn its blueprint (from augment and medical containers) and craft it at Gear Bench 3.","zh":"没有任务奖励，兰斯也不卖。需从强化和医疗类容器找蓝图，再到装备工作台 3 级制作。"},"tips":[{"en":"Pair it with a Heavy Shield; the 2.0 durability decay cut makes that combo cheaper to keep alive.","zh":"搭配重型护盾；2.0 降低了耐久损耗，这套更省修理。"}],"sources":["https://arcraiders.wiki/wiki/Tactical_Mk._3_(Defensive)","https://arcraiders.wiki/wiki/Frozen_Trail","https://allthings.how/arc-raiders-augment-tier-list-best-picks-for-pve-and-pvp/"],"version":"2.0"},"tactical_mk3_healing":{"verdict":{"en":"A medic bag for careful players: three healing slots, three Safe Pockets, a revive cloud.","zh":"谨慎玩家的医疗包：3 个治疗位、3 个安全口袋，被救起时释放治疗云。"},"use":{"en":"Three Healing slots let you carry far more meds and bandages, and the Cloud of Renewal fires when you are revived (45 health, 45-second cooldown in the current data). It takes Light and Medium Shields. Older posts quote 20 health and a 30-second cooldown; that is out of date.","zh":"3 个治疗位可多带药品，被救起时触发复苏云（当前数据为 45 点生命、45 秒冷却）。支持轻、中型护盾。旧文章写的 20 点、30 秒冷却已过时。"},"obtain":{"en":"Lance sells it, limited to one, and these quests reward it: The First Nomads, A Reveal in Ruins, Prescriptions of the Past and On The Map. You can also craft it at Gear Bench 3.","zh":"兰斯有售（限购 1 件），任务“初代游民”“废墟中的揭示”“昔日的药方”“在地图上”均有奖励；也可在装备工作台 3 级制作。"},"tips":[{"en":"Best with a squad that revives you; solo it only helps after you are already back up.","zh":"有队友救你时最有用，单人时只能在爬起后帮忙。"}],"sources":["https://arcraiders.wiki/wiki/Tactical_Mk._3_(Healing)","https://allthings.how/arc-raiders-augment-tier-list-best-picks-for-pve-and-pvp/"],"version":"2.0"},"tactical_mk3_revival":{"verdict":{"en":"Squad and cautious-solo utility: a free defibrillator, but only Light Shields.","zh":"团队和谨慎单人玩家的实用包：自带复苏剂，但只能装轻型护盾。"},"use":{"en":"The Integrated Defibrillator can be reused on a long cooldown (about 4 minutes per the community wiki), and you get slow regen too. It is a good support bag for teams. One guide finds its 5 Quick Use and 2 Safe Pocket slots restrictive and says it doesn't replace Survivor for looting.","zh":"内置复苏剂可重复使用，冷却很长（社区维基约 4 分钟），另有缓慢回血。适合当队伍的支援包。有指南认为它的 5 个快速使用位和 2 个安全口袋偏紧，搜刮上取代不了生存型。"},"obtain":{"en":"Reward for the quest Waking the Grid, or craft it at Gear Bench 3 with the blueprint.","zh":"任务“唤醒安保网络”奖励，或学会蓝图后在装备工作台 3 级制作。"},"tips":[{"en":"It is one of the newer augments; verify the cooldown in-game before relying on it.","zh":"这是较新的强化，依赖它之前先在游戏里确认冷却。"}],"sources":["https://arcraiders.wiki/wiki/Tactical_Mk._3_(Revival)","https://nerdschalk.com/every-new-augment-in-arc-raiders-and-how-to-get-them/"],"version":"2.0"},"tactical_mk3_smoke":{"verdict":{"en":"Mk. 2 with more room: same auto-smoke, two Utility slots, 19 backpack slots.","zh":"加大版 Mk. 2：同样的自动烟雾，2 个功能位、19 格背包。"},"use":{"en":"It keeps the Mk. 2 smoke on shield break and expands capacity, with Light and Medium Shields. If you liked Mk. 2 and want more room, this is the upgrade. The wiki page is still a stub, so there is little community comparison yet.","zh":"保留 Mk. 2 的护盾破裂放烟雾，并扩大容量，支持轻、中型护盾。喜欢 Mk. 2 又想要更多空间就升级它。维基页面还是草稿，社区对比较少。"},"obtain":{"en":"Craft it at Gear Bench 3 with its blueprint; no trader or quest sells it in the current data.","zh":"学会蓝图后在装备工作台 3 级制作；目前没有商人或任务提供。"},"tips":[{"en":"Recycling returns Advanced Electrical Components and a Processor, so a spare is not a total loss.","zh":"回收可得高级电子元件和处理器，多余的也不亏。"}],"sources":["https://arcraiders.wiki/wiki/Tactical_Mk._3_(Smoke)","https://arcraiders.wiki/wiki/Augment"],"version":"2.0"},"light_shield":{"verdict":{"en":"The cheap default: no movement penalty, fits every augment, and almost free to repair.","zh":"便宜的默认款：不减速，所有强化都能装，修理几乎免费。"},"use":{"en":"Charge 40 and 40% reduction. It costs speed nothing, so run it for scouting, loot runs and anywhere you expect to avoid fights. A shield absorbs a percentage of damage, so your health bar matters more than the charge.","zh":"护盾值 40，减伤 40%，不影响移速。适合侦察、搜刮、不想硬打的局。护盾是按比例减伤，真正的血量更关键。"},"obtain":{"en":"Lance sells it, you can craft it at Workbench 1 or Gear Bench 1, and the quest Clearer Skies gives one. Free Loadouts also include one.","zh":"兰斯出售，工作台 1 级或装备工作台 1 级可制作，任务“清朗天空”有奖励；免费配装也自带一个。"},"tips":[{"en":"Repair is only 4 plastic parts, so patch it up every raid rather than replace it.","zh":"修理只要 4 个塑料零件，每局修一修就行，不必换新。"}],"sources":["https://arcraiders.wiki/wiki/Light_Shield","https://arcraiders.wiki/wiki/Shield"],"version":"2.0"},"medium_shield":{"verdict":{"en":"The sweet spot for most raids: more charge for a tiny speed cost, and cheap to repair.","zh":"多数局的甜点：多一截护盾，只损失一点速度，修理也便宜。"},"use":{"en":"70 charge, 42.5% reduction and 5% slower. Take it when you expect fights, then step up to Heavy only if your augment allows it. Requires an augment like Combat, Tactical Mk. 2 or Survivor. The skill Used to the Weight eases the movement penalty.","zh":"护盾值 70，减伤 42.5%，减速 5%。预计有战斗时带它，强化支持再升重型。需要战斗、战术 Mk. 2 或生存型等强化。“负重如常”技能可缓解减速。"},"obtain":{"en":"Lance sells up to 3 per day; the wiki also lists Raider Cache loot and Raider Decks. Several quests reward one (Exploring Pendola Pass, Bait, Fetch, Blast, Down to Earth, With A Trace, Out of the Shadows).","zh":"兰斯每日限购 3 个；维基还列了奇袭者箱和袭击者牌组。多个任务有奖励（探索彭多拉山口、诱饵、搜寻、爆破、踏实补给、蛛丝马迹、走出阴影）。"},"tips":[{"en":"Repair is 1 ARC Circuitry and 1 Battery per patch-up, well under the cost of a new one.","zh":"每次修理仅 1 个 ARC线圈加 1 个电池，远低于买新的。"}],"sources":["https://arcraiders.wiki/wiki/Medium_Shield","https://arcraiders.wiki/wiki/Shield"],"version":"2.0"},"heavy_shield":{"verdict":{"en":"Best protection in the game, and cheaper to run since 2.0 cut its slowdown and wear.","zh":"最强防护；2.0 降低了减速和损耗，用起来更划算。"},"use":{"en":"80 charge and 52.5% reduction. Frozen Trail cut its movement penalty from 15% to 10% and its durability decay from 0.20 to 0.15. Only Combat Mk. 2, Aggressive, Safekeeper and Defensive can carry it. Take it for boss farming and contested loot, and a Defensive augment keeps it topped up.","zh":"护盾值 80，减伤 52.5%。冰封之路（2.0）把减速从 15% 降到 10%，耐久损耗从 0.20 降到 0.15。只有战斗 Mk. 2、进攻型、守护者、防御型能装。适合刷头目和抢点，防御型强化可持续补盾。"},"obtain":{"en":"Lance sells one a day for 16,500 coins; quests Celeste's Teenage Rebellion and Prescriptions of the Past give one. You can craft it at Gear Bench 2 with a Power Rod and 2 Voltage Converters, usually cheaper than buying.","zh":"兰斯每日限购 1 个，要 16500 钱币；任务“塞莱斯特的少年叛逆”“昔日的药方”有奖励。也可在装备工作台 2 级用 1 个能量管和 2 个变电器制作，通常比买便宜。"},"tips":[{"en":"Repairing costs 2 ARC Circuitry and a Voltage Converter, so only bring it when the raid is worth it.","zh":"修理要 2 个 ARC线圈加 1 个变电器，值得的局才带。"},{"en":"Salvaging in raid returns 4 ARC Alloy if you find one and don't need it.","zh":"局内拆解可得 4 个 ARC合金，用不上可拆。"}],"sources":["https://arcraiders.wiki/wiki/Heavy_Shield","https://arcraiders.wiki/wiki/Frozen_Trail","https://arcraiders.wiki/wiki/Shield"],"version":"2.0"},"light_ammo":{"verdict":{"en":"Cheap and plentiful, but weak against ARC armor; craft it rather than buy.","zh":"便宜量大，但打不穿 ARC 装甲；自己做比买划算。"},"use":{"en":"It feeds the Kettle, Burletta, Hairpin, Bobcat and Stitcher. The wiki notes it struggles against ARC plating, so use it for raiders and soft ARC, and switch weapons for heavy robots.","zh":"用于“水壶”“布尔莱塔”“发夹”“山猫”“钉机”。维基提到它很难击穿 ARC 装甲，适合打雷袭者和软目标，打重型机器人要换武器。"},"obtain":{"en":"Wasps and Turrets drop it, Raider Caches hold some, and Tian Wen sells it. A Workbench 1 craft makes 25 from 2 Chemicals and 3 Metal Parts. Quests Snap and Salvage and When Everything Falls give 100 each.","zh":"黄蜂和炮塔掉落，奇袭者箱也有，天玟出售。工作台 1 级用 2 化学品和 3 金属零件做 25 发。任务“拍照并拆解回收”“万物崩塌之时”各给 100 发。"},"tips":[{"en":"Carry roughly two full magazines' worth plus a stack for the raid; each round is almost weightless.","zh":"带两三个弹匣量再加一叠，弹药几乎没重量。"}],"sources":["https://arcraiders.wiki/wiki/Light_Ammo","https://arcraiders.wiki/wiki/Ammo"],"version":"2.0"},"medium_ammo":{"verdict":{"en":"The most useful all-round ammo: it feeds the most guns and punches through ARC better than Light.","zh":"最实用的通用弹药：能用的枪最多，对 ARC 的穿透也比轻型强。"},"use":{"en":"It covers Arpeggio, Rattler, Tempest, Renegade, Torrente and more. Per the wiki it penetrates ARC armor much better than Light and a bit worse than Heavy, so it works for both raiders and drones.","zh":"适用“三连奏”“响尾蛇”“风暴”“叛逆”“奔流”等。维基称穿甲能力远胜轻型、略逊于重型，雷袭者和无人机都能打。"},"obtain":{"en":"Hornets drop it (the wiki also lists Bastion), plus Raider Caches and Tian Wen. Workbench 1 turns 2 Chemicals and 3 Metal Parts into 20. Quests Picking Up The Pieces, Broken Monument and Back on Top give 80 each.","zh":"马蜂掉落（维基还列有堡垒），奇袭者箱和天玟也有。工作台 1 级用 2 化学品、3 金属零件做 20 发。任务“积少成多”“破败的纪念”“重占上风”各给 80 发。"},"tips":[{"en":"Crafting is cheaper than Tian Wen's price; stock a few stacks and keep a reserve in your stash.","zh":"自己做比天玟卖得便宜，仓库留几叠备用。"}],"sources":["https://arcraiders.wiki/wiki/Medium_Ammo","https://arcraiders.wiki/wiki/Ammo"],"version":"2.0"},"heavy_ammo":{"verdict":{"en":"Worth carrying for Anvil, Ferro and Bettina; you get 10 per craft, so stock up between raids.","zh":"“铁砧”“生铁”“贝蒂娜”必备；每次只做 10 发，局间多备。"},"use":{"en":"It beats Medium and Light against ARC armor; only explosive Launcher Ammo is better. Because slow heavy weapons burn rounds quickly, rely on crafting rather than hoping to find enough.","zh":"穿甲优于中、轻型，只有爆炸性的发射器弹药更强。重型武器耗弹快，靠自己做而不是碰运气捡。"},"obtain":{"en":"Rocketeers and Sentinels drop it, Tian Wen sells it, and the wiki lists Raider Caches. Quests Sizing Things Up, The Right Tool, Communication Hideout and A Rising Tide hand it out. The stack grew from 40 to 60 in patch 1.26.","zh":"火箭手和哨卫掉落，天玟出售，维基还列有奇袭者箱。任务“审时度势”“正确工具”“通讯隐蔽处”“涨潮”会发放。1.26 版本把堆叠从 40 提到 60。"},"tips":[{"en":"One craft gives only 10 rounds for the same inputs as 25 Light, so each Heavy round is dearer; carry what you need, not more.","zh":"同样材料轻型能做 25 发，重型只有 10 发，每发更贵，按需带。"}],"sources":["https://arcraiders.wiki/wiki/Heavy_Ammo","https://arcraiders.wiki/wiki/Ammo"],"version":"2.0"},"shotgun_ammo":{"verdict":{"en":"Only for Il Toro and Vulcano; craft a small stock, since five per craft goes fast.","zh":"只给“公牛”和“火山”用；每次只做 5 发，备小量即可。"},"use":{"en":"It beats Light Ammo against ARC armor but trails Medium. Shotguns are close-range tools, so take enough for a few engagements and don't hoard.","zh":"对 ARC 装甲强于轻型弹药、弱于中型弹药。霰弹枪是近战武器，带够几场战斗即可，不必囤积。"},"obtain":{"en":"Shredders drop it, Tian Wen sells it, and Raider Caches have some. Workbench 1 makes 5 from 2 Chemicals and 3 Metal Parts. Quests Unexpected Initiative and Into the Fray give 40 each.","zh":"粉碎者掉落，天玟出售，奇袭者箱也有。工作台 1 级用 2 化学品、3 金属零件做 5 发。任务“计划不如变化快”“投入战斗”各给 40 发。"},"tips":[{"en":"The stack size is 20, so don't count on a full stack of ammo fitting in one slot.","zh":"堆叠上限 20，别指望一格装很多。"}],"sources":["https://arcraiders.wiki/wiki/Shotgun_Ammo","https://arcraiders.wiki/wiki/Ammo"],"version":"2.0"},"launcher_ammo":{"verdict":{"en":"Strongest anti-ARC ammo, but expensive: craft only when you are hunting big targets.","zh":"对 ARC 最强，但成本高：猎大型目标时再做。"},"use":{"en":"Explosive payloads penetrate ARC armor better than Heavy Ammo. It is made for the Hullcracker (the wiki also lists the Rascal). Don't waste it on raiders you could shoot normally.","zh":"爆炸弹头的穿甲优于重型弹药。专为“裂甲者”设计（维基还列了 无赖）。不要浪费在普通雷袭者身上。"},"obtain":{"en":"Bombardiers drop it, and the wiki also lists Turbine, Rocketeer and Rocketeer Husk. Tian Wen sells 6 for 4,500 coins with a daily limit since 2.0, which is steep. Crafting at Workbench 1 uses an ARC Motion Core and 2 Crude Explosives for 6 rounds. Boarding the Frigate rewards 3.","zh":"投弹手掉落，维基还列有涡轮、火箭手和火箭手残骸。天玟 2.0 起每日限购，6 发要 4500 钱币，很贵。工作台 1 级用 1 个 ARC运动核心和 2 个粗制炸药做 6 发。任务“登上护卫者”奖励 3 发。"},"tips":[{"en":"Buying is a last resort at that price; farm Bombardiers for cores and craft instead.","zh":"这价格买只是下策，刷投弹手拿核心自己做。"}],"sources":["https://arcraiders.wiki/wiki/Launcher_Ammo","https://arcraiders.wiki/wiki/Frozen_Trail"],"version":"2.0"},"energy_clip":{"verdict":{"en":"Fuel for Jupiter and Equalizer: one clip fully recharges a weapon, and buying is capped, so craft.","zh":"“木星”和“制裁者”的燃料：一个弹匣可完全充满一把武器，商店限购，所以自己做。"},"use":{"en":"Each clip fully charges one weapon, and the wiki says energy weapons are never worse than Heavy Ammo at piercing armor. Carry one or two spare clips rather than a stack.","zh":"每个弹匣能完全充满一把武器，维基称能量武器的穿甲从不低于重型弹药。带一两个备用即可，不必成叠。"},"obtain":{"en":"Harvesters and Vaporizers drop it (wiki). Tian Wen sells it at 3,000 coins, limit 20; since 2.0 that is a daily limit. The quest Furtive Meetings gives 5. Workbench 1 turns 1 Advanced ARC Powercell and 2 Batteries into 5.","zh":"收割者和汽化者掉落（维基）。天玟出售，3000 钱币，限购 20，2.0 起为每日限购。任务“秘密集会”奖励 5 个。工作台 1 级用 1 个高级ARC能量电池和 2 个电池做 5 个。"},"tips":[{"en":"Selling one yields only 200 coins, so use clips instead of selling them.","zh":"卖一个才 200 钱币，留着用不如卖。"}],"sources":["https://arcraiders.wiki/wiki/Energy_Clip","https://arcraiders.wiki/wiki/Frozen_Trail"],"version":"2.0"},"angled_grip":{"verdict":{"en":"Cheap sideways-recoil fix; II is the sweet spot, III costs 30% ADS speed.","zh":"便宜的横向后坐力修正；II 最划算，III 要付出 30% 开镜速度。"},"use":{"en":"It only trims horizontal kick, so it pays off on guns that drift sideways in bursts, like the Arpeggio and Kettle (guides pick III on the Arpeggio). Tier III slows aiming by 30%, which hurts in close PvP; players call that penalty fine for defensive or PvE play. If your gun mainly climbs, take a Vertical Grip instead.","zh":"它只削减横向后坐力，适合连发会左右漂的枪，比如“三连奏”和“水壶”（攻略给“三连奏”选 III）。III 会让开镜慢 30%，近距离 PvP 很吃亏，更适合防守或 PvE。如果枪主要是上跳，就换垂直握把。"},"obtain":{"en":"Tier I is a starter craft at Gunsmith level 1 and Tian Wen sells it. Tier II and III need their blueprints and Gunsmith 2/3; Tian Wen also stocks them (limit 1 for III). Tier II is a reward for Marked for Death. All can be found by scavenging.","zh":"I 级在武器工作台 1 级就能做，天玟也卖。II、III 需要先学会蓝图，并分别要求武器工作台 2/3 级；天玟同样出售（III 每日限购 1）。II 是任务“死亡标记”的奖励。三者都可在搜刮中找到。"},"tips":[{"en":"Tier I recycles back into 6 Plastic Parts, so crafting and recycling it costs you almost nothing.","zh":"I 级回收能拿回 6 个塑料零件，造了再拆几乎不亏。"},{"en":"Do not stack it with a Horizontal Grip on the same gun; they share the underbarrel slot.","zh":"它和水平握把共用下挂槽，不能同时装。"}],"sources":["https://arcraiders.wiki/wiki/Angled_Grip_III","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://timesaver.gg/blog/arc-raiders-best-attachments"],"version":"2.0"},"anvil_splitter":{"verdict":{"en":"A retired Anvil mod in 2.0; keep it only if you need it for a project, otherwise recycle it for Amplified Fragments.","zh":"2.0 中已退役的“铁砧”改装；不是项目要用就回收成增强碎片。"},"use":{"en":"It added 3 extra projectiles per shot at 70% less damage per projectile. In 2.0 Embark removed the Anvil's tech mod slot and turned the splitter into an Amplified upgrade branch (Amplified Anvil with Projectile Splitter), so this old mod is mostly a leftover item now.","zh":"它让每发多出 3 颗弹丸，但单颗弹丸伤害降低 70%。2.0 中“铁砧”的科技改装槽被移除，分流器改为增强升级分支（“增强型铁砧”分流器），所以这个旧改装现在基本是遗留物品。"},"obtain":{"en":"The quest A Rising Tide gives one, and you can still scavenge it. The Trophy Display project is listed on the community wiki as using it, so check the project before recycling.","zh":"任务“涨潮”会给一个，搜刮也还能找到。社区维基称“战利品展示架”项目会用到它，回收前先确认项目需求。"},"tips":[{"en":"Recycling returns 5 Amplified Fragments, the material used to amplify weapons, which is worth more to most players than the 7,000 coin sale price.","zh":"回收可得 5 个增强碎片，这是增强武器的材料，对多数玩家比卖 7000 钱币更有价值。"}],"sources":["https://arcraiders.wiki/wiki/Anvil_Splitter","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/","https://www.gamebrief.net/arc-raiders/arc-raiders-anvil-bantam-guide-2026"],"version":"2.0"},"compensator":{"verdict":{"en":"Core accuracy mod for semi-auto and burst guns; II is free of drawbacks, III adds wear.","zh":"半自动和点射枪的核心精度改装；II 没有代价，III 会加速磨损。"},"use":{"en":"It shrinks bullet spread per shot and at maximum, so it helps most when you fire quickly and rely on hits at range. Guides name it for the Stitcher, Torrente and Anvil at III, and for the Renegade, Arpeggio and Kettle at II. Tier III burns durability 20% faster, which is why many players stop at II. If recoil climb is the problem, use a Muzzle Brake instead.","zh":"它降低单发散布和最大散布，快速连射、依赖远距离命中的枪最受益。攻略给“钉机”“奔流”“铁砧”选 III，给“叛逆”“三连奏”“水壶”选 II。III 耐久损耗快 20%，所以不少玩家停在 II。如果问题是枪口上跳，应该换枪口制退器。"},"obtain":{"en":"Tier I is a reward from Market Correction and crafts at Gunsmith 1 from Metal Parts and Wires. Tier II is a reward from Broken Monument. Tier III has no trader or quest source in our data, so scavenge it or learn its blueprint and craft at Gunsmith 3.","zh":"I 级是任务“矫正市场规则”的奖励，武器工作台 1 级用金属零件和导线就能做。II 是任务“破败的纪念”的奖励。III 在我们的数据里没有商人或任务来源，只能搜刮，或学会蓝图后在 3 级工作台制作。"},"tips":[{"en":"It shares the muzzle slot with Muzzle Brake, Extended Barrel and Silencer, so pick the one that fixes your gun's actual weakness.","zh":"它与枪口制退器、加长枪管、消音器共用枪口槽，要选真正补你枪短板的那个。"},{"en":"Reviewers say upgrading the gun itself comes before buying rare mods.","zh":"多篇攻略都说，先升级枪本身，再考虑稀有改装。"}],"sources":["https://arcraiders.wiki/wiki/Compensator_III","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://timesaver.gg/blog/arc-raiders-best-attachments"],"version":"2.0"},"extended_barrel":{"verdict":{"en":"A PvE and long-range mod; skip it for close fights, and III trades more vertical kick for velocity.","zh":"偏 PvE 和远距离的改装；近战别用，III 还会增加垂直后坐力。"},"use":{"en":"It raises bullet speed and the distance before damage falloff, which makes leading moving ARC and distant targets easier. Guides recommend it on the Osprey and for an anti-ARC Renegade build. Tier III adds 15% vertical recoil, so I and II are the safer picks on guns that already climb.","zh":"它提高子弹速度和衰减前的射程，打移动中的 ARC 和远处目标更容易。攻略推荐用在“鱼鹰”和反 ARC 的“叛逆”配置上。III 会增加 15% 垂直后坐力，对本来就上跳的枪，I、II 更稳妥。"},"obtain":{"en":"Tier I crafts at Gunsmith 1 with Metal Parts and Wires. Tier II and III need blueprints and Gunsmith 2/3. Tier III is also a reward from A Rising Tide, and everything can be scavenged. No trader sells it.","zh":"I 级在武器工作台 1 级用金属零件和导线制作。II、III 需要蓝图和 2/3 级工作台。III 也是任务“涨潮”的奖励，各级都能搜刮。商人不出售。"},"tips":[{"en":"Ignore it on SMGs and shotguns; the range bonus rarely matters there (it does not fit shotguns at all).","zh":"冲锋枪上基本不需要；霰弹枪根本装不上。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Barrel_III","https://timesaver.gg/blog/arc-raiders-best-attachments","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"extended_light_mag":{"verdict":{"en":"Free extra rounds with no drawback; always worth fitting on light-ammo guns.","zh":"没有任何代价的额外弹量，轻型弹药的枪都值得装。"},"use":{"en":"It is a straight capacity bonus for the Bobcat, Burletta, Hairpin, Kettle and Stitcher. Guides call magazines a free win, and the Bobcat and Burletta builds include Light Mag III. The Hairpin has no other attachment slots, so this is its only upgrade.","zh":"这是对“山猫”“布尔莱塔”“发夹”“水壶”“钉机”的纯弹量加成。攻略把弹匣称为无代价提升，“山猫”和“布尔莱塔”的推荐配置都带轻型扩容弹匣 III。“发夹”没有其他配件槽，这是它唯一的升级。"},"obtain":{"en":"Tian Wen sells I (limit 5) and II (limit 3). Tier I is also a reward from The Right Tool, A Better Use and Market Correction; Tier II from Snap and Salvage. Tier III has no quest or trader source in our data: scavenge or craft it at Gunsmith 3.","zh":"天玟出售 I（限购 5）和 II（限购 3）。I 也是任务“正确工具”“更好的用途”“矫正市场规则”的奖励，II 是“拍照并拆解回收”的奖励。III 在我们的数据中没有任务或商人来源，只能搜刮或在 3 级武器工作台制作。"},"tips":[{"en":"Tier III needs 5 Steel Springs; if you are short, II already gives +10 rounds.","zh":"III 要 5 个钢质弹簧；缺材料的话，II 已经有 +10 发。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Light_Mag_III","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://timesaver.gg/blog/arc-raiders-best-attachments"],"version":"2.0"},"extended_medium_mag":{"verdict":{"en":"The safest upgrade for medium-ammo rifles; craft II or III and move on.","zh":"中型弹药步枪最稳妥的升级；做到 II 或 III 就够了。"},"use":{"en":"It adds capacity to the Arpeggio, Canto, Osprey, Renegade, Tempest, Torrente and Venator. Guides put Medium Mag III on nearly all of them, and testers call magazines a no-downside slot. It helps most on the Renegade, whose stock magazine is small.","zh":"适用于“三连奏”“颂歌”“鱼鹰”“叛逆”“风暴”“奔流”“复仇者”。多篇攻略几乎给每把都配中型扩容弹匣 III，并称弹匣是无代价的槽位。弹匣原本较小的“叛逆”受益最大。"},"obtain":{"en":"Tier II is sold by Tian Wen (limit 5) and is a reward for Eyes on the Prize. Tier III is a reward for Collision Course and Outstanding Balance, or craft it at Gunsmith 3 with its blueprint. Tier I only comes from scavenging or crafting.","zh":"II 由天玟出售（限购 5），也是任务“目光长远”的奖励。III 是任务“碰撞航线”和“未结债务”的奖励，也可学会蓝图后在 3 级武器工作台制作。I 只能搜刮或制作。"},"tips":[{"en":"Keep one spare Mod Component-based III for your main gun rather than fitting it on throwaway loadouts.","zh":"III 成本较高，留给主力枪，不要装在一次性配装上。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Medium_Mag_III","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://timesaver.gg/blog/arc-raiders-best-attachments"],"version":"2.0"},"extended_shotgun_mag":{"verdict":{"en":"Must-have on the Il Toro and Vulcano: more shells means fewer reloads in a fight.","zh":"“公牛”和“火山”必备：多装弹，少换弹。"},"use":{"en":"It only fits the Il Toro and Vulcano. III adds 6 shells, taking the Vulcano from 4 to 10 according to one guide, and every shotgun build lists it with Shotgun Choke III. There is no drawback.","zh":"只能装在“公牛”和“火山”上。III 加 6 发，据一篇攻略，“火山”由 4 发升到 10 发，所有霰弹枪配装都把它和霰弹枪收束器 III 放在一起。没有任何代价。"},"obtain":{"en":"Tier II is a reward for Eyes on the Prize. Tier I and III come from scavenging or crafting (III at Gunsmith 3 with the blueprint). Tian Wen does not sell any tier.","zh":"II 是任务“目光长远”的奖励。I 和 III 来自搜刮或制作（III 需蓝图和 3 级武器工作台）。天玟不卖任何一级。"},"tips":[{"en":"If you only have one shotgun mod budget, spend it here before the Choke.","zh":"预算只够一件霰弹枪改装的话，先买它，再考虑收束器。"}],"sources":["https://arcraiders.wiki/wiki/Extended_Shotgun_Mag_III","https://www.breakflip.com/guide/arc-raiders/les-meilleurs-mods-a-mettre-sur-le-vulcano-dans-arc-raiders-70047","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"horizontal_grip":{"verdict":{"en":"Strong all-round recoil control, but the 30% ADS penalty makes it a steady-fire pick.","zh":"全面的后坐力控制，但开镜慢 30%，适合稳定射击。"},"use":{"en":"It cuts both horizontal and vertical recoil by 30%, which beats Vertical Grip II for long bursts. Reviewers rate it fine for a stationary anti-ARC build, not for mobile fights. One guide pairs it with a Kinetic Converter on the Bettina.","zh":"水平和垂直后坐力各降 30%，长连发比垂直握把 II 更稳。评测认为它适合站桩打 ARC，不适合移动战。有攻略把它和动能转换器一起装在“贝蒂娜”上。"},"obtain":{"en":"The quest Safe Harbor gives one, and you can scavenge it. It cannot be crafted and no trader sells it, so a found one is worth keeping for a main gun.","zh":"任务“安全港湾”奖励一个，也可搜刮。它不能制作，商人也不卖，捡到的值得留给主力枪。"},"tips":[{"en":"It fits 16 weapons but not the Renegade or Torrente.","zh":"能装 16 种武器，但“叛逆”和“奔流”不行。"}],"sources":["https://arcraiders.wiki/wiki/Horizontal_Grip","https://timesaver.gg/blog/arc-raiders-best-attachments","https://thefilibusterblog.com/arc-raiders-top-attachments-for-every-weapon/"],"version":"2.0"},"kinetic_converter":{"verdict":{"en":"Looks great on paper, but most testers skip it: 15% fire rate costs 20% more recoil.","zh":"纸面好看，但多数测试者弃用：射速 +15% 要付 +20% 后坐力。"},"use":{"en":"Only take it on a gun whose recoil you already control. Guides list it for the Stitcher, Torrente, Bettina and Vulcano. One tester advises against it on the Renegade, and the fire rate gain does not fix a gun's real weakness.","zh":"只在你已经压得住后坐力的枪上用。攻略把它列给“钉机”“奔流”“贝蒂娜”“火山”。有测试者不建议装在“叛逆”上，射速提升也补不了枪的真正短板。"},"obtain":{"en":"You can only scavenge it; there is no recipe, trader or quest source in our data. The community wiki also lists it as used in the Trophy Display project (Part 1, Stage 3).","zh":"只能搜刮，我们的数据里没有配方、商人或任务来源。社区维基还称它用于“战利品展示架”项目（第 1 部分第 3 阶段）。"},"tips":[{"en":"If you do not need it for the project, recycling gives only 2 Duct Tape and 1 Mod Component; selling for 7,000 coins is better.","zh":"项目不需要的话，回收只有 2 胶带和 1 改装零件，卖 7000 钱币更划算。"}],"sources":["https://arcraiders.wiki/wiki/Kinetic_Converter","https://timesaver.gg/blog/arc-raiders-best-attachments","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"lightweight_stock":{"verdict":{"en":"A speed mod for fast-swap or flanking play; it makes recoil much worse.","zh":"为快速切枪、绕后设计的速度改装；后坐力会明显变差。"},"use":{"en":"ADS speed is boosted by 200% and equip time is cut 30%, at the price of 50% more vertical recoil and 50% longer recoil recovery. Guides put it on the Bobcat, Ferro and Osprey, and testers suggest it for secondary weapons or shotguns you fire and reposition with. Avoid it on a gun you spray with.","zh":"开镜速度 +200%，持枪时间 -30%，代价是垂直后坐力 +50%、后坐力恢复慢 50%。攻略给“山猫”“生铁”“鱼鹰”选它，测试者建议用在副武器或打了就换位的霰弹枪上。持续扫射的枪不要装。"},"obtain":{"en":"Craft it at Gunsmith 3 (5 Duct Tape, 2 Mod Components) after learning the blueprint, or scavenge it. No trader or quest sells it.","zh":"学会蓝图后在 3 级武器工作台制作（5 胶带、2 改装零件），或搜刮。商人和任务都不提供。"},"tips":[{"en":"It sits in the stock slot with Padded Stock and Stable Stock; choose speed or stability, not both.","zh":"它和减震枪托、稳定枪托共用枪托槽，速度和稳定只能二选一。"}],"sources":["https://arcraiders.wiki/wiki/Lightweight_Stock","https://timesaver.gg/blog/arc-raiders-best-attachments","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"muzzle_brake":{"verdict":{"en":"The go-to recoil mod for climbing rifles; II is the usual pick, III only for the Bettina-style heavy hitters.","zh":"对上跳严重的步枪是首选；II 最常用，III 主要给“贝蒂娜”这类重型枪。"},"use":{"en":"Cuts both horizontal and vertical kick. Guides use II on the Bobcat, Burletta, Venator, Tempest, Rattler and Aphelion (no penalties), and III on the Bettina. Tier III burns durability 20% faster. Testers rank it above Compensator when climb is the problem.","zh":"同时降低横向和纵向后坐力。攻略把 II 用在“山猫”“布尔莱塔”“复仇者”“风暴”“响尾蛇”“远日点”上（无副作用），III 用在“贝蒂娜”上。III 耐久损耗快 20%。当问题是上跳时，测试者认为它比补偿器更好。"},"obtain":{"en":"Tian Wen sells tier I (limit 5). Tier II is a reward for A Better Use, Collision Course and What We Left Behind. Tier III has no quest or trader source: scavenge or craft at Gunsmith 3 after learning the blueprint.","zh":"I 级天玟出售（限购 5）。II 是任务“更好的用途”“碰撞航线”“遗留之物”的奖励。III 没有任务或商人来源，只能搜刮，或学会蓝图后在 3 级武器工作台制作。"},"tips":[{"en":"Do not craft III unless your gun is the Bettina; II gives most of the effect without extra repair bills.","zh":"不是“贝蒂娜”就别做 III，II 效果接近，还不增加修理开销。"}],"sources":["https://arcraiders.wiki/wiki/Muzzle_Brake_III","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://timesaver.gg/blog/arc-raiders-best-attachments"],"version":"2.0"},"padded_stock":{"verdict":{"en":"Solid stability for steady shooters; the slow ADS and swap make it a poor choice on shotguns.","zh":"给稳定射击型玩家的稳定性改装；开镜和切枪慢，不适合霰弹枪。"},"use":{"en":"Recoil down 15% on both axes and spread down 20%, but ADS is 30% slower and equip is 20% slower. Guides use it on the Rattler and recommend skipping it on the Il Toro. One combo shown for the Torrente is Padded Stock with Kinetic Converter, but they share the stock slot, so check before copying it.","zh":"两个方向后坐力各降 15%、散布降 20%，但开镜慢 30%、持枪慢 20%。攻略用在“响尾蛇”上，并建议“公牛”不要装。有攻略给“奔流”推荐减震枪托加动能转换器，但两者共用枪托槽，照搬前先确认。"},"obtain":{"en":"Tian Wen sells it for 15,000 coins (1 per day). Otherwise learn the blueprint and craft it at Gunsmith 3 with 5 Duct Tape and 2 Mod Components, or scavenge it.","zh":"天玟出售，15000 钱币，每日限购 1。也可学会蓝图后在 3 级武器工作台用 5 胶带和 2 改装零件制作，或搜刮。"},"tips":[{"en":"The 15,000 coin trader price is three times its value; crafting is far cheaper if you have the blueprint.","zh":"商人价 15000 是它价值的三倍，有蓝图的话自己做便宜得多。"}],"sources":["https://arcraiders.wiki/wiki/Padded_Stock","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://thefilibusterblog.com/arc-raiders-top-attachments-for-every-weapon/"],"version":"2.0"},"shotgun_choke":{"verdict":{"en":"Tighter pellet spread for the Il Toro and Vulcano; III is the standard pick despite the extra wear.","zh":"给“公牛”和“火山”收紧弹丸散布；III 是常规选择，虽然更费耐久。"},"use":{"en":"It lowers base spread, so more pellets land at range. Every shotgun build in guides runs Shotgun Choke III next to an Extended Shotgun Mag III. Tier III burns durability 20% faster, which is acceptable on a main shotgun. It takes the muzzle slot, so you cannot also use the Shotgun Silencer.","zh":"它降低基础散布，让更多弹丸在中距离命中。攻略里所有霰弹枪配装都是霰弹枪收束器 III 加霰弹扩容弹匣 III。III 耐久损耗快 20%，主力霰弹枪可以接受。它占用枪口槽，不能同时装霰弹枪消音器。"},"obtain":{"en":"Tier II is sold by Tian Wen (limit 3) and rewarded by Marked for Death and Unexpected Initiative. Tier I and III come from scavenging or crafting (III at Gunsmith 3 with the blueprint).","zh":"II 由天玟出售（限购 3），也是任务“死亡标记”和“计划不如变化快”的奖励。I 和 III 来自搜刮或制作（III 需蓝图和 3 级武器工作台）。"},"tips":[{"en":"Choke II is a cheap trader buy and has no wear penalty if you run shotguns casually.","zh":"收束器 II 可以从商人处买，没有耐久惩罚，适合随手带霰弹枪。"}],"sources":["https://arcraiders.wiki/wiki/Shotgun_Choke_III","https://www.breakflip.com/guide/arc-raiders/les-meilleurs-mods-a-mettre-sur-le-vulcano-dans-arc-raiders-70047","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"shotgun_silencer":{"verdict":{"en":"A stealth option for solo shotgun farming runs; you give up the Choke's tighter spread.","zh":"单刷霰弹枪潜行的选择；代价是放弃收束器的聚拢效果。"},"use":{"en":"It halves the noise of a shotgun blast without any other penalty, but it takes the same slot as the Shotgun Choke. Take it for quiet material runs on a busy map, and stay with the Choke if you hunt players up close.","zh":"不带其他惩罚，把枪声降低一半，但与霰弹枪收束器共用槽位。人多的地图上安静刷材料时带它，近距离找人对枪还是用收束器。"},"obtain":{"en":"Craft it at Gunsmith 3 after learning the blueprint (2 Mod Components, 8 Wires), or scavenge it. No trader or quest provides it. It fits only the Il Toro and Vulcano.","zh":"学会蓝图后在 3 级武器工作台制作（2 改装零件、8 导线），或搜刮。商人和任务都不提供。只能装在“公牛”和“火山”上。"},"tips":[{"en":"Recycling returns only 1 Mod Component and 1 Wires, so keep it for builds you actually use.","zh":"回收只返 1 个改装零件和 1 个导线，不用的话比卖掉更亏，按需留着。"}],"sources":["https://arcraiders.wiki/wiki/Shotgun_Silencer","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://timesaver.gg/blog/arc-raiders-best-attachments"],"version":"2.0"},"silencer":{"verdict":{"en":"Great for stealth and avoiding ARC aggro; II is the best value, III adds durability wear.","zh":"潜行和避免引来 ARC 的好选择；II 性价比最高，III 会加速磨损。"},"use":{"en":"Cuts the noise you make. Guides pick II for the Renegade and Anvil and a silencer for the Ferro. It has no accuracy penalty, but it occupies the muzzle slot, so you give up a Compensator or Muzzle Brake. Tier III is 60% quieter but wears the gun 20% faster.","zh":"降低开火噪音。攻略给“叛逆”“铁砧”选 II，给“生铁”选消音器。没有精度惩罚，但占用枪口槽，要放弃补偿器或枪口制退器。III 噪音降 60%，枪磨损快 20%。"},"obtain":{"en":"Tian Wen sells tier I (limit 1), a reward for When Everything Falls. Tier II rewards come from Snap and Salvage, Outstanding Balance and Market Correction. Tier III is scavenge-only with no recipe in our data.","zh":"天玟出售 I 级（限购 1），任务“万物崩塌之时”也会给。II 的奖励来自“拍照并拆解回收”“未结债务”“矫正市场规则”。III 只能搜刮，我们的数据里没有配方。"},"tips":[{"en":"Hairpin already has a built-in silencer, and the Hairpin cannot take any muzzle mods.","zh":"“发夹”自带消音，无法再装枪口改装。"}],"sources":["https://arcraiders.wiki/wiki/Silencer_III","https://timesaver.gg/blog/arc-raiders-best-attachments","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"stable_stock":{"verdict":{"en":"One of the best mods for burst and semi-auto guns; the 20% slower swap on III hardly matters.","zh":"点射和半自动枪最好的改装之一；III 切枪慢 20% 基本无关紧要。"},"use":{"en":"It shortens how long the reticle takes to settle after each shot. A tier list puts Stable Stock III at the top, and guides pick it for the Torrente, Arpeggio, Aphelion and Renegade (one tester found a III stock alone beats a full kit of weaker mods). Equip is slower, but on a primary weapon you seldom notice.","zh":"它缩短每发之后准星回稳的时间。有排名把稳定枪托 III 放在最前，攻略给“奔流”“三连奏”“远日点”“叛逆”选它（有测试者称只装 III 枪托就胜过一整套低级改装）。持枪变慢，但主武器上很少有感觉。"},"obtain":{"en":"Tier I is a reward for A Better Use. Tier II is a reward for What We Left Behind. Tier III is sold by Tian Wen for 15,000 coins (limit 2) and is a reward for Back on Top, or craft it at Gunsmith 3.","zh":"I 级是任务“更好的用途”奖励，II 是“遗留之物”奖励。III 由天玟出售（15000 钱币，限购 2），也是任务“重占上风”的奖励，或在 3 级武器工作台制作。"},"tips":[{"en":"Tier III is the one to save for: it costs 15,000 at the trader, so craft it once you have the blueprint.","zh":"III 值得投入：商人价 15000，学会蓝图后自己做更省。"}],"sources":["https://arcraiders.wiki/wiki/Stable_Stock_III","https://timesaver.gg/blog/arc-raiders-best-attachments","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"vertical_grip":{"verdict":{"en":"The standard fix for rifles that climb; III is strong but its ADS penalty hurts in PvP.","zh":"上跳严重的步枪的标准解法；III 很强，但开镜惩罚在 PvP 中很吃亏。"},"use":{"en":"It cuts vertical recoil by 20/30/40%. Guides recommend III on the Aphelion, Bobcat, Burletta, Venator, Tempest, Il Toro and Vulcano, and II on the Torrente. Tier III slows aiming by 30%; testers call it better for defensive or PvE play than for snappy PvP.","zh":"垂直后坐力分别降低 20/30/40%。攻略给“远日点”“山猫”“布尔莱塔”“复仇者”“风暴”“公牛”“火山”推荐 III，给“奔流”推荐 II。III 开镜慢 30%，测试者认为更适合防守或 PvE，不适合灵活的 PvP。"},"obtain":{"en":"Tian Wen sells II (limit 5), which is also a reward for What We Left Behind. Tier I crafts at Gunsmith 1 from Duct Tape and Plastic Parts. Tier III needs its blueprint and Gunsmith 3, or scavenge it.","zh":"天玟出售 II（限购 5），“遗留之物”也会给。I 级在 1 级武器工作台用胶带和塑料零件制作。III 需要蓝图和 3 级武器工作台，或搜刮。"},"tips":[{"en":"Vertical Grip III recycles into 2 Mechanical Components and 2 Duct Tape, a decent refund.","zh":"垂直握把 III 回收可得 2 机械元件和 2 胶带，返还不错。"}],"sources":["https://arcraiders.wiki/wiki/Vertical_Grip_III","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://timesaver.gg/blog/arc-raiders-best-attachments"],"version":"2.0"},"ancient_fort_security_code":{"verdict":{"en":"Only useful during the Locked Gate event: hand it in at the control room, never extract with it.","zh":"仅在“上锁的大门”事件中有用：送到控制室，别带出局。"},"use":{"en":"One of four codes that open the main gate on The Blue Gate during Locked Gate. Take it to the Gate Control Room and put it in one of the four terminals; it is removed on submission. Extract with it and it turns into an Expired Security Code, which is worthless, and the gate may then never open for the lobby.","zh":"它是“上锁的大门”事件中打开蓝门主闸门所需的四枚安全码之一。带到蓝门控制室，插入四个终端之一，提交后即被消耗。若带着它撤离，会变成过期安全码，毫无用处，还可能让整局的大门打不开。"},"obtain":{"en":"Search any lootable container in the Ancient Fort. At least one code spawns per round, sometimes more. The other three codes come from Raider's Refuge, Pilgrim's Peak and Reinforced Reception.","zh":"在古代要塞搜任意可搜刮容器即可，每局至少刷出一枚，有时更多。另外三枚分别在奇袭者避难所、朝圣峰和加固前台。"},"tips":[{"en":"It sells for next to nothing, so the only reason to carry it is to submit it. Don't pocket it for a later raid.","zh":"它几乎不值钱，带着只为提交。别留到下一局，它是临时物品。"},{"en":"A teammate can find the same code, so you don't need to be the one who reaches the control room.","zh":"同一枚码队友也能找到，不一定非得你自己送到控制室。"}],"sources":["https://arcraiders.wiki/wiki/Ancient_Fort_Security_Code","https://wzstats.gg/arc-raiders/wiki/items/keys/ancient-fort-security-code","https://mein-mmo.de/en/arc-raiders-locked-gate-time-and-where-to-find-the-keys,1556271"],"version":"2.0"},"blue_gate_cellar_key":{"verdict":{"en":"A cheap, low-risk key for cellar stashes: use it if you pass the spot, don't plan a raid around it.","zh":"地窖钥匙便宜又低风险：路过就开，不值得专门跑一趟。"},"use":{"en":"It opens several cellar doors on The Blue Gate, not one fixed room. Reports name a cellar at Trapper's Glade and another left of Ruined Homestead; the second is said to hold weapons, blueprints, grenades and healing items. Treat it as a small bonus stash.","zh":"它能打开蓝门的多个地窖门，而不是某个固定房间。有攻略提到猎人林地的地窖和废弃农庄左侧的地窖，后者可能出武器、蓝图、手雷和治疗物品。当作小型额外藏点即可。"},"obtain":{"en":"Random drop while scavenging; the wiki places one west of Olive Grove. A hatch entrance south of Olive Grove and Ruined Homestead is one reliable way in.","zh":"搜刮时随机获得，社区维基标注其中一处在橄榄树林以西。橄榄树林和废弃农庄以南有一处舱口入口，比较好找。"},"tips":[{"en":"It sells for only 100 and nothing in the workshop needs it, so using it costs you nothing.","zh":"只值100钱币，工坊也不需要，用掉不亏。"}],"sources":["https://arcraiders.wiki/wiki/Blue_Gate_Cellar_Key","https://gameriv.com/arc-raiders-all-key-locations-and-what-each-key-unlocks/","https://www.dexerto.com/wikis/arc-raiders/all-keys-and-what-they-open"],"version":"2.0"},"blue_gate_communication_tower_key":{"verdict":{"en":"A middling key: the basement room is quiet, but loot is mostly electrical items.","zh":"中等偏下：地下室相对安静，但多是电子类物资。"},"use":{"en":"The door is a locked metal door in the basement of Pilgrim's Peak, by the Communication Tower in the far north of The Blue Gate. The room has server racks, a weapon box, drawers and resource crates. One guide says it is mostly electrical items, so rate it a situational stop.","zh":"门在蓝门最北侧、通讯塔旁的朝圣峰地下室，是一扇金属门。房间里有服务器机架、武器箱、抽屉和资源箱。有攻略称主要出电子类物品，属于顺路再开的点。"},"obtain":{"en":"The quest Groundbreaking gives one. Otherwise it is a random drop from containers in residential and commercial buildings, and no quest guarantees more.","zh":"完成任务“突破性进展”可获得一把；其余只能靠居民区和商业区容器随机掉落。"},"tips":[{"en":"If you will do Groundbreaking anyway, keep the first key for it before sparing later ones.","zh":"打算做“突破性进展”的话，先留一把给任务，多出来的再用或卖。"},{"en":"A zipline runs down to the tower area, so the approach is easier from above.","zh":"通讯塔有索道可以从高处下来，进入更方便。"}],"sources":["https://arcraiders.wiki/wiki/Blue_Gate_Communication_Tower_Key","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-all-keys-and-key-room-locations/","https://gameriv.com/arc-raiders-all-key-locations-and-what-each-key-unlocks/"],"version":"2.0"},"blue_gate_confiscation_room_key":{"verdict":{"en":"The best Blue Gate key to open, but the room is contested, so go in ready for a fight.","zh":"蓝门最值得开的钥匙，但这间房很抢手，要做好交火准备。"},"use":{"en":"The door is in the underground tunnels, in the confiscated goods area under the Security Wing. Guides call it one of the map's best loot rooms and one of the keys most worth using, but also very risky because other raiders target it. Bring a shield and clear the approach before you open it.","zh":"门在蓝门地下隧道的没收物库房，位于安保区辅楼下方。攻略普遍称它是全图最好的战利品房之一、最值得用的钥匙之一，但也很危险，常有人蹲守。带好护盾，开门前先清场。"},"obtain":{"en":"Scavenging only. The wiki puts one on the ground floor of the Security Wing, next to the Traffic Tunnel below the Headhouse. Containers near Ruby Residence are also named.","zh":"只能搜刮获得。社区维基称在安保区辅楼一层、候车室下方通行隧道旁有刷新点；红宝石宅邸附近的容器也有人提到。"},"tips":[{"en":"Players often zipline down from Reinforced Reception to reach the tunnels; the vertical shaft and Communication Tower are other routes.","zh":"常见路线是从加固前台沿索道下去，也可走竖井或通讯塔。"},{"en":"Epic rarity but only 100 coins to a trader, so selling it is a waste.","zh":"稀有度为史诗，商人只给100钱币，卖掉太亏。"}],"sources":["https://arcraiders.wiki/wiki/Blue_Gate_Confiscation_Room_Key","https://gameriv.com/arc-raiders-all-key-locations-and-what-each-key-unlocks/","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-all-keys-and-key-room-locations/"],"version":"2.0"},"blue_gate_village_key":{"verdict":{"en":"A safe, modest key: one old village house with decent but unremarkable loot.","zh":"安全但收益一般：只开一栋旧村屋，战利品中规中矩。"},"use":{"en":"It opens a locked building in the Village on the west side of The Blue Gate. Guides split on the reward: one calls the loot usually modest and the safer option, another a high-tier area. Expect ordinary containers rather than a jackpot.","zh":"它打开蓝门西侧村庄里的一栋上锁建筑。各家评价不一：一份攻略说收益通常一般、胜在安全，另一份称是高档区域。预期是普通容器，不是大奖。"},"obtain":{"en":"Random drop from containers in residential areas; no quest hands one out, so it can take several raids to see one.","zh":"居民区容器随机掉落，没有任务发放，可能要跑几局才见到。"},"tips":[{"en":"You can only get 100 coins for it, so open the house if you walk past and skip it if the village is busy.","zh":"卖也只有100钱币，路过就开；村庄人多就别硬进。"}],"sources":["https://arcraiders.wiki/wiki/Blue_Gate_Village_Key","https://gameriv.com/arc-raiders-all-key-locations-and-what-each-key-unlocks/","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-all-keys-and-key-room-locations/"],"version":"2.0"},"buried_city_hospital_key":{"verdict":{"en":"Worth opening when you already hold it, not worth a raid spent hunting for it.","zh":"手上有就值得开，不值得专门去找。"},"use":{"en":"The door is in the north-west corner of the Hospital second floor (one guide counts it as the third). From the Northern Metro entrance, climb the stairs, turn left through the long hall to the locker room, leave by the far door and turn right. Expect roughly ten containers: weapons, blueprints, consumables and valuables.","zh":"门在医院二楼西北角（有攻略算作三楼）。从北侧地铁站入口上楼左转，穿过长走廊到储物柜房间，从对面门出去后立刻右转。里面约有十个可搜刮点，可能出武器、蓝图、消耗品和贵重物品。"},"obtain":{"en":"Random drop from cabinets, drawers and desks in Buried City buildings; a raider who dies carrying one also drops it.","zh":"掩埋废城建筑里的柜子、抽屉和书桌随机掉落；带钥匙死亡的玩家也会掉出。"},"tips":[{"en":"A documented run found a Dam Control Tower Key in this room, which chains into another vault.","zh":"曾有人在这间房里开出大坝控制塔钥匙，可以接着开下一个房间。"},{"en":"Keep it in a Safe Pocket so a death doesn't cost it; leave via the Northern Metro entrance for a quiet exit.","zh":"放进安全口袋防止死亡丢失；从北侧地铁站撤离比较隐蔽。"}],"sources":["https://arcraiders.wiki/wiki/Buried_City_Hospital_Key","https://timesaver.gg/blog/arc-raiders-buried-city-hospital-key-location-loot","https://allthings.how/arc-raiders-buried-city-hospital-key-location-and-use/"],"version":"2.0"},"buried_city_jkv_employee_access_card":{"verdict":{"en":"A solid mid-tier key: one fourth-floor room with weapons, mods and rare materials.","zh":"中档好钥匙：四楼一间房，可能出武器、配件和稀有材料。"},"use":{"en":"It opens a locked room on the fourth floor, north side, of the J Kozma Ventures building, called the Space Travel on the map. Gameriv lists it among the keys most worth using, with weapons, weapon mods and rare materials possible. It is a single room, so loot is limited.","zh":"它打开J·科兹马创投公司大楼（地图上称航天大楼）四楼北侧的一间上锁房间。有攻略把它列入最值得用的钥匙，可能出武器、武器配件和稀有材料。只有一间房，总量有限。"},"obtain":{"en":"Scavenging only, mainly from residential containers. No quest gives it.","zh":"只能搜刮，多来自居民区容器，没有任务奖励。"},"tips":[{"en":"Fourth-floor rooms leave few escape routes, so check the stairwell before you commit.","zh":"四楼退路少，进房前先确认楼梯间安全。"}],"sources":["https://arcraiders.wiki/wiki/Buried_City_JKV_Employee_Access_Card","https://gameriv.com/arc-raiders-all-key-locations-and-what-each-key-unlocks/","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-all-keys-and-key-room-locations/"],"version":"2.0"},"buried_city_residential_master_key":{"verdict":{"en":"Opens a few apartment doors; handy if you are already in the apartments, otherwise skip.","zh":"能开几扇公寓门，人在公寓区时顺手用，否则不必专程。"},"use":{"en":"It opens several locked apartment doors in Buried City, so it is not tied to one room. Sources place one in the northern Grandioso Apartments (described as useful loot), one near Plaza Rosa by Main Street, and another south of West Village. Details are thin, and reports disagree on how good the loot is.","zh":"它能开掩埋废城的多扇公寓门，不对应单一房间。资料中提到北部奢华公寓（战利品还不错）、玫瑰广场附近的主街，以及西村以南的楼。信息很少，对收益的评价也不一。"},"obtain":{"en":"Scavenging only; drawers and shelves in residential buildings are the usual places.","zh":"只能搜刮，居民楼的抽屉和架子是常见来源。"},"tips":[{"en":"It is Uncommon and sells for 100, so using it costs little.","zh":"稀有度只有优秀，卖也只有100钱币，用了不心疼。"}],"sources":["https://arcraiders.wiki/wiki/Buried_City_Residential_Master_Key","https://gameriv.com/arc-raiders-all-key-locations-and-what-each-key-unlocks/","https://www.dexerto.com/wikis/arc-raiders/all-keys-and-what-they-open"],"version":"2.0"},"buried_city_town_hall_key":{"verdict":{"en":"The best key in Buried City: it opens the Town Hall, a loot room worth fighting for.","zh":"掩埋废城最值得的钥匙：市政厅的战利品房值得为它拼一把。"},"use":{"en":"The door is on the north side of the Town Hall, at ground level, and the room holds two Security Lockers and a Weapon Case. Guides call it one of the best key uses in the game, though a player post claims big credit hauls plus blueprints. Expect company, so loot fast and plan your exit.","zh":"门在市政厅北侧一层，房内有两个保安储物柜和一个武器箱。攻略称它是全游戏最值得的钥匙之一，玩家帖子称一趟能赚不少钱币，还可能出蓝图。多半有人来抢，速战速决并提前想好撤离路线。"},"obtain":{"en":"The quest Our Presence up There gives one. Otherwise random drops, with Security Lockers and Weapon Cases listed on the wiki; Grandioso Apartments containers are named too.","zh":"完成任务“我们在上面的据点”送一把；其余随机掉落，社区维基列出保安储物柜和武器箱，也有人提到奢华公寓的容器。"},"tips":[{"en":"Set mines or a barrier at the door before opening; rushing the lock is how people die.","zh":"开门前先在门口布地雷或设障，莽开最容易送命。"},{"en":"Don't sell it for 100 coins, and put it in a Safe Pocket.","zh":"别卖100钱币，放进安全口袋带着。"}],"sources":["https://arcraiders.wiki/wiki/Buried_City_Town_Hall_Key","https://nerdschalk.com/arc-raiders-buried-city-town-hall-key-location-and-use-guide/","https://microstudio.dev/community/off-topic/rsvsr-where-to-farm-buried-city-town-hall-key-room-loot/2453/"],"version":"2.0"},"dam_control_tower_key":{"verdict":{"en":"Opens the top of the Control Tower: strong loot on paper, but the tower is dangerous and opinions are split.","zh":"开控制塔顶部：纸面战利品强，但很危险，评价两极。"},"use":{"en":"The door is on the top floor of the Control Tower on Dam Battlegrounds. Lockers, medical bags, weapon cases and ammo cases can spawn inside. One guide ranks the loot among the map's strongest but very dangerous, another says low priority, so treat it as a gamble.","zh":"门在大坝战场控制塔顶层，房内可能刷出储物柜、医疗包、武器箱和弹药箱。一份攻略把战利品列为全图前列、但极其危险，另一份认为优先级低，算是一场赌博。"},"obtain":{"en":"The quest The Trifecta gives one. Otherwise it drops from containers in admin and residential buildings; the Buried City Hospital room has also dropped one.","zh":"完成任务“三连胜”送一把；其余在行政楼和居民楼的容器里随机掉落，掩埋废城医院的房间也曾开出过。"},"tips":[{"en":"Keep one for The Trifecta before spending others.","zh":"先留一把给“三连胜”，再考虑其他用途。"},{"en":"At 100 coins it is a poor sale, so take the gamble only if you can hold the tower.","zh":"卖只有100钱币，不划算；有把握守住控制塔再去赌。"}],"sources":["https://arcraiders.wiki/wiki/Dam_Control_Tower_Key","https://blast.tv/gaming/news/arc-raiders-keys-dam-battlegrounds-unlock-guide","https://gameriv.com/arc-raiders-all-key-locations-and-what-each-key-unlocks/"],"version":"2.0"},"dam_controlled_access_zone_key":{"verdict":{"en":"A newer Dam key with thin community info; don't count on it until you see the room yourself.","zh":"较新的大坝钥匙，社区资料很少，亲自看过再决定值不值。"},"use":{"en":"It opens a locked door in the Controlled Access Zone on Dam Battlegrounds, which one guide places at the top of the area. Nobody I found describes the loot behind it, so I can't say what it holds.","zh":"它打开大坝战场受控访问区里的一扇上锁门，有攻略称位置在该区域顶部。没找到任何关于房内战利品的描述，不能下结论。"},"obtain":{"en":"Scavenging; the wiki lists electrical panels, computers, drawers and filing cabinets as containers in the area, without saying which drop the key.","zh":"搜刮获得；社区维基列出该区的配电箱、电脑、抽屉和文件柜，但未说明哪些会出钥匙。"},"tips":[{"en":"Added in 1.17, so older key lists leave it out.","zh":"1.17版本新增，旧的钥匙清单里没有它。"}],"sources":["https://arcraiders.wiki/wiki/Dam_Controlled_Access_Zone_Key","https://www.dexerto.com/wikis/arc-raiders/all-keys-and-what-they-open"],"version":"2.0"},"dam_staff_room_key":{"verdict":{"en":"Decent loot, but the building is crowded; fine for The Stench of Corruption, optional otherwise.","zh":"战利品尚可但人多；做“腐败的恶臭”时需要，其余看心情。"},"use":{"en":"The door is on the first floor of the Research & Administration building. From the west entrance it is almost straight ahead; from the south entrance it is on your right. Several red lockers can drop high-rarity gear. Guides split between decent and not worth the risk. Close the door behind you.","zh":"门在研究与行政区大楼一层。从西入口进几乎正对面，从南入口进则在右手边。房内有数个红色储物柜，可能出高稀有度装备。攻略评价不一，有说不错的，也有说不值得冒险的。进房后记得关门。"},"obtain":{"en":"The quest The Stench of Corruption gives one. Otherwise random drops from containers, especially in the Research & Administration itself.","zh":"完成任务“腐败的恶臭”送一把；其余在容器中随机掉落，尤其是研究与行政区本身。"},"tips":[{"en":"Raiders rush in when they hear the door unlock, so open it only after clearing the hall.","zh":"开锁声会引来其他人，先清场再开门。"}],"sources":["https://arcraiders.wiki/wiki/Dam_Staff_Room_Key","https://players.com.ua/en/news/dam-staff-room-key-in-arc-raiders/","https://blast.tv/gaming/news/arc-raiders-keys-dam-battlegrounds-unlock-guide"],"version":"2.0"},"dam_surveillance_key":{"verdict":{"en":"A quick, safe-ish early key: standard loot in a small room, and a quest needs two.","zh":"早期快速又相对安全的钥匙：小房间普通战利品，任务要两把。"},"use":{"en":"The door is on the first floor, south side, of the Water Treatment Control buildings on Dam Battlegrounds. Guides call the loot standard but inconsistent, good for quick scavenging runs, especially early in the game. It won't change your economy.","zh":"门在大坝战场水处理控制中心建筑一层南侧。攻略称战利品普通且不稳定，适合快速搜刮，尤其是前期。不会改变你的经济。"},"obtain":{"en":"The quest Greasing Her Palms gives two. Otherwise random drops in Ruby Residence and Research & Administration containers.","zh":"完成任务“打通通路”送两把；其余在红宝石宅邸和研究与行政区的容器里随机掉落。"},"tips":[{"en":"Hold what Greasing Her Palms asks for before opening any on your own.","zh":"先留够“打通通路”要的数量，再用多余的。"}],"sources":["https://arcraiders.wiki/wiki/Dam_Surveillance_Key","https://blast.tv/gaming/news/arc-raiders-keys-dam-battlegrounds-unlock-guide","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-all-keys-and-key-room-locations/"],"version":"2.0"},"dam_testing_annex_key":{"verdict":{"en":"Worth a quick stop if you're nearby, but one key opens only one of the two doors.","zh":"就在附近时值得顺路开，但一把钥匙只能开两扇门中的一扇。"},"use":{"en":"The Testing Annex has two locked doors on the ground floor, one on the south side and one on the east. One key opens one door, so you need two for both. Guides call the loot mid-tier, sometimes rated lower-end.","zh":"测试附楼一层有两扇上锁的门，一扇在南侧，一扇在东侧。一把钥匙只能开其中一扇，两扇都开需要两把。攻略评价为中档战利品，有时被排在偏下。"},"obtain":{"en":"The quest A Lay of the Land gives one. Otherwise lockers, drawers and filing cabinets in admin buildings.","zh":"完成任务“地形勘查”送一把；其余在行政楼的储物柜、抽屉和文件柜里随机掉落。"},"tips":[{"en":"If you carry only one, pick the door that is easier to reach and ignore the other.","zh":"只有一把时选更好到达的那扇门，别纠结另一扇。"}],"sources":["https://arcraiders.wiki/wiki/Dam_Testing_Annex_Key","https://blast.tv/gaming/news/arc-raiders-keys-dam-battlegrounds-unlock-guide","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-all-keys-and-key-room-locations/"],"version":"2.0"},"emperor_gateway_conduit":{"verdict":{"en":"A one-use pass into the Fallen Emperor at Pendola Pass, which guides call the map's best loot spot.","zh":"进入彭多拉山口“陨落帝王”的一次性通行证，攻略称是该图最好的战利品点。"},"use":{"en":"Take it to the entrance at the base of the Fallen Emperor on Pendola Pass and use it there. Guides say the interior holds rare blueprints and loot pods that can drop the Emperor Modulator. One guide notes the interior was locked early on, so some details are unconfirmed.","zh":"带到彭多拉山口陨落帝王底部的入口使用。攻略称内部有稀有蓝图，战利品舱可能掉落“帝王”调制器。有攻略提到内部早期上锁，部分细节尚未证实。"},"obtain":{"en":"Craft it at the Workbench once you learn its blueprint, using the three couplers. Blueprint and couplers drop from Harvester payloads and Bully ARC during Redirection. Alternatively it is the last reward of the Frozen Trail Reward Pass.","zh":"学会蓝图后在工作台制作，需要三种耦合器。蓝图和耦合器出自“航向重定向”事件中的收割者空投和恶霸ARC；也可作为霜痕小径奖励通行证的最后一项奖励。"},"tips":[{"en":"Blueprint chances are low, so expect several Redirection raids. Don't sell it for 1000.","zh":"蓝图掉率低，要做好跑多局“航向重定向”的准备；别卖那1000钱币。"},{"en":"Reward Pass level 60 is the guaranteed route if you play the pass anyway.","zh":"如果本来就在刷通行证，60级是最稳的方式。"}],"sources":["https://arcraiders.wiki/wiki/Emperor_Gateway_Conduit","https://beebom.com/how-to-get-emperor-gateway-conduit-key-in-arc-raiders/","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-the-emperor-gateway-conduit-key/"],"version":"2.0"},"expired_security_code":{"verdict":{"en":"Pure junk: a spent Locked Gate code that opens nothing. Sell it for 10 coins.","zh":"纯废品：用过的上锁大门安全码，什么也打不开，卖掉换10钱币。"},"obtain":{"en":"You don't find it. Bringing a used Locked Gate security key to Speranza turns it into this item, so it only shows up if you hoard old codes.","zh":"无法在局内捡到。把用过的上锁大门安全码交给斯佩兰扎就会变成它，所以只有囤旧码时才会出现。"},"tips":[{"en":"Nothing in the workshop or quests asks for it, so free the inventory slot (it doesn't stack).","zh":"工作台和任务都不需要它，而且不能堆叠，直接清掉省格子。"}],"sources":["https://arcraiders.wiki/wiki/Expired_Security_Code","https://www.dexerto.com/wikis/arc-raiders/locked-gate-event/"],"version":"2.0"},"hidden_bunker_key":{"verdict":{"en":"Don't plan around it: current guides open the Spaceport bunker with antennas, not a key, so treat this as a 100-coin sale item.","zh":"别指望它：现有攻略里太空港地堡靠天线开启而非钥匙，当作100钱币的卖品即可。"},"use":{"en":"The item says it opens a bunker on The Spaceport. Every guide I found describes the Hidden Bunker map condition instead: you activate four antennas, then the entrances just west of the Departure Building open for the whole lobby. Inside are eight data terminals worth 500 XP each, but no guide lists a loot table, and the key's own door is unconfirmed.","zh":"物品说明称它能打开太空港的一处地堡。但我查到的攻略都说隐藏地堡是地图条件：激活四座天线后，候机楼西侧的入口对全场开放；里面有8个数据终端，每个给500经验。没有攻略列出具体战利品，这把钥匙对应的门也无法证实。"},"obtain":{"en":"No source says where it drops. The bunker is only available while the Hidden Bunker condition is active, and raids last 40 minutes then.","zh":"没有资料说明它的掉落来源。地堡只在“隐藏地堡”地图条件生效时出现，此时每局40分钟。"},"tips":[{"en":"If you do get one, keep it only if you want to test the door yourself; the bunker's XP terminals work without it.","zh":"如果捡到，除非想亲自试门，否则直接卖；地堡的经验终端不需要它。"},{"en":"Antennas alert the whole lobby and bring ARC (Bastions and a Bombardier guard the entrances), so expect company.","zh":"激活天线会惊动全场并引来ARC，入口还有堡垒和投弹手守着，做好遇敌准备。"}],"sources":["https://arcraiders.wiki/wiki/Hidden_Bunker","https://insider-gaming.com/hidden-bunker-arc-raiders-how-to-open-guide/","https://www.dexerto.com/wikis/arc-raiders/spaceport-hidden-bunker-arc-raiders"],"version":"2.0"},"patrol_car_key":{"verdict":{"en":"A decent one-off gamble for a blue weapon and ammo, not worth a risky trip; the car is hard to find and the key sells for 100.","zh":"一次性的小赌注，能换一把蓝色武器和弹药，但车不好找，不值得冒险专程跑。"},"use":{"en":"The key opens the rear door of an armored patrol car. Guides put those cars in the underground highway of the Blue Gate (reached by stairs and a zipline from the Headhouse), with several possible spawn spots and ARC around. Reported loot is mid-tier: usually one blue rifle or SMG plus ammo, sometimes attachments or materials. The key is consumed.","zh":"钥匙用来打开装甲巡逻车的后门。攻略把这些车放在蓝门的地下高速隧道（从候车室走楼梯、坐滑索下去），刷新点不固定，周围有ARC。战利品中等：通常一把蓝色步枪或冲锋枪加弹药，偶尔有配件或材料。钥匙用完即消耗。"},"obtain":{"en":"The quest A Prime Specimen rewards one. Otherwise it is a random find; guides name the Ruby Residence and Research & Administration areas on the Dam, plus Checkpoint guardhouses. The wiki also lists Riven Tides for the car.","zh":"任务“完美样本”奖励一把。其余靠随机搜到，攻略提到大坝的红宝石宅邸、研究与行政区和检查站岗亭。社区维基也把裂潮镇列为巡逻车所在地。"},"tips":[{"en":"Put it in your Safe Pocket right away; dying with it loses the whole trip.","zh":"拿到后马上放进安全口袋，带着它死掉整趟就白跑。"},{"en":"The car's position changes each raid and is not marked, so only go if you are already heading underground.","zh":"车的位置每局不同且地图不标，顺路下地下时再去。"}],"sources":["https://arcraiders.wiki/wiki/Patrol_Car_Key","https://nerdschalk.com/arc-raiders-patrol-car-key-location-and-use-guide/","https://www.destructoid.com/patrol-car-key-location-in-arc-raiders/"],"version":"2.0"},"pendola_pass_observatory_key":{"verdict":{"en":"Worth using if you have it: the Observatory key room is one of Pendola Pass's better stash rooms, and the key only sells for 100.","zh":"拿到就值得用：晴空天文台的钥匙房是彭多拉山口较好的藏货点，而钥匙只值100钱币。"},"use":{"en":"It opens a door in the Cielo Sereno Observatory main building, on the northeast edge of the map. Per one guide's route: go up the stairs between the two buildings at the top, enter, turn right, then left, then right, and follow the path to the corner. Early notes describe many cabinets and containers (blueprints, gear, keys). Those notes predate release, so don't count on specific drops.","zh":"它打开彭多拉山口东北角晴空天文台主楼里的一扇门。按某攻略的路线：走上两栋楼之间的台阶进门，右转、左转、再右转，沿路走到拐角尽头。早期测试记录提到房内有很多柜子和容器（蓝图、装备、钥匙），但那是公测前的信息，别指望具体掉落。"},"obtain":{"en":"The quest Belly of the Beast rewards one. No source gives a reliable random-drop spot.","zh":"任务“兽腹深处”奖励一把。随机掉落点目前没有可靠资料。"},"tips":[{"en":"Don't go during the ARC Frigate condition: every locked door is already open then and loot value is lower, so the key would be wasted.","zh":"ARC护卫者条件下别去：此时所有锁门已经开着，战利品价值也偏低，钥匙会浪费。"},{"en":"The Observatory has a Bastion near its power console; avoid it unless you want a fight.","zh":"天文台电源控制台附近有堡垒，不想硬打就绕开。"}],"sources":["https://www.mmoexp.com/News/arc-raiders-pendola-pass-map-guide-flash-freeze-gondola-extraction-and-key-looting-zones.html","https://quoramarketing.com/all-pendola-pass-key-door-locations-in-arc-raiders/","https://games.gg/arc-raiders/guides/arc-raiders-pendola-pass-map-guide/"],"version":"2.0"},"pendola_pass_old_town_key":{"verdict":{"en":"A cheap apartment key worth using on a normal Old Town pass, but it's not worth a dedicated trip.","zh":"便宜的公寓钥匙，路过老城区顺手用就行，不值得专程跑。"},"use":{"en":"It opens a locked apartment door in the Old Town. One guide places it inside Hotel Pensione: enter through the blown-out gap in the southwest wall and the door is on your left. Another route reaches it from the upper floor through a window. The same guide says the downstairs part holds the better loot. No source lists exact contents.","zh":"它能打开老城区一间上锁的公寓。一份攻略说在彭西奥内酒店里：从西南墙的破洞进去，门在左手边；另一条路线是从二楼窗户进入。该攻略称楼下的战利品更好。没有资料列出具体物品。"},"obtain":{"en":"No source documents a drop spot. Keys in this game are random container finds, and residential buildings are the usual place to search.","zh":"没有资料记载掉落点。游戏里的钥匙都是容器随机刷出，住宅类建筑最常搜到。"},"tips":[{"en":"Skip it during the ARC Frigate condition, when all locked doors are open anyway.","zh":"ARC护卫者条件下别用，此时所有锁门本来就是开的。"},{"en":"Sale value is 100; if you won't be in Old Town soon, selling is fine.","zh":"售价100钱币；短期不去老城区的话卖掉也无妨。"}],"sources":["https://quoramarketing.com/all-pendola-pass-key-door-locations-in-arc-raiders/","https://allthings.how/arc-raiders/map/loot-residential/","https://gameshorizon.com/?p=78483"],"version":"2.0"},"pendola_pass_railyard_key":{"verdict":{"en":"Use it: the Railyard key room is a single small room reported to be packed with loot, and the door is easy to find.","zh":"值得用：铁路站场的钥匙房只有一个小房间，据说堆满战利品，门也很好找。"},"use":{"en":"It opens a door in the Controlled Receiving Facility at the Railyard. Enter by the east side door, climb the stairs to the second floor, and the door sits beside the stairs behind a pillar. If you have the key, one guide suggests going there first, then searching the Railyard's many containers and wall lockers on the way out.","zh":"它打开铁路场受控接收设施里的一扇门。从东侧门进入，上楼到二层，门就在楼梯旁的柱子后面。有钥匙的话，有攻略建议先来这里，再顺路搜铁路场的大量容器和墙柜。"},"obtain":{"en":"No source documents where the key drops. Treat it as a random find in Pendola Pass containers.","zh":"没有资料说明钥匙掉在哪，当作彭多拉山口容器里的随机物品即可。"},"tips":[{"en":"Not worth carrying into an ARC Frigate raid, where the door is already open.","zh":"ARC护卫者条件下不用带，门本来就是开的。"},{"en":"Rare rarity but the same 100 coin sale price as common keys, so using it beats selling it.","zh":"稀有度是稀有，但售价和普通钥匙一样只有100钱币，用掉比卖掉划算。"}],"sources":["https://quoramarketing.com/all-pendola-pass-key-door-locations-in-arc-raiders/","https://www.mmoexp.com/News/arc-raiders-pendola-pass-map-guide-flash-freeze-gondola-extraction-and-key-looting-zones.html","https://allthings.how/arc-raiders/map/loot-residential/"],"version":"2.0"},"pendola_pass_train_station_key":{"verdict":{"en":"Probably worth a stop if you pass Almatera Station, but loot reports are thin, so don't build a run around it.","zh":"路过阿尔玛特拉站时可以用，但战利品情报很少，别围着它安排整局。"},"use":{"en":"It opens the Train Station Room at Almatera Station, on the west side: go in through the main door and turn left at once. One guide lists a Leviathan ship-model trinket as the best-supported find, though it is unconfirmed. The station's general loot leans commercial, so expect sellable trinkets more than gear.","zh":"它打开阿尔玛特拉站的火车站房间，位于西侧：从正门进入后立刻左转。有攻略把“利维坦”船模饰品列为最可能的产出，但未证实。车站整体战利品偏商业类，更像是能卖钱的饰品，而不是装备。"},"obtain":{"en":"No source gives a spawn location for the key, so it is a random find.","zh":"没有资料给出钥匙的刷新位置，只能当作随机物品。"},"tips":[{"en":"The sale price is only 100, so the key is only worth keeping if you actually plan to visit the station.","zh":"售价只有100，只有真打算去车站时才值得留着。"}],"sources":["https://quoramarketing.com/all-pendola-pass-key-door-locations-in-arc-raiders/","https://games.gg/arc-raiders/guides/arc-raiders-pendola-pass-map-guide/"],"version":"2.0"},"pilgrims_peak_security_code":{"verdict":{"en":"Only matters during the Blue Gate Locked Gate event; otherwise it's a 100-coin throwaway.","zh":"只在蓝门的“上锁的大门”事件中有用，平时就是100钱币的杂物。"},"use":{"en":"One of four codes needed to open the main gate in the Checkpoint area. Take all four to the Gate Control Room and enter them at its terminals. The gate then opens, and guides say it leads to plenty of valuable loot. During the event Raider Hatches and underground tunnels are blocked and the raid is 40 minutes, so expect contested fights.","zh":"打开检查站主门所需的四个安全码之一。把四个码带到蓝门控制室的终端输入，大门就会开启，攻略称里面有不少高价值战利品。事件期间奇袭者暗门和地下隧道不可用，每局40分钟，对抗激烈。"},"obtain":{"en":"Search containers in Pilgrim's Peak on the Blue Gate; two Rocketeers guard it. The codes appear only while the Locked Gate event is active, and you can collect them across raids by extracting.","zh":"在蓝门的朝圣峰搜容器，那里有两名火箭手守着。安全码只在事件期间出现，可以分几局带出来凑齐。"},"tips":[{"en":"If you extract or use a Safe Pocket you needn't find all four codes in one raid.","zh":"成功撤离或放进安全口袋的话，不必在一局里集齐四个码。"}],"sources":["https://metaforge.app/arc-raiders/database/item/pilgrims-peak-security-code","https://www.destructoid.com/how-to-complete-locked-gate-event-in-arc-raiders/","https://www.dexerto.com/wikis/arc-raiders/locked-gate-event/"],"version":"2.0"},"raider_hatch_key":{"verdict":{"en":"An insurance exit: craft it, keep one in your Safe Pocket, and spend it only on loot worth more than the key.","zh":"保险用的撤离钥匙：自己制作，安全口袋里留一把，只在战利品比钥匙值钱时才用。"},"use":{"en":"It opens any Raider Hatch, a quiet exit with no alarm that avoids crowded extraction points. It is single-use. Guides advise not burning one on a cheap run, and saving it for a bad exfil situation or a quest that needs a hatch. Hatches are disabled during Night Raids and the Locked Gate event.","zh":"它能打开任何奇袭者暗门，是不拉警报、避开拥挤撤离点的安静出口，一次性消耗。攻略建议别在低价值的局里浪费，留给撤离点被堵的情况或需要暗门的任务。夜间奇袭和上锁的大门事件中暗门不可用。"},"obtain":{"en":"Craft it in-raid or at Utility Station level 2 from Advanced Electrical Components and Sensors, far cheaper than Shani's 9,000-coin offer (limit 2). Six quests (Hatch Repairs, Cold Storage, The Trifecta, Mixed Signals, Our Presence up There, Paving the Way) also reward one.","zh":"在局内或2级工具工作台用高级电子元件和传感器制作，比萨尼9000钱币（限购2把）划算得多。暗门维修、冷冻储藏、三连胜、混合信号、我们在上面的据点、开辟道路六个任务也会奖励一把。"},"tips":[{"en":"Extra crafted keys are worth selling: the materials cost far less than the 2,000-coin sale price.","zh":"多做的钥匙可以卖，材料成本远低于2000钱币的售价。"},{"en":"Plan the exit early instead of waiting for the last exfil.","zh":"撤离路线要提前规划，别等到最后一个撤离点。"}],"sources":["https://arcraiders.wiki/wiki/Raider_Hatch_Key","https://www.pcgamesn.com/arc-raiders/hatch-key","https://nerdschalk.com/how-to-get-raider-hatch-keys-in-arc-raiders/"],"version":"2.0"},"raiders_refuge_security_code":{"verdict":{"en":"One of four Locked Gate event codes on the Blue Gate; useful only during that event, otherwise worth 100 coins.","zh":"蓝门“上锁的大门”事件四个安全码之一，只在事件期间有用，否则值100钱币。"},"use":{"en":"Enter it with the other three at the terminals in the Gate Control Room, which sits in the Warehouse Complex between the central and northern Blue Gate. When all four are in, the main gate in the Checkpoint area opens to valuable loot.","zh":"和其他三个码一起输入蓝门控制室的终端，控制室在蓝门中北部的仓储综合区。四个码齐了，检查站的主门就会开启，里面有高价值战利品。"},"obtain":{"en":"Loot containers in Raider's Refuge on the Blue Gate, only while the Locked Gate event is active. Guides say the four codes always spawn in the same four areas, but descriptions of this one vary.","zh":"事件期间在蓝门的奇袭者避难所搜容器。攻略称四个码固定刷在四个区域，但各攻略对这里的描述不一。"},"tips":[{"en":"Each code can be carried out over several raids if you extract, so collect and bank them.","zh":"成功撤离就能分多局把码带出来，先存着。"}],"sources":["https://www.dexerto.com/wikis/arc-raiders/locked-gate-event/","https://deltiasgaming.com/?p=399960"],"version":"2.0"},"reinforced_reception_security_code":{"verdict":{"en":"A Locked Gate event code: worth picking up if you are doing that event, otherwise a 100-coin sale.","zh":"“上锁的大门”事件用码：做事件时顺手拿，否则卖100钱币。"},"use":{"en":"It is one of the four codes entered at the Gate Control Room terminals on the Blue Gate. Entering all four opens the central gate at the Checkpoint. The event removes the tunnels and Raider Hatches, and the raid runs 40 minutes.","zh":"在蓝门控制室终端输入的四个码之一，四个码输入完成后检查站的中央大门开启。该事件会移除地下隧道和奇袭者暗门，每局40分钟。"},"obtain":{"en":"Search containers in Reinforced Reception on the Blue Gate during the event. Exact container spots are not documented; expect to sweep the whole area.","zh":"事件期间在蓝门的加固前台搜容器。没有资料写明具体容器，需要花时间把整个区域搜一遍。"},"tips":[{"en":"The event isn't always on the map rotation, so don't hold the code waiting for it indefinitely.","zh":"事件并非一直在地图轮换里，别无限期囤着等。"}],"sources":["https://www.destructoid.com/how-to-complete-locked-gate-event-in-arc-raiders/","https://metaforge.app/arc-raiders/locked-gate-arc-raiders-event-guide"],"version":"2.0"},"riven_tides_classified_records_keycard":{"verdict":{"en":"A high-risk, high-reward room: the key is worth using if you can survive the Port Authority Building.","zh":"高风险高回报：能在港务局大楼活下来的话，这张卡值得用。"},"use":{"en":"It opens the Classified Records room on the upper floor of the Port Authority Building in the north of Riven Tides. Follow the stairs to the second floor and turn right; two doors close together lead into the same room. Reported loot is high-tier containers and tech parts. The area has turrets, cameras and Shredders, and is busy with other raiders.","zh":"它打开裂潮镇北部港务局大楼二层的机密档案室。上楼到二层右转，两扇相邻的门通往同一个房间。据报道里面有高级容器和科技类材料。这里有炮塔、摄像头和粉碎者，其他玩家也很多。"},"obtain":{"en":"Random card from containers or enemies on Riven Tides. The room is fixed, but the card is not. Loot details come partly from seller sites, so treat them loosely.","zh":"在裂潮镇从容器或敌人身上随机获得。房间位置固定，但卡不固定。部分战利品说明来自卖号网站，请当参考。"},"tips":[{"en":"Bring a second keycard if you have one; both Port Authority rooms are near each other.","zh":"如果有第二张卡一起带，港务局的两个房间离得很近。"},{"en":"Others may have already cleared the room before you arrive.","zh":"别人可能在你到之前已经搜空了房间。"}],"sources":["https://www.destructoid.com/riven-tides-classfied-records-keycard-location-in-arc-raiders/","https://nerdschalk.com/arc-raiders-how-to-find-classified-records-keycard-room-exact-location-on-riven-tides/","https://rutab.net/b/games/2026/05/12/arc-raiders-gde-nayti-klyuch-kartu-riven-tides-classified-records-i-chto-vnutri.html"],"version":"2.0"},"riven_tides_crane_house_keycard":{"verdict":{"en":"Decent grenade-and-weapon room, but it is a PvP hotspot with a single exit, so go ready for a fight.","zh":"能出手雷和武器的不错房间，但是PvP热点且只有一个出口，要做好战斗准备。"},"use":{"en":"It opens a door in one of the Crane Houses on Riven Tides' industrial waterfront. One guide says to enter from the side facing the cranes and go upstairs; there are two doors and it doesn't say which one is the key door. Rough loot odds: grenades and mines high, weapons medium, rare materials medium, a security locker low.","zh":"它打开裂潮镇工业码头某座起重机控制室的门。一份攻略说从面向起重机的一侧进入并上楼；有两扇门，没写明哪一扇是钥匙门。大致概率：手雷和地雷高，武器和稀有材料中等，保险柜低。"},"obtain":{"en":"A random drop from containers or enemies on Riven Tides, and occasionally on Buried City.","zh":"在裂潮镇从容器或敌人身上随机获得，掩埋废城偶尔也能拿到。"},"tips":[{"en":"Place mines at the entrance; the single exit can be camped, so bring a backup route or teammate.","zh":"在入口放地雷；唯一的出口容易被蹲，最好带队友或备用路线。"},{"en":"Sources disagree on the exact crane house, so confirm the door in-game.","zh":"各攻略对具体是哪座起重机控制室有分歧，进游戏后自己确认。"}],"sources":["https://nerdschalk.com/arc-raiders-riven-tides-crane-house-keycard-room-location-and-loot-guide/","https://metaforge.app/arc-raiders/database/item/riven-tides-crane-house-keycard"],"version":"2.0"},"riven_tides_hotel_keycard_no_102":{"verdict":{"en":"A cheap suite key at the Panorama Azzurro hotel; use it if you are there, but loot reports are unverified.","zh":"蔚蓝全景酒店的廉价套房钥匙，在酒店附近可以用，但战利品情报没有核实。"},"use":{"en":"It opens suite 102 in the Hotel Panorama Azzurro. One service blog places the room on the west side of the hotel via a first-floor window, but its author did not have the key, so the route is unverified. No source I could open itemizes what the room holds.","zh":"它打开蔚蓝全景酒店的102号套房。一个代练博客把房间放在酒店西侧，从一层窗户进入，但作者自己没有钥匙，路线未经验证。我能打开的资料都没有列出房内物品。"},"obtain":{"en":"Found by looting on Riven Tides; no guaranteed source.","zh":"在裂潮镇搜刮获得，没有固定来源。"},"tips":[{"en":"Pair it with another hotel card to make a hotel run worthwhile.","zh":"和其他酒店房卡一起用，才值得跑一趟酒店。"}],"sources":["https://metaforge.app/arc-raiders/database/item/riven-tides-hotel-keycard-no-102","https://hub.tcno.co/videos/all-keys-in-riven-tides-location-guide-arc-raiders/"],"version":"2.0"},"riven_tides_hotel_keycard_no_107":{"verdict":{"en":"Use it: room 107 has decent loot plus a safe that can hand you a Room 208 keycard.","zh":"值得用：107号房有不错的战利品，保险箱还能给你一张208号房卡。"},"use":{"en":"The hotel is on the west side of Riven Tides. Room 107 is on the first floor, central corridor (take the lobby zipline or stairs; look for the red number over the door). It has suitcases, drawers and cabinets; high-tier weapons like Il Toro shotguns and Osprey rifles were seen. Check under the bed: the first visit's safe holds the No. 208 card, later visits usually random items.","zh":"酒店在裂潮镇西侧。107号房在二楼（即大堂上一层）的中央走廊，坐大堂滑索或走楼梯，门上方有红色房号。房里有行李箱、抽屉和柜子，见过高阶“公牛”霰弹枪和“鱼鹰”狙击枪。床下有保险箱：首次通常给208号房卡，之后多是随机物品。"},"obtain":{"en":"The quest Battening Down rewards a card. It can also drop from residential looting on Riven Tides.","zh":"任务“加固防御”奖励一张，也可能在裂潮镇住宅区搜到。"},"tips":[{"en":"After room 107, go up the stairs to room 208 for a chained run.","zh":"搜完107后上楼去208，可以连着做。"},{"en":"Hallways are tight, so bring a close-range weapon.","zh":"走廊狭窄，带近战距离武器。"}],"sources":["https://www.fdaytalk.com/riven-tides-hotel-keycard-no-107/","https://www.dexerto.com/wikis/arc-raiders/items/key/riven-tides-hotel-keycard-no-107/"],"version":"2.0"},"riven_tides_hotel_keycard_no_113":{"verdict":{"en":"A low-stakes suite key: fine if you already hold it, not worth a trip.","zh":"低风险的套房钥匙：手上有就用，不值得专程去。"},"use":{"en":"The door is in the east wing on the first floor of Hotel Panorama Azzurro, so it is the easiest suite to reach. Guides don't list its loot and the community wiki page is a stub, so expect a modest room, not a jackpot.","zh":"房门在蔚蓝全景酒店东翼一楼，是最容易到达的套房。目前没有攻略列出房内战利品，社区维基页面也只是草稿，别指望有大收获。"},"obtain":{"en":"It turns up as a random drop from residential drawers, desks and lockers, or from downed players. Nobody has confirmed a fixed spawn.","zh":"随机掉落，常见于住宅抽屉、办公桌和储物柜，也可能从被击倒的玩家身上获得，目前没有确认的固定刷新点。"},"tips":[{"en":"Sells for 100 coins, so using it on a door you pass anyway beats selling it.","zh":"卖价只有100钱币，顺路有门就用掉，比卖掉划算。"},{"en":"One guide says keys are consumed on use and lost if you die, so don't carry it into a risky fight for a small room.","zh":"有攻略称钥匙用一次就消耗，死亡会丢失，为一间小房间冒险带进高风险战斗不值得。"}],"sources":["https://arcraiders.wiki/wiki/Riven_Tides_Hotel_Keycard_No._113","https://skycoach.gg/blog/arc-raiders/articles/riven-tides-map-guide","https://www.neonlightsmedia.com/blog/arc-raiders-hotel-keycards-locations"],"version":"2.0"},"riven_tides_hotel_keycard_no_205":{"verdict":{"en":"One of the better hotel suites: worth opening when you are already inside the hotel.","zh":"酒店里较值得开的套房之一，人已经在酒店里时再开。"},"use":{"en":"Room 205 is on the second floor, central area of Hotel Panorama Azzurro; a stairs or zipline gets you up. One community guide says it holds weapons, medical items, chemicals and attachments, but that guide's details are unverified. Another guide wants a turret cleared first, and the hotel is a heavily contested PvP zone.","zh":"205号房在蔚蓝全景酒店二楼中部，可走楼梯或滑索上去。有社区攻略称房内有武器、医疗品、化学品和配件，但这些说法未经证实。另一篇攻略建议先清掉一座炮塔，而且酒店本身PvP激烈。"},"obtain":{"en":"Random container drop; community guides name bedside tables, closets and bars, but none is confirmed. ","zh":"随机容器掉落。社区攻略提到床头柜、清洁间和酒吧等地点，但都未经证实。"},"tips":[{"en":"Sell value is only 100 coins, so the room is the whole point: use it or leave it.","zh":"卖价只有100钱币，价值全在房间里：要么用掉，要么留着。"}],"sources":["https://arcraiders.wiki/wiki/Riven_Tides_Hotel_Keycard_No._205","https://nerdschalk.com/arc-raiders-riven-tides-hotel-keycard-no-205-exact-location-and-loot-guide/","https://www.neonlightsmedia.com/blog/arc-raiders-hotel-keycards-locations"],"version":"2.0"},"riven_tides_hotel_keycard_no_208":{"verdict":{"en":"Worth using: Room 208 is billed as the biggest suite on the floor.","zh":"值得用：208号房被称为该层最大的套房。"},"use":{"en":"Room 208 sits on the second floor of Hotel Panorama Azzurro, at the end of the corridor past 204-207, though guides disagree on whether it is east wing or central. One guide lists SMG and sniper blueprints, armor kits and high-grade components, but that list is unconfirmed. Expect PvP in the hotel.","zh":"208号房在蔚蓝全景酒店二楼，走廊尽头、204至207号房之后，但各攻略对在东翼还是中部说法不一。有攻略列出冲锋枪和狙击枪蓝图、护甲套件及高级部件，未经证实。酒店内PvP频繁。"},"obtain":{"en":"Community reports say Room 107 has the 208 card in an under-bed safe, but this is unverified; other guides say it's a random container drop.","zh":"社区传言107号房床下保险箱有208号房卡，但未经证实；其他攻略说是随机容器掉落。"},"tips":[{"en":"If the 107 to 208 chain is real, it is the best use of this card; confirm in a raid before planning around it.","zh":"若107到208的连锁属实，这就是它的最佳用法；先在实战中确认再安排行程。"}],"sources":["https://arcraiders.wiki/wiki/Riven_Tides_Hotel_Keycard_No._208","https://nerdschalk.com/arc-raiders-riven-tides-exact-location-of-hotel-door-208-in-azzurro-hotel-with-hotel-keycard-no-208/","https://有攻略/blog/arc-raiders-riven-tides-keycards","https://skycoach.gg/blog/arc-raiders/articles/riven-tides-map-guide"],"version":"2.0"},"riven_tides_hotel_keycard_no_311":{"verdict":{"en":"Reasonable suite key, best paired with the 404 room on the same run.","zh":"不错的套房钥匙，最好和404号房同一趟一起开。"},"use":{"en":"Several guides put Room 311 on the third floor of the hotel's east side, behind the east tower stairwell rather than the main entrance. Loot is not documented; one unreliable guide mentions a pull-style chest. One guide treats 311 and 404 as a pair with a rooftop extract.","zh":"多篇攻略把311号房放在酒店东侧三楼，要走东塔楼梯而非正门。房内战利品没有可靠记录，有篇可信度一般的攻略提到拉杆式箱子。有攻略把311和404当作一组，可从屋顶撤离。"},"obtain":{"en":"Sources conflict on how it drops; looting the hotel is the usual route. Check what the hotel's containers give on your own runs.","zh":"来源对获取方式说法不一，通常靠搜刮酒店获得。实际以你自己搜刮酒店的结果为准。"},"tips":[{"en":"It is a common 100 coin key, so only carry it if you plan to open Room 311.","zh":"只是100钱币的普通钥匙，打算开311号房时再带。"}],"sources":["https://arcraiders.wiki/wiki/Riven_Tides_Hotel_Keycard_No._311","https://nerdschalk.com/arc-raiders-riven-tides-exact-location-of-hotel-room-311-and-hotel-keycard-no-311/","https://hub.tcno.co/videos/hotel-keycard-no-311-loot-guide-arc-raiders-keys-riven-tides/","https://www.neonlightsmedia.com/blog/arc-raiders-hotel-keycards-locations","https://有攻略/blog/arc-raiders-riven-tides-keycards"],"version":"2.0"},"riven_tides_hotel_keycard_no_404":{"verdict":{"en":"Top-floor suite key with almost no loot info: use it if the route is safe, don't plan around it.","zh":"顶层套房钥匙，几乎没有战利品信息：路线安全就用，别专门规划。"},"use":{"en":"Two guides put Room 404 on the fourth floor at the hotel's west end, reached via the rooftop or a zipline; another instead links it to the 311 room. No guide documents the loot, and the community wiki page is a stub.","zh":"两篇攻略把404号房放在酒店最西侧四楼，可经屋顶或滑索到达；另有攻略则把它与311号房联系起来。没有攻略记录房内战利品，社区维基页面也是草稿。"},"obtain":{"en":"One source says it is found by looting; the community wiki lists the source as unknown. No confirmed spawn spot.","zh":"有来源称靠搜刮获得，社区维基标注来源未知，没有确认的刷新点。"},"tips":[{"en":"Keys sell for 100 coins, so only keep it if you plan to open the door this raid.","zh":"钥匙只卖100钱币，本局打算开门才值得留。"}],"sources":["https://arcraiders.wiki/wiki/Riven_Tides_Hotel_Keycard_No._404","https://www.dexerto.com/wikis/arc-raiders/items/key/riven-tides-hotel-keycard-no-404/","https://有攻略/blog/arc-raiders-riven-tides-keycards","https://www.neonlightsmedia.com/blog/arc-raiders-hotel-keycards-locations"],"version":"2.0"},"riven_tides_secure_storage_keycard":{"verdict":{"en":"The most valuable Riven Tides card: an Epic key to the Port Authority's inner storage room.","zh":"裂潮镇最值钱的一张卡：港务局内部储藏室的史诗钥匙。"},"use":{"en":"It opens the Secure Storage room in the Port Authority Building, in the north of the map. Guides disagree on the route: one says the room is inside the Classified Records room on the top floor, another says it shares that corridor and its turret. Loot is not documented, but guides call it high tier and less contested than the hotel.","zh":"它开启港务局大楼里的安全储藏室，位于地图北部。路线说法不一：有攻略称它在顶层机密档案室内，也有称与机密档案室共用走廊和炮塔。房内战利品没有记录，但攻略称其为高档位，且比酒店人少。"},"obtain":{"en":"A random container drop, mostly from breachable containers; it is reported on several maps, not only Riven Tides.","zh":"随机容器掉落，多来自可破拆容器，据报其他地图上也能找到，不限于裂潮镇。"},"tips":[{"en":"Bring it in a Safe Pocket; a keycard is lost if you die.","zh":"放进安全口袋带入，死亡会丢卡。"}],"sources":["https://arcraiders.wiki/wiki/Riven_Tides_Secure_Storage_Keycard","https://有攻略/blog/arc-raiders-riven-tides-keycards","https://skycoach.gg/blog/arc-raiders/articles/riven-tides-map-guide"],"version":"2.0"},"seed_vault_box_key":{"verdict":{"en":"A quest key: only matters for the Last Entry quest, otherwise a 100-coin item.","zh":"任务钥匙：只对“最后条目”任务有用，否则只值100钱币。"},"use":{"en":"It opens the seed deposit box in the Seed Vault on Stella Montis. The Last Entry quest from Shani has you find the hidden key in the room next to the vault, then open the box; the wiki says the box held the Official Shutdown Documentation the quest needs.","zh":"它开启星辰山种子库里的种子保管箱。萨尼的“最后条目”任务要求你在保险库隔壁房间找到隐藏钥匙，再打开箱子；维基称箱中有任务所需的官方关停文件。"},"obtain":{"en":"Found in the room adjacent to the vault during the quest. No other source is documented.","zh":"在任务中于保险库相邻房间找到，没有记录其他来源。"},"tips":[{"en":"Finish the quest before selling it; the quest rewards a Yellow Light Stick blueprint and a Warden color.","zh":"先完成任务再考虑卖；任务奖励黄色荧光棒蓝图和守护者配色。"}],"sources":["https://arcraiders.wiki/wiki/Seed_Vault_Box_Key","https://arcraiders.wiki/wiki/Last_Entry"],"version":"2.0"},"spaceport_container_storage_key":{"verdict":{"en":"Rare key to a top-floor room in Container Storage, but nobody has documented what's inside.","zh":"集装箱仓库顶层房间的稀有钥匙，但没人记录过里面有什么。"},"use":{"en":"It fits one of three locked doors on the east side of the Container Storage top floor on The Spaceport. The wiki's loot list is empty and one guide rates it only moderate for lack of data.","zh":"它能开太空港集装箱仓库顶层东侧三扇锁门中的一扇。维基的战利品列表为空，有攻略因缺少数据只给了中等评价。"},"obtain":{"en":"Random container drop only; no quest gives it and no spawn spot is documented.","zh":"只有随机容器掉落，没有任务奖励，也没有记录刷新点。"},"tips":[{"en":"If you find it, try the door; selling nets just 100 coins.","zh":"捡到就去试试那扇门，卖掉只有100钱币。"}],"sources":["https://arcraiders.wiki/wiki/Spaceport_Container_Storage_Key","https://有攻略/blog/arc-raiders-keys"],"version":"2.0"},"spaceport_control_tower_key":{"verdict":{"en":"Given free by Lost in Transmission; it is the key to the top of Control Tower A6.","zh":"“迷失在传输中”任务免费赠送，用于进入控制塔A6顶部。"},"use":{"en":"The doors are at ground level in Control Tower A6 and lead up to the top floor. The quest has you reach the top and use the terminal there. The wiki says the tower is dangerous and suggests going first or last to avoid PvP. Loot there isn't documented.","zh":"门在控制塔A6底层，通往顶层。任务要求你上到塔顶并使用终端。维基称这座塔很危险，建议第一个或最后一个进入以避开PvP。塔内战利品没有记录。"},"obtain":{"en":"Shani hands you one when you accept Lost in Transmission; if lost, a replacement may appear in the Spaceport offices. It can also drop randomly.","zh":"接下“迷失在传输中”时萨尼会给你一把；丢失后可能在太空港办公室找到替代品。也可能随机掉落。"},"tips":[{"en":"The task must be done in one round, so don't wander off with the key.","zh":"任务需在单局内完成，别拿着钥匙乱逛。"}],"sources":["https://arcraiders.wiki/wiki/Spaceport_Control_Tower_Key","https://arcraiders.wiki/wiki/Lost_In_Transmission"],"version":"2.0"},"spaceport_trench_tower_key":{"verdict":{"en":"Mostly a quest key: it opens one of eight Trench Tower doors.","zh":"主要是任务钥匙：能开壕沟塔八扇门中的一扇。"},"use":{"en":"Each Trench Tower has two doors on the first floor and two on the second, eight in total, and one key opens one door. Turnabout sends you to the North Trench Tower for blackmail files. Loot behind the other doors is not documented.","zh":"每座壕沟塔一楼和二楼各有两扇门，共八扇，一把钥匙只能开一扇。“反将一军”任务要你去北壕沟塔找勒索文件。其他门后的战利品没有记录。"},"obtain":{"en":"Celeste rewards one for Switching the Supply and gives one for Turnabout; it also drops randomly.","zh":"塞莱斯特会在“更换水源”给一把奖励，“反将一军”也会发一把；也可能随机掉落。"},"tips":[{"en":"One guide rates it low priority; use it for the quest, then sell spares for 100 coins.","zh":"有攻略评为低优先级；任务用掉，多余的卖100钱币。"}],"sources":["https://arcraiders.wiki/wiki/Spaceport_Trench_Tower_Key","https://arcraiders.wiki/wiki/Switching_The_Supply","https://arcraiders.wiki/wiki/Turnabout"],"version":"2.0"},"spaceport_warehouse_key":{"verdict":{"en":"Low-priority key for second-floor doors in the Shipping Warehouse; loot is undocumented.","zh":"货运仓库二楼门的低优先级钥匙，战利品没有记录。"},"use":{"en":"It opens a set of locked doors on the north side of the second floor of the Shipping Warehouse on The Spaceport. No community source says what is inside; one guide rates it low priority.","zh":"它开启太空港货运仓库北侧二楼的一组锁门。没有社区来源说明里面有什么，有攻略评为低优先级。"},"obtain":{"en":"Random container drop only; no quest rewards it.","zh":"只有随机容器掉落，没有任务奖励。"},"tips":[{"en":"With no known payoff, selling for 100 coins is fine unless you scout the room yourself.","zh":"没有已知回报，除非想自己探房，卖掉换100钱币也行。"}],"sources":["https://arcraiders.wiki/wiki/Spaceport_Warehouse_Key","https://有攻略/blog/arc-raiders-keys"],"version":"2.0"},"stella_montis_archives_key":{"verdict":{"en":"The Epic key of the Stella Montis set: worth taking to its door.","zh":"星辰山钥匙里的史诗级一把：值得带去开门。"},"use":{"en":"It opens a top-floor door in the east-right Storage Room of the Archives. The wiki shows the door on a map but lists no loot. One guide ranks it the strongest Stella Montis key by rarity alone, so treat that as a guess.","zh":"它开启档案馆东右侧储存室顶层的一扇门。维基用地图标出了门的位置，但没有列出战利品。有攻略仅凭稀有度把它排为星辰山最强的钥匙，这只是推测。"},"obtain":{"en":"Random container drop; keys can show up on other maps but only work on Stella Montis.","zh":"随机容器掉落；钥匙可能在其他地图出现，但只能在星辰山使用。"},"tips":[{"en":"Carry it in a Safe Pocket if you can; it is unrecoverable if you die.","zh":"尽量放进安全口袋，死亡后就丢了。"}],"sources":["https://arcraiders.wiki/wiki/Stella_Montis_Archives_Key","https://有攻略/blog/arc-raiders-keys"],"version":"2.0"},"stella_montis_assembly_admin_key":{"verdict":{"en":"Uncommon key for a door in Assembly; no one has documented the payoff.","zh":"组装厂一扇门的优秀级钥匙，没人记录过回报。"},"use":{"en":"It unlocks a door in Assembly on Stella Montis, probably the Assembly Admin area. The wiki says only that, with an empty loot list, so the contents are unknown.","zh":"它开启星辰山组装厂的一扇门，大概是组装厂管理区。维基只说了这些，战利品列表为空，房内内容未知。"},"obtain":{"en":"Random container drop only; no quest gives it.","zh":"只有随机容器掉落，没有任务奖励。"},"tips":[{"en":"Without known loot, selling for 100 coins is reasonable.","zh":"没有已知战利品，卖掉换100钱币也合理。"}],"sources":["https://arcraiders.wiki/wiki/Stella_Montis_Assembly_Admin_Key","https://arcraiders.wiki/wiki/Stella_Montis"],"version":"2.0"},"stella_montis_medical_storage_key":{"verdict":{"en":"Quest key for Someone Else's Shoes; otherwise a door in Medical Research with unknown loot.","zh":"“换核思考”的任务钥匙；否则只是医学研究部一扇战利品未知的门。"},"use":{"en":"It unlocks a door in Medical Research on Stella Montis. The wiki gives no room position or loot.","zh":"它开启星辰山医学研究部的一扇门。维基没有给出房间位置或战利品。"},"obtain":{"en":"The quest Someone Else's Shoes gives you one; it can also drop from containers.","zh":"任务“换核思考”会给你一把；也可能从容器中掉落。"},"tips":[{"en":"Use the quest copy first; extras sell for only 100 coins.","zh":"先用任务那把；多的只卖100钱币。"}],"sources":["https://arcraiders.wiki/wiki/Stella_Montis_Medical_Storage_Key","https://arcraiders.wiki/wiki/Stella_Montis"],"version":"2.0"},"stella_montis_security_checkpoint_key":{"verdict":{"en":"Rare key to the Security Checkpoint; the only Stella Montis key with any documented loot, a Box Locker.","zh":"安全检查站的稀有钥匙，是星辰山唯一有战利品记录的钥匙，内有储物箱。"},"use":{"en":"It opens a door in the Security Checkpoint on Stella Montis. The wiki names a Box Locker as the only loot container, while one guide rates it moderate priority.","zh":"它开启星辰山安全检查站的一扇门。维基仅提到一个储物箱作为战利品容器，有攻略评为中等优先级。"},"obtain":{"en":"Random container drop only; no quest gives it.","zh":"只有随机容器掉落，没有任务奖励。"},"tips":[{"en":"If you are already near the checkpoint, try it; a Box Locker is thin payoff for a long detour.","zh":"人已在检查站附近就去试试；为一个储物箱绕远路不划算。"}],"sources":["https://arcraiders.wiki/wiki/Stella_Montis_Security_Checkpoint_Key","https://有攻略/blog/arc-raiders-keys","https://arcraiders.wiki/wiki/Stella_Montis"],"version":"2.0"},"advanced_arc_powercell":{"verdict":{"en":"Boss-tier ARC loot: hold a few for Energy Clips and Surge Shield Rechargers, sell the surplus at 640 each.","zh":"大型ARC的战利品：留几个做能量弹匣和爆能护盾充能器，多余的按640钱币卖掉。"},"use":{"en":"Feeds Energy Clip crafting and the Surge Shield Recharger (Medical Lab 2), and Research Station blueprints such as Jolt Mine and Tactical Mk. 3 (Defensive) need it too.","zh":"用于制作能量弹匣和爆能护盾充能器（医疗实验室2级），研究站里的电击地雷、战术 Mk. 3（防御型）蓝图也要用到。"},"obtain":{"en":"Drops from tougher ARC: Queen, Matriarch, Bombardier, Leaper, Rocketeer. Queen and Matriarch debris holds it in both main and small piles, but those only appear with their map conditions and are very dangerous.","zh":"由女王、族母、投弹手、跳跃者、火箭手等较强的ARC掉落。女王和族母的残骸大小堆里都有，但它们只在对应地图条件下出现，难度很高。"},"tips":[{"en":"No live project asks for it. Keep a couple for Energy Clips and Surge Shield Rechargers and sell the rest.","zh":"目前没有进行中的项目需要它。留几个做能量弹匣和爆能护盾充能器，其余卖掉。"},{"en":"Recycling only gives 2 ARC Powercells (270 each), far below the 640 sell price.","zh":"回收只得2个ARC能量电池（各270），远低于640的售价。"}],"sources":["https://arcraiders.wiki/wiki/Advanced_ARC_Powercell","https://arcraiders.wiki/wiki/Queen"],"version":"2.0"},"advanced_electrical_components":{"verdict":{"en":"Keep it: Gear Bench 3 and Utility Station 3 upgrades, a long list of Mk. 3 augments and Sheltered Retreat all use it.","zh":"留着：装备工作台3级、工具工作台3级升级、一大堆 Mk. 3 增强和掩护撤退都要用。"},"use":{"en":"Needed for every Mk. 3 augment blueprint craft at the Gear Bench, plus Photoelectric Cloak, Power Rod and Raider Hatch Key.","zh":"装备工作台制作 Mk. 3 增强要用，光电斗篷、能量管、奇袭者暗门钥匙也需要。"},"obtain":{"en":"Rare loot from Electrical containers, and from Queen debris. Several quests pay it out, so finish Taking Stock, Bees!, Paving the Way and Digging Up Dirt first. You can also craft it at Refiner 2 from Electrical Components and Wires.","zh":"出自电子类容器和女王残骸。清点物资、蜜蜂！、开辟道路、揭露丑闻几个任务会直接奖励，先做完。也可以在精加工机2级用电子元件和导线合成。"},"tips":[{"en":"Keep 5 for Gear Bench 3 and 5 more for Utility Station 3 before you sell any. Sheltered Retreat phase 2 also wants 3.","zh":"装备工作台3级和工具工作台3级各要5个，先留够再卖；掩护撤退第2阶段另要3个。"},{"en":"Recycling returns one Electrical Components and one Wires, worth far less than 1,750.","zh":"回收只返还1个电子元件和1个导线，远不值1750。"}],"sources":["https://arcraiders.wiki/wiki/Advanced_Electrical_Components","https://arcraiders.wiki/wiki/Medical_Lab"],"version":"2.0"},"advanced_mechanical_components":{"verdict":{"en":"The Gunsmith item: it gates the Gunsmith 3 upgrade and most weapon crafts and repairs, so keep a healthy stack.","zh":"武器工作台的核心材料：3级升级以及大部分武器制作、修理都离不开它，多留一些。"},"use":{"en":"Used to craft Anvil, Bettina, Osprey, Rascal, Renegade, Torrente, Venator and others, and for the Magnetic Accelerator. Several weapon repairs also use it.","zh":"制作铁砧、贝蒂娜、鱼鹰、无赖、叛逆、奔流、复仇者等武器和磁力加速器都要用，部分武器修理也消耗它。"},"obtain":{"en":"Dropped by Queen and Matriarch, and found in Mechanical containers such as Industrial Cleaners and Control Panels. Quests like Straight Record, A Balanced Harvest and Tribute to Toledo hand out several. Refiner 2 can craft it from Mechanical Components and Steel Springs.","zh":"女王和族母会掉落，机械类容器（工业清洁器、控制面板）里也能找到。理顺记录、丰富收获、给托雷多管理层上贡等任务奖励不少。精加工机2级可用机械元件和钢质弹簧合成。"},"tips":[{"en":"Gunsmith 3 needs 5; after that, keep only what weapon crafts need.","zh":"武器工作台3级要5个，之后只留武器制作用得上的。"},{"en":"Recycling high-tier weapons can return some, which is a cheaper route than farming bosses.","zh":"回收高阶武器能返还一些，比刷首领省事。"}],"sources":["https://arcraiders.wiki/wiki/Advanced_Mechanical_Components","https://arcraiders.wiki/wiki/Matriarch"],"version":"2.0"},"agave":{"verdict":{"en":"A weak heal that is worth more as an ingredient: keep a few for Agave Juice, otherwise break it into seeds.","zh":"治疗效果很弱，更适合当材料：留几片做龙舌兰汁，其余拆成种子。"},"use":{"en":"Heals 1 per second for 10 seconds. With In-Round Crafting, combine it with an Empty Wine Bottle to make Agave Juice.","zh":"每秒回复1点，持续10秒。有局内制作技能时，可与空酒瓶合成龙舌兰汁。"},"obtain":{"en":"Harvest agave plants (the community wiki shows one on Dam Battlegrounds) or look in Wicker Baskets. Baskets show up on maps with Lush Blooms or Cold Snap active.","zh":"可采集龙舌兰植株（社区维基标注大坝战场有），或在柳条篮里找。柳条篮在“繁花盛开”或“寒流”条件的地图出现。"},"tips":[{"en":"No live project needs it, so only Agave Juice crafting is a reason to hold any.","zh":"目前没有进行中的项目需要它，只有制作龙舌兰汁才值得留。"},{"en":"Feeding it to Scrappy gives +5 Assorted Seeds; recycling gives 3.","zh":"喂给废品仔可得5个混合种子，回收得3个。"}],"sources":["https://arcraiders.wiki/wiki/Agave","https://arcraiders.wiki/wiki/Scrappy","https://arcraiders.wiki/wiki/Wicker_Basket"],"version":"2.0"},"amplification_module_mk_i":{"verdict":{"en":"Common-tier amplification key. It sells for 7,000, so only keep it if you are actually amplifying a common weapon.","zh":"普通品质武器的增强模块。售价7000，除非你真要增强普通武器，否则卖掉。"},"use":{"en":"Amplification permanently rebuilds a weapon and cannot be undone; it needs the Outpost plus Gunsmith and Research Station at level 4.","zh":"增强会永久改造武器且不可撤销，需要解锁前哨站，并把武器工作台和研究站升到4级。"},"obtain":{"en":"Scavenged from the Fallen Emperor and the ARC Frigate, both 2.0 events. The Frigate appears on every map and has no free loadout.","zh":"来自“堕落的皇帝”和ARC护卫舰，都是2.0的活动内容。护卫舰各地图都会出现，且没有免费装备。"},"tips":[{"en":"The wiki says it cannot be broken down, but local data shows 7 Amplified Fragments on recycling, worth 500 each. Selling at 7,000 pays double.","zh":"社区维基称不可分解，但本站数据显示回收得7个增强碎片（各500）。直接卖7000更划算。"}],"sources":["https://arcraiders.wiki/wiki/Amplification_Module_Mk._I","https://arcraiders.wiki/wiki/Amplification","https://arcraiders.wiki/wiki/ARC_Frigate"],"version":"2.0"},"amplification_module_mk_ii":{"verdict":{"en":"Unlocks Amplification for uncommon weapons. Sell it for 7,000 unless you plan to amplify one.","zh":"解锁罕见武器的增强。不打算增强就直接卖7000。"},"use":{"en":"Pick the module that matches the weapon's rarity; this one is the Uncommon match.","zh":"模块要和武器品质对应，这一个对应罕见品质。"},"obtain":{"en":"Same pool as the rest of the line: the Fallen Emperor and the ARC Frigate event.","zh":"与同系列一样，来自“堕落的皇帝”和ARC护卫舰活动。"},"tips":[{"en":"Recycling gives 7 Amplified Fragments, only 3,500 coins of value, and those fragments are also what repairs amplified guns.","zh":"回收得7个增强碎片，仅值3500，不过增强武器的修理也靠它们。"}],"sources":["https://arcraiders.wiki/wiki/Amplification_Module_Mk._II","https://arcraiders.wiki/wiki/Amplification"],"version":"2.0"},"amplification_module_mk_iii":{"verdict":{"en":"The Rare-weapon module. Mid-tier guns are the best amplification candidates; otherwise sell.","zh":"稀有武器模块。中阶武器最适合增强，否则卖掉。"},"use":{"en":"Matches Rare weapons. Amplified weapons gain +70 max durability but cannot be reverted.","zh":"对应稀有武器。增强后最大耐久+70，但不可还原。"},"obtain":{"en":"Drops come from Fallen Emperor and the ARC Frigate; plan around them rather than random loot.","zh":"来自“堕落的皇帝”和ARC护卫舰，要靠打这些活动，而不是随机搜刮。"},"tips":[{"en":"If it ends up unused, selling is worth 7,000 against 3,500 from recycled fragments.","zh":"用不上的话卖7000，回收碎片只值约3500。"}],"sources":["https://arcraiders.wiki/wiki/Amplification_Module_Mk._III","https://arcraiders.wiki/wiki/Amplification"],"version":"2.0"},"amplification_module_mk_iv":{"verdict":{"en":"Epic-tier module for a favorite epic weapon; spare ones are 7,000 coins each.","zh":"史诗武器的模块，用于你最爱的史诗武器；多余的每个能卖7000。"},"use":{"en":"Pairs with Epic weapons. Make sure the build is one you will keep, because the change is permanent.","zh":"适配史诗武器。确认是自己要长期用的配装，因为改造是永久的。"},"obtain":{"en":"Event loot from the Fallen Emperor and ARC Frigate.","zh":"来自“堕落的皇帝”和ARC护卫舰的活动战利品。"},"tips":[{"en":"The Amplified Fragments to repair these guns come only from recycling, so budget for them.","zh":"这类武器的修理材料增强碎片只能靠回收获得，要提前算好。"}],"sources":["https://arcraiders.wiki/wiki/Amplification_Module_Mk._IV","https://arcraiders.wiki/wiki/Amplification"],"version":"2.0"},"amplification_module_mk_v":{"verdict":{"en":"Legendary-weapon module. Only worth using on a gun you will carry for ages; otherwise it is a 7,000 coin sale.","zh":"传奇武器的模块。只给会长期使用的枪用，否则就是一笔7000的买卖。"},"use":{"en":"Legendary guns get +100 durability from amplification instead of +70.","zh":"传奇武器增强后耐久+100，普通是+70。"},"obtain":{"en":"Comes from the Fallen Emperor and the ARC Frigate, the 2.0 event bosses.","zh":"来自2.0的活动首领“堕落的皇帝”和ARC护卫舰。"},"tips":[{"en":"Spares can be recycled for fragments, but selling pays twice as much.","zh":"多余的可回收成碎片，但卖掉收益高一倍。"}],"sources":["https://arcraiders.wiki/wiki/Amplification_Module_Mk._V","https://arcraiders.wiki/wiki/Amplification","https://arcraiders.wiki/wiki/Research_Station"],"version":"2.0"},"amplified_fragments":{"verdict":{"en":"Repair currency for amplified weapons only; worthless if you do not use them, 500 coins each if you sell.","zh":"只用于修理增强武器；不用增强武器的话，每个卖500。"},"use":{"en":"Spent on repairing amplified weapons. Cannot be recycled itself.","zh":"用于修理增强武器，本身不可回收。"},"obtain":{"en":"Only obtained through recycling, such as breaking down amplified weapons or Amplification Modules (7 each).","zh":"只能通过回收获得，例如分解增强武器或增强模块（每个模块7个）。"},"tips":[{"en":"Stack size is 50, so keep a reserve before taking an amplified gun into a raid.","zh":"一组可堆叠50个，带增强武器出击前先备一批。"},{"en":"Check an amplified weapon's repair cost before buying into it; the fragments add up.","zh":"增强前先看修理成本，碎片消耗会累积。"}],"sources":["https://arcraiders.wiki/wiki/Amplified_Fragments","https://arcraiders.wiki/wiki/Update_2.0"],"version":"2.0"},"antiseptic":{"verdict":{"en":"Keep 8 for Medical Lab 3, then hold some for Vita Spray and Sterilized Bandages.","zh":"留8个给医疗实验室3级，再留一些做补水喷雾和消毒绷带。"},"use":{"en":"Goes into Sterilized Bandage, Vita Shot and Vita Spray, and the Tactical Mk. 3 (Revival) blueprint.","zh":"用于消毒绷带、生命针剂、补水喷雾，以及战术 Mk. 3（复苏）蓝图。"},"obtain":{"en":"Look in medical containers, or take it as a quest reward: A New Type of Plant (5), After Rain Comes (3) and Home to Roost (2). Refiner 2 turns 10 Chemicals and 2 Great Mullein into one.","zh":"去医疗类容器里找，或拿任务奖励：新型植物（5）、风雨过后（3）、归巢（2）。精加工机2级可用10化学品加2大毛蕊花合成。"},"tips":[{"en":"The quest Doctor's Orders also takes 2.","zh":"医生的订单任务还要2个。"},{"en":"Recycling only returns chemicals, so crafting from them is a net loss.","zh":"回收只得化学品，用化学品合成则不划算。"}],"sources":["https://arcraiders.wiki/wiki/Antiseptic","https://arcraiders.wiki/wiki/Medical_Lab"],"version":"2.0"},"apricot":{"verdict":{"en":"Cheap fruit with one real purpose: Scrappy upgrades. Keep 15 until levels 3 and 5 are done.","zh":"便宜的水果，真正用途是废品仔升级。留15个，直到3级和5级完成。"},"use":{"en":"Restores 20 stamina. Also a Fruit Mix ingredient with Lemon and Prickly Pear.","zh":"回复20体力，也可与柠檬、仙人掌果合成水果拼盘。"},"obtain":{"en":"Pick them under apricot trees or search Wicker Baskets. Trees drop 1 to 4 on the ground, and circling the tree can reveal more. Baskets appear with Lush Blooms or Cold Snap.","zh":"在杏树下捡，或搜柳条篮。杏树地上有1到4个，绕树可能还有额外掉落。柳条篮在“繁花盛开”或“寒流”条件下出现。"},"tips":[{"en":"Scrappy level 3 needs 3 and level 5 needs 12.","zh":"废品仔3级要3个，5级要12个。"},{"en":"Feeding one to Scrappy gives metal parts; recycling gives 3 seeds.","zh":"喂给废品仔可得金属零件，回收得3个种子。"}],"sources":["https://arcraiders.wiki/wiki/Apricot","https://arcraiders.wiki/wiki/Scrappy"],"version":"2.0"},"arc_alloy":{"verdict":{"en":"The workhorse ARC material: keep it for workshop upgrades, Sheltered Retreat and recipes, sell only extras.","zh":"最常用的ARC材料：留给工作台升级、掩护撤退和合成配方，只卖多余的。"},"use":{"en":"Needed for Utility Station, Explosives Station and Medical Lab level 1 upgrades, and as the base material for ARC Circuitry and ARC Motion Core.","zh":"工具工作台、爆炸物工作台、医疗实验室1级升级要用，也是ARC线圈和ARC运动核心的原料。"},"obtain":{"en":"Every ARC enemy drops it, so kill anything: Wasps, Ticks and Turrets are cheap. Surveyors and Leapers drop more kinds of materials.","zh":"所有ARC都会掉落，随便打小怪即可，黄蜂、跳蚤、炮塔最省力。"},"tips":[{"en":"Utility Station, Explosives Station and Medical Lab level 1 need 6 each; Sheltered Retreat phase 2 wants 10.","zh":"工具工作台、爆炸物工作台、医疗实验室1级各要6个；掩护撤退第2阶段要10个。"},{"en":"It only recycles into 2 Metal Parts at 200 coins, so do not recycle.","zh":"回收只得2个金属零件，别回收。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Alloy","https://arcraiders.wiki/wiki/ARC_Circuitry"],"version":"2.0"},"arc_circuitry":{"verdict":{"en":"Keep 10 for the Refiner 3 upgrade plus more for blueprints; recycle only the extras into alloy.","zh":"精加工机3级需要10个，蓝图还要更多；只回收多余的换成合金。"},"use":{"en":"Required for Research Station 3 blueprints, Deadline, Medium Shield and Power Rod.","zh":"研究站3级蓝图、死线、中型护盾、能量管都要用。"},"obtain":{"en":"Dropped by Bastion, Leaper, Rocketeer, Surveyor, Matriarch and Queen. Bastions and Leapers are the practical farm targets.","zh":"堡垒、跳跃者、火箭手、ARC勘测师、族母、女王会掉落。实际刷的话主要打堡垒和跳跃者。"},"tips":[{"en":"Nothing Ventured wants 6. No live project uses it, so sell or recycle surplus beyond upgrades and crafts.","zh":"焉得虎子要6个。目前没有进行中的项目需要它，升级和制作之外的多余部分可卖或回收。"},{"en":"Do not craft it from 8 alloy; that wastes alloy.","zh":"别用8个合金去合成，亏。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Circuitry","https://arcraiders.wiki/wiki/Medical_Lab"],"version":"2.0"},"arc_motion_core":{"verdict":{"en":"Keep 5 for the Refiner 2 upgrade and 6 for Nothing Ventured; the rest only matters for a few gun crafts.","zh":"留5个升精加工机2级、6个给焉得虎子，其余只用于几个武器制作。"},"use":{"en":"Goes into Launcher Ammo, Magnetic Accelerator and Wolfpack. Also a Vertical Grip III blueprint ingredient.","zh":"用于发射器弹药、磁力加速器、狼群，以及垂直握把 III蓝图。"},"obtain":{"en":"Dropped by Bastion, Leaper, Rocketeer, Sentinel, Surveyor and Queen. Sentinels are the easier option.","zh":"堡垒、跳跃者、火箭手、哨卫、ARC勘测师、女王会掉落，哨卫相对好打。"},"tips":[{"en":"No live project needs it, so after the upgrade and quest, sell extras.","zh":"目前没有进行中的项目需要它，升级和任务用完后多余的可以卖。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Motion_Core","https://arcraiders.wiki/wiki/Medical_Lab"],"version":"2.0"},"arc_powercell":{"verdict":{"en":"Keep 5 for the Refiner 1 upgrade and a few for shield recharging; sell the rest at 270.","zh":"留5个升精加工机1级，再留几个充护盾；其余按270卖。"},"use":{"en":"Recharges 2 shield per second for 10s and is the base of Shield Recharger.","zh":"每秒恢复2点护盾，持续10秒，是护盾充能器的原料。"},"obtain":{"en":"Every ARC enemy drops it, so Wasps, Hornets and Snitches are the cheap farm.","zh":"所有ARC都掉，打黄蜂、马蜂、告密者最轻松。"},"tips":[{"en":"A Prime Specimen needs 2. No live project uses it, so sell the rest.","zh":"完美样本要2个。目前没有进行中的项目需要它，其余卖掉。"},{"en":"It cannot be recycled, so selling is the only cash-out.","zh":"无法回收，只能卖。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Powercell","https://arcraiders.wiki/wiki/Advanced_ARC_Powercell"],"version":"2.0"},"arc_conductive_coupler":{"verdict":{"en":"Keep one for Sizing Things Up; otherwise it is a 100 coin sale.","zh":"留1个做审时度势任务，其余卖100钱币。"},"use":{"en":"One of three couplers for the Emperor Gateway Conduit.","zh":"是“帝王”通道导管三个耦合器之一。"},"obtain":{"en":"Scavenged from a Harvester Payload after deploying an Emperor Beacon, which comes from a fallen beacon on Pendola Pass. Rocketeers are also listed as a source.","zh":"部署“帝王”信标后从收割者载荷中取得，信标来自彭多拉山口的坠落信标。火箭手也可能掉落。"},"tips":[{"en":"Beacon debris can hit hard, so stay clear.","zh":"信标落物伤害高，注意躲开。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Conductive_Coupler","https://arcraiders.wiki/wiki/Emperor_Beacon"],"version":"2.0"},"arc_data_module":{"verdict":{"en":"Keep 3 for Research Station 4, then use the rest for Research Points or sell at 2,000.","zh":"留3个升研究站4级，其余可用掉换研究点或卖2000。"},"use":{"en":"Gives 200 Research Points when used, which pays for blueprints.","zh":"使用后获得200研究点，可用于解锁蓝图。"},"obtain":{"en":"Scavenged from ARC machines, and cannot be crafted or recycled.","zh":"从ARC机械上搜刮，无法制作或回收。"},"tips":[{"en":"Station 4 also needs 3 Thermal Shakers and a Frigate Inductor.","zh":"研究站4级还要3个热能摇杆和1个“护卫者”感应器。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Data_Module","https://arcraiders.wiki/wiki/Research_Station"],"version":"2.0"},"arc_insulated_coupler":{"verdict":{"en":"Only useful for the Emperor Gateway Conduit; otherwise sell it for 100.","zh":"只用于“帝王”通道导管，不然卖100。"},"use":{"en":"One of three required couplers, together with the Conductive and Plated types and the blueprint.","zh":"三个耦合器之一，另外还需导电、镀层两种及蓝图。"},"obtain":{"en":"Comes out of a Harvester Payload after you activate an Emperor Beacon.","zh":"启用“帝王”信标后，从收割者载荷中获得。"},"tips":[{"en":"Only craft once you hold all three plus the blueprint.","zh":"三个和蓝图凑齐再制作。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Insulated_Coupler","https://arcraiders.wiki/wiki/Emperor_Beacon"],"version":"2.0"},"arc_plated_coupler":{"verdict":{"en":"A one-purpose item: only the Emperor Gateway Conduit uses it, so sell it unless you are crafting that.","zh":"只有一个用途：“帝王”通道导管。不做的话卖掉。"},"obtain":{"en":"Scavenged from a Harvester Payload after deploying an Emperor Beacon.","zh":"部署“帝王”信标后从收割者载荷中取得。"},"tips":[{"en":"Weighs little, so keeping one costs almost nothing.","zh":"重量很小，留着几乎没代价。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Plated_Coupler","https://arcraiders.wiki/wiki/Emperor_Beacon"],"version":"2.0"},"assorted_seeds":{"verdict":{"en":"Currency for Celeste: bank them, because they are light and only worth 100 coins each as junk.","zh":"给塞莱斯特换货用的货币：很轻，直接卖才100，不如攒着。"},"use":{"en":"Trade seeds to Celeste: 1 buys a Metal Part, 15 buys a gun-part set, 60 buys Complex Gun Parts. Scrappy also accepts them for better materials.","zh":"向塞莱斯特换货：1个换金属零件，15个换武器零件，60个换复杂枪械零件。废品仔也收，可能给更好的材料。"},"obtain":{"en":"Break down any Nature item, or open Fridges, Lockers, Seed Drawer Boxes and Wicker Baskets.","zh":"分解自然类物品，或搜冰箱、储物柜、种子抽屉盒、柳条篮。"},"tips":[{"en":"Shaker needs 7. Weight is 0.05.","zh":"摇铃要7个，重量仅0.05。"}],"sources":["https://arcraiders.wiki/wiki/Assorted_Seeds","https://arcraiders.wiki/wiki/Celeste","https://arcraiders.wiki/wiki/Scrappy"],"version":"2.0"},"battered_paperback":{"verdict":{"en":"Keep 5 for the Research Station level 1 upgrade; after that it is only a 270-coin sell item.","zh":"留5本升级研究站1级，之后只是270钱币的卖品。"},"obtain":{"en":"It comes from ordinary scavenging with no known fixed spot. The Clean Hands quest also pays one out. It cannot be recycled, so extras can only be sold.","zh":"来自常规搜刮，没有已知的固定刷新点；任务“清理指针”也会奖励一本。无法回收，多余的只能卖。"},"tips":[{"en":"Using one directly gives 50 Research Points, but only do that once you hold the 5 the upgrade needs.","zh":"直接使用可得50研究点，但要先凑够升级所需的5本。"}],"sources":["https://arcraiders.wiki/wiki/Battered_Paperback"],"version":"2.0"},"battery":{"verdict":{"en":"A useful crafting staple: keep a stack for crafting and quests, recycle only the surplus.","zh":"常用制作材料：留一叠给制作和任务，多余的再回收。"},"use":{"en":"It goes into Energy Clips, Jolt Mines and Medium Shields (4 each), plus a few for the Trash Into Treasure, Clamoring for Attention and After Rain Comes quests.","zh":"用于制作能量弹匣、电击地雷和中型护盾（中型护盾每个4个），任务“变废为宝”“哗众取宠”“风雨过后”也要用。"},"obtain":{"en":"Open technological and electrical containers such as terminals, computers, recording panels, oscilloscopes and control consoles. Celeste sells up to 10 a day for 5 Assorted Seeds each.","zh":"搜刮终端、电脑、录音面板、示波器和控制台等科技与电子类容器。塞莱斯特每天限购10个，每个5混合种子。"},"tips":[{"en":"Recycling only gives 2 Metal Parts, far below the 250 coin value, so sell surplus rather than break it down.","zh":"回收只得2个金属零件，远不如250钱币的价值，多余的直接卖，别拆。"}],"sources":["https://arcraiders.wiki/wiki/Battery"],"version":"2.0"},"cable_stripper":{"verdict":{"en":"Only worth keeping one for the Grappling Hook; otherwise sell it for 270.","zh":"只需留1个做钩爪，其余卖掉换270钱币。"},"obtain":{"en":"Look in mechanical and industrial containers. You can also get one back by recycling a Grappling Hook or Tether Launcher.","zh":"在机械和工业类容器里找。回收钩爪或系索发射器也能拿回1个。"},"tips":[{"en":"Recycling returns just 2 Metal Parts, so selling is the better deal.","zh":"回收只有2个金属零件，卖掉更划算。"}],"sources":["https://arcraiders.wiki/wiki/Cable_Stripper"],"version":"2.0"},"calculator":{"verdict":{"en":"Keep 3 for the Research Station level 2 upgrade, then sell extras at 640 each.","zh":"留3个升级研究站2级，多余的按640钱币卖掉。"},"use":{"en":"Besides the Research Station upgrade, it is a one-off ingredient in the Advanced Camera, Mountaineer's Detector and Tether Launcher.","zh":"除研究站升级外，还是高级相机、登山者探测器和系索发射器的单件配料。"},"obtain":{"en":"The community wiki lists Pendola Pass as the scavenging source, in technological and electrical loot. No exact containers are documented yet.","zh":"社区维基列出彭多拉山口为搜刮来源，属于科技和电子类战利品，尚无确切容器记录。"},"tips":[{"en":"Stack size is only 3, so plan inventory space before a Pendola Pass run.","zh":"堆叠上限只有3，去彭多拉山口前留好背包空间。"}],"sources":["https://arcraiders.wiki/wiki/Calculator"],"version":"2.0"},"candleberries":{"verdict":{"en":"A weak heal with no live project needing it: eat them or sell at 460.","zh":"治疗很弱，目前没有项目需要：直接吃掉，或按460钱币卖。"},"use":{"en":"As food they heal only 1 per second for 10 seconds, so do not rely on them in a fight. Nothing currently being built or crafted needs them.","zh":"作为食物每秒只回1点，持续10秒，战斗中不要指望它。目前没有进行中的项目或配方需要它。"},"obtain":{"en":"Candleberry bushes appear on Pendola Pass and on maps running the Cold Snap condition, each giving 1 to 3 berries. Wicker baskets there also hold some.","zh":"烛莓灌木出现在彭多拉山口以及“寒潮”条件的地图上，每丛1到3颗，当地的柳条篮里也有。"},"tips":[{"en":"Recycling gives 2 Assorted Seeds, which is poor next to the 460 coin value.","zh":"回收只得2个混合种子，不如460钱币的卖价。"}],"sources":["https://arcraiders.wiki/wiki/Candleberries"],"version":"2.0"},"canister":{"verdict":{"en":"Keep a working stock for grenades and gun crafts; the rest is fine to sell at 300.","zh":"留一批做手雷和武器制作，其余可按300钱币卖掉。"},"use":{"en":"It is needed for Bettina I (3), Rascal I (5), Heavy Fuze Grenades, Smoke Grenades, Shaker and Vita Spray.","zh":"用于制作贝蒂娜 I（3个）、无赖 I（5个）、重型引信手雷、烟雾手雷、摇铃和补水喷雾。"},"obtain":{"en":"Search commercial containers. Celeste also sells 10 a day for 6 Assorted Seeds each, and Untended Garden pays 5.","zh":"搜刮商业类容器。塞莱斯特每天限售10个，每个6混合种子，任务“无人照看的农园”奖励5个。"},"tips":[{"en":"Recycling gives 3 Plastic Parts, so only break them down if you are short on plastic.","zh":"回收得3个塑料零件，缺塑料时才拆。"}],"sources":["https://arcraiders.wiki/wiki/Canister"],"version":"2.0"},"chemicals":{"verdict":{"en":"Keep it: Explosives Station 1 needs 50, and ammo and grenades all burn through it.","zh":"别卖：爆炸物工作台1级要50个，弹药和手雷也都离不开它。"},"use":{"en":"The Explosives Station level 1 upgrade needs 50, Smoke Grenades eat 14 each, and light, medium, heavy and shotgun ammo all use it. It is also the base of Crude Explosives.","zh":"爆炸物工作台1级需要50个，烟雾手雷每个耗14个，轻中重型和霰弹枪弹药都要用，还是粗制炸药的原料。"},"obtain":{"en":"Medical, residential and mechanical containers carry it. Recycling Laboratory Reagents (16) or Impure ARC Coolant (12) is a fast way to bulk up. Celeste sells it for 1 Assorted Seed.","zh":"医疗、居住和机械类容器都有。回收实验室试剂（16个）或不纯净的ARC冷却剂（12个）能快速囤货。塞莱斯特1混合种子就卖。"},"tips":[{"en":"It is worth only 50 coins, so the value is all in the crafting.","zh":"只值50钱币，价值全在制作上。"}],"sources":["https://arcraiders.wiki/wiki/Chemicals"],"version":"2.0"},"complex_gun_parts":{"verdict":{"en":"Keep every one: the Aphelion, Equalizer and Jupiter each need 3.","zh":"全部留着：远日点、制裁者、木星各需要3个。"},"use":{"en":"Besides the three weapons, Research Station 3 blueprints for the Bettina and Hullcracker take 1 each, and the Complex Gun Parts blueprint itself takes 2.","zh":"除了这三把枪，研究站3级的贝蒂娜和裂甲者蓝图各要1个，复杂枪械零件蓝图本身要2个。"},"obtain":{"en":"Kill the Queen or the Matriarch, or search security containers. Celeste sells 1 a day for 60 Assorted Seeds. Learning the blueprint lets the Refiner level 3 craft it from six gun parts.","zh":"击杀女王或族母，或搜刮安保类容器。塞莱斯特每天限售1个，60混合种子。学会蓝图后可在精加工机3级用六个枪械零件合成。"},"tips":[{"en":"Recycling one gives only 3 Simple Gun Parts, a bad trade for 3000 coin value.","zh":"回收只得3个简易枪械零件，对不起3000钱币的价值。"}],"sources":["https://arcraiders.wiki/wiki/Complex_Gun_Parts"],"version":"2.0"},"crude_explosives":{"verdict":{"en":"Keep 5 for Explosives Station 2, craft more from Chemicals when you need them.","zh":"留5个升级爆炸物工作台2级，缺了用化学品自己合。"},"use":{"en":"It feeds Explosive Compound, Pulse Mine, Seeker, Shrapnel and Snap Blast grenades, Launcher Ammo and the Trailblazer blueprint. Thrown directly it only does 15 damage.","zh":"用于炸药混合物、跳雷：冲击、追踪手雷、碎片手雷、闪爆手雷、发射器弹药和开拓者蓝图。直接投掷只有15点伤害。"},"obtain":{"en":"Kill Pops and Fireballs, or search industrial and security containers. Quests Sparks Fly and Echoes of Victory Ridge pay 4 and 6.","zh":"击杀爆爆和火球，或搜刮工业与安保类容器。任务“灭蜂大计”和“凯旋岭的回声”分别奖励4个和6个。"},"tips":[{"en":"Six Chemicals craft one at Refiner 1, so you rarely need to hunt it.","zh":"六个化学品在精加工机1级就能合成，一般不用专门找。"}],"sources":["https://arcraiders.wiki/wiki/Crude_Explosives"],"version":"2.0"},"duct_tape":{"verdict":{"en":"Stockpile it for weapon grips and stocks; tier III mods take 5 each.","zh":"为握把和枪托囤货，III级配件每个要5卷。"},"use":{"en":"Angled and Vertical Grips and Stable Stocks scale from 1 to 5 tape per tier, and Padded and Lightweight Stocks take 5.","zh":"直角握把、垂直握把和稳定枪托按等级需要1到5卷，减震与轻型枪托各要5卷。"},"obtain":{"en":"Search residential and commercial containers. Four quests (A Bad Feeling, Keeping the Memory, A Symbol of Unification, Source of the Contamination) pay 5 each, and Celeste sells 10 a day for 6 Assorted Seeds.","zh":"搜刮居住和商业类容器。四个任务“不祥预感”“铭记于心”“团结的象征”“污染源头”各奖励5卷，塞莱斯特每天限售10卷，每卷6混合种子。"},"tips":[{"en":"Recycling returns 3 Fabric, which is cheap, so keep the tape.","zh":"回收只得3个布料很亏，胶带别拆。"}],"sources":["https://arcraiders.wiki/wiki/Duct_Tape"],"version":"2.0"},"durable_cloth":{"verdict":{"en":"Keep some: the Medical Lab 2 upgrade, bandages and Crash Mats all use it.","zh":"留一些：医疗实验室2级、绷带和缓冲垫都要用。"},"use":{"en":"It is needed for Sterilized and Herbal Bandages and Crash Mats, plus the Medical Lab level 2 upgrade (5) and the Doctor's Orders quest.","zh":"用于消毒绷带、草药绷带和缓冲垫，另需用于医疗实验室2级（5块）和任务“医生的订单”。"},"obtain":{"en":"Medical and commercial containers hold it. You can also craft one from 14 Fabric at Refiner 1, and the quests After Rain Comes and Divided pay 5 and 2.","zh":"医疗和商业类容器会出。也可用14个布料在精加工机1级合成，任务“风雨过后”和“分歧”分别奖励5块和2块。"},"tips":[{"en":"Recycling gives 6 Fabric from a 14 Fabric recipe, so avoid breaking it down.","zh":"14个布料合成的东西回收只回6个，别拆。"}],"sources":["https://arcraiders.wiki/wiki/Durable_Cloth"],"version":"2.0"},"electrical_components":{"verdict":{"en":"Keep 10 for the Gear Bench and Utility Station upgrades; extra feeds Mk. 2 augments and Advanced Electrical Components.","zh":"留10个升级装备工作台和工具工作台，多余的用来做Mk. 2配件和高级电子元件。"},"use":{"en":"Gear Bench 2 and Utility Station 2 take 5 each. It also goes into Mk. 2 augments, Advanced Electrical Components, Surge Coil and Jolt Mine.","zh":"装备工作台2级与工具工作台2级各需5个。还用于Mk. 2配件、高级电子元件、涌能线圈和电击地雷。"},"obtain":{"en":"Search electrical containers, or kill Rocketeers and Vaporizers. The quests Wires Crossed, Ruins and Reverberations and Greasing Her Palms give 3 each.","zh":"搜刮电子类容器，或击杀火箭手和汽化者。任务“线路交错”“废墟和回响”“打通通路”各奖励3个。"},"tips":[{"en":"Crafting one costs 8 Plastic Parts and 4 Rubber Parts, but recycling returns only 3 of each, so craft rather than lose them.","zh":"合成要8塑料零件和4橡胶零件，回收只回各3个，别拆。"}],"sources":["https://arcraiders.wiki/wiki/Electrical_Components"],"version":"2.0"},"emperor_modulator":{"verdict":{"en":"Hold it: you need exactly one for Gunsmith level 4 and for Belly of the Beast.","zh":"留着：武器工作台4级和“兽腹深处”任务都要一个。"},"obtain":{"en":"It is scavenged from the Fallen Emperor. The wiki gives no spawn spot, and you cannot recycle it, so treat it as a boss reward.","zh":"来自陨落帝王，维基没有给出具体刷新点，也无法回收，视作首领奖励。"},"tips":[{"en":"It sells for 7000, but the workshop and quest both need it, so do not sell the only copy.","zh":"能卖7000，但工作台和任务都要它，唯一的一个别卖。"}],"sources":["https://arcraiders.wiki/wiki/Emperor_Modulator"],"version":"2.0"},"exodus_modules":{"verdict":{"en":"Keep 5 for the Trophy Display and a few for weapon crafts; otherwise a solid 2750 coin sale.","zh":"留5个给战利品展示架，再留几个做武器；其余可按2750钱币出手。"},"use":{"en":"They are in Bobcat I, Hullcracker I, Tempest I, Vulcano I and Snap Hook, and Trophy Display phase 5 takes 5.","zh":"用于山猫 I、裂甲者 I、风暴 I、火山 I 和安全钩，战利品展示架第5阶段要5个。"},"obtain":{"en":"Exodus containers drop them. Celeste sells 1 a day for 55 Assorted Seeds, and the quests Nothing Ventured, Celeste's Journals and Line in the Sand pay 1 to 2.","zh":"离巢类容器会出。塞莱斯特每天限售1个，55混合种子；任务“焉得虎子”“塞莱斯特的日记”“沙滩防线”奖励1到2个。"},"tips":[{"en":"Stack size is 3, and recycling gives 2 Magnets and 2 Processors, which is not worth it unless you need them.","zh":"堆叠上限3；回收得2磁铁和2处理器，不缺就别拆。"}],"sources":["https://arcraiders.wiki/wiki/Exodus_Modules"],"version":"2.0"},"exodus_technical_handbook":{"verdict":{"en":"Keep 3 for the Research Station level 3 upgrade; use or sell any extra.","zh":"留3本升级研究站3级，多余的使用或出售。"},"obtain":{"en":"The wiki lists Exodus loot and Pendola Pass as sources, with no exact containers. Quest Sizing Things Up pays one.","zh":"维基列出离巢类战利品和彭多拉山口为来源，没有具体容器；任务“审时度势”奖励一本。"},"tips":[{"en":"Using one gives 150 Research Points, but spare the first three for the upgrade.","zh":"使用可得150研究点，但前三本先留给升级。"}],"sources":["https://arcraiders.wiki/wiki/Exodus_Technical_Handbook"],"version":"2.0"},"explosive_compound":{"verdict":{"en":"Keep 5 for Explosives Station 3; the rest is a decent 1000 coin sale.","zh":"留5个升级爆炸物工作台3级，其余按1000钱币卖。"},"use":{"en":"It goes into the Deadline, Wolfpack, Explosive Mine, Fireworks Box, Blaze Grenade and Heavy Fuze Grenade, and Explosives Station 3 takes 5.","zh":"用于死线、狼群、爆炸地雷、烟花箱、火焰手雷和重型引信手雷，爆炸物工作台3级要5个。"},"obtain":{"en":"Kill a Comet or a Leaper, or search industrial and security containers. The Power Out quest pays 5. Two Crude Explosives and two Oil craft one at Refiner 2.","zh":"击杀彗星或跳跃者，或搜刮工业与安保类容器。任务“电力不足”奖励5个。两个粗制炸药加两份油可在精加工机2级合成。"},"tips":[{"en":"Recycling yields 2 Crude Explosives, so it is cheaper to keep or sell than to break down.","zh":"回收只得2个粗制炸药，不如留着或卖掉。"}],"sources":["https://arcraiders.wiki/wiki/Explosive_Compound"],"version":"2.0"},"fabric":{"verdict":{"en":"Never sell: Gear Bench 1 and Medical Lab 1 take 80 between them, and bandages use it.","zh":"别卖：装备工作台1级和医疗实验室1级共要80个，绷带也用它。"},"use":{"en":"It makes Bandages (5), Durable Cloth (14) and White Flags (10). It also restores 0.4 health per second for 25 seconds when used on its own.","zh":"用于制作绷带（5）、耐磨布料（14）和白旗（10）。单独使用每秒回0.4点生命，持续25秒。"},"obtain":{"en":"Commercial, medical and residential containers. Recycling Duct Tape (3) or ARC Thermo Lining (16) gives lots, and Celeste sells it for 1 Assorted Seed.","zh":"商业、医疗和居住类容器都有。回收胶带（3）或ARC隔热衬里（16）可大量获得，塞莱斯特1混合种子就卖。"},"tips":[{"en":"Worth just 50 coins, so spend your carry space on better loot once your upgrades are done.","zh":"只值50钱币，升级完成后背包空间留给更好的战利品。"}],"sources":["https://arcraiders.wiki/wiki/Fabric"],"version":"2.0"},"fertilizer":{"verdict":{"en":"No live project or recipe uses it: sell it, 1000 coins for a nature drop.","zh":"目前没有项目或配方需要它，直接卖掉，一份值1000钱币。"},"obtain":{"en":"It spawns in garden beds, such as the greenhouses in the Village on The Blue Gate and the hydroponic domes on Dam Battlegrounds. Wicker baskets also hold some.","zh":"刷新在花圃里，如蓝门的村庄温室和大坝战场的水培穹顶，柳条篮里也有。"},"tips":[{"en":"Recycling gives only 2 Assorted Seeds, so sell it unless you need seeds for Celeste.","zh":"回收只得2个混合种子，不缺种子换塞莱斯特的东西就直接卖。"}],"sources":["https://arcraiders.wiki/wiki/Fertilizer"],"version":"2.0"},"fluted_rotor_core":{"verdict":{"en":"A new 2.0 Amplified weapon material with unclear sources; keep it until recipes are confirmed.","zh":"2.0新增的强化武器材料，来源尚不明，配方确认前先留着。"},"use":{"en":"The game describes it as crafting material for Amplified weapons. No recipe, project or quest uses it yet, and it cannot be recycled.","zh":"游戏描述为强化武器制作材料。目前还没有配方、项目或任务使用它，也无法回收。"},"obtain":{"en":"The community wiki lists only generic scavenging and its page is still a stub, so no spawn location is confirmed.","zh":"社区维基只写了常规搜刮，页面仍是草稿，尚无确认的刷新点。"},"tips":[{"en":"It sells for 5000, so if you never find a use, selling is a safe fallback.","zh":"能卖5000钱币，最终用不上卖掉也不亏。"}],"sources":["https://arcraiders.wiki/wiki/Fluted_Rotor_Core"],"version":"2.0"},"fossilized_lightning":{"verdict":{"en":"Sell or recycle it: it has no quest use, and recycling gives Explosive Compound.","zh":"卖掉或回收：没有任何任务用途，回收可得炸药混合物。"},"obtain":{"en":"It is found at the epicenter of lightning strikes on maps with the Electromagnetic Storm condition. Nature loot can also hold it.","zh":"出现在“电磁风暴”条件的地图上，闪电落点的中心，自然类战利品里也可能有。"},"tips":[{"en":"Recycling gives 3 Explosive Compound (1000 each), the same as the 4000 coin sale or better. Your Explosives Station 3 upgrade needs 5 compound.","zh":"回收得3份炸药混合物（每份1000），与4000钱币卖价相当甚至更好；爆炸物工作台3级正好要5份。"}],"sources":["https://arcraiders.wiki/wiki/Fossilized_Lightning"],"version":"2.0"},"frigate_diagnostic_node":{"verdict":{"en":"Use it for 1000 Research Points or sell it for 3000; it has no other purpose.","zh":"可用来换1000研究点，或卖3000钱币，没有别的用途。"},"obtain":{"en":"It is found in the trail left behind by a Frigate. The wiki gives no map or spawn point, and it cannot be recycled.","zh":"掉在“护卫者”留下的轨迹上。维基没有给出地图或刷新点，也无法回收。"},"tips":[{"en":"Use it if you need the Research Station upgrades; otherwise take the coins, since nothing needs it.","zh":"研究站升级缺研究点就用掉，否则没有项目需要它，直接卖钱。"}],"sources":["https://arcraiders.wiki/wiki/Frigate_Diagnostic_Node"],"version":"2.0"},"frigate_inductor":{"verdict":{"en":"Keep exactly one: it is the single gate to Research Station level 4, and it sells for a lot if you never get there.","zh":"只留一个：它是研究站 4 级的唯一门槛，用不上再卖。"},"obtain":{"en":"It comes from scavenging the ARC Frigate, so you need to bring one down and loot it. Nothing else is known to drop it. The wiki gives no map or area, so treat any specific spot claims with suspicion.","zh":"来自拆解“ARC护卫者”，需要先击落并搜刮。目前没有其他来源，社区也没给出具体地图或区域。"},"tips":[{"en":"Research Station levels also need a matching Outpost level, so the inductor is wasted if you pick it up long before you are ready.","zh":"研究站升级还要求哨站等级达标，太早拿到也派不上用场。"},{"en":"Recycling gives Advanced ARC Powercells and ARC Circuitry; only do that once level 4 is done.","zh":"回收可得高级ARC能量电池和ARC线圈，等研究站升到 4 级后再考虑。"}],"sources":["https://arcraiders.wiki/wiki/Frigate_Inductor","https://arcraiders.wiki/wiki/Research_Station"],"version":"2.0"},"great_mullein":{"verdict":{"en":"A cheap herb worth a few copies for Antiseptic and Herbal Bandages; do not stockpile it.","zh":"便宜的草药，留几株做防腐剂和草药绷带即可，无需囤。"},"use":{"en":"Antiseptic takes 2 and an Herbal Bandage takes 1, so a handful covers several crafts. One quest, Doctor's Orders, also asks for one.","zh":"防腐剂要 2 株，草药绷带要 1 株，几株就够做好几次。任务“医生的订单”也要 1 株。"},"obtain":{"en":"Harvest the plants in nature areas or open Wicker Baskets and backpacks. Celeste also sells it for 5 Assorted Seeds, 10 per day, which is the easy route if you have seeds to burn.","zh":"在自然区域采摘植株，或开柳条篮和背包。塞莱斯特也以 5 个混合种子出售，每日限购 10 个，有闲置种子时最省事。"},"tips":[{"en":"Once you have what Antiseptic needs, recycle extras into Assorted Seeds (2 each).","zh":"够做防腐剂之后，多余的回收成混合种子（每株 2 个）。"}],"sources":["https://arcraiders.wiki/wiki/Great_Mullein"],"version":"2.0"},"hand_drill":{"verdict":{"en":"Keep three if you want the Anvil I; otherwise it is only worth its 640 coin sale price.","zh":"想做“铁砧 I”就留 3 个，否则只能按 640 钱币卖。"},"use":{"en":"Its only crafting use is Anvil I, which needs three. Recycling returns a single Mechanical Component, which is poor.","zh":"唯一的制作用途是“铁砧 I”（需要 3 个）。回收只得 1 个机械元件，不划算。"},"obtain":{"en":"New in 2.0. It spawns in Mechanical and Industrial type containers; the wiki names no specific map or area yet.","zh":"2.0 新增物品。出现在机械类和工业类容器中，目前没有具体地图或区域的记录。"},"tips":[{"en":"Do not recycle one before you decide on the Anvil, since salvage only gives 2 Metal Parts.","zh":"没决定要不要做“铁砧”之前别回收，拆解只得 2 个金属零件。"}],"sources":["https://arcraiders.wiki/wiki/Hand_Drill"],"version":"2.0"},"heavy_gun_parts":{"verdict":{"en":"The bottleneck for heavy weapon crafts: keep about 3 per gun you plan to build, then sell the rest.","zh":"重型武器制作的瓶颈：每把计划造的枪留约 3 个，其余卖掉。"},"use":{"en":"Anvil I, Bettina I, Hullcracker I, Rascal I and Vulcano I each take 3 at tier one, and Complex Gun Parts takes 2. Several quests also hand them out, so check rewards before buying.","zh":"“铁砧 I”“贝蒂娜 I”“裂甲者 I”“无赖 I”“火山 I”一阶都要 3 个，复杂枪械零件要 2 个。不少任务会送，购买前先看看奖励。"},"obtain":{"en":"Kill Rocketeers (the wiki also lists Bombardier) and loot the Security and Raider type containers. Celeste sells 3 a day for 15 Assorted Seeds each, a decent seed sink. Quests like Nothing Ventured and Untended Garden give 3 each.","zh":"击杀“火箭手”（社区资料还列有“投弹手”），并搜刮安保类和奇袭者类容器。塞莱斯特每天限购 3 个，每个 15 混合种子。任务“焉得虎子”“无人照看的农园”各送 3 个。"},"tips":[{"en":"Recycling only gives 2 Simple Gun Parts, while crafting one costs 4. Never recycle if you can sell for 700.","zh":"回收只得 2 个简易枪械零件，而制作一个要 4 个，不如直接卖 700。"}],"sources":["https://arcraiders.wiki/wiki/Heavy_Gun_Parts"],"version":"2.0"},"laser_level":{"verdict":{"en":"Pure loot: no recipe or upgrade uses it, so sell it for 2000 unless you need the Steel Springs.","zh":"纯战利品：没有配方或升级用它，直接卖 2000，除非你缺钢质弹簧。"},"obtain":{"en":"A 2.0 find in Mechanical and Industrial containers. No community post names a better area yet.","zh":"2.0 新增，出现在机械类和工业类容器。目前没有人总结出更好的刷取地点。"},"tips":[{"en":"Recycling gives 2 Mechanical Components and 2 Steel Springs, which feed Mod Components, so it is useful if you craft those.","zh":"回收得 2 个机械元件和 2 个钢质弹簧，可用来做改装零件。"}],"sources":["https://arcraiders.wiki/wiki/Laser_Level"],"version":"2.0"},"lemon":{"verdict":{"en":"Grab a few for the Scrappy level 3 upgrade, then treat it as a 640 coin sell item.","zh":"拿几个给“废品仔”3 级升级，之后当作 640 钱币的出售品。"},"use":{"en":"Scrappy level 3 needs 3 Lemons. Scrappy can also eat one as a feed boost, which gives Chemicals. Eating it yourself only restores a little stamina.","zh":"“废品仔”3 级升级需要 3 个柠檬。也可以喂给废品仔换取化学品加成。自己吃只恢复少量耐力。"},"obtain":{"en":"Walk around lemon trees (small trees with a thick green crown) and pick up the fruit below them, 1 to 4 per tree. Wicker Baskets also hold some. If no prompt shows, circle the tree.","zh":"绕着柠檬树（树冠浓密的小树）走，捡树下的果实，每棵 1 至 4 个。柳条篮里也有。看不到提示时绕树转一圈。"},"tips":[{"en":"Recycling gives 3 Assorted Seeds, which beats the 2 you get from salvage.","zh":"回收得 3 个混合种子，多于拆解的 2 个。"}],"sources":["https://arcraiders.wiki/wiki/Lemon","https://arcraiders.wiki/wiki/Scrappy"],"version":"2.0"},"light_gun_parts":{"verdict":{"en":"Only the Bobcat needs it, so keep a few for that and sell the rest at 700.","zh":"只有“山猫”会用到，留几个就够，其余卖 700。"},"use":{"en":"Bobcat I needs 3, and Complex Gun Parts needs 2. The wiki also lists higher tiers of Bobcat, Burletta and Stiletto for repair or upgrade.","zh":"“山猫 I”需要 3 个，复杂枪械零件需要 2 个。社区资料还提到更高阶的“山猫”“布尔莱塔”“细剑”会用到。"},"obtain":{"en":"Loot Raider and Security type containers. Celeste sells 3 a day for 15 Assorted Seeds each.","zh":"搜刮奇袭者类和安保类容器。塞莱斯特每天限购 3 个，每个 15 混合种子。"},"tips":[{"en":"Recycling returns 2 Simple Gun Parts for something that costs 4 to craft, so don't recycle it.","zh":"制作要 4 个简易枪械零件，回收只返还 2 个，不要回收。"}],"sources":["https://arcraiders.wiki/wiki/Light_Gun_Parts"],"version":"2.0"},"magnet":{"verdict":{"en":"Keep around 10 while you work through Venator, Canto and Mk. 2 augments; they are cheap to rebuy from Celeste.","zh":"在做“复仇者”“颂歌”和 Mk. 2 增幅器期间留约 10 个，塞莱斯特处买很便宜。"},"use":{"en":"Canto I and Venator I take 5 each. Combat, Looting and Tactical Mk. 2 take 3 each. No live project needs it, so stock only what those crafts use.","zh":"“颂歌 I”和“复仇者 I”各要 5 个，战斗、搜刮、战术 Mk. 2 各要 3 个。目前没有项目需要它，按这些制作所需留够即可。"},"obtain":{"en":"Look in Exodus type containers; the wiki names no specific map. Celeste sells 10 a day for 6 seeds each. Quests such as Keeping the Memory and Tribute to Toledo pay 5 each.","zh":"出现在 离巢类容器，社区没给具体地图。塞莱斯特每天限购 10 个，每个 6 种子。任务“铭记于心”和“给托雷多管理层上贡”各送 5 个。"},"tips":[{"en":"At 300 coins it is a poor sale, and recycling gives only 2 Metal Parts.","zh":"只值 300 钱币，回收也只得 2 个金属零件，卖了不划算。"}],"sources":["https://arcraiders.wiki/wiki/Magnet"],"version":"2.0"},"magnetic_accelerator":{"verdict":{"en":"Do not sell it: Gunsmith level 4, many top weapons and several repairs all eat these.","zh":"别卖：武器工作台 4 级、多把高阶武器和部分维修都要用它。"},"use":{"en":"Gunsmith 4 needs 3. Aphelion, Dolabra, Equalizer and Jupiter each take 3 to craft, and the wiki says repairing them takes 2. Trophy Display phase 4 wants 10.","zh":"武器工作台 4 级要 3 个。“远日点”“錾斧”“制裁者”“木星”制作各要 3 个，社区资料称维修要 2 个。战利品展示架第 4 阶段要 10 个。"},"obtain":{"en":"Kill the Matriarch or The Queen. It also shows up in Exodus type containers, and the Refiner level 3 can craft it from 2 Advanced Mechanical Components and 2 ARC Motion Cores. The Line in the Sand quest gives 2.","zh":"击杀“族母”或“女王”。离巢类容器也会出，精加工机 3 级可用 2 个高级机械元件和 2 个ARC运动核心制作。任务“沙滩防线”送 2 个。"},"tips":[{"en":"Crafting one from components gets you back only half on recycling, so never recycle it for parts.","zh":"回收只能返还一半材料，别为了拿零件去回收。"}],"sources":["https://arcraiders.wiki/wiki/Magnetic_Accelerator"],"version":"2.0"},"mechanical_components":{"verdict":{"en":"The workhorse of weapon crafts: keep a stack of 20 or more instead of selling at 640.","zh":"制作武器的主力材料：留 20 个以上，别按 640 卖掉。"},"use":{"en":"Gunsmith level 2 needs 5, mods like Extended Barrel II and Silencer I need 2 to 3, and many weapon tiers need 3 to 6. Mod Components also eat them.","zh":"武器工作台 2 级要 5 个，加长枪管 II、消音器 I 等配件要 2 至 3 个，多款武器一阶要 3 至 6 个，改装零件也要用。"},"obtain":{"en":"Kill Leapers, Bastions, Bombardiers and Shredders, or open Mechanical type containers. Three quests (A Wrench in the Works, Industrial Espionage, Water Troubles) give some. You can also refine them: 7 Metal Parts and 3 Rubber Parts at Refiner 1.","zh":"击杀“跳跃者”“堡垒”“投弹手”“粉碎者”，或开机械类容器。任务“暗中破坏”“工业间谍”“水源问题”也送。精加工机 1 级可用 7 个金属零件和 3 个橡胶零件合成。"},"tips":[{"en":"If you have spare Metal Parts, crafting is a fair backup when drops run dry.","zh":"金属零件有富余时，合成是掉落不足时的备选。"}],"sources":["https://arcraiders.wiki/wiki/Mechanical_Components"],"version":"2.0"},"medium_gun_parts":{"verdict":{"en":"Keep a few for rifle crafts; do not recycle, since crafting one costs twice what recycling returns.","zh":"为步枪制作留几个；别回收，合成一个的成本是回收所得的两倍。"},"use":{"en":"Canto I, Osprey I, Renegade I, Tempest I, Torrente I and Venator I each take 3, and Complex Gun Parts takes 2. Four quests also ask for them.","zh":"“颂歌 I”“鱼鹰 I”“叛逆 I”“风暴 I”“奔流 I”“复仇者 I”各要 3 个，复杂枪械零件要 2 个，还有四个任务需要。"},"obtain":{"en":"Kill Bastions and Sentinels, and loot Raider and Security type containers. Celeste sells 3 per day for 15 seeds each, and quests like Straight Record and Flickering Threat pay 5.","zh":"击杀“堡垒”和“哨卫”，搜刮奇袭者类和安保类容器。塞莱斯特每天限购 3 个，每个 15 种子，任务“理顺记录”“初露端倪的威胁”各送 5 个。"},"tips":[{"en":"Stacks hold 5 and weigh 0.4 each, so don't hoard beyond what your planned guns need.","zh":"单组最多 5 个且每个重 0.4，别超出计划武器所需太多。"}],"sources":["https://arcraiders.wiki/wiki/Medium_Gun_Parts"],"version":"2.0"},"metal_parts":{"verdict":{"en":"Never sell or break these: Gunsmith 1 and Refiner 1 upgrades need piles, and weapon crafts and ammo keep using them.","zh":"别卖也别浪费：武器工作台、精加工机升级要一大堆，武器和弹药制作也一直在用。"},"use":{"en":"Gunsmith 1 needs 20 and Refiner 1 needs 60. Weapon mods and ammo use 3 to 6 each, Mechanical Components 7.","zh":"武器工作台 1 级要 20 个，精加工机 1 级要 60 个。配件和弹药各用 3 至 6 个，机械元件要 7 个。"},"obtain":{"en":"Open Metal Crates, car hoods and server racks; the wiki lists Mechanical, Industrial, Electrical and Technological areas. Dismantling magnets and Mechanical Components gives some back. Celeste sells it for seeds.","zh":"开金属箱、车头盖和服务器机架，社区资料列出机械、工业、电气和科技类区域。拆磁铁和机械元件也能得到一些。塞莱斯特也用种子出售。"},"tips":[{"en":"The wiki says Metal Parts cannot be recycled, and at 75 coins a stack of 50 is weak money.","zh":"社区资料称金属零件无法回收，单价 75，一组 50 个也卖不了多少钱。"}],"sources":["https://arcraiders.wiki/wiki/Metal_Parts"],"version":"2.0"},"mod_components":{"verdict":{"en":"Keep them for tier III mods; at 1750 they are decent coin only if you skip Gunsmith 3.","zh":"留着做三阶配件；不做武器工作台 3 级配件时 1750 一个才值得卖。"},"use":{"en":"Every tier III mod blueprint takes 2, plus 5 Duct Tape, 8 Wires or 5 Steel Springs depending on the mod. A few quests and the Trophy Display project want them too.","zh":"所有三阶配件都要 2 个，另加 5 个胶带、8 条导线或 5 个钢质弹簧。部分任务和战利品展示架也需要。"},"obtain":{"en":"Found in Security type containers; no named map yet. You can also refine them from 2 Mechanical Components and 2 Steel Springs. A Wrench in the Works pays 3.","zh":"出现在安保类容器，暂无具体地图。也可用 2 个机械元件和 2 个钢质弹簧合成。任务“暗中破坏”送 3 个。"},"tips":[{"en":"Recycling gives back only half of the crafting cost, so craft or keep instead.","zh":"回收只返还制作成本的一半，要么合成要么留着。"}],"sources":["https://arcraiders.wiki/wiki/Mod_Components"],"version":"2.0"},"moss":{"verdict":{"en":"One piece is enough for a Defibrillator; no live project needs it, so recycle the rest for seeds.","zh":"做一个复苏剂只要 1 个，目前没有项目需要它，其余回收成种子。"},"use":{"en":"A Defibrillator takes 1 Moss and 9 Plastic Parts. It heals 1 per second for 10 seconds, which is weak.","zh":"复苏剂需要 1 个苔藓加 9 个塑料零件。治疗效果每秒 1 点持续 10 秒，很弱。"},"obtain":{"en":"Harvest dead trees and Hydroponic Domes (the Hydroponic Dome Complex on Dam Battlegrounds has plenty). Wicker Baskets also hold it. Celeste sells 5 a day for 10 seeds each.","zh":"采集枯树和水培穹顶（大坝战场的水培穹顶综合体较多），柳条篮里也有。塞莱斯特每天限购 5 个，每个 10 种子。"},"tips":[{"en":"Recycling gives 3 Assorted Seeds each, so surplus Moss is a seed source.","zh":"回收每个得 3 个混合种子，多余的苔藓可以换种子。"}],"sources":["https://arcraiders.wiki/wiki/Moss"],"version":"2.0"},"mushroom":{"verdict":{"en":"Stockpile 12 for the Scrappy level 5 upgrade; at 1000 coins it is also a nice sell.","zh":"为“废品仔”5 级升级囤 12 个；单价 1000，卖也不错。"},"use":{"en":"Scrappy level 5 needs 12. Feeding one to Scrappy gives Plastic Parts. It heals 15 health, but you will not use it for that.","zh":"“废品仔”5 级要 12 个。喂给废品仔可得塑料零件。可回复 15 点生命，但没必要这么用。"},"obtain":{"en":"On Dam Battlegrounds try Water Treatment Control, the Hydroponic Dome Complex, the Central Swamp Lift and the wreckage near Baron Husk. On The Spaceport, the East Container Yard has a tree with three guaranteed. Riven Tides: Dried Riverbed trees. Wicker Baskets too.","zh":"大坝战场：水处理控制中心、水培穹顶综合体、中央沼泽暗门、“男爵外壳”附近残骸。太空港：东侧集装箱堆场有一棵必出 3 个的树。裂潮镇：干涸河床的树上。柳条篮也有。"},"tips":[{"en":"It cannot be recycled or salvaged, so selling is the only way to cash out.","zh":"无法回收或拆解，想变现只能出售。"}],"sources":["https://arcraiders.wiki/wiki/Mushroom","https://arcraiders.wiki/wiki/Scrappy"],"version":"2.0"},"oil":{"verdict":{"en":"Cheap and easy to rebuy: keep a few for Renegade I and Explosive Compound, sell or recycle the rest.","zh":"便宜又好买：留几个做叛逆 I 和炸药混合物，其余卖掉或回收。"},"use":{"en":"Renegade I takes 5. Explosive Compound and Blaze Grenade take 2 each, and Power Out pays 5. No live project needs it.","zh":"“叛逆 I”要 5 个，炸药混合物和火焰手雷各要 2 个，任务“电力不足”送 5 个。目前没有项目需要它。"},"obtain":{"en":"Mechanical type containers. Motors recycle into the most Oil per item, and Celeste sells 10 a day at 6 seeds each, which is the easy way to stock up.","zh":"机械类容器。电机回收出的油最多，塞莱斯特每天限购 10 个，每个 6 种子，是囤货的捷径。"},"tips":[{"en":"At 300 coins it sells poorly; recycling into 3 Chemicals is often the better move.","zh":"仅值 300 钱币，回收成 3 个化学品往往更划算。"}],"sources":["https://arcraiders.wiki/wiki/Oil"],"version":"2.0"},"olives":{"verdict":{"en":"Pick six for the Scrappy level 4 upgrade; every extra sells for 640.","zh":"为“废品仔”4 级升级采 6 个，多余的按 640 卖。"},"use":{"en":"Scrappy level 4 needs 6 Olives and 6 Prickly Pears. Feeding one to Scrappy gives Fabric.","zh":"“废品仔”4 级升级要 6 个橄榄和 6 个仙人掌果。喂给废品仔可得布料。"},"obtain":{"en":"Head to the Olive Grove on The Blue Gate and check the ground under each tree for 1 to 4 olives. Look for a small white circle when you are close. Wicker Baskets also hold some.","zh":"去蓝门的橄榄树林，查看每棵树下的 1 至 4 个橄榄。靠近时会出现白色小圆圈。柳条篮里也有。"},"tips":[{"en":"Unused ones recycle into 2 Assorted Seeds each.","zh":"用不上的回收后每个得 2 个混合种子。"}],"sources":["https://arcraiders.wiki/wiki/Olives","https://arcraiders.wiki/wiki/Scrappy"],"version":"2.0"},"planks":{"verdict":{"en":"Needed in bulk for Research Station level 1, so buy them with spare seeds rather than hunt.","zh":"研究站 1 级要大量木板，用多余种子买比到处找更省事。"},"use":{"en":"Research Station level 1 takes 35 Planks. They are also needed for Outpost furniture and a Sheltered Retreat phase, and 5 plus 500 Research Points makes a White Flag blueprint.","zh":"研究站 1 级要 35 块木板。哨站家具和“掩护撤退”某阶段也要，5 块加 500 研究点数可得白旗蓝图。"},"obtain":{"en":"New in 2.0. Sources are scavenging and Celeste, who sells them for 3 Assorted Seeds each. No community post names an area yet, so buying is the sure way.","zh":"2.0 新增。来源是搜刮和塞莱斯特（每块 3 混合种子）。社区还没总结出具体区域，买最稳妥。"},"tips":[{"en":"The wiki says Planks cannot be recycled, and at 100 coins they sell poorly.","zh":"社区资料称木板无法回收，单价 100，卖不了几个钱。"}],"sources":["https://arcraiders.wiki/wiki/Planks","https://arcraiders.wiki/wiki/Research_Station"],"version":"2.0"},"plastic_parts":{"verdict":{"en":"Keep a big stack; Gear Bench 1, Utility Station 1 and many crafts want dozens.","zh":"多囤一些：装备工作台1级、工具工作台1级和很多制作都要几十个。"},"use":{"en":"Gear Bench 1 needs 25 and Utility Station 1 needs 50. Tier I mods use 6 apiece, and Defibrillator 9 and Electrical Components 8.","zh":"装备工作台 1 级要 25 个，工具工作台 1 级要 50 个。一阶配件各要 6 个，复苏剂要 9 个，电子元件要 8 个。"},"obtain":{"en":"Open Industrial drawers and server racks, and check Commercial, Residential and Technological areas. Celeste sells it for seeds, and dismantling cooling fans or recorders yields 10 to 14 each.","zh":"开工业抽屉和服务器机架，搜刮商业、居住和科技类区域。塞莱斯特用种子出售，拆冷却风扇、录音机等可得 10 至 14 个。"},"tips":[{"en":"The wiki says it cannot be recycled, and it only sells for 60 coins.","zh":"社区资料称无法回收，单价只有 60。"}],"sources":["https://arcraiders.wiki/wiki/Plastic_Parts"],"version":"2.0"},"pneumatic_actuator":{"verdict":{"en":"A 2.0 Amplified weapon material worth 5000; hold it only if you are building one of those guns.","zh":"2.0 新增的强化武器材料，值 5000；只有在造强化武器时才留。"},"use":{"en":"Used to craft Amplified weapons. The local data lists no recycle output and no workshop or quest uses.","zh":"用于制作强化武器。本站数据里没有回收产物，也没有工作台或任务需求。"},"obtain":{"en":"The community wiki has no page for it yet, so the exact drop spots are not documented. Check back after more raids are reported.","zh":"社区维基尚无词条，具体掉落点没有记录，等玩家实测之后再补充。"},"tips":[{"en":"If you are not planning an Amplified build, it sells for a very good price.","zh":"不打算做强化武器的话，卖价相当可观。"}],"sources":["https://arcraiders.wiki/wiki/Pneumatic_Actuator"],"version":"2.0"},"power_rod":{"verdict":{"en":"Keep one for Tribute to Toledo and the gear it crafts; sell extras for 5000.","zh":"留一个给“给托雷多管理层上贡”和相关装备，多余的卖 5000。"},"use":{"en":"Heavy Shield takes 1, Powered Descender 1, and Snap Hook 2. Tribute to Toledo needs one. The wiki also says one opens a door in the Power Generation Complex on Dam Battlegrounds.","zh":"重型护盾要 1 个，动力下降器 1 个，安全钩 2 个，任务“给托雷多管理层上贡”需要 1 个。社区资料还称它可打开大坝战场发电厂综合体的一扇门。"},"obtain":{"en":"Look in Exodus type containers (no specific map yet). Refiner 3 can craft it from 2 Advanced Electrical Components and 2 ARC Circuitry, and the Groundbreaking quest rewards one.","zh":"出现在 离巢类容器（暂无具体地图）。精加工机 3 级可用 2 个高级电子元件和 2 个ARC线圈合成，任务“突破性进展”送 1 个。"},"tips":[{"en":"Recycling returns only half the crafting cost, so selling beats recycling.","zh":"回收只返还制作成本的一半，卖比回收划算。"}],"sources":["https://arcraiders.wiki/wiki/Power_Rod"],"version":"2.0"},"pressure_regulator":{"verdict":{"en":"An Epic Amplification ingredient worth 5,000 coins: hold it for Amplified crafts, and sell only if you have no use.","zh":"价值 5000 的史诗级增幅材料：留着做增幅武器，用不上再卖。"},"obtain":{"en":"A guide names Emperor Payloads dropped during the Redirection condition on Pendola Pass as an important source. Treat that as a lead, not a guarantee; nothing confirms a drop rate.","zh":"有攻略称彭多拉山口“航向重定向”期间的“帝王”载荷是重要来源，但未见掉率数据，仅作参考。"},"tips":[{"en":"It stacks to only 3, so a full carry slot of them is worth a lot; put them in your Safe Pocket if you find any.","zh":"堆叠上限只有 3，但价值极高，捡到后优先放进安全口袋。"}],"sources":["https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://metaforge.app/arc-raiders/arc-raiders-redirection-map-condition-guide-emperor-relays-beacons-and-payload-loot"],"version":"2.0"},"prickly_pear":{"verdict":{"en":"Keep 6 for the Scrappy level 4 upgrade; after that it is a decent 640-coin sell.","zh":"留 6 个给废品仔 4 级升级，之后可以卖 640 一个。"},"use":{"en":"Eating one gives a small stamina boost. It is also an ingredient of Fruit Mix, together with a Lemon and an Apricot.","zh":"吃掉可小幅恢复耐力，也是“水果拼盘”的原料之一，需配合柠檬和杏子。"},"obtain":{"en":"Check the base of cacti in Nature zones (1-3 pears each) and Wicker Baskets. Guides point to Marano Park in Buried City, the north and the area near Pattern House on Dam Battlegrounds, and Spaceport edges. Lush Blooms makes baskets more reliable.","zh":"在自然区域的仙人掌根部找（每株 1–3 个），或搜柳条篮。攻略多提到掩埋废城的马拉诺公园、大坝战场北部和壁画屋附近、太空港边缘；“收获季节”期间柳条篮更稳。"},"tips":[{"en":"Put the pears in your Safe Pocket: nature items have no found-in-raid limit, so you can hand them to Scrappy later.","zh":"放进安全口袋即可，自然类物品没有“带出才算”的限制，回去再交给废品仔。"},{"en":"Recycling only returns Assorted Seeds, so selling beats recycling.","zh":"回收只能得到混合种子，直接卖更划算。"}],"sources":["https://arcraiders.wiki/wiki/Prickly_Pear","https://www.shacknews.com/article/147115/where-to-get-prickly-pears-in-arc-raiders"],"version":"2.0"},"processor":{"verdict":{"en":"Keep at least 3 for any Mk. 3 augment you plan to craft, and sell or buy the rest by need.","zh":"想做 Mk. 3 增幅就至少留 3 个，多余的按需出售。"},"use":{"en":"Every Mk. 3 augment (Combat, Looting, Tactical) costs 3 Processors plus Advanced Electrical Components. The Trigger 'Nade also takes one.","zh":"所有 Mk. 3 增幅（战斗、搜刮、战术）都要 3 个处理器和高级电子元件，触发式手雷也要 1 个。"},"obtain":{"en":"Loot Server Racks, Recording Panels, Oscilloscopes and Computers in Technological areas. A May guide also suggests Stella Montis lockboxes in the Assembly Workshop and Medical Research. Celeste sells 5 a day for seeds.","zh":"在科技类区域搜刮服务器机架、录音面板、示波器和电脑。有攻略建议去星辰山组装厂车间和医学研究部的箱柜。塞莱斯特每天限售 5 个。"},"tips":[{"en":"Recycling returns only Plastic Parts and Wires, far below its 500 value, so never recycle it.","zh":"回收只得塑料零件和导线，远不如 500 的售价，别回收。"}],"sources":["https://arcraiders.wiki/wiki/Processor","https://nerdschalk.com/arc-raiders-processor-location-use-guide/"],"version":"2.0"},"propellant_valve_assembly":{"verdict":{"en":"Epic Amplification material worth 5,000 coins; keep it for Amplified weapon crafts.","zh":"价值 5000 的史诗级增幅材料，留着做增幅武器。"},"obtain":{"en":"I could not find a confirmed source. It is likely tied to the same Pendola Pass content as the Pressure Regulator, but no guide says so yet, so check the in-game item page.","zh":"暂未找到可靠来源。可能与压力调节器同属彭多拉山口内容，但尚无攻略证实，请以游戏内信息为准。"},"tips":[{"en":"New in 2.0 and stacks to 3; do not sell before you know what your Amplified crafts need.","zh":"2.0 新增，堆叠上限 3；先弄清增幅制作的需求再考虑出售。"}],"sources":["https://arcraiders.wiki/wiki/Pressure_Regulator"],"version":"2.0"},"radial_press":{"verdict":{"en":"Keep 3 for the Gunsmith level 4 upgrade; every extra is a 3,000-coin sale.","zh":"留 3 个给武器工作台 4 级，多余的每个能卖 3000。"},"obtain":{"en":"The wiki only says it is scavenged in Mechanical and Industrial areas, and no guide gives a container or map. Search machinery-heavy industrial spots and treat any find as valuable.","zh":"维基只说在机械与工业类区域搜刮得到，暂无具体地图或容器信息。多搜机械设备密集的工业区。"},"tips":[{"en":"Gunsmith 4 also needs an Emperor Modulator from the Fallen Emperor on Pendola Pass, so the Press alone will not finish the upgrade.","zh":"武器工作台 4 级还需要彭多拉山口陨落帝王里的帝王调制器，只凑齐径向压力机还不够。"},{"en":"Recycling gives one Advanced Mechanical Components, which is worth much less than selling.","zh":"回收只得 1 个高级机械元件，远不如直接卖。"}],"sources":["https://arcraiders.wiki/wiki/Radial_Press"],"version":"2.0"},"raider_logbook":{"verdict":{"en":"Keep 3 for the Research Station level 2 upgrade; after that it is a plain 640-coin sale.","zh":"留 3 个给研究站 2 级升级，之后当 640 的杂物卖掉。"},"use":{"en":"Besides the upgrade, using one gives Research Points, which pay for blueprint crafts at the Research Station.","zh":"除了升级，使用一本还能获得研究点数，用于研究站解锁蓝图。"},"obtain":{"en":"The wiki lists it as scavenged in Raider areas only. I found no map-specific spawn, so loot Raider-type camps and containers as you pass.","zh":"维基只标注在奇袭者类区域搜刮得到，未见具体地图刷新点，路过奇袭者据点顺手搜即可。"},"tips":[{"en":"New in 2.0, so spawn data is thin; recheck after more players report spots.","zh":"2.0 新物品，来源信息还很少，之后可再核对。"}],"sources":["https://arcraiders.wiki/wiki/Raider_Logbook"],"version":"2.0"},"resin":{"verdict":{"en":"Sell it: at 1,000 coins it is one of the best-paying common pickups.","zh":"直接卖：一个 1000，是最划算的常见拾取物之一。"},"use":{"en":"It heals about 1 HP per second for 10 seconds, which is weak. Its real value is the sale price, and the wiki notes extra value during Lush Blooms and Cold Snap.","zh":"每秒回 1 点生命、持续 10 秒，效果很弱，价值主要在卖钱；维基提到在“收获季节”和“寒潮”条件下更值钱。"},"obtain":{"en":"Open Wicker Baskets in Nature areas. Nothing more specific is documented.","zh":"在自然区域搜柳条篮，暂无更具体的位置信息。"},"tips":[{"en":"It cannot be recycled, so selling is the only conversion.","zh":"无法回收，只能卖。"}],"sources":["https://arcraiders.wiki/wiki/Resin"],"version":"2.0"},"roots":{"verdict":{"en":"No live project or upgrade needs it; sell for 640 each.","zh":"目前没有进行中的项目或升级要它，按 640 一个卖掉。"},"obtain":{"en":"Dig them at the base of certain trees in Nature areas, or find them in Wicker Baskets. The wiki does not name the trees or maps.","zh":"在自然区域特定树木根部采集，或搜柳条篮；维基未说明具体树木与地图。"},"tips":[{"en":"Despite the flavor text, the 640 value is not tiny. Recycling returns one seed only, so sell.","zh":"介绍里说“值几个钱”，但实际有 640。回收只得 1 颗种子，直接卖。"}],"sources":["https://arcraiders.wiki/wiki/Roots"],"version":"2.0"},"rope":{"verdict":{"en":"Keep a few for Grappling Hook or Yank Grenade crafts; otherwise it is a cheap 300-coin item.","zh":"留几根做钩爪或系索弹，其余只值 300。"},"use":{"en":"Grappling Hook takes 2 Ropes and Yank Grenade takes 1. The Grappling Hook blueprint itself also costs 10 Ropes at the Research Station.","zh":"钩爪要 2 根绳子，系索弹要 1 根；钩爪蓝图本身还需要在研究站交 10 根。"},"obtain":{"en":"Search Residential and Commercial areas. Celeste sells 5 a day, and recycling spent grappling gear also returns some.","zh":"搜住宅与商业类区域；塞莱斯特每天限售 5 根，回收用过的钩爪类装备也会返还。"},"sources":["https://arcraiders.wiki/wiki/Rope"],"version":"2.0"},"rubber_parts":{"verdict":{"en":"Keep 30 for the Gunsmith 1 upgrade; it also feeds many crafts and repairs.","zh":"留 30 个给武器工作台 1 级，也用于大量制作和修理。"},"obtain":{"en":"Search Mechanical, Industrial and Electrical areas. Rubber Parts cannot be recycled, but items like Ruined Accordion, Rubber Pad and ARC Flex Rubber recycle into a lot of them. Celeste sells them for 1 seed each.","zh":"搜机械、工业、电气类区域。橡胶零件本身无法回收，但“损毁的手风琴”“橡胶垫”“ARC弹性橡胶”等回收后能出很多；塞莱斯特 1 颗种子一个。"},"tips":[{"en":"Repairs use 1 to 6 per item, so keep a buffer for gear upkeep too.","zh":"修理装备每次也要消耗 1–6 个，留一点存货。"}],"sources":["https://arcraiders.wiki/wiki/Rubber_Parts"],"version":"2.0"},"sensors":{"verdict":{"en":"Hold a few: they feed traps and the Raider Hatch Key; no live project needs them.","zh":"留几个：用于地雷、手雷和奇袭者暗门钥匙；目前没有项目需要。"},"use":{"en":"The Raider Hatch Key takes 3. Explosive Mine, Surge Coil and Tagging Grenade take 1 each.","zh":"奇袭者暗门钥匙要 3 个；爆炸地雷、涌能线圈、标记手雷各要 1 个。"},"obtain":{"en":"Kill Snitches and Spotters, or loot Server Racks and Android drops. A farming guide recommends the metal cabinets in the Assembly Workshop and Medical Research on Stella Montis; Pilgrim's Peak on Blue Gate has many cabinets but heavy ARC patrols.","zh":"击杀告密者与侦察员，或搜服务器机架。有攻略推荐星辰山组装厂车间和医学研究部的金属柜；蓝门朝圣峰柜子多，但 ARC 巡逻很猛。"},"tips":[{"en":"Celeste sells 5 a day; buying beats risky farming if you are short.","zh":"塞莱斯特每天卖 5 个，缺口小时买比冒险刷更省。"}],"sources":["https://arcraiders.wiki/wiki/Sensors","https://players.com.ua/en/news/arc-raiders-guide-best-ways-to-farm-sensors/"],"version":"2.0"},"sheetmetal":{"verdict":{"en":"Keep 5 for the Sheltered Retreat project, then more if you build Outpost furniture.","zh":"留 5 个给“掩护撤退”项目，建哨站家具还需要更多。"},"obtain":{"en":"Scavenge it or buy it from Celeste for 3 seeds. The wiki gives no spawn spots.","zh":"搜刮得到，或向塞莱斯特花 3 颗种子购买；维基没有具体刷新点。"},"tips":[{"en":"It cannot be recycled, and at 100 coins it is not worth selling while you are building the Outpost.","zh":"无法回收，且只值 100，建哨站期间别卖。"}],"sources":["https://arcraiders.wiki/wiki/Sheet_Metal"],"version":"2.0"},"simple_gun_parts":{"verdict":{"en":"Keep a stock for weapon crafts and repairs; only surplus is worth selling at 330.","zh":"留一批做武器和修理，多出来的再按 330 卖。"},"use":{"en":"It goes into most tier I weapon crafts (4 to 6 each) and into Light, Medium and Heavy Gun Parts refining. Repairs also use it.","zh":"大多数 I 级武器制作要 4–6 个，也用于精炼轻、中、重型枪械零件，修理同样要用。"},"obtain":{"en":"Kill Hornets and Turrets, or loot Raider and Security areas. Celeste sells 5 a day.","zh":"击杀马蜂和炮塔，或搜奇袭者与安保类区域；塞莱斯特每天限售 5 个。"},"sources":["https://arcraiders.wiki/wiki/Simple_Gun_Parts"],"version":"2.0"},"speaker_component":{"verdict":{"en":"Keep 4 if you want a Photoelectric Cloak; sell the extras.","zh":"想做光电斗篷就留 4 个，多的卖掉。"},"use":{"en":"Photoelectric Cloak takes 4. Lure Grenade and Noisemaker take 1 each.","zh":"光电斗篷要 4 个，诱捕手雷和发声器各要 1 个。"},"obtain":{"en":"Search Commercial points of interest. Space Travel in Buried City is a commonly named spot; Plaza Rosa and Galleria are other candidates. Headphones recycle into one.","zh":"搜商业类地点，常被点名的是掩埋废城的航天大楼，其他还有罗莎广场和购物廊。回收耳机也能得到 1 个。"},"sources":["https://arcraiders.wiki/wiki/Speaker_Component","https://xboxplay.games/arc-raiders/where-to-find-speaker-components-in-arc-raiders-68653"],"version":"2.0"},"steel_spring":{"verdict":{"en":"Keep some for magazine mods and Torrente; no live project needs it.","zh":"留一些给扩容弹匣和“奔流”；目前没有项目需要。"},"obtain":{"en":"Check Metal Crates and shelves in Industrial areas. Guides name the Power Generation Complex basement, Water Treatment, and Hydroponic Dome Complex shelves. A Bad Feeling and other quests also reward some.","zh":"搜工业区的金属箱和货架。攻略提到发电厂综合体地下、水处理设施和水培穹顶综合体货架；“不祥预感”等任务也有奖励。"},"tips":[{"en":"Recycling gives just 2 Metal Parts, so do not break them down.","zh":"回收仅得 2 个金属零件，不要拆。"}],"sources":["https://arcraiders.wiki/wiki/Steel_Spring","https://nerdschalk.com/arc-raiders-steel-spring-location-use-guide/"],"version":"2.0"},"stencil_parts":{"verdict":{"en":"Never sell or waste them: they are the only way to apply stencils to weapons.","zh":"别卖：它们是给武器上贴花的唯一材料。"},"use":{"en":"Each application costs 2 to 15 parts depending on stencil rarity, based on tooltips reported by players.","zh":"每次上贴花消耗 2–15 个，取决于贴花稀有度（玩家报告的数据）。"},"obtain":{"en":"They drop at random in Commercial, Residential and Industrial areas. No guide names a best map or guaranteed container, and the Reward Pass also gives some.","zh":"在商业、住宅、工业区域随机掉落，没有公认的最佳地图或固定容器；奖励通行证也有。"},"tips":[{"en":"The skin travels with the gun, so a looted weapon takes your stencil with it.","zh":"贴花跟着枪走，枪被人捡走，贴花也就没了。"}],"sources":["https://arcraiders.wiki/wiki/Stencil_Parts","https://www.itechguides.com/how-to-farm-stencil-parts-in-arc-raiders/"],"version":"2.0"},"synthesized_fuel":{"verdict":{"en":"Keep 3 for the Explosives Station level 2 upgrade, then sell for 700 or keep one for a Trailblazer.","zh":"留 3 个给爆炸物工作台 2 级，之后可卖 700 或留 1 个做开拓者。"},"obtain":{"en":"Loot Exodus-tagged points of interest. Rocket Assembly on The Spaceport is the one most guides name, and recycling Rocket Thrusters returns 2. Celeste sells 5 a day.","zh":"搜带“离巢”标记的地点，攻略最常提到太空港的火箭组装区；回收火箭推进器可得 2 个。塞莱斯特每天限售 5 个。"},"tips":[{"en":"It explodes if shot, so do not stand next to a stack when fighting.","zh":"被击中会爆炸，交火时别站在旁边。"}],"sources":["https://arcraiders.wiki/wiki/Synthesized_Fuel","https://allthings.how/arc-raiders-exodus-loot-explained-what-it-is-and-where-to-find-it/"],"version":"2.0"},"syringe":{"verdict":{"en":"Keep 1 for the Doctor's Orders quest and a few for Vita Shot; recycle or sell the rest.","zh":"留 1 个交“医生的订单”，再留几个做生命针剂，其余回收或卖。"},"obtain":{"en":"Search Medical areas. Recycling Rusted Shut Medical Kits gives 2 each, and Vita Shots give 1. Celeste sells 5 a day.","zh":"搜医疗类区域；回收锈蚀封死的医疗箱可得 2 个，生命针剂 1 个。塞莱斯特每天限售 5 个。"},"tips":[{"en":"Recycling returns 3 Plastic Parts and 2 Chemicals, which can beat the 500 sale when you need crafting stock.","zh":"回收得 3 个塑料零件和 2 个化学品，缺材料时比卖 500 更有用。"}],"sources":["https://arcraiders.wiki/wiki/Syringe"],"version":"2.0"},"volcanic_rock":{"verdict":{"en":"A throwable that is worth 270 coins; sell it, there is no other use.","zh":"能扔的石头，值 270，除了卖没有别的用处。"},"obtain":{"en":"Pick it up from rocky ground on The Blue Gate. It is tagged Nature.","zh":"在蓝门的岩石地面上捡取，归类为自然。"},"tips":[{"en":"It cannot be recycled, and its 10 throwing damage is not worth a slot.","zh":"无法回收，投掷伤害只有 10，不值得占格子。"}],"sources":["https://arcraiders.wiki/wiki/Volcanic_Rock"],"version":"2.0"},"voltage_converter":{"verdict":{"en":"Keep a few for Heavy Shield (2 per craft); sell the rest.","zh":"留几个给重型护盾（每次用 2 个），其余卖掉。"},"obtain":{"en":"Search Electrical areas. Guides suggest Pilgrim's Peak on The Blue Gate, the Power Generation Complex on Dam Battlegrounds, and the Arrival Building on The Spaceport. Celeste sells 5 a day.","zh":"搜电气类区域。攻略推荐蓝门朝圣峰、大坝战场发电厂综合体和太空港到达大楼；塞莱斯特每天限售 5 个。"},"sources":["https://arcraiders.wiki/wiki/Voltage_Converter","https://nerdschalk.com/arc-raiders-voltage-converter-location-use-guide/"],"version":"2.0"},"wires":{"verdict":{"en":"Hoard it: attachments, quests and other crafts all want it.","zh":"一定要囤：配件、任务和其他制作都要。"},"use":{"en":"Silencers, muzzle brakes, compensators, chokes and extended barrels all use it, up to 8 at tier III.","zh":"消音器、枪口制退器、补偿器、收束器和加长枪管都要用，III 级最多 8 个。"},"obtain":{"en":"Loot Server Racks, Power Distribution Boxes, Oscilloscopes, Heaters and Generator Fuse Boxes in Electrical and Technological areas. Celeste sells 10 a day.","zh":"在电气和科技类区域搜服务器机架、配电箱、示波器、加热器和发电机保险丝盒。塞莱斯特每天限售 10 个。"},"tips":[{"en":"Do not recycle Wires; it only returns 2 Rubber Parts.","zh":"不要回收导线，只能换 2 个橡胶零件。"}],"sources":["https://arcraiders.wiki/wiki/Wires"],"version":"2.0"},"battered_weapon_rack":{"verdict":{"en":"The cheapest way to get guns out of your stash and onto the wall: 3 slots for 10 Sheet Metal.","zh":"最便宜的壁挂武器架：10 块金属板换 3 个挂位，能把枪从储备箱里腾出来。"},"use":{"en":"Weapon racks hold guns outside the stash grid. Place it in a room, right-click it and choose Decorate to hang weapons, or \"clear all attached items\" to send them back to the stash. Three slots is the smallest rack, so it suits a few display or backup guns.","zh":"武器架能在储备箱格子之外存放枪械。把它摆进房间，右键选“装饰”挂枪，选“清除所有附加物品”就能收回储备箱。3 个挂位是最小的一款，适合放几把展示枪或备用枪。"},"obtain":{"en":"Learn the Battered Weapon Rack Design (a Topside find), then craft it at the Research Station for 10 Sheet Metal. Recycling the piece returns the same 10 Sheet Metal.","zh":"先拿到并学会破旧武器展示架设计图（地表掉落），再到研究站用 10 块金属板制作。拆解成品会返还同样的 10 块金属板。"},"tips":[{"en":"The Sturdy rack costs the same 10 Sheet Metal and has 4 slots, so skip this one if you already own the Sturdy Design.","zh":"坚固武器展示架同样只要 10 块金属板，却有 4 个挂位；已有坚固款设计图就不必做这个。"}],"sources":["https://arcraiders.wiki/wiki/Furniture#Battered_Weapon_Rack","https://arcraiders.wiki/wiki/Outpost"],"version":"2.0"},"sturdy_weapon_rack":{"verdict":{"en":"Best value weapon rack: 4 slots for 10 Sheet Metal, same slots as the Polished one.","zh":"性价比最高的武器架：10 块金属板换 4 个挂位，与抛光款挂位一样多。"},"use":{"en":"Holds four guns outside your stash grid. Use it for the weapons you rotate between raids so they stop eating stash space.","zh":"可挂 4 把枪，不占储备箱格子。适合放几把常换的备用武器，给战利品腾地方。"},"obtain":{"en":"Craft at the Research Station after learning the Sturdy Weapon Rack Design from Topside loot. Cost is only 10 Sheet Metal.","zh":"在地表搜到并学会坚固武器展示架设计图后，到研究站用 10 块金属板制作。"},"tips":[{"en":"Polished costs double the metal plus Plastic Parts for the same 4 slots; it is a cosmetic upgrade only.","zh":"抛光款要两倍金属板外加塑料零件，挂位同样是 4 个，只是外观升级。"}],"sources":["https://arcraiders.wiki/wiki/Furniture#Sturdy_Weapon_Rack","https://www.pcgamer.com/games/third-person-shooter/dont-neglect-crafting-furniture-in-your-arc-raiders-outpost-it-unlocks-100s-of-extra-storage-slots/"],"version":"2.0"},"polished_weapon_rack":{"verdict":{"en":"Epic-looking rack with no extra slots over the Sturdy one; build it for looks.","zh":"史诗品质的武器架，挂位并不比坚固款多，主要图个好看。"},"use":{"en":"Four weapon slots, identical to the Sturdy rack. If you only care about storage, the Sturdy rack is the better deal.","zh":"有 4 个挂位，与坚固款相同。只在乎存储的话，坚固款更划算。"},"obtain":{"en":"Needs its Epic Design from Topside loot, then 20 Sheet Metal and 10 Plastic Parts at the Research Station.","zh":"需要地表掉落的史诗设计图，再到研究站花 20 块金属板和 10 个塑料零件制作。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Polished_Weapon_Rack"],"version":"2.0"},"battered_stash":{"verdict":{"en":"Entry-level Stash furniture; cheap, but only worth it if you have the Design to spare.","zh":"入门级储备箱家具，造价低，有多余设计图再做。"},"use":{"en":"The Stash furniture line adds storage inside your Outpost. The community wiki lists no slot count for this piece, so check the number in the in-game build menu before committing.","zh":"储备箱系列家具用来给哨站增加存储空间。社区维基没有列出这一件的格数，建造前请在游戏内建造菜单里确认。"},"obtain":{"en":"Learn the Battered Stash Design from Topside loot or Outpost upgrades, then craft with 3 Chemicals and 10 Sheet Metal.","zh":"从地表或哨站升级拿到破旧储备箱设计图后，用 3 份化学品和 10 块金属板制作。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Battered_Stash","https://www.pcgamer.com/games/third-person-shooter/dont-neglect-crafting-furniture-in-your-arc-raiders-outpost-it-unlocks-100s-of-extra-storage-slots/"],"version":"2.0"},"sturdy_stash":{"verdict":{"en":"Mid-tier Stash piece; it needs Voltage Converters, so craft it only once you have the Design.","zh":"中档储备箱家具，需要变电器，拿到设计图后再造。"},"use":{"en":"Adds Outpost storage. No slot count is published on the wiki; read it off the in-game recipe screen.","zh":"为哨站增加存储。维基没有公布格数，请看游戏内配方界面。"},"obtain":{"en":"Craft for 15 Sheet Metal and 3 Voltage Converters after learning the Design.","zh":"学会设计图后，用 15 块金属板和 3 个变电器制作。"},"tips":[{"en":"Voltage Converters are the bottleneck here; check your stock before recycling electronics.","zh":"变电器是瓶颈，拆解电子零件前先看看库存。"}],"sources":["https://arcraiders.wiki/wiki/Furniture#Sturdy_Stash"],"version":"2.0"},"polished_stash":{"verdict":{"en":"Rare Stash piece that only asks for a single Flow Controller on top of metal.","zh":"稀有储备箱，除金属板外只多要 1 个流量控制器。"},"use":{"en":"Another Outpost storage upgrade; slot count is not listed on the wiki.","zh":"又一款哨站存储家具，维基未列出格数。"},"obtain":{"en":"Craft for 15 Sheet Metal and 1 Flow Controller once the Polished Stash Design is learned.","zh":"学会精致储备箱设计图后，用 15 块金属板和 1 个流量控制器制作。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Polished_Stash"],"version":"2.0"},"ornate_stash":{"verdict":{"en":"Top Stash tier; costs 3 Ion Sputters, so build it last.","zh":"最高阶储备箱，需要 3 个离子溅射仪，最后再造。"},"use":{"en":"Epic Stash furniture for extra Outpost storage. Slot count is not listed on the wiki.","zh":"史诗级储备箱家具，用于扩充哨站存储，维基未列出格数。"},"obtain":{"en":"Craft for 20 Sheet Metal and 3 Ion Sputters after learning the Ornate Stash Design.","zh":"学会华丽储备箱设计图后，用 20 块金属板和 3 个离子溅射仪制作。"},"tips":[{"en":"Ion Sputters are the pricey part; do not spend them on decor first.","zh":"离子溅射仪是主要成本，别先拿去做装饰品。"}],"sources":["https://arcraiders.wiki/wiki/Furniture#Ornate_Stash"],"version":"2.0"},"battered_den_shelf":{"verdict":{"en":"The cheapest shelf: 2 slots for 5 Planks.","zh":"最便宜的架子：5 块木板换 2 个格位。"},"use":{"en":"A small wall shelf for trinkets and collectibles outside your stash; right-click to Decorate.","zh":"放小摆件和收藏品的小壁架，不占储备箱，右键选“装饰”即可摆放。"},"obtain":{"en":"Learn the Design from Topside loot; craft for 5 Planks.","zh":"从地表拿到设计图后，用 5 块木板制作。"},"tips":[{"en":"Only 2 slots; upgrade to the Sturdy version if you collect trinkets.","zh":"只有 2 格，收集摆件的话换坚固款。"}],"sources":["https://arcraiders.wiki/wiki/Furniture#Battered_Den_Shelf"],"version":"2.0"},"sturdy_den_shelf":{"verdict":{"en":"3 slots for 10 Planks: a fair step up from Battered.","zh":"10 块木板换 3 格，比破旧款划算一点。"},"use":{"en":"Display shelf for small items and trophies; Decorate it from the right-click menu.","zh":"用来陈列小物件和战利品，右键选“装饰”摆放。"},"obtain":{"en":"Craft for 10 Planks after learning the Design.","zh":"学会设计图后用 10 块木板制作。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Sturdy_Den_Shelf"],"version":"2.0"},"polished_den_shelf":{"verdict":{"en":"6 slots for 20 Planks; the sweet spot of the Den shelf line.","zh":"20 块木板换 6 格，巢穴架子系列里性价比最好。"},"use":{"en":"Six slots for display items; doubles the Sturdy shelf for twice the planks.","zh":"6 个格位，木板消耗翻倍，格数也翻倍。"},"obtain":{"en":"Craft for 20 Planks after learning the Rare Design.","zh":"学会稀有设计图后用 20 块木板制作。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Polished_Den_Shelf"],"version":"2.0"},"ornate_den_shelf":{"verdict":{"en":"Biggest Den shelf at 7 slots; only 1 more slot than Polished for 5 more Planks.","zh":"7 格的最大巢穴架子，比抛光款只多 1 格，多花 5 块木板。"},"use":{"en":"Seven display slots at Epic quality.","zh":"史诗品质，7 个格位。"},"obtain":{"en":"Craft for 25 Planks once the Design is learned.","zh":"学会设计图后用 25 块木板制作。"},"tips":[{"en":"If planks are tight, the Polished shelf gives almost the same space.","zh":"木板紧张的话，抛光款的空间几乎一样。"}],"sources":["https://arcraiders.wiki/wiki/Furniture#Ornate_Den_Shelf"],"version":"2.0"},"chambers_shelf":{"verdict":{"en":"12 slots for just 10 Sheet Metal: great display space for the price.","zh":"10 块金属板换 12 格，价格极低的展示空间。"},"use":{"en":"A large shelf compared with the Den line. Use it for collectibles you want out of the stash.","zh":"比巢穴架子大得多，适合放想从储备箱里拿出来的收藏品。"},"obtain":{"en":"Craft for 10 Sheet Metal once the Chambers Shelf Design is learned.","zh":"学会商会架子设计图后用 10 块金属板制作。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Chambers_Shelf"],"version":"2.0"},"diner_cupboard":{"verdict":{"en":"The biggest storage listing on the wiki: 16 slots, but it needs research.","zh":"维基上格数最多的存储家具：16 格，但需要研究。"},"use":{"en":"16 slots makes this the best pick for freeing stash space among listed pieces.","zh":"16 格，是已列出家具里腾出储备箱空间的最佳选择。"},"obtain":{"en":"Needs 1000 RP and 40 Planks of research, then 1 Metal Brackets and 20 Planks to craft.","zh":"需要 1000 研究点数和 40 块木板的研究投入，制作再花 1 个金属支架和 20 块木板。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Diner_Cupboard"],"version":"2.0"},"study_piano":{"verdict":{"en":"Legendary showpiece with 3 slots; expensive for what it does.","zh":"传说级展示品，有 3 格，花费偏高。"},"use":{"en":"Mostly a showpiece, though it has 3 attached slots.","zh":"主要用来摆场面，带 3 个格位。"},"obtain":{"en":"Costs 50 Planks and 3 Advanced Mechanical Components; one guide notes a Design was found under a car hood on Dam Battlegrounds.","zh":"需要 50 块木板和 3 个高级机械元件；有攻略称曾在大坝战场的车引擎盖下找到设计图。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Study_Piano","https://www.pcgamer.com/games/third-person-shooter/dont-neglect-crafting-furniture-in-your-arc-raiders-outpost-it-unlocks-100s-of-extra-storage-slots/"],"version":"2.0"},"holly_bush":{"verdict":{"en":"Seasonal plant decor built from seeds and fertilizer.","zh":"用种子和肥料做的绿植装饰。"},"use":{"en":"Pure decoration, no slots.","zh":"纯装饰，没有格位。"},"obtain":{"en":"Craft for 30 Assorted Seeds and 3 Fertilizer. Recycling returns the seeds and fertilizer.","zh":"用 30 份混合种子和 3 份肥料制作，拆解会返还种子和肥料。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Holly_Bush"],"version":"2.0"},"lab_cabinets":{"verdict":{"en":"Lab cabinets are Sheet Metal storage pieces; the Sturdy ones are cheaper to research.","zh":"实验室柜是金属板系列的存储家具，坚固款研究更便宜。"},"use":{"en":"Storage cabinets in the Lab style. Slot counts are not listed on the wiki, so check in game.","zh":"实验室风格的存储柜。维基未列出格数，请在游戏内查看。"},"obtain":{"en":"Research costs range from 500 RP (Sturdy, Small) to 1000 RP (Battered, Blue), plus metal parts and plastic.","zh":"研究点数从 500（坚固款、小型）到 1000（破旧款、蓝色），另需金属和塑料材料。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Sturdy_Lab_Cabinet","https://arcraiders.wiki/wiki/Furniture#Blue_Lab_Cabinet"],"version":"2.0"},"shelves":{"verdict":{"en":"Three shelving units; all need research, and Sturdy costs the most metal.","zh":"三款置物架都要研究，坚固款耗金属最多。"},"use":{"en":"Wall or standing shelves for display.","zh":"用来陈列的壁架或立式架。"},"obtain":{"en":"Battered and Sturdy need 1000 RP and a Rusted Bolt; Diner needs 1500 RP and a Laser Level.","zh":"破旧款和坚固款要 1000 研究点数和 1 个生锈螺栓；餐馆架子要 1500 点数和 1 个激光水平仪。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Battered_Shelf","https://arcraiders.wiki/wiki/Furniture#Diner_Shelf"],"version":"2.0"},"wardrobes":{"verdict":{"en":"Wardrobes are bulky decor; Sturdy is the cheap one.","zh":"衣柜体积大，主要是装饰，坚固款最便宜。"},"use":{"en":"Standing wardrobes. Alpine and Ornate use Planks, Sturdy and Polished use metal.","zh":"立式衣柜。高山和华丽款用木板，坚固和抛光款用金属。"},"obtain":{"en":"Sturdy: 8 Sheet Metal and 4 Plastic Parts; Ornate: 50 Planks and 2 Metal Brackets.","zh":"坚固款 8 块金属板加 4 个塑料零件；华丽款 50 块木板加 2 个金属支架。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Sturdy_Wardrobe","https://arcraiders.wiki/wiki/Furniture#Ornate_Wardrobe"],"version":"2.0"},"dressers_cabinets":{"verdict":{"en":"Assorted dressers and cabinets; a few need research before crafting.","zh":"各式五斗柜和柜子，部分需先研究。"},"use":{"en":"Furniture for decorating rooms.","zh":"给房间做装饰的家具。"},"obtain":{"en":"Venetian Dresser needs 25 Planks, Console Chest 20 Planks; the rest need research of 500 to 1500 RP.","zh":"威尼斯梳妆台要 25 块木板，控制台宝箱要 20 块；其余需要 500 到 1500 研究点数。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Venetian_Dresser","https://arcraiders.wiki/wiki/Furniture#Faculty_Closet"],"version":"2.0"},"den_beds":{"verdict":{"en":"Beds are decor only; Battered is nearly free.","zh":"床只是装饰，破旧款几乎不花钱。"},"use":{"en":"Four tiers of the same bed.","zh":"同一款床的四个档次。"},"obtain":{"en":"Battered needs 2 Sheet Metal and a Torn Blanket; Ornate needs 20 Planks and 2 Very Comfortable Pillows.","zh":"破旧款 2 块金属板加 1 条破损的毯子；华丽款 20 块木板加 2 个极为舒适的枕头。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Battered_Den_Bed"],"version":"2.0"},"tables_basic":{"verdict":{"en":"Cheap everyday tables; decor.","zh":"便宜的日常桌子，纯装饰。"},"use":{"en":"Plain tables for rooms.","zh":"给房间用的普通桌子。"},"obtain":{"en":"Mostly 14-20 Sheet Metal plus plastic or rubber; some need 500 to 1000 RP.","zh":"多数要 14 到 20 块金属板加塑料或橡胶；部分需要 500 到 1000 研究点数。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Bar_Table","https://arcraiders.wiki/wiki/Furniture#Winter_Table"],"version":"2.0"},"tables_premium":{"verdict":{"en":"Higher-tier tables with heavier research costs.","zh":"高档桌子，研究成本较高。"},"use":{"en":"Decor tables.","zh":"装饰桌。"},"obtain":{"en":"Diner Table needs 2000 RP and a Statuette; others need 1500 RP and a Laser Level or similar.","zh":"小餐馆桌子要 2000 研究点数和 1 个小雕像；其余要 1500 点数和激光水平仪之类的材料。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Diner_Table","https://arcraiders.wiki/wiki/Furniture#Restaurant_Table"],"version":"2.0"},"sofas_cheap":{"verdict":{"en":"Basic sofas; Bureau ones are the cheapest.","zh":"基础沙发，办公沙发最便宜。"},"use":{"en":"Seating decor.","zh":"座椅装饰。"},"obtain":{"en":"Battered Bureau Sofa: 1 Spring Cushion and 10 Planks.","zh":"破旧办公沙发：1 个弹簧靠枕和 10 块木板。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Battered_Bureau_Sofa","https://arcraiders.wiki/wiki/Furniture#Diner_Sofa"],"version":"2.0"},"sofas_geometric":{"verdict":{"en":"Two Rare geometric sofas at identical cost.","zh":"两款稀有几何沙发，造价相同。"},"use":{"en":"Decor.","zh":"装饰。"},"obtain":{"en":"Each needs 5 Durable Cloth and 15 Sheet Metal.","zh":"各需 5 份耐磨布料和 15 块金属板。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Green_Geometric_Sofa"],"version":"2.0"},"sofas_premium":{"verdict":{"en":"Top-end seating; needs Spring Cushions and research.","zh":"高档座椅，需要弹簧靠枕和研究。"},"use":{"en":"Decor seating.","zh":"座椅装饰。"},"obtain":{"en":"Tufted Sofa needs 2000 RP and 3 Very Comfortable Pillows; Round and Red Study need 1500 RP.","zh":"绗缝沙发要 2000 研究点数和 3 个极为舒适的枕头；圆形沙发和红色书房沙发要 1500 点数。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Tufted_Sofa","https://arcraiders.wiki/wiki/Furniture#Study_Armchair"],"version":"2.0"},"chairs_work":{"verdict":{"en":"Office and lab chairs: cheap decor; Hotel Chair comes from the unlock project.","zh":"办公和实验室椅子，便宜的装饰；酒店座椅来自哨站解锁项目。"},"use":{"en":"Seating.","zh":"座椅。"},"obtain":{"en":"Most cost 5-8 Sheet Metal plus fabric or plastic. The Hotel Chair Design is the Sheltered Retreat stage 3 reward.","zh":"多数要 5 到 8 块金属板加布料或塑料。酒店椅设计图是“庇护所”项目第 3 阶段奖励。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Hotel_Chair","https://arcraiders.wiki/wiki/Outpost#Sheltered_Retreat"],"version":"2.0"},"chairs_fabric":{"verdict":{"en":"Four Rare fabric chairs; Durable Cloth is the cost.","zh":"四款稀有布艺椅，主要消耗耐磨布料。"},"use":{"en":"Seating.","zh":"座椅。"},"obtain":{"en":"3 to 5 Durable Cloth and 10 to 15 Sheet Metal each.","zh":"每把要 3 到 5 份耐磨布料和 10 到 15 块金属板。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Solid_Green_Chair"],"version":"2.0"},"stools":{"verdict":{"en":"Three cheap stools.","zh":"三款便宜的凳子。"},"use":{"en":"Seating.","zh":"座椅。"},"obtain":{"en":"Barstool: 4 Fabric, 8 Sheet Metal. Diner Stool needs 500 RP.","zh":"吧台凳：4 份布料和 8 块金属板。餐馆凳子需要 500 研究点数。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Barstool"],"version":"2.0"},"ceiling_lamps":{"verdict":{"en":"Ceiling lamps are cheap, 10 Sheet Metal and a bulb or two.","zh":"吸顶灯很便宜，10 块金属板加一两个灯泡。"},"use":{"en":"Lighting decor.","zh":"灯光装饰。"},"obtain":{"en":"Each takes 10 Sheet Metal and 1 or 2 Light Bulbs.","zh":"每盏要 10 块金属板和 1 到 2 个灯泡。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Diner_Ceiling_Lamp"],"version":"2.0"},"lamps_special":{"verdict":{"en":"Floor lamps and specials; Chandelier is the Legendary one.","zh":"落地灯和特色灯，吊灯是传说级。"},"use":{"en":"Lighting decor.","zh":"灯光装饰。"},"obtain":{"en":"Chandelier: 3 Candle Holders and 20 Sheet Metal. Work Light: 3 Red Light Sticks.","zh":"吊灯：3 个烛台和 20 块金属板。工作灯：3 根红色荧光棒。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Chandelier"],"version":"2.0"},"draped_debris":{"verdict":{"en":"Cheap debris decor: 5 Planks and 5 Fabric each.","zh":"便宜的残骸装饰：每件 5 块木板加 5 份布料。"},"use":{"en":"Decor, no slots.","zh":"纯装饰，无格位。"},"obtain":{"en":"All six cost the same.","zh":"六件造价相同。"},"sources":["https://arcraiders.wiki/wiki/Furniture#Draped_Debris_A"],"version":"2.0"},"action_economy":{"verdict":{"en":"A cheap, safe research: 1,000 damage with the Hairpin is a few raids of normal play.","zh":"门槛很低：用“发夹”打出1000点伤害，正常玩几局就够。"},"use":{"en":"Completing it opens the Amplified perk path tied to the Jupiter and Osprey (players link it to their scoped options; the exact perk mapping is not confirmed). Each Amplified research also costs 5,000 Research Points and a stack of Sentinel Firing Cores.","zh":"完成后可解锁木星与鱼鹰的增强强化路线（玩家推测与瞄具方向相关，具体对应关系未证实）。每项增强研究还要消耗5000研究点数和一批哨卫发射核心。"},"obtain":{"en":"Take a Hairpin into any raid and shoot ARC or Raiders until the counter hits 1,000. Damage counts across raids, so a cheap kit is fine. The Sentinel Firing Cores are the real bottleneck, so start farming Sentinels early.","zh":"带着“发夹”进任何一局，打ARC或玩家直到累计1000点。伤害可跨局累计，带便宜配置即可。真正卡人的是哨卫发射核心，要提前去打哨卫。"},"tips":[{"en":"Only worth doing early if you plan to amplify the Jupiter or Osprey; otherwise skip it.","zh":"只有打算增强木星或鱼鹰时才值得早做，否则可以先放着。"}],"sources":["https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://arcraiders.wiki/wiki/Research_Station"],"version":"2.0"},"beam_resonance_tech":{"verdict":{"en":"Hard-ish and Equalizer-only: do it only if you already run the Equalizer.","zh":"要求偏高且只服务“制裁者”：不用这把枪就别急着做。"},"use":{"en":"It unlocks the Equalizer's Amplified research path. The cost is 5,000 Research Points plus 2 Queen Reactors, which are among the toughest ARC drops, so this is a late-game project.","zh":"解锁“制裁者”的增强研究路线。除5000研究点数外还要2个女王反应堆，这是最难拿的ARC掉落之一，属于后期项目。"},"obtain":{"en":"You need 1,500 damage to Vaporizers with an Equalizer in a single round, so find Vaporizers first and keep your ammo for them. The Equalizer blueprint itself only comes from the Harvester event.","zh":"需要在单局内用“制裁者”对“汽化者”打出1500点伤害，所以要先找到“汽化者”，把弹药留给它们。“制裁者”蓝图本身只能通过收割者事件获得。"},"tips":[{"en":"The damage must happen in one round, so do not split it across raids.","zh":"伤害必须在单局内完成，别分几局打。"}],"sources":["https://metaforge.app/arc-raiders/how-to-get-the-equalizer-blueprint-in-arc-raiders","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/"],"version":"2.0"},"burst_assembly_recovery":{"verdict":{"en":"Only for Burletta fans, and gated by Shredders, which are hard to find.","zh":"只对“布尔莱塔”玩家有用，而且“粉碎者”不好找。"},"use":{"en":"Unlocks a Burletta Amplified research path. Needs 20 Pop Triggers on top of 5,000 Research Points.","zh":"解锁“布尔莱塔”的一条增强研究路线。除5000研究点数外还要20个弹出式扳机。"},"obtain":{"en":"Destroy 3 Shredders with a Raider Tool. One guide says Shredders are currently exclusive to Stella Montis, so plan runs there. Shredder Gyros from the same kills are also needed by Speranza projects, so you get double value.","zh":"用奇袭工具摧毁3个“粉碎者”。有攻略称“粉碎者”目前只在星辰山出现，所以要专门跑那张图。同样的击杀掉落的“粉碎者”陀螺仪也是斯佩兰扎项目所需，一举两得。"},"tips":[{"en":"Bring several Raider Tools: the objective needs the tool to do the destroying, not your gun.","zh":"多带几个奇袭工具：目标要求由工具摧毁，不是用枪打。"}],"sources":["https://metaforge.app/arc-raiders/how-to-get-shredder-gyros-in-arc-raiders","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/"],"version":"2.0"},"compact_combustion_charges":{"verdict":{"en":"Easy if you carry Blaze Grenades: 3,000 damage over a few raids.","zh":"带火焰手雷就不难：几局内累计3000点伤害。"},"use":{"en":"Unlocks Amplified research for the Hullcracker and Rascal. Also needs 5 Bombardier Cells and 5,000 Research Points.","zh":"解锁“裂甲者”和“无赖”的增强研究。另需5个投弹手电池和5000研究点数。"},"obtain":{"en":"Throw Blaze Grenades at ARC groups or at any target standing in the burn zone, since the objective counts total damage. Bombardier Cells come from Bombardiers, so combine both goals.","zh":"把火焰手雷扔向ARC群或站在燃烧区的目标，目标统计总伤害。投弹手电池来自“投弹手”，可以两件事一起做。"},"tips":[{"en":"Craft Blaze Grenades in bulk before starting; a few raids of grenade-only play finishes it.","zh":"先批量制作火焰手雷，几局专心扔雷就能完成。"}],"sources":["https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://beebom.com/arc-raiders-amplified-weapons-guide/"],"version":"2.0"},"embedded_blast_engineering":{"verdict":{"en":"The most tedious research: four ARC types, 1,000 grenade damage each.","zh":"最繁琐的研究之一：四种ARC，每种用手雷打1000点。"},"use":{"en":"Unlocks Amplified research for the Anvil, Bettina and Kettle, so it matters if you use any of the three. Also needs 5 Rocketeer Drivers.","zh":"解锁“铁砧”“贝蒂娜”“水壶”的增强研究，用其中任何一把都值得做。另需5个火箭手引擎。"},"obtain":{"en":"Use Light Impact Grenades on Fireflies, Hornets, Fireballs and Surveyors, 1,000 damage each. Fireballs are mostly in bunkers or underground, such as the Buried City Metro entrances and the big Blue Gate bunker, so do them last. Fireflies, Hornets and Surveyors are flying or drone ARC you meet in the open.","zh":"用轻型冲击手雷分别对萤火虫、马蜂、火球和勘测师打出1000点伤害。火球多在地堡或地下，如掩埋废城的地铁入口和蓝门的大地堡，放最后做。萤火虫、马蜂、勘测师在野外较常见。"},"tips":[{"en":"Each ARC type has its own counter, so check progress after every raid instead of throwing everything at one target.","zh":"每种ARC各自计数，每局结束后看进度，别把雷都扔在同一种目标上。"}],"sources":["https://arcraiders.wiki/wiki/Fireball","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/"],"version":"2.0"},"extended_burst_cycles":{"verdict":{"en":"A grind: 10,000 damage, but it covers two weapons.","zh":"要刷：1000点变成10000点，不过能服务两把枪。"},"use":{"en":"Unlocks Amplified research for the Aphelion and Burletta. Also needs 10 Comet Igniters.","zh":"解锁“远日点”和“布尔莱塔”的增强研究。另需10个彗星点火器。"},"obtain":{"en":"Deal 10,000 damage with a Burst Burletta or a Charged Burst Aphelion. Both are burst setups from the Amplified tree, so expect to amplify one first. Damage counts over many raids.","zh":"用连发形态的“布尔莱塔”或蓄力连发形态的“远日点”打出10000点伤害。这两种都是增强后的配置，所以必须先把其中一把增强成对应形态才能开始计数，伤害可跨多局累计。"},"tips":[{"en":"Do this after you finish easier projects; it is one of the longest grinds in the list.","zh":"放在较简单的项目之后，它是清单里最耗时的刷伤害项目之一。"}],"sources":["https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://beebom.com/arc-raiders-amplified-weapons-guide/"],"version":"2.0"},"high_voltage_exposure":{"verdict":{"en":"Simple and cheap: blow up 5 ARC Turbines for the Aphelion path.","zh":"简单便宜：炸掉5个ARC涡轮，解锁“远日点”路线。"},"use":{"en":"Unlocks Amplified research for the Aphelion. Also needs 5 Leaper Pulse Units, which drop from Leapers.","zh":"解锁“远日点”的增强研究。另需5个跳跃者脉冲单元，来自“跳跃者”。"},"obtain":{"en":"Destroy any ARC Turbine you come across, preferably with explosives, and hunt Leapers on the same run for the Pulse Units. I found no community page listing turbine spots, so check the map for them in game.","zh":"遇到ARC涡轮就摧毁，最好用爆炸物，同一局顺便去打“跳跃者”拿脉冲单元。没有找到社区页面列出涡轮位置，请在游戏内地图中确认。"},"tips":[{"en":"Explosives make it fast. Only worth early if you want an amplified Aphelion.","zh":"用爆炸物最快。只有想要增强版“远日点”时才值得早做。"}],"sources":["https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://beebom.com/arc-raiders-outpost-guide/"],"version":"2.0"},"magazine_geometry_101":{"verdict":{"en":"Expensive: killing a Bastion with the Rattler alone is the hard part.","zh":"成本高：只用“响尾蛇”击杀“堡垒”是难点。"},"use":{"en":"Unlocks the Rattler's Amplified path, which includes the drum magazine (+40 rounds, at the cost of more recoil and slower aim-down-sights). Also needs 5 Bastion Cells.","zh":"解锁“响尾蛇”的增强路线，其中包含弹鼓（弹匣+40发，但后坐力更大、开镜更慢）。另需5个“堡垒”电池。"},"obtain":{"en":"Deal 15,000 damage to a Bastion with a Rattler and destroy 1 Bastion with it. The usual Bastion advice is to hit the weak spots and joints, and to bring explosives, but explosives will not count here, so bring a lot of ammo and a squad to distract it.","zh":"用“响尾蛇”对“堡垒”造成15000点伤害并摧毁1个。通用打法是瞄准弱点和腿部关节，并带爆炸物，但这里爆炸物不计入，所以要带足弹药，最好有队友吸引火力。"},"tips":[{"en":"Rattler damage on a Bastion is slow, so plan for a long fight and a safe fallback.","zh":"“响尾蛇”打“堡垒”比较慢，要预留长时间战斗和安全撤退路线。"}],"sources":["https://www.shacknews.com/article/148833/how-to-destroy-bastions-in-arc-raiders","https://8bittoast.com/how-to-kill-bastion-arc-raiders/"],"version":"2.0"},"mobile_fire_grip_fittings":{"verdict":{"en":"A sightseeing quest: visit seven locations, no combat required.","zh":"跑图型任务：到七个地点打卡，不强制战斗。"},"use":{"en":"Unlocks the Sprint Shooting perk path for the Burletta, Canto, Hairpin and Rascal (the link is inferred from the weapons that offer the perk). It also needs 20 Skulker Drivers.","zh":"解锁“布尔莱塔”“颂歌”“发夹”“无赖”的冲刺射击路线（对应关系由拥有该强化的武器推断）。另需20个“潜伏者”引擎。"},"obtain":{"en":"Visit the Electrical Substation, Truck Stop, Old Town, Almatera Station, Researcher Lodgings, Deep-Space Telescope and Commissary Supermarket. They are spread over several maps, so tick off two or three per raid with a light kit. The 20 Skulker Drivers are the real work.","zh":"前往变电站、卡车停靠站、老城区、阿尔玛特拉站、研究员住所区、深空望远镜和军需超市。它们分布在不同地图，每局带轻装备顺路完成两三处即可。真正耗时的是20个“潜伏者”引擎。"},"tips":[{"en":"Combine visits with loot runs. Old Town and the Commissary Supermarket are also good for Outpost materials.","zh":"打卡和搜刮一起做，老城区和军需超市也是哨站材料的好去处。"}],"sources":["https://beebom.com/arc-raiders-outpost-guide/","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/"],"version":"2.0"},"shield_stress_testing":{"verdict":{"en":"Only 700 damage to Raiders, but 2 Matriarch Reactors make it a late project.","zh":"只要对玩家造成700点伤害，但需要2个族母反应堆，属于后期项目。"},"use":{"en":"Unlocks the Kettle's Amplified path, including the Anti-Shield variants. Needs 2 Matriarch Reactors and 5,000 Research Points.","zh":"解锁“水壶”的增强路线，包括反护盾变体。需要2个族母反应堆和5000研究点数。"},"obtain":{"en":"The objective counts damage to encountered Raiders, so a few fights in a PvP-heavy map finish it, and the damage does not need to be a kill. The Matriarch Reactors come from the Matriarch, which is the real obstacle.","zh":"目标统计对遇到的玩家造成的伤害，在PvP较多的地图打几场即可，不必击杀。族母反应堆来自“族母”，这才是真正的障碍。"},"tips":[{"en":"Do the damage when you meet Raiders anyway; do not go hunting players just for this.","zh":"遇到玩家时顺手完成，不必专门去找人打。"}],"sources":["https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://beebom.com/arc-raiders-amplified-weapons-guide/"],"version":"2.0"},"solid_core_casting_tech":{"verdict":{"en":"A shotgun grind: 50 flying ARC, only worth it for the Il Toro.","zh":"霰弹枪刷怪：击落50个飞行ARC，只有用“公牛”才值得。"},"use":{"en":"Unlocks the Il Toro's Amplified research. Also needs 20 Tick Pods.","zh":"解锁“公牛”的增强研究。另需20个跳蚤荚。"},"obtain":{"en":"Destroy 50 flying ARC with shotguns. Wasps, Hornets and Fireflies are flying ARC, and Pendola Pass has plenty of flyers. Shotguns are strongest up close, so wait for drones to dive at you.","zh":"用霰弹枪摧毁50个飞行ARC。黄蜂、马蜂和萤火虫都算飞行ARC，彭多拉山口飞行单位很多。霰弹枪近距离最强，等无人机俯冲过来再打。"},"tips":[{"en":"The 20 Tick Pods are as much work as the kills, so farm Ticks in the same runs.","zh":"20个跳蚤荚的工作量不亚于击杀，同一局顺便刷“跳蚤”。"}],"sources":["https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://www.playnews.gg/en/guides/arc-raiders-the-complete-arc-bestiary-guide-for-2026-the-13-machines-you-need-to-know-to-survive"],"version":"2.0"},"targeted_component_trial":{"verdict":{"en":"A long flyer hunt, worth it for the Equalizer and Osprey.","zh":"要长时间打飞行ARC，用“制裁者”和“鱼鹰”才值得。"},"use":{"en":"Unlocks Amplified research for the Equalizer and Osprey (the Osprey's anti-weak-point option fits the theme). Also needs 20 Fireball Burners.","zh":"解锁“制裁者”和“鱼鹰”的增强研究（“鱼鹰”的弱点强化方向与此吻合）。另需20个“火球”燃烧炉。"},"obtain":{"en":"Destroy 40 thrusters on flying ARC. Shooting thrusters, not bodies, is what counts, so aim at the engines. Fireball Burners are the harder part because Fireballs are mostly in bunkers or underground.","zh":"摧毁飞行ARC的40个推进器。要打的是推进器而不是机身，请瞄准引擎。“火球”燃烧炉更难，因为火球多在地堡或地下。"},"tips":[{"en":"Fireball Burners are also needed for the Refiner upgrade, so keep them.","zh":"“火球”燃烧炉还用于升级精加工机，请先留着。"}],"sources":["https://arcraiders.wiki/wiki/Fireball","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/"],"version":"2.0"},"thermite_tipped_rounds":{"verdict":{"en":"The best-value research: it unlocks incendiary rounds on four weapons.","zh":"性价比最高的研究：为四把武器解锁燃烧弹。"},"use":{"en":"Opens the incendiary path for the Aphelion, Canto, Hairpin and Rattler, which adds burn damage over time. It also needs 5 Firefly Burners.","zh":"为“远日点”“颂歌”“发夹”“响尾蛇”开启燃烧弹路线，增加持续灼烧伤害。另需5个萤火虫燃烧炉。"},"obtain":{"en":"Destroy 30 Fireballs with Explosive Mines. Fireballs hide in bunkers and underground, such as the Buried City Metro entrances and the large Blue Gate bunker, so lay mines on their patrol paths. Fireballs spawn infrequently, so expect many raids.","zh":"用爆炸地雷摧毁30个火球。火球多在地堡和地下，如掩埋废城地铁入口、蓝门大地堡，把地雷放在它们的巡逻路线上。火球刷新不多，需要多局。"},"tips":[{"en":"Mines are cheap, but each kill sets the area on fire, so retreat before collecting.","zh":"地雷便宜，但击杀会引燃周围，等火熄了再去捡。"}],"sources":["https://arcraiders.wiki/wiki/Fireball","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/"],"version":"2.0"},"top_mounted_optics_retrofittings":{"verdict":{"en":"Quick: visit Pilgrim's Peak and deal 1,000 damage with an Osprey.","zh":"很快：去朝圣峰，再用“鱼鹰”打出1000点伤害。"},"use":{"en":"Unlocks scope upgrades in the Amplified paths of the Jupiter and Renegade (as listed by the keengamer guide). Also needs 14 Snitch Scanners.","zh":"解锁“木星”和“叛逆”增强路线中的瞄具升级（来自玩家攻略的列表）。另需14个告密者扫描仪。"},"obtain":{"en":"On Blue Gate head to Pilgrim's Peak and shoot ARC with an Osprey, 1,000 damage in total. The objective is cheap, but you need to own the Osprey and a Pilgrim's Peak Security Code may be needed to enter parts of the area.","zh":"在蓝门前往朝圣峰，用“鱼鹰”攻击ARC，累计1000点。目标本身便宜，但需要拥有“鱼鹰”，进入该区域部分地点可能需要朝圣峰安全码。"},"tips":[{"en":"Snitch Scanners come from Snitches, so farm them alongside.","zh":"告密者扫描仪来自“告密者”，可以一起刷。"}],"sources":["https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://beebom.com/arc-raiders-amplified-weapons-guide/"],"version":"2.0"},"trigger_reset_systems":{"verdict":{"en":"Cheap: 5 Skulkers with a Raider Tool, unlocks the Bettina and Hairpin paths.","zh":"便宜：用奇袭工具打掉5个潜伏者，解锁“贝蒂娜”和“发夹”路线。"},"use":{"en":"Unlocks Amplified research for the Bettina and Hairpin. Also needs 4 Vaporizer Regulators.","zh":"解锁“贝蒂娜”和“发夹”的增强研究。另需4个“汽化者”调节器。"},"obtain":{"en":"Destroy 5 Skulkers with a Raider Tool. Skulkers ambush then glide away, and explosives destroy them easily, so a Raider Tool placed near their ambush spot works. They are tied to low-visibility weather such as blizzards and storms.","zh":"用奇袭工具摧毁5个“潜伏者”。它们先埋伏再滑行撤离，爆炸物很容易消灭，把奇袭工具放在它们埋伏点附近就行。它们与暴风雪、风暴等低能见度天气有关。"},"tips":[{"en":"Skulker Targeters from the same kills are needed for Research Station level 2.","zh":"同样的击杀掉落的“潜伏者”瞄准组件还要用于研究站2级升级。"}],"sources":["https://arcraiders.wiki/wiki/Skulker","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/"],"version":"2.0"},"stencils":{"verdict":{"en":"Pure cosmetics: keep them for your main gun, nothing here changes stats.","zh":"纯外观：留给常用武器，不影响任何数值。"},"use":{"en":"Learn a stencil from your inventory, then apply it to a matching weapon for Stencil Parts: 2 for Common or Uncommon, 4 for Rare, 7 for Epic, 15 for Legendary. The stencil stays on the weapon after death. Garnet and Ochre fit nearly every weapon; others are weapon-specific, for example Bulwark on the Hullcracker, Serac on the Bobcat and Sacrifice on the Renegade.","zh":"在背包里学习贴花，再花费贴花组件应用到匹配的武器上：普通或优秀2个、稀有4个、史诗7个、传奇15个。贴花在死亡后仍保留在武器上。石榴石和赭石几乎适配所有武器，其他多为专属，如“裂甲者”的壁垒、“山猫”的冰塔、“叛逆”的献祭。"},"obtain":{"en":"Most drop as random loot in Topside containers, with Stencil Parts found in commercial, residential and industrial areas of maps such as Buried City and Blue Gate. Cerulean is reported from the Pendola Pass Observatory key room, Fortuna is from the Frozen Trail premium pass, and Dragon's Breath is from the Collector Set.","zh":"多数为地表容器的随机掉落，贴花组件则在掩埋废城、蓝门等地图的商业、居住和工业区域刷新。苍蓝据报来自彭多拉山口天文台钥匙房，命运女神来自冰封之路付费奖励通行证，龙息来自收藏家礼包。"},"tips":[{"en":"Check the weapon list before spending parts, because only stencils you have learned and that fit the gun are offered.","zh":"花组件前先看适配武器，只有已学会且适配的贴花才会出现。"},{"en":"Reported rarities from outside sources differ on a few stencils, so trust the in-game rarity.","zh":"外部来源对个别贴花的稀有度说法不一，以游戏内为准。"}],"sources":["https://arcraiders.wiki/wiki/Stencils","https://www.destructoid.com/all-weapon-stencils-in-arc-raiders-and-how-to-get-them/","https://games.gg/arc-raiders/guides/arc-raiders-all-stencils-and-how-to-get-them/"],"version":"2.0"},"outpost_rooms":{"verdict":{"en":"Rooms are mostly style: the slots raise your Outpost level, but the look is your choice.","zh":"房间主要是风格选择：房间位提升哨站等级，外观随你喜欢。"},"use":{"en":"The Base Room is included. You can add three of four optional rooms (Panoramic, Timeless, Chalet, Studious), and they cannot be moved or swapped once placed. Each room raises the cap for the Research Station and Gunsmith, and level 4 is needed for Amplified weapons. Players call Chalet the nicest and Timeless the least appealing.","zh":"基础房间自带。四个可选房间（全景、永恒、木屋、研究室）可选三个，放置后无法移动或更换。每个房间提高研究站和武器工作台的等级上限，4级才能做增强武器。玩家普遍认为木屋最好看，永恒最一般。"},"obtain":{"en":"Unlock the Outpost first (Raider level 18, then the three-stage Sheltered Retreat project). Then expand with the plus icon. The first expansion costs 3 Steel Cables, 20 Sheet Metal and 3 Cable Strippers; later ones cost more, and cost follows the slot rather than the room.","zh":"先解锁哨站（突袭者等级18，完成三阶段“庇护所”项目），再点加号扩建。首次扩建需要3个钢缆、20个金属板和3个电缆剥线钳，后续更贵，费用取决于房间位而不是房间种类。"},"tips":[{"en":"Sources disagree on when the Studious Room becomes available, so check in game.","zh":"各来源对研究室何时可选说法不一，请以游戏内为准。"}],"sources":["https://beebom.com/arc-raiders-outpost-guide/","https://allthings.how/arc-raiders-outpost-how-to-unlock-upgrade-and-use-the-research-workstation/","https://arcraiders.wiki/wiki/Outpost","https://www.keengamer.com/articles/guides/arc-raiders-how-to-unlock-the-outpost/"],"version":"2.0"},"blaze_grenade":{"verdict":{"en":"A fire-zone tool for blocking corridors and chipping big ARC, not a way to get kills quickly.","zh":"封路与消耗大型ARC的火区工具，不适合快速击杀。"},"use":{"en":"The fire burns for 10 seconds in a wide area, so throw it into a hallway or stair while you heal, loot or retreat. Players can simply walk out, so expect to herd them, not kill them. Against Bastions and Bombardiers it stacks as steady chip damage; community trial guides use 5 or 6 on a Bombardier. The trap version only adds a tripwire.","zh":"火焰在大范围内持续10秒，适合在你回血、搜刮或撤退时封住走廊或楼梯。玩家走出去就行，所以它是逼人改路线而不是杀人。对“堡垒”和“投弹手”是稳定的持续伤害，社区的试炼攻略会用5到6颗打一只“投弹手”。陷阱版只是多了绊线触发。"},"obtain":{"en":"Craft it at the Explosives Station level 3 once you have the blueprint, or buy it from Apollo (limit 3). The quests What Goes Around and Test Case also hand out 3 each. Oil is the main input, so keep some in stock.","zh":"学会蓝图后在爆炸物工作台3级制作，也可向阿波罗购买（限购3个）。任务“因果报应”和“测试案例”各奖励3个。主要材料是油，记得备着。"},"tips":[{"en":"Recycling returns Metal Parts and Oil, so spares are not wasted.","zh":"回收能得到金属零件和油，多余的不亏。"},{"en":"The trap needs only a Wires on top of a grenade; make it only if you like ambush setups.","zh":"陷阱只需在手雷上加一个导线；喜欢设伏再做。"}],"sources":["https://arcraiders.wiki/wiki/Blaze_Grenade","https://nerdschalk.com/arc-raiders-blaze-grenade-guide-specs-crafting-and-usage/","https://metaforge.app/arc-raiders/damage-arc-using-blaze-grenade"],"version":"2.0"},"explosive_mine":{"verdict":{"en":"The only mine that really hurts, worth two or three in a PvP loadout, but it will not kill a healthy Raider alone.","zh":"唯一真正能造成伤害的地雷，PvP配装带两三个值得，但单靠它杀不死满血玩家。"},"use":{"en":"It pops up and blows after a 1 second delay, so place it where people must pass: behind a door, near loot, in grass or around a corner. Its damage swings a fight by putting the target behind, and the bang tells you where they are. Do not set it in a contested spot you will walk through yourself; a clip going around shows a camper's mine killing him and his killer.","zh":"它弹起后延迟1秒爆炸，要放在必经之路：门后、战利品旁、草丛或拐角。伤害足以让对手处于劣势，爆炸声还会暴露他的位置。别布在自己也要经过的争夺点；有视频里蹲点者的地雷把他和击杀他的人一起炸死了。"},"obtain":{"en":"No trader sells it. Craft it at the Explosives Station level 3 after learning the blueprint, scavenge one, or take the Building a Library quest reward. The AR/RD 001 Ryder & Voyager Raider Deck also lists it.","zh":"商人不卖。学会蓝图后在爆炸物工作台3级制作，也可搜刮或领取“丰富图书室”的任务奖励。猎人卡组 AR/RD 001 中也有。"},"tips":[{"en":"Keep one for Building a Library; recycling gives only Oil and Sensors.","zh":"留一个给“丰富图书室”；回收只有油和传感器。"},{"en":"Check before you walk back through your own placement.","zh":"回头经过自己布雷的位置前先确认。"}],"sources":["https://arcraiders.wiki/wiki/Explosive_Mine","https://www.dexerto.com/wikis/arc-raiders/items/quick-use/explosive-mine/","https://www.notebookcheck.net/Cinematic-gold-ARC-Raiders-player-outplays-a-camper-mocks-him-and-instantly-gets-karma.1182531.0.html"],"version":"2.0"},"firecracker":{"verdict":{"en":"A harmless noisemaker, only worth holding for the Combat Recon and The League quests.","zh":"只会发声发光的小玩意，只有“战斗侦察”和“球队”任务才值得留。"},"use":{"en":"It sparks and pops for a few seconds and deals no damage. I found no source claiming it changes ARC behavior, so if you want a decoy use a Lure Grenade instead.","zh":"它会噼啪冒火花几秒，没有伤害。我没找到说它能影响ARC行为的来源，想要诱饵请用诱捕手雷。"},"obtain":{"en":"Shani sells it, you can craft it at the Utility Station level 1, or scavenge it. Both The League and Combat Recon reward 5.","zh":"萨尼出售，也可在工具工作台1级制作或搜刮。“球队”和“战斗侦察”各奖励5个。"},"tips":[{"en":"Do not craft more than the quests need; recycling returns less than half the Plastic Parts it cost.","zh":"别多做；回收返还的塑料零件不到成本的一半。"}],"sources":["https://arcraiders.wiki/wiki/Firecracker","https://wzstats.gg/arc-raiders/wiki/items/quick-use/throwables/firecracker"],"version":"2.0"},"fireworks_box":{"verdict":{"en":"A remote-fired damage tool aimed at ARC, best against flyers, and not a replacement for real grenades.","zh":"遥控引爆、主要对付ARC（尤其飞行单位）的伤害工具，替代不了正经手雷。"},"use":{"en":"Place it, back away and trigger it yourself. Guides describe steady damage to ARC rather than one big hit, strongest on flying ARC and turrets. Mounting it on a wall makes the fireworks fly sideways at a flyer. It is not meant for killing players.","zh":"放好后退开再自己引爆。攻略称其对ARC是持续的累积伤害而非一击重创，对飞行ARC和炮塔最好用。装在墙上能让烟花横向射向飞行单位。它不是用来杀玩家的。"},"obtain":{"en":"Shani sells it for 6000 coins (limit 3). Craft it at the Explosives Station level 2 from an Explosive Compound and 3 Pop Triggers. Movie Night and Combat Recon each give one.","zh":"萨尼出售，售价6000钱币（限购3个）。可在爆炸物工作台2级用炸药混合物和3个“爆爆”触发器制作。“电影之夜”和“战斗侦察”各奖励一个。"},"tips":[{"en":"Do not recycle it: you only get back the Explosive Compound, losing the Pop Triggers.","zh":"别回收：只返还炸药混合物，“爆爆”触发器就白费了。"}],"sources":["https://arcraiders.wiki/wiki/Fireworks_Box","https://metaforge.app/arc-raiders/damage-flying-arc-using-fireworks","https://www.exitlag.com/blog/arc-raiders-fireworks-damage/"],"version":"2.0"},"flame_spray":{"verdict":{"en":"A short-range novelty flamethrower: low damage, and every one costs a Fireball Burner you must hunt.","zh":"近距离的噱头喷火器：伤害低，而且每把都要消耗一个得去猎杀才能拿到的“火球”燃烧炉。"},"use":{"en":"It sprays fire where you aim at 10 damage per second, which is modest next to any gun. Its only real appeal is close ambushes or burning a target in a tight space. I found no player write-up calling it worth a quick-use slot.","zh":"它朝瞄准方向喷火，每秒10点伤害，比任何枪都低。唯一的价值是近距离偷袭或在狭窄空间点燃目标。我没找到玩家说它值得占一个快捷栏。"},"obtain":{"en":"It can only be crafted in a raid, from an Air Freshener and a Fireball Burner. Burners drop from Fireball ARC; the Water Treatment area on Dam Battlegrounds is a reliable place to kill one. Keeping an Eye Out also rewards one.","zh":"只能在局内用空气清新剂和“火球”燃烧炉制作。燃烧炉由“火球”掉落；大坝战场的水处理厂是比较稳的刷点。“循目追踪”任务也奖励一把。"},"tips":[{"en":"If you do not plan to use it, recycle it: you get the Canister and the Burner back.","zh":"不打算用就回收：能拿回小罐和燃烧炉。"}],"sources":["https://arcraiders.wiki/wiki/Flame_Spray","https://metaforge.app/arc-raiders/what-goes-around-quest-guide-arc-raiders","https://wzstats.gg/arc-raiders/wiki/items/quick-use/gadgets/flame-spray"],"version":"2.0"},"gas_grenade":{"verdict":{"en":"A cheap PvP disruptor that stops people running, but the tripwire trap version is widely seen as the weakest trap.","zh":"便宜的PvP干扰手雷，能让人跑不动；但绊线陷阱版被普遍认为是最弱的陷阱。"},"use":{"en":"It does no health damage; it drains stamina so a Raider in the cloud cannot sprint, slide or jump. That makes it good for cutting off a fleeing player or stalling a push in a corridor. One wiki note says the cloud actually lasts about 10 seconds, not the listed 20, so time your follow-up.","zh":"它不造成生命伤害，而是消耗耐力，云里的玩家无法冲刺、滑铲或跳跃。适合堵截逃跑的人或在走廊拖住对方推进。有维基备注称云实际约持续10秒，而非列出的20秒，所以要抓紧追击。"},"obtain":{"en":"Cheap to make: Explosives Station level 1 with Chemicals and Rubber Parts. Apollo sells it for 810 coins.","zh":"制作便宜：爆炸物工作台1级，用化学品和橡胶零件。阿波罗售价810钱币。"},"tips":[{"en":"Skip the trap; a thrown grenade or a plain smoke is more flexible.","zh":"陷阱版可以不做；直接扔手雷或烟雾更灵活。"}],"sources":["https://arcraiders.wiki/wiki/Gas_Grenade","https://allthings.how/every-throwable-in-arc-raiders-all-25-grenades-drivers-and-scavenged-items/","https://blog.acer.com/en/discussion/3859/all-traps-in-arc-raiders-ranked"],"version":"2.0"},"gas_mine":{"verdict":{"en":"A situational defensive mine; it slows people down but never kills, so it is only for chokepoint play.","zh":"偏防守的情境地雷，只能拖慢对手而不能击杀，仅适合守点位。"},"use":{"en":"It triggers when someone walks into range, then lays a stamina-draining cloud. Put it at a doorway or retreat route so pursuers lose their sprint. For kills, the Explosive Mine is the better pick.","zh":"有人进入范围就触发，释放消耗耐力的云。放在门口或撤退路线上，让追兵失去冲刺。想要击杀，爆炸地雷更合适。"},"obtain":{"en":"Craft it at the Explosives Station level 1 once you hold the blueprint. Cold Storage and A Toxic Trail each reward 3. I found no reliable spawn spots.","zh":"拿到蓝图后在爆炸物工作台1级制作。“冷冻储藏”和“有毒的踪迹”各奖励3个。没有找到可靠的刷新点。"},"tips":[{"en":"Salvaging gives 2 Chemicals, more than recycling back the 1 each, if you only want Chemicals.","zh":"只想要化学品的话，拆解能得2个化学品，比回收各1个更多。"}],"sources":["https://arcraiders.wiki/wiki/Gas_Mine","https://www.u4n.com/tw/news/arc-raiders-gas-mine-how-to-get-best-use.html","https://nerdschalk.com/arc-raiders-all-traps-guide/"],"version":"2.0"},"heavy_fuze_grenade":{"verdict":{"en":"The hardest-hitting craftable grenade, best on big ARC; the 3 second fuse makes it unreliable against players.","zh":"可制作手雷中爆发最高，适合打大型ARC；3秒引信让它对玩家不稳定。"},"use":{"en":"Strong when it lands: 80 damage over a wide radius, good for Bastions, Bombardiers and trial scoring. Players have time to step out, and it can roll somewhere awkward. Pairing it with a Lure Grenade to hold a target still helps the blast land. One guide still calls it the most reliable all-purpose explosive.","zh":"命中时很强：范围大、80点伤害，适合“堡垒”、“投弹手”和试炼刷分。玩家有时间躲开，它也可能滚到奇怪的位置。配合诱捕手雷固定目标能提高命中。有攻略仍称它是最可靠的万能爆炸物。"},"obtain":{"en":"Craft it at the Explosives Station level 3 (Canisters and an Explosive Compound), or buy from Apollo (limit 3). A First Foothold and The Clean Dream reward 3 each.","zh":"在爆炸物工作台3级用小罐和炸药混合物制作，或向阿波罗购买（限购3个）。“首个立足点”和“净梦计划”各奖励3个。"},"tips":[{"en":"It sells for 1600; do not burn them on small ARC.","zh":"它能卖1600；别拿来打小型ARC。"}],"sources":["https://arcraiders.wiki/wiki/Heavy_Fuze_Grenade","https://metaforge.app/arc-raiders/deal-as-much-damage-as-possible-using-a-heavy-fuze-grenade","https://allthings.how/every-throwable-in-arc-raiders-all-25-grenades-drivers-and-scavenged-items/"],"version":"2.0"},"jolt_mine":{"verdict":{"en":"Craft it for fighting ARC: the stun lasts almost twice as long on machines as on Raiders.","zh":"为打ARC而做：对机器的眩晕时间几乎是对玩家的两倍。"},"use":{"en":"Place it ahead of the path, not at your feet, since it needs a moment to arm. It stuns for 7 seconds on ARC and 4 on Raiders, which gives you a free window to flank or shoot a large machine. Against players the 4 seconds is short, so a stun grenade or Showstopper is usually better.","zh":"要放在前进路径前方而不是脚下，因为需要一点时间启动。对ARC眩晕7秒、对玩家4秒，让你有空档绕后或输出大型机器。对玩家4秒偏短，通常用眩晕类手雷或“耀眼明星”更好。"},"obtain":{"en":"Craft it at the Explosives Station level 2 from a Battery and Electrical Components. Taking Stock, Mixed Signals, Our Presence up There and Building a Library reward it. Apollo also sells it for 2550.","zh":"在爆炸物工作台2级用电池和电子元件制作。“清点物资”、“混合信号”、“我们在上面的据点”和“丰富图书室”任务奖励。阿波罗也有售，价格2550。"},"tips":[{"en":"It can be picked up again if it has not triggered, so you can reposition.","zh":"未触发时可以收回重新布置。"}],"sources":["https://arcraiders.wiki/wiki/Jolt_Mine","https://wzstats.gg/arc-raiders/wiki/items/quick-use/traps/jolt-mine","https://www.exitlag.com/blog/arc-raiders-jump-mine/"],"version":"2.0"},"light_impact_grenade":{"verdict":{"en":"The starter grenade: weak, cheap, and mainly a quest tool for Safe Passage.","zh":"入门手雷：威力弱、成本低，主要是“安全通路”的任务道具。"},"use":{"en":"Thirty damage in a tiny radius will not threaten much; it is for finishing weakened targets or the Safe Passage quest, which only needs a couple of explosive kills. Replace it with a stronger grenade as soon as you can craft one.","zh":"小范围30点伤害构不成威胁，用来补刀或完成“安全通路”，该任务只需要几次爆炸击杀。能做出更强的手雷后就换掉。"},"obtain":{"en":"Apollo hands out the free ones with Safe Passage. Otherwise craft it at the Explosives Station level 1; it is cheaper to craft than to buy at 810.","zh":"阿波罗在“安全通路”里发放免费的。否则在爆炸物工作台1级制作，比810的购买价便宜。"},"tips":[{"en":"Stay a few meters back; the small radius still hurts you.","zh":"退开几米再扔；小范围也会炸到自己。"}],"sources":["https://arcraiders.wiki/wiki/Light_Impact_Grenade","https://metaforge.app/arc-raiders/safe-passage-quest-arc-raiders","https://allthings.how/every-throwable-in-arc-raiders-all-25-grenades-drivers-and-scavenged-items/"],"version":"2.0"},"lil_smoke_grenade":{"verdict":{"en":"Cheap personal cover; bring a few, but it is too small to hide a squad.","zh":"便宜的个人掩护；带几个就行，但小得遮不住小队。"},"use":{"en":"Use it to break a sniper's line of sight, cross open ground or loot a risky body. The cloud is small and lasts 6 seconds, so move as you throw. For revives or extraction cover you want the full Smoke Grenade.","zh":"用来切断狙击视线、穿越空地或搜刮危险的尸体。烟团小、只持续6秒，扔出后要立刻移动。想掩护救援或撤离，需要完整的烟雾手雷。"},"obtain":{"en":"Craft it at the Utility Station level 1 or in raid. Safe Passage gives 5 and Dormant Barons 3. The AR/RD 001 deck's Ninja Pack also lists some.","zh":"在工具工作台1级或局内制作。“安全通路”给5个，“休眠的男爵”给3个。AR/RD 001 卡组的忍者包中也有。"},"tips":[{"en":"Recycling returns just 1 Chemicals of the 5 spent, so craft only what you use.","zh":"回收只返还5个化学品中的1个，按需制作。"}],"sources":["https://arcraiders.wiki/wiki/Li%27l_Smoke_Grenade","https://www.dexerto.com/wikis/arc-raiders/items/quick-use/li-l-smoke-grenade/","https://allthings.how/every-throwable-in-arc-raiders-all-25-grenades-drivers-and-scavenged-items/"],"version":"2.0"},"lure_grenade":{"verdict":{"en":"A good PvE tool for pulling ARC aggro, useless against players, and results are not guaranteed.","zh":"拉ARC仇恨的PvE好工具，对玩家无效，效果也不保证。"},"use":{"en":"It sticks to surfaces and makes noise within a very large radius for 15 seconds. Use it to draw fire while you reposition, revive, loot, or to hold a big ARC still for a Heavy Fuze. It does not stick to Raiders, and one guide notes ARC sometimes ignores it. The trap version is rated lower than the plain grenade; it only suits ambush setups.","zh":"它能粘在表面上，在极大范围内持续发声15秒。用来在你转移、救援、搜刮时吸引火力，或固定大型ARC配合重型引信手雷。它不会粘在玩家身上，也有攻略提到ARC有时会无视它。陷阱版评价低于普通手雷，只适合设伏。"},"obtain":{"en":"Craft it at the Utility Station level 2 after learning the blueprint (Speaker Component and Electrical Components). It is needed by many quests: Boarding the Frigate, Tracks of the Beast, Clamoring for Attention, Stable Housing, On Deaf Ears.","zh":"学会蓝图后在工具工作台2级用扬声器零件和电子元件制作。许多任务需要：“登上护卫者”、“巨兽踪迹”、“哗众取宠”、“稳固住宅”、“充耳不闻”。"},"tips":[{"en":"Keep several for quests before using them freely.","zh":"先给任务留够数量再随便用。"}],"sources":["https://arcraiders.wiki/wiki/Lure_Grenade","https://www.dexerto.com/wikis/arc-raiders/items/quick-use/lure-grenade-trap/","https://www.u4n.com/news/arc-raiders-lure-grenade-trap-craft-recipe-how-to-get.html"],"version":"2.0"},"pulse_mine":{"verdict":{"en":"A knockback mine for creating space, with a minor payoff against players who can step around it.","zh":"用于制造空间的击退地雷，对能绕开的玩家收益有限。"},"use":{"en":"It knocks everyone in a wide radius backward and does no damage. Near ledges, ziplines or stairs the push can drop or disorient people, and it throws off hitboxes for a moment. It can push you too if you stand close. One ranking calls its PvP impact minimal because players avoid or step out of it.","zh":"它把范围内所有人击退，不造成伤害。在高台、滑索或楼梯附近，击退可能让人摔落或失去方向，短暂扰乱判定。你站太近也会被推开。有排行称它的PvP影响很小，因为玩家会躲开。"},"obtain":{"en":"Apollo sells it for 1410 (limit 3). Craft it at the Explosives Station level 1 from Crude Explosives and Wires. A Toxic Trail and Keeping an Eye Out reward it.","zh":"阿波罗售价1410（限购3个）。在爆炸物工作台1级用粗制炸药和导线制作。“有毒的踪迹”和“循目追踪”奖励。"},"tips":[{"en":"Recycling returns 6 Chemicals, a decent consolation if you never use it.","zh":"回收可得6个化学品，不用也不算亏。"}],"sources":["https://arcraiders.wiki/wiki/Pulse_Mine","https://wzstats.gg/arc-raiders/wiki/items/quick-use/traps/pulse-mine","https://boostmatch.gg/blog/arc-raiders/articles/arc-raiders-traps-tier-list-1-3"],"version":"2.0"},"seeker_grenade":{"verdict":{"en":"The go-to answer to flying ARC; poor against big ground machines and useless against players.","zh":"对付飞行ARC的首选；打大型地面机器不行，对玩家无效。"},"use":{"en":"Throw it within 20 meters and it homes on the nearest ARC for 50 damage. Guides say one kills a Wasp, two a Hornet, and a stack handles Launch Tower waves. It can chew through a Leaper with about eight hits but a full stack will not finish a Bastion from full health, so use it as a finisher there. Better than a gun when you want to avoid exposing yourself to players.","zh":"在20米内扔出，会追踪最近的ARC造成50点伤害。攻略称一颗能解决“黄蜂”，两颗解决“马蜂”，一叠可以应付发射塔的波次。大约八颗能磨掉一只“跳跃者”，但一整叠也无法从满血打死“堡垒”，只适合补刀。想避免在玩家面前暴露时，比开枪更好。"},"obtain":{"en":"Apollo sells it for 1920 (limit 6). Craft it at the Explosives Station level 1 from ARC Alloy and Crude Explosives. Boarding the Frigate, Shoring Up Defenses, Sparks Fly, Stable Housing, Test Case and Paving the Way reward it.","zh":"阿波罗售价1920（限购6个）。在爆炸物工作台1级用ARC合金和粗制炸药制作。“登上护卫者”、“加固海岸防线”、“灭蜂大计”、“稳固住宅”、“测试案例”和“开辟道路”奖励。"},"tips":[{"en":"Apollo caps purchases at 6 a day, so crafting is the way to build a stockpile.","zh":"阿波罗每天限购6个，想囤货要靠自己制作。"},{"en":"Keep a stack for Launch Tower events.","zh":"留一叠应对发射塔事件。"}],"sources":["https://arcraiders.wiki/wiki/Seeker_Grenade","https://allthings.how/how-many-seeker-grenades-it-takes-to-kill-a-bastion-in-arc-raiders/","https://www.dexerto.com/wikis/arc-raiders/items/quick-use/seeker-grenade"],"version":"2.0"},"showstopper":{"verdict":{"en":"A strong escape and crowd-control tool, mostly for ARC: the 7-second ARC stun is worth far more than the 2 seconds you get on players.","zh":"逃生和控场利器，主要对付ARC：对ARC眩晕7秒，对玩家只有2秒。"},"use":{"en":"Throw it at a group of pushing ARC, or at your own feet when a big machine closes in, to freeze them while you reload, revive a teammate or walk to extraction. Against raiders the short stun only buys a moment to swap weapons or finish a downed player. It also goes off on direct impact, so it works in a pinch.","zh":"对着正在逼近的ARC群投掷，或在大型机器贴脸时扔向脚边，趁它们被定住时换弹、救队友或走向撤离点。对玩家只有短暂眩晕，只够你换枪或补倒地的人。直接命中目标也会立刻引爆，危急时可用。"},"obtain":{"en":"Craft it at the Explosives Station once you have the blueprint (Voltage Converters are the awkward part). The grenade drops from explosive-type loot such as military storage and Raider camp grenade lockers, and quests hand out several copies.","zh":"学会蓝图后在爆炸物工作台制作，变电器是比较难凑的材料。手雷本体多出自军事仓储和袭击者营地的手雷柜等爆炸物类容器，任务也会送出不少。"},"tips":[{"en":"Quests such as Tracks of the Beast and The Clean Dream already give you several, so don't craft until those are spent.","zh":"“巨兽踪迹”“净梦计划”等任务就会送你好几枚，用完再考虑制作。"},{"en":"Recycling returns two of the three recipe parts, so a spare one is better recycled than sold at 2,100.","zh":"分解能返还三种材料里的两种，多余的拿去分解比卖2100更划算。"}],"sources":["https://arcraiders.wiki/wiki/Showstopper","https://nerdschalk.com/arc-raiders-showstopper-location-use-guide/","https://allthings.how/every-throwable-in-arc-raiders-all-25-grenades-drivers-and-scavenged-items/"],"version":"2.0"},"shrapnel_grenade":{"verdict":{"en":"A cheap early frag for unarmored targets and players; it falls behind heavier grenades once you fight armored ARC.","zh":"便宜的早期破片手雷，适合打玩家和无甲目标；遇到重甲ARC就吃力。"},"use":{"en":"Use it to clear a doorway or flush a player out of a corner. Armor plating shrugs off the 60 damage, so don't count on it against bigger machines; players rate the Heavy Fuze Grenade above it for tougher targets.","zh":"用来清门口或把玩家逼出墙角。60点伤害打不穿装甲板，别指望它对付大型机器；玩家普遍认为更厉害的“重型引信手雷”更适合硬目标。"},"obtain":{"en":"Cheap to craft from Crude Explosives and Steel Springs, and the first quests (A First Foothold, Safe Passage) give three each. Apollo also sells it, but the coin price is steep for what it does.","zh":"用粗制炸药和钢质弹簧制作成本低，“首个立足点”“安全通路”各送三枚。阿波罗也卖，但价格对其威力来说偏高。"},"tips":[{"en":"Craft it in raid if you have the parts rather than buying: Apollo's price is three times the sell value.","zh":"有材料就在局内自己做，阿波罗的售价是出售价的三倍。"}],"sources":["https://arcraiders.wiki/wiki/Shrapnel_Grenade","https://www.dexerto.com/wikis/arc-raiders/items/quick-use/shrapnel-grenade/","https://allthings.how/every-throwable-in-arc-raiders-all-25-grenades-drivers-and-scavenged-items/"],"version":"2.0"},"smoke_grenade":{"verdict":{"en":"Worth keeping a few: a 20-second cloud saves revives, crossings and extractions, and it is made from common Chemicals.","zh":"值得常备几枚：20秒烟幕能保住救人、过空地和撤离，材料只是常见的化学品。"},"use":{"en":"Drop it between you and a sniper, on a downed teammate before a revive, or over the extraction point. It blocks sight for both ARC and raiders. Combine it with a Tagging Grenade to see enemies inside the smoke while they cannot see you.","zh":"扔在你和狙击手之间、救倒地队友之前，或撤离点上方。它同时遮挡ARC和玩家的视线。配合标记手雷，可以看到烟里的敌人而对方看不到你。"},"obtain":{"en":"The blueprint comes from residential containers, so loot homes rather than industrial spots. Once learned, 14 Chemicals and a Canister make one; otherwise Apollo sells a few each day.","zh":"蓝图出自居民类容器，所以应搜居住区而非工业区。学会后用14份化学品和一个小罐即可制作，也可以向阿波罗购买，每天有限量。"},"tips":[{"en":"The cheaper Li'l Smoke Grenade covers short dashes; save the big one for revives and extraction.","zh":"便宜的小型烟雾手雷适合短距离冲刺，大烟雾手雷留给救人和撤离。"}],"sources":["https://arcraiders.wiki/wiki/Smoke_Grenade","https://metaforge.app/arc-raiders/database/item/smoke-grenade-blueprint","https://blog.acer.com/en/discussion/3827/best-grenades-to-use-in-arc-raiders"],"version":"2.0"},"smoke_grenade_trap":{"verdict":{"en":"A niche trap: fine as an automatic escape screen at a choke point, but a thrown smoke is faster and more reliable.","zh":"偏冷门的陷阱：放在要道自动放烟还行，但直接扔烟雾手雷更快更稳。"},"use":{"en":"Stretch the laser across your retreat path or a doorway so it blankets the area when someone crosses. The beam is red and visible, so hide it behind cover or corners. An untriggered trap can be disarmed and picked up, so it costs nothing to reposition.","zh":"把激光拉在撤退路线或门口，有人经过时自动放烟。红色光束肉眼可见，要藏在掩体或拐角后。未触发的陷阱可以拆除回收，换位置不会亏。"},"obtain":{"en":"Craft it from a Smoke Grenade and Wires, in raid or at the Workbench, after learning the blueprint. The quest Battening Down gives three.","zh":"学会蓝图后，用一枚烟雾手雷加导线制作，局内或工作台均可。“加固防御”任务送三枚。"},"tips":[{"en":"It uses up a whole Smoke Grenade, so only build one when you will actually be setting up a position.","zh":"它会消耗一整枚烟雾手雷，真要守点时再做。"}],"sources":["https://arcraiders.wiki/wiki/Laser_Trap:_Smoke","https://nerdschalk.com/arc-raiders-all-traps-guide/","https://blog.acer.com/en/discussion/3859/all-traps-in-arc-raiders-ranked"],"version":"2.0"},"snap_blast_grenade":{"verdict":{"en":"Craft a stack of these: a sticky 70-damage bomb that works on players and flying ARC.","zh":"值得做一叠：粘性的70点伤害炸弹，对玩家和飞行ARC都管用。"},"use":{"en":"It sticks where it lands, so throw it at a rushing opponent or into a doorway and it is hard to dodge. Against flying ARC it is a go-to: a Wasp dies to one, while a Rocketeer takes a few.","zh":"落地即粘，扔向冲来的对手或门口很难躲。对付飞行ARC尤其好用：黄蜂一枚就死，火箭手要几枚。"},"obtain":{"en":"Craft it from Crude Explosives and a Magnet; the Magnet is the limiting part. A First Foothold, Safe Passage and Sparks Fly all pay out copies, and Apollo stocks three a day.","zh":"用粗制炸药和磁铁制作，磁铁是瓶颈。“首个立足点”“安全通路”“灭蜂大计”都会给，阿波罗每天供应三枚。"},"tips":[{"en":"Sparks Fly asks you to hand some in, so don't recycle early copies.","zh":"“灭蜂大计”需要上交，前期别分解。"},{"en":"Recycling returns only one Magnet and one Chemicals, so keep them for throwing.","zh":"回收只得 1 个磁铁和 1 份化学品，留着当手雷用更划算。"}],"sources":["https://arcraiders.wiki/wiki/Snap_Blast_Grenade","https://esports.ru/guides/kak-ispolzovat-granaty-v-arc-raiders/","https://allthings.how/every-throwable-in-arc-raiders-all-25-grenades-drivers-and-scavenged-items/"],"version":"2.0"},"snowball":{"verdict":{"en":"A joke item: harmless, worthless and gone when the raid ends, only useful for Cold Snap trials.","zh":"纯娱乐道具：几乎没伤害、不值钱，离局即消，只有寒潮的试炼用得上。"},"obtain":{"en":"Only on Cold Snap variants of Dam Battlegrounds, Buried City, The Spaceport and The Blue Gate. Pick up from snow piles on the surface; none on Stella Montis. Unspent snowballs turn to water in the stash.","zh":"只出现在寒潮版的大坝战场、掩埋废城、太空港和蓝门地表，从雪堆中拾取。星辰山没有。没用掉的雪球回到藏身处会化成水。"},"tips":[{"en":"Weekly trials like throwing snowballs at Rocketeers or Bastions are the only real reason to collect them.","zh":"每周试炼里要求向火箭手或堡垒扔雪球，这才是收集它们的实际理由。"},{"en":"Staying outside in the cold builds frostbite, so grab them and move on.","zh":"在室外久待会积累冻伤，捡了就走。"}],"sources":["https://arcraiders.wiki/wiki/Snowball","https://allthings.how/snowball-fights-in-arc-raiders-how-they-work-and-where-to-find-them/","https://nerdschalk.com/throw-snowballs-at-rocketeers-weekly-trial-in-arc-raiders-locations-loadouts-tips/"],"version":"2.0"},"surge_coil":{"verdict":{"en":"A situational decoy and zone-denial gadget; interesting for holding a spot, too expensive to bring casually.","zh":"偏场合的诱饵和区域封锁装置，适合守点，不适合随便带。"},"use":{"en":"Place it where you plan to hold or loot. It zaps everything within 10 metres every couple of seconds and ARC redirect their aggression toward it like a lure. Its small health pool means it wears out, so treat it as a temporary shield for a fight or revive.","zh":"放在你要守或要搜刮的地方。它每隔几秒电击10米内一切，ARC会像被诱饵吸引一样转而攻击它。血量不高会被磨掉，当作战斗或救人时的临时屏障。"},"obtain":{"en":"Apollo sells it for a lot of coins, or craft it at Explosives Station 3 after learning the blueprint. The First Nomads and Safe Harbor reward copies.","zh":"阿波罗有售但很贵，也可学会蓝图后在爆炸物工作台3级制作。“初代游民”和“安全港湾”会送。"},"tips":[{"en":"Do not buy it from Apollo: his price is three times its sell value, and quests already supply a few.","zh":"别向阿波罗买：售价是出售价的三倍，任务本来就会送几个。"}],"sources":["https://arcraiders.wiki/wiki/Surge_Coil","https://arcraiders.wiki/wiki/Grenades"],"version":"2.0"},"tagging_grenade":{"verdict":{"en":"An information tool for players hiding in buildings or smoke; skip it if you mostly fight ARC.","zh":"情报道具，用来揪藏在建筑或烟里的玩家；主要打ARC就别带。"},"use":{"en":"Throw it into a room or smoke cloud to reveal everyone inside for about 30 seconds. Players describe pairing it with a Smoke Grenade as the best use. Some say the tag lasts shorter than the tooltip claims.","zh":"扔进房间或烟幕，大约30秒内显示里面所有人。玩家认为配烟雾手雷最好用，也有人说实际标记时间比说明短。"},"obtain":{"en":"Craft at the Utility Station level 3 from Electrical Components and Sensors. The League gives five, and Clamoring for Attention and Eyes in the Sky three each.","zh":"在工具工作台3级用电子元件和传感器制作。“球队”送五枚，“哗众取宠”“天空之眼”各送三枚。"},"tips":[{"en":"Quest rewards cover most needs, so there is little reason to build many.","zh":"任务奖励基本够用，没必要大量制作。"}],"sources":["https://arcraiders.wiki/wiki/Tagging_Grenade","https://www.rosenberryrooms.com/arc-raiders-explosives-tier-list/","https://allthings.how/every-throwable-in-arc-raiders-all-25-grenades-drivers-and-scavenged-items/"],"version":"2.0"},"trigger_nade":{"verdict":{"en":"Cheap and flexible: the best ambush grenade when you control the timing, and a PvE tool for sticking to ARC.","zh":"便宜又灵活：你掌握引爆时机时是最好的伏击手雷，也能粘在ARC身上。"},"use":{"en":"Throw it onto a surface, ARC or player and detonate it with the aim button when targets are in range. It never explodes on its own. Use at extraction points and chokepoints. A nerf in early 2026 lengthened the delay, so mid-air detonation is harder.","zh":"扔到墙面、ARC或玩家身上，目标进入范围后用瞄准键引爆，它不会自己爆炸。适合撤离点和要道。早先的削弱拉长了延迟，半空引爆更难。"},"obtain":{"en":"Finish the Sparks Fly quest for the blueprint, then craft at the Explosives Station with Crude Explosives and a Processor. Loot drops are inconsistent.","zh":"完成“灭蜂大计”任务拿蓝图，之后用粗制炸药和处理器在爆炸物工作台制作。掉落不稳定。"},"tips":[{"en":"Switch away and back later and you can still detonate it.","zh":"切换到别的物品再切回来，仍能引爆。"}],"sources":["https://arcraiders.wiki/wiki/Trigger_%27Nade","https://allthings.how/how-trigger-nades-detonate-in-arc-raiders-and-how-to-use-them/","https://nerdschalk.com/trigger-nades-in-arc-raiders-stats-uses-how-to-unlock/"],"version":"2.0"},"wolfpack":{"verdict":{"en":"The best anti-ARC grenade for big targets, but it is pricey and unreliable against players.","zh":"对付大型ARC最好的手雷，但造价高，对玩家不太行。"},"use":{"en":"Throw it when several ARC are visible so the 12 homing missiles split across targets. Players rate it for Rocketeers, flyers, Bastions and Bombardiers; bosses with many hitboxes use the spread less efficiently. Missiles hunt ARC, not raiders.","zh":"在多个ARC同时可见时投掷，12枚追踪导弹会分散命中。玩家推荐用来打火箭手、飞行单位、堡垒和投弹手；多部位的首领会让弹幕效率变低。导弹追踪ARC，不针对玩家。"},"obtain":{"en":"Craft at Explosives Station 3 with ARC Motion Cores and a Rocketeer Driver; those parts are the expense. Bait, Fetch, Blast, Out of the Shadows and Tracks of the Beast reward some.","zh":"在爆炸物工作台3级制作，需要ARC运动核心和“火箭手”引擎，开销主要在这里。“诱饵、搜寻、爆破”“走出阴影”“巨兽踪迹”有奖励。"},"tips":[{"en":"It does not stack, so one slot per grenade; carry few.","zh":"不能堆叠，一枚占一格，少带。"},{"en":"Trophy Display needs five, so hold off recycling.","zh":"“战利品展示”项目需要五枚，别急着分解。"}],"sources":["https://arcraiders.wiki/wiki/Wolfpack","https://nerdschalk.com/arc-raiders-wolfpack-location-crafting-and-usage-guide/","https://deltiasgaming.com/?p=395655"],"version":"2.0"},"yank_grenade":{"verdict":{"en":"A new 2.0 utility grenade with little community data yet; try it before spending parts.","zh":"2.0新增的功能手雷，社区资料还很少，先试用再投入材料。"},"use":{"en":"It anchors a line to whatever it hits and pulls the target toward the point of impact for a second. The wiki page is still a stub, so exact matchups are unconfirmed.","zh":"它会把绳索固定在命中物上，把目标拉向落点约1秒。维基页面仍是草稿，具体对阵效果尚未证实。"},"obtain":{"en":"Craft at Explosives Station 2 with Crude Explosives and Rope after learning the blueprint. Salvaging returns Fabric.","zh":"学会蓝图后在爆炸物工作台2级用粗制炸药和绳子制作。拆解可得布料。"},"tips":[{"en":"Avoid third-party sites selling the blueprint.","zh":"不要从第三方网站购买蓝图。"}],"sources":["https://arcraiders.wiki/wiki/Yank_Grenade","https://arcraiders.wiki/wiki/Grenades"],"version":"2.0"},"deadline":{"verdict":{"en":"Worth owning the blueprint for: a 1,000-damage mine that can erase a Bastion or Bombardier in one blast.","zh":"值得入手蓝图：1000点伤害的地雷，一发就能炸掉堡垒或投弹手。"},"use":{"en":"Arm it next to a big ARC or inside a room you will bait enemies into. You cannot disarm or detonate it early; it blows after 6 seconds, hits several parts of large machines at once, and is lethal to raiders without cover. Run before it goes.","zh":"贴在大型ARC旁，或布置在你要引敌进入的房间里。放下后无法拆除或提前引爆，6秒后爆炸，大型机器的多个部位同时受伤，没掩体的玩家会被秒。记得及时撤开。"},"obtain":{"en":"Blueprints come from Raider Caches, weapon boxes, medical bags and grenade tubes; reports mention the Control Tower on Dam Battlegrounds and Town Hall in Buried City. The Clean Dream gives two.","zh":"蓝图出自袭击者储物箱、武器箱、医疗包和榴弹筒；有人提到大坝战场控制塔和掩埋废城市政厅。“净梦计划”送两枚。"},"tips":[{"en":"Craft rather than buy; Apollo's daily stock of one is very expensive.","zh":"自己制作，别买；阿波罗每天只有一枚，价格很高。"},{"en":"Do not recycle it: the return is only half the materials.","zh":"别分解，只能拿回一部分材料。"}],"sources":["https://arcraiders.wiki/wiki/Deadline","https://allthings.how/how-the-deadline-blueprint-works-in-arc-raiders-and-why-its-worth-chasing/","https://timesaver.gg/blog/arc-raiders-deadline-mine-guide"],"version":"2.0"},"barricade_kit":{"verdict":{"en":"A reusable shield for revives and holding a corner; cheap, and anyone can pull it down in five seconds.","zh":"可重复使用的掩体，适合救人和守拐角；便宜，但谁都能5秒拆掉。"},"use":{"en":"Deploy it between you and incoming fire while reviving, reloading or healing. Dismantle and pick it up to redeploy at full health. Laser traps work on it, while mines placed on it fall to the ground without triggering.","zh":"在救人、换弹、治疗时架在你和火力之间。拆下后可回收，满血重新部署。激光陷阱能放在上面，地雷会掉到地面且不触发。"},"obtain":{"en":"Craft it with one Mechanical Component at the Utility Station after learning the blueprint, or buy up to six a day from Apollo. Safe Passage, Reduced to Rubble and Shoring Up Defenses give three each.","zh":"学会蓝图后用一个机械元件在工具工作台制作，或每天向阿波罗买最多六个。“安全通路”“化为废墟”“加固海岸防线”各送三个。"},"tips":[{"en":"If you leave it behind, the next raider can use it too, so take it with you.","zh":"留下的话别人也能用，走时带走。"}],"sources":["https://arcraiders.wiki/wiki/Barricade_Kit","https://www.dexerto.com/wikis/arc-raiders/items/quick-use/barricade-kit/"],"version":"2.0"},"door_blocker":{"verdict":{"en":"A cheap single-use lock for button-operated doors, mainly worth carrying for the quests that ask for them.","zh":"便宜的一次性锁，用于按钮门；主要是任务需要才值得带。"},"use":{"en":"Stick it on a door you have just passed through, to slow pursuers or protect a room while you loot. It cannot be recovered, only breached.","zh":"贴在你刚通过的门上，拖延追兵或在搜刮时守住房间。无法回收，只能破门。"},"obtain":{"en":"Cheap to craft from Metal Parts and Rubber Parts at the Utility Station. Reduced to Rubble, A Prime Specimen and Dormant Barons each give three.","zh":"在工具工作台用金属零件和橡胶零件就能做。“化为废墟”“完美样本”“休眠的男爵”各送三个。"},"tips":[{"en":"Apollo's price is three times its sell value; craft or use quest copies.","zh":"阿波罗卖的价格是出售价三倍，自己做或用任务奖励。"}],"sources":["https://arcraiders.wiki/wiki/Door_Blocker","https://www.dexerto.com/wikis/arc-raiders/items/quick-use/door-blocker/"],"version":"2.0"},"noisemaker":{"verdict":{"en":"A cheap early-warning alarm; fine for sleeping spots, but quests ask for it more than combat does.","zh":"便宜的预警警报；适合守着休息，更多是任务在要它。"},"use":{"en":"Attach it near a door or stairwell you are looting; it sounds an alarm when raiders enter its 8 metre radius, so you can fight on your terms.","zh":"装在你搜刮时附近的门口或楼梯口；玩家进入8米范围就会响铃，让你先手。"},"obtain":{"en":"Craft it in raid from Plastic Parts and a Speaker Component. Many early quests take it: Clamoring for Attention and On Deaf Ears want five each.","zh":"可在局内用塑料零件和扬声器零件制作。很多前期任务要它：“哗众取宠”“充耳不闻”各要五个。"},"tips":[{"en":"Do not buy at Apollo's price; the recipe is two cheap parts.","zh":"别按阿波罗的价格买，配方只要两种便宜材料。"}],"sources":["https://arcraiders.wiki/wiki/Noisemaker","https://www.dexerto.com/wikis/arc-raiders/items/quick-use/noisemaker/"],"version":"2.0"},"trailblazer":{"verdict":{"en":"A niche fire trap for corridors and large ground ARC like Leapers, not a general-purpose grenade.","zh":"小众的火焰陷阱，适合走廊和“跳跃者”这类大型地面ARC，不是万能手雷。"},"use":{"en":"Throw it so the gas trail lies where enemies must cross, then it ignites in a chain. Trial guides say Leapers are the best target. Players also throw it into a room and shut the door on a Shredder. Stack several for a Bastion.","zh":"让气体拖尾铺在敌人必经之路，随后连锁点燃。试炼攻略认为“跳跃者”最合适。也有人把它扔进房间再关门对付“粉碎者”。打“堡垒”要叠几枚。"},"obtain":{"en":"Craft at Explosives Station 3 with a Firefly Burner and Synthesized Fuel. Deciphering The Data and Fragmented Logs give three each.","zh":"在爆炸物工作台3级用“萤火虫”燃烧炉和合成燃料制作。“解密数据”“碎片日志”各送三枚。"},"tips":[{"en":"Quest copies cover testing; skip building spares unless a trial needs it.","zh":"任务奖励够试用，除非试炼需要，别特意做备用。"}],"sources":["https://arcraiders.wiki/wiki/Trailblazer","https://www.altchar.com/guides/arc-raiders-how-to-complete-the-deal-damage-using-a-trailblazer-grenade-trial-aQXsi7e8ANPc","https://allthings.how/every-throwable-in-arc-raiders-all-25-grenades-drivers-and-scavenged-items/"],"version":"2.0"},"acoustic_guitar":{"verdict":{"en":"A social toy with zero combat value; hold it only for the Trophy Display project or to jam with friends.","zh":"纯社交道具，没有战斗价值，只为“战利品展示架”项目或和朋友合奏留着。"},"use":{"en":"It plays one of seven melodies, and nearby Raiders can join in with a Recorder or Shaker. While you play, many two-handed actions are blocked, so only strum when the area is quiet and you are not about to loot or climb.","zh":"能演奏七段旋律之一，附近的奇袭者可以用可演奏长笛或摇铃加入合奏。演奏时许多双手操作会被禁用，只适合在安静时弹，别在要搜刮或攀爬前用。"},"obtain":{"en":"Shani no longer sells it after 2.0, and no quest rewards it. The reliable routes are completing the Trophy Display project and the Goalie Raider Deck (AR/RD 002). Recycling returns Metal Parts and Wires, far below its 7000 sale value, so keep or sell it rather than break it down.","zh":"2.0 后萨尼不再出售，也没有任务奖励。稳妥的来源是完成“战利品展示架”项目，或奇袭者套件 AR/RD 002。回收只得金属零件和导线，远低于 7000 的售价，别拆。"},"tips":[{"en":"At 7000 it is one of the most valuable Quick Use items to sell, but it takes a quick use slot and stacks to 1.","zh":"售价 7000，是最值钱的快速使用物品之一，但堆叠上限为 1，还占快速使用栏。"}],"sources":["https://arcraiders.维基/维基/Acoustic_Guitar","https://www.dexerto.com/维基s/arc-raiders/items/quick-use/acoustic-guitar/"],"version":"2.0"},"adrenaline_shot":{"verdict":{"en":"Cheap stamina refill that is good for kiting and escapes, but never a replacement for healing.","zh":"便宜的体力回复针，适合风筝和脱身，但不能代替治疗。"},"use":{"en":"It fully refills stamina in one second and then boosts regeneration for 10 seconds. Use it when you are out of stamina mid-chase or mid-climb, not as a health item. Players ranking post-Riven Tides items rate it as a cheap raid saver, but not top tier.","zh":"1 秒内回满体力，之后 10 秒内体力恢复加快。适合追逐或攀爬中体力耗尽时用，不回血。玩家对裂潮镇更新后物品的排名里它算便宜的救场道具，但不是顶级。"},"obtain":{"en":"Lance sells it for 900, three times its 300 value. Crafting costs six materials but recycling returns only two, so crafting is poor value. Seven quests, including Espresso and Doctor's Orders, hand you three each, which covers most needs.","zh":"兰斯卖 900，是价值 300 的三倍。制作要六份材料而回收只返还两份，不划算。“浓缩咖啡”“医生的订单”等七个任务各送三支，基本够用。"},"tips":[{"en":"Do not buy it from Lance; take the quest copies and craft only if you have spare Chemicals.","zh":"别向兰斯买，用任务送的就好，化学品有富余再制作。"}],"sources":["https://arcraiders.维基/维基/Adrenaline_Shot","https://nerdschalk.com/arc-raiders-adrenaline-shot-location-use-guide/","https://ggwtb.com/blog/arc-raiders-best-items-guide-top-10-overpowered-items-after-riven-tides"],"version":"2.0"},"advanced_camera":{"verdict":{"en":"A sidegrade to the Basic Camera that only photography fans need; skip it for your quick use slots.","zh":"是简易相机的升级款，只有爱拍照的玩家需要，快速使用栏不必给它。"},"use":{"en":"The wiki says it does everything the Basic Camera does and more, but community pages have not documented the extras yet. For quests that ask for photos, the Basic Camera already works.","zh":"社区维基称它能完成简易相机的一切并有额外功能，但目前还没有页面写明具体差别。需要拍照的任务用简易相机就够了。"},"obtain":{"en":"Shani sells up to 3 at 3000 each, and it also appears in the free Reward Pass. You can craft it at Utility Station level 1 once you learn the blueprint, from a Calculator, Camera Lens and Electrical Components.","zh":"萨尼出售，限购 3 个，每个 3000；免费奖励通行证也有。学会蓝图后可在工具工作台 1 级用计算器、相机镜头和电子元件制作。"},"tips":[{"en":"Recycling gives back a Calculator, so a spare is not a total loss.","zh":"回收可得到计算器，多出来的也不算白费。"}],"sources":["https://arcraiders.维基/维基/Advanced_Camera","https://beebom.com/how-to-unlock-camera-in-arc-raiders/"],"version":"2.0"},"agave_juice":{"verdict":{"en":"A cheap in-raid stamina drink; it sells for more than bandages, but the health cost makes it a niche pick.","zh":"局内可造的廉价体力饮料，卖价比绷带高，但要扣血，属于小众选择。"},"use":{"en":"It boosts stamina regeneration for 10 seconds at a cost of 5 health. Drink it before a sprint or long fight when you are healthy; do not use it at low health. The Adrenaline Shot does the same job without hurting you and also refills stamina instantly.","zh":"10 秒内加快体力恢复，代价是扣 5 点生命。在血量健康、要冲刺或长时间交战前饮用，残血别喝。肾上腺素针剂不扣血，还能立即回满体力，效果更好。"},"obtain":{"en":"Craft it in a raid from Agave and an Empty Wine Bottle. Players report Agave around Riven Tides dunes and the northwest of Dam Battlegrounds; bottles show up in homes and kitchens. Salvaging the juice returns the bottle.","zh":"在局内用龙舌兰叶和空酒瓶制作。玩家反馈龙舌兰叶多见于裂潮镇沙丘和大坝战场西北，空酒瓶常在民居和厨房。拆解成品能拿回酒瓶。"},"tips":[{"en":"Its 1800 sale value is high for two cheap inputs, so it is also a small money-maker if you already carry the ingredients.","zh":"两份便宜材料就值 1800，顺手带着材料的话也算小赚。"}],"sources":["https://arcraiders.维基/维基/Agave_Juice","https://www.millenium.org/guide/430229.html","https://nerdschalk.com/arc-raiders-empty-wine-bottle-location-use-guide/"],"version":"2.0"},"bandage":{"verdict":{"en":"The default early heal: craft it from Fabric and never buy it from Lance.","zh":"前期的默认治疗品：用布料自己做，别向兰斯买。"},"use":{"en":"It heals 2 per second for 10 seconds, about 20 health, after a 1.5 second use. That is slow, so apply it after you break line of sight. The Herbal Bandage heals faster but is costlier to buy.","zh":"使用 1.5 秒后 10 秒内每秒回 2 点，共约 20 点。回血慢，先脱离视线再用。草药绷带回得更快，但购买更贵。"},"obtain":{"en":"Five Fabric at a Workbench or Medical Lab, or in the raid with in-round crafting. Lance asks 750, three times its 250 value. Recycling returns only 2 Fabric.","zh":"用五份布料在工作台或医疗实验室制作，学会局内制作后也能在局内做。兰斯卖 750，是价值 250 的三倍。回收只返还 2 份布料。"},"tips":[{"en":"Keep a stack of five in your quick use bar and carry spare Fabric to craft more mid-raid.","zh":"快速使用栏放满五个，另带些布料以便局内补做。"}],"sources":["https://arcraiders.维基/维基/Bandage","https://nerdschalk.com/arc-raiders-all-medical-supplies-locations-and-usage-guide/"],"version":"2.0"},"banjo":{"verdict":{"en":"A novelty instrument with no combat use; keep it only if you want to play music in raids.","zh":"纯娱乐乐器，没有战斗用途，想在局内弹奏再留着。"},"use":{"en":"Like the other instruments, it attracts ARC attention and impresses other Raiders, and blocks many two-handed actions while you play. Do not play it when enemies are near.","zh":"和其他乐器一样，会吸引 ARC 注意，也能让其他奇袭者眼前一亮，弹奏时许多双手操作会被禁用。附近有敌人时别弹。"},"obtain":{"en":"New in 2.0. The community wiki lists no spawn source, and I found no map location for it. A French report says its blueprint comes with the Collector DLC set. You can craft it at a Workbench level 1 after learning the blueprint, from Plastic Parts and Steel Cable.","zh":"2.0 新增。社区维基没有列出来源，也没找到地图位置；有法语报道称蓝图随收藏家 DLC 套装附送。学会蓝图后可在工作台 1 级用塑料零件和钢缆制作。"},"tips":[{"en":"Its 1000 sale value beats its crafting cost, but check that blueprint availability first.","zh":"它 1000 的售价高于制作成本，但先确认你有没有蓝图。"}],"sources":["https://arcraiders.维基/维基/Banjo","https://www.xboxygen.com/?p=368617"],"version":"2.0"},"basic_camera":{"verdict":{"en":"Needed for photo quests and then dead weight; carry one only when a quest asks for it.","zh":"只有拍照任务才需要，完成后就是累赘，要做任务时再带。"},"use":{"en":"Equip it in a quick use slot, aim and shoot. Sizing Things Up asks you to photograph fixed subjects, and several other quests give you a camera. It is lost if you die with it, so a spare is cheap insurance.","zh":"放入快速使用栏，瞄准后拍摄。“审时度势”要求拍摄固定目标，另有多个任务会送你相机。带着死亡会丢失，所以备一个便宜的当保险。"},"obtain":{"en":"Shani sells up to 3 daily for 1920. Eight quests, such as Sizing Things Up, hand you one, so buying is rarely needed. Crafting costs 8 Plastic Parts and a Wires at Workbench level 1.","zh":"萨尼每天限购 3 个，每个 1920。“审时度势”等八个任务会送一个，所以很少需要买。工作台 1 级用 8 塑料零件和 1 导线即可制作。"},"tips":[{"en":"Recycling returns Plastic Parts, but crafting it is cheap, so only sell it if you have no photo quest left.","zh":"回收只得塑料零件，而制作成本很低，没有拍照任务了再卖掉。"}],"sources":["https://arcraiders.维基/维基/Basic_Camera","https://www.destructoid.com/how-to-get-and-use-the-camera-in-arc-raiders/","https://www.playnews.gg/en/guides/arc-raiders-basic-camera-how-to-craft-it-and-take-a-photo"],"version":"2.0"},"binoculars":{"verdict":{"en":"A scouting tool for careful players; worth a slot only if you have spare quick use space.","zh":"给谨慎玩家侦察用的工具，快速使用栏有空位才值得带。"},"use":{"en":"It gives two zoom levels, and you can ping enemies or items while scoped. Use it to check open ground and POIs before committing. It gives information only, so a Zipline or Barricade Kit beats it when slots are tight.","zh":"有两档放大，开镜时可标记敌人或物品。适合在推进前观察空地和兴趣点。它只提供情报，栏位紧张时不如滑索或路障工具。"},"obtain":{"en":"Craft it at Utility Station level 1 from Plastic and Rubber Parts, no blueprint needed. Six quests, like Combat Recon, give you one, and the Ryder and Voyager Raider Deck holds 3. Shani sells it for 1920.","zh":"在工具工作台 1 级用塑料零件和橡胶零件制作，无需蓝图。“战斗侦察”等六个任务会送一个，奇袭者套件 AR/RD 001里有 3 个。萨尼卖 1920。"},"tips":[{"en":"It has durability, so repair it with Plastic and Rubber Parts instead of buying a new one.","zh":"它有耐久，用塑料零件和橡胶零件修理，比重买划算。"}],"sources":["https://arcraiders.维基/维基/Binoculars","https://allthings.how/arc-raiders-gadgets-and-utilities-every-item-uses-and-crafting/","https://www.dexerto.com/维基s/arc-raiders/items/quick-use/binoculars/"],"version":"2.0"},"light_sticks_blue_green":{"verdict":{"en":"Cheap throwable lights; keep a handful for quests and skip them in your quick use bar.","zh":"廉价投掷照明，留几根交任务，不必占快速使用栏。"},"use":{"en":"Each lights a 7m radius for 40 seconds. That helps in dark interiors and for marking a spot, but it also shows others where you threw it. Red and yellow versions work the same.","zh":"每根照亮半径 7 米，持续 40 秒。适合照亮黑暗室内或做标记，但也会暴露你的位置。红色、黄色版本效果相同。"},"obtain":{"en":"Quests give them: A Warm Place To Rest, After Rain Comes and The Clean Dream five each of Blue, In My Image five Green. Shani sells for 3000, but Apollo's 450 offer was listed by the community wiki. Both need the blueprint and 3 Chemicals at a Utility Station.","zh":"任务会送：“温暖的休憩之地”“风雨过后”“净梦计划”各 5 根蓝色，“与我同形”5 根绿色。萨尼标价 3000，社区维基另提到阿波罗 450。在工具工作台制作需要蓝图和 3 化学品。"},"tips":[{"en":"Crafting spends 3 Chemicals but recycling returns 1, so use quest copies and do not craft extras.","zh":"制作花 3 化学品，回收只返还 1，用任务送的，别额外制作。"}],"sources":["https://arcraiders.维基/维基/Blue_Light_Stick","https://arcraiders.维基/维基/Green_Light_Stick","https://www.dexerto.com/维基s/arc-raiders/items/quick-use/blue-light-stick/"],"version":"2.0"},"crash_mat":{"verdict":{"en":"A niche but real escape tool for big drops; craft a few when you need one.","zh":"高处跳落时很实用的小众保命道具；需要时做几个备着。"},"use":{"en":"Throw it at the ground before you jump, then land on it to avoid fall damage up to 10m. The mat is small and lasts about 10 seconds, so a bad throw or drift misses it. A teammate cannot reuse your mat.","zh":"先把它扔到地上再跳，落在垫上可避免 10 米内的摔伤。垫子不大且持续约 10 秒，投偏或下落时漂移就会落空。队友不能共用同一块垫子。"},"obtain":{"en":"Wires Crossed gives you 2. Craft it from Durable Cloth and Electrical Components after learning the blueprint, at Utility Station level 2 or in the raid. Sources differ on where the blueprint drops, so treat any specific spot as unverified.","zh":"“线路交错”送 2 个。学会蓝图后，用耐磨布料和电子元件在工具工作台 2 级或局内制作。蓝图掉落位置各来源说法不一，具体地点不要尽信。"},"tips":[{"en":"No live project needs it, so keep only what you will throw; recycling returns 6 Fabric and 3 Plastic Parts.","zh":"目前没有进行中的项目要它，只留自己要扔的；回收可得 6 布料和 3 塑料零件。"}],"sources":["https://arcraiders.维基/维基/Crash_Mat","https://nerdschalk.com/arc-raiders-crash-mat-blueprint-location-crafting-and-uses-explained/","https://www.destructoid.com/how-to-get-the-crash-mat-blueprint-in-arc-raiders/"],"version":"2.0"},"defibrillator":{"verdict":{"en":"A strong squad insurance item; carry one or two when you play with friends.","zh":"组队时的强力保险，和朋友一起玩带一两支。"},"use":{"en":"It revives a downed Raider, in your party or not, and restores health faster than a normal revive. It only works on downed players, not fully dead ones. Reviving a random player for 3000 coins is rarely worth it, but it can win you an ally.","zh":"能救起倒地的奇袭者，无论是否在你队里，且回血比普通救援多。只对倒地者有效，对已死亡者无效。花 3000 钱币救陌生人通常不划算，但有时能换来盟友。"},"obtain":{"en":"Lance sells it for 3000. Nine quests such as Medical Merchandise and Armored Transports reward it, and the Raider Decks hold 3 each. Crafting needs the blueprint, Medical Lab level 2, 9 Plastic Parts and 1 Moss.","zh":"兰斯卖 3000。“医疗物资”“装甲运输”等九个任务会奖励，奇袭者套件里各有 3 支。制作需要蓝图、医疗实验室 2 级、9 塑料零件和 1 苔藓。"},"tips":[{"en":"Do not recycle it: you get only 1 Moss and 1 Plastic Part back from a 1000 value item.","zh":"别回收，一件价值 1000 的物品只返还 1 苔藓和 1 塑料零件。"}],"sources":["https://arcraiders.维基/维基/Defibrillator","https://www.neonlightsmedia.com/blog/arc-raiders-how-to-revive-enemies-teammates-defib-guide","https://wzstats.gg/arc-raiders/维基/items/quick-use/healing/defibrillator"],"version":"2.0"},"dockmasters_detector":{"verdict":{"en":"Only useful on Riven Tides when Beachcombing is active; skip it on every other run.","zh":"仅在裂潮镇“海滩拾荒点”条件开启时有用，其他对局别带。"},"use":{"en":"It reveals caches buried in the sand: beeps speed up as you near one. You walk slowly while it runs, and a shared energy meter means carrying several does not extend runtime. Digging can turn up ARC Ticks and mines, so check surroundings first.","zh":"能找出埋在沙里的物资，越近蜂鸣越快。使用时只能慢走，所有探测器共用一条能量，多带无用。挖掘可能挖出 ARC 蜱虫或地雷，先看四周。"},"obtain":{"en":"Apollo sells up to 2 at 1920, and Shoring Up Defenses rewards one. Community guides also name shipping containers, but that is unconfirmed here. It cannot be recycled.","zh":"阿波罗限购 2 个，每个 1920；“加固海岸防线”送一个。社区攻略还提到货柜，这里未能确认。无法回收。"},"tips":[{"en":"Keep it for the Mountaineer's Detector ingredient, and bring Batteries to repair it.","zh":"它是“登山者探测器”的材料，别随手卖，另带电池以便修理。"}],"sources":["https://arcraiders.维基/维基/Dockmaster%27s_Detector","https://www.keengamer.com/articles/guides/arc-raiders-beachcombing-cache-locations-and-dockmasters-detector/","https://nerdschalk.com/arc-raiders-beachcombing-on-the-riven-tides-map-dockmasters-detector-tool-requirements-and-using-detector-guide/"],"version":"2.0"},"emperor_beacon":{"verdict":{"en":"Use it on the spot at Pendola Pass: it is the key to the Emperor's coupler loot.","zh":"在彭多拉山口当场使用：它是拿“帝王”耦合器战利品的钥匙。"},"use":{"en":"Place it in an open area to call in Harvester Payloads. Debris starts falling soon after, so move away at once. One main payload holds the three Couplers and the Emperor Gateway Conduit blueprint; the smaller containers never hold Couplers.","zh":"在空旷处放置，召来“收割者”空投。碎片很快落下，立刻跑开。其中一个主空投里有三种耦合器和“帝王”通道导管蓝图，小型容器不会出耦合器。"},"obtain":{"en":"Interact with a damaged Emperor relay during the Redirection condition on Pendola Pass, or pick up a fallen beacon. You can carry 3, but it cannot be kept between raids.","zh":"在彭多拉山口“航向重定向”期间与受损的“帝王”中继站互动，或拾取倒落的信标。最多带 3 个，不能带到下一局。"},"tips":[{"en":"Couplers and the blueprint are random, so expect several payloads; store each Coupler in your stash.","zh":"耦合器和蓝图都是随机的，需要多开几次空投，拿到的耦合器放进仓库。"}],"sources":["https://arcraiders.维基/维基/Emperor_Beacon","https://metaforge.app/arc-raiders/arc-raiders-redirection-map-condition-guide-emperor-relays-beacons-and-payload-loot","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-the-emperor-gateway-conduit-key/"],"version":"2.0"},"fruit_mix":{"verdict":{"en":"A balanced food that heals and refills stamina, good for forage-minded players, but not an emergency heal.","zh":"兼顾回血和体力的食物，适合爱采集的玩家，但不适合紧急治疗。"},"use":{"en":"It restores 25 health and 50 stamina in one 2 second action. It is a decent top-up between fights, but the Bandage and Herbal Bandage heal more over time.","zh":"一次 2 秒的使用回 25 点生命和 50 点体力。适合战斗间隙补充，但治疗量不如绷带和草药绷带。"},"obtain":{"en":"Only by in-raid crafting from an Apricot, Lemon and Prickly Pear. No source for the fruit locations was found, so I cannot give spots. It cannot be recycled.","zh":"只能局内用杏子、柠檬和仙人掌果制作。没找到水果的具体分布资料，这里不写地点。无法回收。"},"tips":[{"en":"It sells for 1800, so selling it is better than crafting it if you only need Fruit for money.","zh":"售价 1800，如果只是为了赚钱，做出来卖也可以。"}],"sources":["https://arcraiders.维基/维基/Fruit_Mix","https://www.dexerto.com/维基s/arc-raiders/items/quick-use/fruit-mix/"],"version":"2.0"},"grappling_hook":{"verdict":{"en":"A 2.0 mobility gadget worth a slot on vertical maps if you already have the blueprint.","zh":"2.0 新增的机动道具，有蓝图的话在多垂直落差的地图值得带。"},"use":{"en":"It anchors to most surfaces at up to 20m, for reaching ledges and shortcuts. Community coverage is thin; the wiki page is a stub. It also weighs 5, far more than most gadgets, and wears down, so pack it only when your route needs it.","zh":"最远 20 米可钩住大多数表面，用来上高处和抄近路。社区资料很少，维基页面还是草稿。它重量为 5，比大多数道具重，还会磨损，路线需要时再带。"},"obtain":{"en":"Quests give one each: Boarding the Frigate, Tracks of the Beast, Belly of the Beast, Ruins and Reverberations and Empathetic Prototypes. After learning the blueprint, craft from a Cable Stripper, Mechanical Components and 2 Rope in the raid or at Utility Station 1.","zh":"任务各送一个：“登上护卫者”“巨兽踪迹”“兽腹深处”“废墟和回响”“共情原型机”。学会蓝图后可在局内或工具工作台 1 级用剥线钳、机械元件和 2 绳子制作。"},"tips":[{"en":"Repair costs a Cable Stripper and Rope, so do not mistake it for the older Snap Hook.","zh":"修理要剥线钳和绳子，别和旧的安全钩搞混。"}],"sources":["https://arcraiders.维基/维基/Grappling_Hook","https://allthings.how/arc-raiders-gadgets-and-utilities-every-item-uses-and-crafting/"],"version":"2.0"},"harmonica":{"verdict":{"en":"A pocket novelty instrument; fun, but sell it unless you want to play.","zh":"随身的娱乐乐器，好玩但没用，不想吹就卖掉。"},"use":{"en":"It attracts ARC attention and impresses other Raiders, and many two-handed actions are blocked while you play. Light at 0.2 weight, it is the easiest instrument to carry.","zh":"会吸引 ARC 注意，也能让其他奇袭者眼前一亮，演奏时许多双手操作被禁用。重量只有 0.2，是最好带的乐器。"},"obtain":{"en":"New in 2.0; the wiki lists it as a scavenged item, with Residential as the only location. Recycling returns 4 Metal Parts, while its sale value is 1000, so selling is the better deal.","zh":"2.0 新增；维基记录为搜刮获得，地点只写了住宅区。回收得 4 金属零件，而售价为 1000，卖掉更划算。"},"tips":[{"en":"It is a stub on the community wiki, so details may change.","zh":"社区维基页面还是草稿，细节可能变动。"}],"sources":["https://arcraiders.维基/维基/Harmonica","https://www.gamingonlinux.com/2026/10/arc-raiders-massive-frozen-trail-2-0-update-is-out-and-free-to-play-for-a-few-days/"],"version":"2.0"},"herbal_bandage":{"verdict":{"en":"Heals about 75% faster than a Bandage and is worth carrying, but buying it from Lance is pricey.","zh":"回血比绷带快约 75%，值得携带，但向兰斯购买偏贵。"},"use":{"en":"It heals 3.5 per second for 10 seconds, about 35 health, with the same 1.5 second use. Players favor it as the main heal for mid-gear runs. The Bandage heals around 20 for much less.","zh":"每秒回 3.5 点，持续 10 秒，约 35 点，使用时间同样是 1.5 秒。玩家常把它当中期装备的主力治疗。绷带约 20 点但便宜得多。"},"obtain":{"en":"Craft it with Durable Cloth and Great Mullein at the Medical Lab or in the raid. Lance sells up to 10 for 2700, and the Ryder and Voyager Raider Deck holds 5. Recycling returns Assorted Seeds and Fabric.","zh":"在医疗实验室或局内用耐磨布料和大毛蕊花制作。兰斯每天限购 10 个，每个 2700；奇袭者套件 AR/RD 001里有 5 个。回收可得混合种子和布料。"},"tips":[{"en":"Per coin the Bandage is about twice as efficient, so buy neither: craft the Herbal Bandage.","zh":"按钱币计算绷带效率约为两倍，所以都别买，自己做草药绷带。"}],"sources":["https://arcraiders.维基/维基/Herbal_Bandage","https://www.dexerto.com/维基s/arc-raiders/items/quick-use/herbal-bandage/","https://allthings.how/?p=4658"],"version":"2.0"},"mountaineers_detector":{"verdict":{"en":"A niche digger for Pendola Pass snow and Riven Tides sand: fun for treasure hunts, a poor use of a slot on a normal loot run.","zh":"彭多拉山口雪地和裂潮镇沙滩的挖宝专用，普通搜刮不值得占快捷栏。"},"use":{"en":"It finds objects buried in snow or sand: beeps speed up as you close in, and you walk slowly while it runs. Switching on costs a chunk of its energy meter, so one long sweep beats several short ones. The meter refills while it is off, and carrying extra detectors does not add energy.","zh":"它能探测埋在雪地或沙地里的物体：越靠近，提示音越急促，使用时只能慢走。开启瞬间会消耗一截能量，所以连续探一次比多次短开更划算。关闭后能量会回复，多带几个也不会增加能量。"},"obtain":{"en":"Craft it at the Workbench once you have learned the blueprint; the recipe eats a Dockmaster's Detector, so you are upgrading one rather than starting from scratch. The community wiki lists scavenging only and no quest source.","zh":"学会蓝图后在工作台制作，配方要消耗一个码头主管探测器，相当于升级旧探测器。社区维基只列出搜刮来源，没有任务奖励。"},"tips":[{"en":"Only worth bringing on Pendola Pass or Riven Tides runs where you plan to dig; elsewhere it does nothing.","zh":"只有计划去彭多拉山口或裂潮镇挖宝时才带，其他地图完全没用。"},{"en":"Buried spots can hold traps such as mines or ARC Ticks, so slow down once the beeping turns frantic.","zh":"埋藏点可能有地雷或ARC跳蚤之类的陷阱，提示音急促时要放慢脚步。"}],"sources":["https://arcraiders.wiki/wiki/Mountaineer's_Detector","https://nerdschalk.com/arc-raiders-dockmasters-detector-guide-how-to-find-hidden-loot-easily/"],"version":"2.0"},"photoelectric_cloak":{"verdict":{"en":"Cheap insurance against ARC: it breaks line of sight even mid-fight, but you only walk and it does nothing against players.","zh":"对付ARC的保险：连交战中的ARC也会丢失目标，但只能走路，且对玩家无效。"},"use":{"en":"While active, ARC lose track of you, which makes it good for sneaking past a Bastion, crossing a patrolled room or breaking off a bad fight. Your speed drops to a slow walk, and the energy meter is shared between cloaks, so extra copies do not extend the cloak. Players have also paired it with Deadline Mines to take down big ARC unnoticed. Patch 1.29 halved its power drain.","zh":"开启后ARC会丢失你的踪迹，适合绕过“堡垒”、穿过有巡逻的房间或从不利战斗中脱身。使用时只能慢走，多个斗篷共用同一条能量，多带也不会更久。玩家还会配合“死线”地雷无声清掉大型ARC。1.29补丁把耗电减半了。"},"obtain":{"en":"Craft at Utility Station level 3 (it is not a blueprint item). The Mixed Signals quest hands one out, and the community wiki says the Trophy Display project asks for 3 of them, so hold some back.","zh":"在工具工作台3级制作，无需蓝图。任务“混合信号”会送一个；社区维基提到“战利品展示”项目需要3个，别全卖掉。"},"tips":[{"en":"Repair is cheaper than a new craft, and recycling gives back half the parts, so repair a worn cloak instead of scrapping it.","zh":"修理比重做便宜，回收只返还一部分材料，磨损的斗篷优先修理。"},{"en":"Do not rely on it against other Raiders: it only hides you from ARC.","zh":"别指望它躲玩家，它只对ARC有效。"}],"sources":["https://arcraiders.wiki/wiki/Photoelectric_Cloak","https://metaforge.app/arc-raiders/patch-notes-1-29-0"],"version":"2.0"},"powered_descender":{"verdict":{"en":"A genuine traversal tool for rooftops and tall drops, but it needs wind-up time, so use it early and treat it as a luxury slot.","zh":"屋顶和高处下落的实用位移工具，但需要起转时间，要提前开，属于奢侈型快捷栏。"},"use":{"en":"Turn it on before you jump, not mid-fall; it slows your descent and gives a short lift, and it shuts off when its power runs out. Players use it to reach high loot (rooftops, ledges, skylight rooms) and to drop out of sight when a PvP fight goes badly. It is not dependable from the very tallest towers.","zh":"要在起跳前就开启，而不是下落途中；它能减缓下落并带来短暂上升，能量耗尽就会关闭。玩家用它够到屋顶、壁架、天窗房间里的物资，也用来在PvP不利时借高度脱离视线。从最高的塔上跳下仍不可靠。"},"obtain":{"en":"Craft at Utility Station level 3 after learning the blueprint, which drops randomly; guides suggest checking Hotel Panorama Azzurro in Riven Tides. The Disrupting the Frigate quest also gives one.","zh":"学会蓝图后在工具工作台3级制作，蓝图随机掉落，有攻略建议去裂潮镇的蔚蓝全景酒店碰运气。任务“干扰护卫者”也会送一个。"},"tips":[{"en":"It weighs 5 and wears out, so the repair parts (ARC Circuitry) add up if you use it every raid.","zh":"它重量为5且会磨损，每局都用的话ARC线圈的修理开销会累积。"},{"en":"If your only goal is surviving falls, a cheaper fall-softening item does the job.","zh":"如果只想摔不死，更便宜的缓降道具就够了。"}],"sources":["https://arcraiders.wiki/wiki/Powered_Descender","https://ggwtb.com/blog/arc-raiders-powered-descender-guide-how-to-jump-higher--loot-faster--and-stop-wasting-it"],"version":"2.0"},"recorder":{"verdict":{"en":"A fun social toy, not a tool: playing it draws ARC, so skip it unless you are in a safe spot or with friends.","zh":"社交玩具而非工具：吹奏会引来ARC，除非在安全处或和朋友一起，否则别带。"},"use":{"en":"It plays one of two melodies. Nearby Raiders can listen or join in with a Shaker or Acoustic Guitar for a group jam. You cannot do many two-handed actions while playing, and the noise attracts ARC, so use it near extraction or in a cleared building.","zh":"可以演奏两段旋律，附近的奇袭者可以驻足欣赏，或用摇铃、原声吉他加入合奏。演奏时很多双手动作无法使用，声音还会招来ARC，适合在撤离点附近或已清空的建筑里用。"},"obtain":{"en":"Buy from Apollo (limit 6 a day); the community wiki says Shani stopped selling it in 2.0. It also turns up as loot in Residential areas.","zh":"可向阿波罗购买（每日限购6个）；社区维基称2.0之后萨尼不再出售。居民区也能搜到。"},"tips":[{"en":"Recycling gives 10 Plastic Parts, which is worth far less than the 3000 coins Apollo charges, so never buy one for materials.","zh":"回收只给10个塑料零件，远不及阿波罗3000钱币的售价，别为材料去买。"}],"sources":["https://arcraiders.wiki/wiki/Recorder","https://insider-gaming.com/how-to-find-guitars-shakers-in-arc-raiders-buried-city-easter-egg/"],"version":"2.0"},"shaker":{"verdict":{"en":"A novelty instrument you can craft in a raid; it attracts ARC, so only shake it somewhere safe.","zh":"可在局内制作的趣味乐器，会招来ARC，只在安全的地方摇。"},"use":{"en":"It plays one of two rhythms and pairs with the Recorder and Acoustic Guitar for group jams. Two-handed actions are blocked while you play, and the sound draws ARC.","zh":"能摇出两种节奏，可与可演奏长笛、原声吉他合奏。演奏时无法做双手动作，声音还会引来ARC。"},"obtain":{"en":"Craft it in-raid from Assorted Seeds and a Canister; loot in Residential areas also works. On Deaf Ears hands one out, and the community wiki says traders no longer sell it.","zh":"可在局内用混合种子和小罐制作，也能在居民区搜到。任务“充耳不闻”会送一个；社区维基称商人已不再出售。"},"tips":[{"en":"Source accounts disagree on spawn spots (random loot versus a Buried City easter egg), so do not plan a route around one.","zh":"关于刷新点说法不一（随机搜刮或掩埋废城彩蛋），别专门为它规划路线。"}],"sources":["https://arcraiders.wiki/wiki/Shaker","https://www.destructoid.com/how-to-get-and-use-the-shaker-in-arc-raiders/"],"version":"2.0"},"light_sticks_red_yellow":{"verdict":{"en":"Cheap throwable lights for dark interiors, plus quest fodder; carry a few for darkness, never for fights.","zh":"便宜的投掷照明，用于黑暗室内和任务材料；照明时带几根，不是战斗工具。"},"use":{"en":"Throw one to light a 7 m circle for 40 seconds. It helps in unlit buildings, tunnels and night raids, and marks a spot for teammates. Red and yellow behave identically, so colour is just a signalling choice.","zh":"投出后照亮7米范围，持续40秒，适合无灯建筑、隧道和夜间局，也能给队友标记位置。红色和黄色效果相同，颜色只是用来区分信号。"},"obtain":{"en":"Craft with 3 Chemicals at Utility Station level 1 after learning the blueprint, or buy from Shani. Several quests reward stacks of 5 (The League, What Goes Around, Eyes in the Sky, Bees!, Movie Night).","zh":"学会蓝图后在工具工作台1级用3份化学品制作，也可向萨尼购买。多个任务会送5根一组（球队、因果报应、天空之眼、蜜蜂！、电影之夜）。"},"tips":[{"en":"Recycling returns only one Chemical for three spent, so use them rather than scrap them.","zh":"回收只返还1份化学品，而制作要3份，用掉它们别拆。"}],"sources":["https://arcraiders.wiki/wiki/Red_Light_Stick","https://www.dexerto.com/wikis/arc-raiders/items/quick-use/yellow-light-stick/"],"version":"2.0"},"remote_raider_flare":{"verdict":{"en":"A signalling toy and quest item: cheap to make, rarely worth a slot in a normal loadout.","zh":"信号玩具兼任务道具：做起来便宜，但普通配装里很少值得占一格。"},"use":{"en":"Place it, then trigger it by hand to fire a Raider Distress Flare, the same flare shown when a Raider goes down. It can mark a rally point or an extraction spot.","zh":"先放置，再手动触发，会打出与倒地求救相同的雷达求救信号弹。可用来标记集合点或撤离点，也能伪装成有人倒地。"},"obtain":{"en":"Craft at Utility Station level 1 with the blueprint, or buy from Apollo. Off The Radar, The Trifecta and A Prime Specimen each give some, so the quests may already cover you.","zh":"拥有蓝图后在工具工作台1级制作，也可向阿波罗购买。“销声匿迹”“三连胜”“完美样本”都会送，任务可能已经替你备好。"},"tips":[{"en":"Draws attention to your position, so trigger it from a spot you can leave.","zh":"信号弹会暴露位置，触发后要能立刻离开。"}],"sources":["https://arcraiders.wiki/wiki/Remote_Raider_Flare","https://wzstats.gg/arc-raiders/wiki/items/quick-use/utilities/remote-raider-flare"],"version":"2.0"},"shield_recharger":{"verdict":{"en":"The budget shield refill: slow, but it fills a Light Shield and can be made in the field.","zh":"经济型护盾补充：慢，但能充满轻型护盾，还能在局内制作。"},"use":{"en":"It gives 4 shield per second for 10 seconds, so use it once you are out of the fight rather than mid-fire. It restores shield only, never health. For a faster top-up in combat, the Surge Shield Recharger delivers 50 at once.","zh":"每秒恢复4点护盾，共10秒，所以要在脱离交火后使用，而不是交火中。它只补护盾，不补生命。想在战斗中快速补盾，爆能护盾充能器能一次给50点。"},"obtain":{"en":"Craft in-raid, at a Workbench, or at the Medical Lab, using an ARC Powercell and Rubber Parts. Lance sells it too, and Clean Hands, Belly of the Beast and Someone Else's Shoes give some.","zh":"可在局内、工作台或医疗实验室用ARC能量电池和橡胶零件制作；兰斯也出售，任务“清理指针”“兽腹深处”“换核思考”也会送。"},"tips":[{"en":"The ARC Powercell is the bottleneck, so only craft as many as you will use.","zh":"ARC能量电池是瓶颈，按用量制作，别囤太多。"},{"en":"Recycling gives just 4 Rubber Parts, so sell or use spares.","zh":"回收只给4份橡胶零件，多余的直接用掉或卖掉。"}],"sources":["https://arcraiders.wiki/wiki/Shield_Recharger","https://deltiasgaming.com/?p=391428"],"version":"2.0"},"surge_shield_recharger":{"verdict":{"en":"Worth a slot if you run a shield: 50 shield in one go beats the basic recharger, but costs a 5 second window.","zh":"带护盾的话值得占一格：一次补50点，强于基础充能器，但要5秒读条。"},"use":{"en":"Applied on use after a short 5-second animation, so duck behind cover first. It suits mid-fight resets between pushes better than the 10-second trickle of the basic version. Several quests (Waking the Grid, Out of the Shadows, On The Map) hand them out, so you get free stock early.","zh":"使用需约5秒读条，先找掩体。比基础版10秒的缓慢回复更适合在交火间隙重整。“唤醒安保网络”“走出阴影”“在地图上”等任务会送，早期库存不愁。"},"obtain":{"en":"Craft at Medical Lab level 2 with an Advanced ARC Powercell and Electrical Components, or buy from Lance (limit 5 a day).","zh":"在医疗实验室2级用高级ARC能量电池和电子元件制作，或向兰斯购买（每日限购5个）。"},"tips":[{"en":"Advanced ARC Powercells are scarcer than basic ones; craft in batches only when you have a surplus.","zh":"高级ARC能量电池比基础款稀缺，有富余再批量制作。"}],"sources":["https://arcraiders.wiki/wiki/Surge_Shield_Recharger","https://wzstats.gg/arc-raiders/wiki/items/quick-use/healing/surge-shield-recharger"],"version":"2.0"},"snap_hook":{"verdict":{"en":"The premium mobility tool: great for verticality, flanks and climbing big ARC, but expensive to craft and repair.","zh":"高端位移工具：垂直机动、绕后和攀爬大型ARC都很强，但制作和修理都贵。"},"use":{"en":"Chain short hooks between ledges and railings to climb faster than one big swing, and keep a charge for escapes since the bar refills slowly. Players also hook large ARC like the Queen or Matriarch to reach the shielded hull, and grab a wall mid-fall to stop short of the ground. A fall-clip using it went viral on Reddit.","zh":"在壁架和栏杆间短距离连续钩爬，比一次长摆更快；因为能量条回复慢，要留一格应急。玩家还会钩上“女王”“族母”等大型ARC去打顶部护甲，或下落中钩墙避免摔死。一段用它在空中击杀的视频曾在ç¤¾åº爆火。"},"obtain":{"en":"Craft at Utility Station level 3 after learning the blueprint, or find one while scavenging. Boarding the Frigate, Belly of the Beast, Stable Housing and Lost in Transmission each give one, so quests can supply your first.","zh":"学会蓝图后在工具工作台3级制作，或搜刮获得。“登上护卫者”“兽腹深处”“稳固住宅”“迷失在传输中”都会送一个，首个可以靠任务拿到。"},"tips":[{"en":"Repair eats an Exodus Module, which is expensive, so do not spam it in routes that sprinting would clear.","zh":"修理要耗离巢模块，开销不小，跑过去就行的路线别乱用。"},{"en":"The community wiki reports the 2.0 patch cut its range and raised wear per use; check the in-game numbers.","zh":"社区维基称2.0削弱了射程并提高了单次磨损，请以游戏内数值为准。"}],"sources":["https://arcraiders.wiki/wiki/Snap_Hook","https://allthings.how/arc-raiders-snap-hook-stats-range-crafting-repair/"],"version":"2.0"},"sterilized_bandage":{"verdict":{"en":"The reliable mid-tier heal: slow to finish, but quick to start and easy to stock, so it earns a quick-use slot early on.","zh":"可靠的中阶治疗：起效慢但上手快、好囤货，前期值得占一格。"},"use":{"en":"It heals 5 per second for 10 seconds, so about 50 in total after only 1.5 seconds to start. Best once you are behind cover or moving away; it is poor as a panic button. Pair it with an instant heal like the Vita Shot.","zh":"每秒恢复5点，共10秒，约合50点，但只需1.5秒起手。适合躲进掩体或边撤边用，不适合当救急键。可搭配生命针剂这类瞬间治疗。"},"obtain":{"en":"Craft at Medical Lab level 2 from Antiseptic and Durable Cloth, or buy from Lance (limit 3 a day). Many quests (Clearer Skies, Doctor's Orders, Home to Roost and others) give 2 to 3 at once.","zh":"在医疗实验室2级用防腐剂和耐磨布料制作，或向兰斯购买（每日限购3个）。“清朗天空”“医生的订单”“归巢”等任务一次送2到3个。"},"tips":[{"en":"Because quests hand out so many, check your stash before buying from Lance at 6000 coins.","zh":"任务送得多，向兰斯花6000钱币购买前先看看仓库。"}],"sources":["https://arcraiders.wiki/wiki/Sterilized_Bandage","https://nerdschalk.com/arc-raiders-all-medical-supplies-locations-and-usage-guide/"],"version":"2.0"},"tether_launcher":{"verdict":{"en":"A new 2.0 gadget with niche utility: it can link two points at long range, but it is a squad or puzzle tool, not a general slot.","zh":"2.0新增的小众工具，能在远距离连接两点，是小队或解谜用，不是通用快捷栏。"},"use":{"en":"Two shots anchor a line to whatever each hits, linking both points for 10 seconds at up to 30 m. Early guides suggest pairing it with a grappling hook to take high ground, and say it can tie a Raider to an ARC machine. Treat that as unverified, since the community wiki page is a stub.","zh":"两发各自将绳索固定在命中处，连接两点，持续10秒，最远30米。早期攻略建议与抓钩搭配抢高地，并称可以把雷达与ARC机器绑在一起，但社区维基页面只是草稿，这一点未经证实。"},"obtain":{"en":"Craft at Utility Station level 2 once you have learned the blueprint. I found no confirmed drop location for the blueprint, so expect it from general containers and locked rooms.","zh":"学会蓝图后在工具工作台2级制作。蓝图的掉落地点没有可靠来源，大概率出自普通容器和上锁房间。"},"tips":[{"en":"Few sources have tested it yet; try it on a quiet run before committing a slot.","zh":"实测资料很少，先在安静的局里试试再决定占不占格。"}],"sources":["https://arcraiders.wiki/wiki/Tether_Launcher","https://www.u4gm.com/arc-raiders/blog-arc-raiders-frozen-trail-grappling-hook-guide"],"version":"2.0"},"vita_shot":{"verdict":{"en":"The best burst heal in the early-to-mid game: bring one or two for the emergencies a bandage cannot cover.","zh":"前中期最好的爆发治疗：带一两支，应对绷带来不及的紧急情况。"},"use":{"en":"Restores 50 health after a 4-second use, much quicker to deliver than the Sterilized Bandage. Guides recommend one instant heal plus one over-time heal in the same loadout. The 4 seconds is still long, so break line of sight first.","zh":"4秒读条后恢复50点生命，起效比消毒绷带快得多。攻略建议配装里带一个瞬间治疗加一个持续治疗。4秒仍然不短，先躲开视线。"},"obtain":{"en":"Craft at Medical Lab level 3 with Antiseptic and a Syringe after learning the blueprint, or find in the field. Medical Merchandise, Waking the Grid and Empathetic Prototypes all give some.","zh":"学会蓝图后在医疗实验室3级用防腐剂和注射器制作，也可在局内找到。“医疗物资”“唤醒安保网络”“共情原型机”都会送。"},"tips":[{"en":"Recycling returns 4 Chemicals and a Syringe, so a spare is worth keeping rather than scrapping.","zh":"回收可得4份化学品和1支注射器，富余的留着比拆掉划算。"}],"sources":["https://arcraiders.wiki/wiki/Vita_Shot","https://nerdschalk.com/arc-raiders-all-medical-supplies-locations-and-usage-guide/"],"version":"2.0"},"vita_spray":{"verdict":{"en":"The team medic's tool: the most healing per item and it works on allies, but it is bulky and costly to craft and repair.","zh":"队医专用：单件治疗量最大，还能给队友用，但体积大，制作和修理都贵。"},"use":{"en":"Heals 10 per second, up to 150 total, so a full tank takes about 15 seconds of holding still. That is a lot for a solo player, but ideal when a squad regroups behind cover or someone needs reviving back to health. It wears out and must be repaired.","zh":"每秒恢复10点，总量150，用完约需15秒站定。单人用太奢侈，但小队在掩体后整备或帮队友回血时很理想。它会磨损，需要修理。"},"obtain":{"en":"Craft at Medical Lab level 3, which needs a Tick Pod on top of Antiseptic and a Canister, so farm Ticks first. Eyes in the Sky and Disrupting the Frigate each give one, and the community wiki says the Trophy Display project needs 3.","zh":"在医疗实验室3级制作，除防腐剂和小罐外还要“跳蚤”收纳舱，得先去刷跳蚤。“天空之眼”和“干扰护卫者”各送一个；社区维基称“战利品展示”项目需要3个。"},"tips":[{"en":"Solo players are better off with a Vita Shot plus Sterilized Bandage.","zh":"单人玩家带生命针剂加消毒绷带更合适。"}],"sources":["https://arcraiders.wiki/wiki/Vita_Spray","https://allthings.how/?p=4658"],"version":"2.0"},"white_flag":{"verdict":{"en":"A social prop with no combat value: skip the slot unless you like roleplaying a surrender.","zh":"没有战斗价值的社交道具：除非想演投降戏，否则别占格。"},"use":{"en":"You plant it or wave it to signal a truce to other Raiders. It does nothing against ARC, and it only works if the other player chooses to respect it. Guides also note it costs a quick-use slot for no mechanical benefit.","zh":"放置或挥动，用来向其他雷达示意停战。对ARC无效，也只有对方愿意配合才有用。攻略也指出它占一个快捷栏却没有实际收益。"},"obtain":{"en":"Craft in-raid or at the Medical Lab level 1 with the blueprint. The blueprint is a random Riven Tides drop, reportedly more likely in industrial areas like the Stacking Yard.","zh":"拥有蓝图后可在局内或医疗实验室1级制作。蓝图是裂潮镇的随机掉落，据称工业区（如堆场）机会更大。"},"tips":[{"en":"Recycling gives back half the Fabric, so extras are better recycled than carried.","zh":"回收可返还一半布料，多余的拆掉比带着强。"}],"sources":["https://arcraiders.wiki/wiki/White_Flag","https://nerdschalk.com/arc-raiders-white-flag-blueprint-location-uses-and-recipe-explained/"],"version":"2.0"},"zipline":{"verdict":{"en":"A cheap, reliable mobility item that unlocks quest objectives, especially on Pendola Pass; worth a slot when you need height or speed.","zh":"便宜好用的位移道具，尤其在彭多拉山口能解锁任务目标；需要高度或速度时值得带。"},"use":{"en":"Deploy two ends up to 60 m apart on most surfaces and ride between them. It is required for the Exploring Pendola Pass antenna on the Railyard tower, and a fast way onto the Cielo Sereno Observatory roof. You can place and reuse the line during a raid.","zh":"在最远60米的两点之间放置，几乎能挂在任何表面上并滑行。“探索彭多拉山口”中铁路调度场塔楼的天线必须用它，也是上西耶洛·塞雷诺天文台楼顶的快路。"},"obtain":{"en":"Craft in-raid or at Utility Station level 2 from Mechanical Components and Steel Cable, or buy from Apollo (limit 2 a day). Many Pendola Pass quests hand out several, so you rarely need to buy.","zh":"可在局内或工具工作台2级用机械元件和钢缆制作，或向阿波罗购买（每日限购2个）。许多彭多拉山口任务会送好几个，基本不用买。"},"tips":[{"en":"Salvaging in raid gives 4 Metal Parts, so spare ones are worth a quick scrap.","zh":"局内分解可得4份金属零件，富余的可以顺手拆。"}],"sources":["https://arcraiders.wiki/wiki/Zipline","https://www.destructoid.com/how-to-complete-exploring-pendola-pass-in-arc-raiders/"],"version":"2.0"},"arc_coolant":{"verdict":{"en":"Nothing live needs it: sell it for 1,000 coins, or recycle for 16 Chemicals if you are short.","zh":"没有进行中的需求：卖 1000 钱币；缺化学品时可拆成 16 个。"},"obtain":{"en":"Only The Queen and Sentinel drop it. The Queen needs a Harvester map condition; Sentinels sit at Outer Gates (The Blue Gate) and Breach (Dam Battlegrounds) and are more common in Hurricane.","zh":"只有女王和哨卫掉落。女王要在“收割者”地图条件下才出现；哨卫常驻蓝门外部大门、大坝战场裂口一带，飓风天气更多。"},"tips":[{"en":"Recycling gives 16 Chemicals, nearly twice the 9 from salvaging in a raid, so do it at the workshop. Chemicals are cheap, so the 1,000 sale price is the better payout.","zh":"工作台回收得 16 个化学品，局内拆解只有 9 个。化学品便宜，卖 1000 更划算。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Coolant","https://arcraiders.wiki/wiki/Sentinel","https://arcraiders.wiki/wiki/Queen"],"version":"2.0"},"arc_flex_rubber":{"verdict":{"en":"Nothing live needs it: sell for 1,000 coins, or recycle for 16 Rubber Parts if you are short.","zh":"没有进行中的需求：卖 1000 钱币；缺橡胶零件时可拆成 16 个。"},"obtain":{"en":"Drops from Matriarch, The Queen and Leaper. Leapers are the realistic farm: they spawn on Dam Battlegrounds (most spots), Buried City, The Spaceport, The Blue Gate and Riven Tides, not on Stella Montis.","zh":"掉落自族母、女王和跳跃者。跳跃者最现实：大坝战场刷新点最多，掩埋废城、太空港、蓝门、裂潮镇也有，星辰山没有。"},"tips":[{"en":"Rubber Parts are common elsewhere, so only recycle if you are short; otherwise the 1,000 sale price is the easier win.","zh":"橡胶零件别处很好找，缺才拆；否则直接卖 1000 更省事。"},{"en":"Leapers die fast to a Blaze Grenade followed by one or two Heavy Ammo shots, which makes this one of the cheaper rares to farm.","zh":"用火焰手雷加一两发重型弹药就能放倒跳跃者，是比较省成本的稀有材料来源。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Flex_Rubber","https://arcraiders.wiki/wiki/Leaper","https://nerdschalk.com/arc-raiders-arc-flex-rubber-location-use-guide/"],"version":"2.0"},"arc_performance_steel":{"verdict":{"en":"Keep 10 for Trophy Display phase 3 and 1 for To The Skies; the rest recycles into 12 Metal Parts or sells for 1,000.","zh":"留 10 个给战利品展示架第 3 阶段，“飞向苍穹”要 1 个；其余拆成 12 个金属零件或卖 1000。"},"obtain":{"en":"Never in containers; it comes from big ARC: Matriarch, The Queen and Leaper (also Bastion and Bombardier, per player guides). Leapers on Dam Battlegrounds and The Spaceport are the steadiest source; Matriarchs need their map condition.","zh":"容器里没有，只来自大型 ARC：族母、女王、跳跃者（玩家攻略还提到堡垒、投弹手）。大坝战场和太空港的跳跃者最稳；族母需要对应地图条件。"},"tips":[{"en":"Trophy Display phase 3 needs 10 and To The Skies rewards 3, so you may already be partway there.","zh":"战利品展示架第 3 阶段要 10 个，“飞向苍穹”还送 3 个，你可能已经有一部分了。"},{"en":"After the projects, 12 Metal Parts is poor value against a 1,000 sale. Just sell.","zh":"项目做完后，12 个金属零件远不如卖 1000，直接卖。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Performance_Steel","https://arcraiders.wiki/wiki/Matriarch","https://nerdschalk.com/arc-performance-steel-arc-raiders-location-use-guide/"],"version":"2.0"},"arc_synthetic_resin":{"verdict":{"en":"Keep 10 for Trophy Display phase 4 and 1 for To The Skies; the rest recycles into 14 Plastic Parts or sells for 1,000.","zh":"留 10 个给战利品展示架第 4 阶段，“飞向苍穹”要 1 个；其余拆成 14 个塑料零件或卖 1000。"},"obtain":{"en":"Matriarch, The Queen, Sentinel and Snitch drop it. Snitch is the easy one: it patrols open areas on any map, dies to a few Medium or Heavy Ammo shots, and its reinforcement calls give you more wrecks to loot.","zh":"族母、女王、哨卫和告密者掉落。告密者最容易：各图空旷处都有，几发中型或重型弹药就倒，召来的增援也能多摸几具残骸。"},"tips":[{"en":"Hunt Snitches early in the raid, before they call reinforcements: reinforcements only come reliably after the third call.","zh":"趁告密者还没叫援军就解决：第三次呼叫后才会稳定增援。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Synthetic_Resin","https://arcraiders.wiki/wiki/Snitch","https://allthings.how/how-to-get-arc-synthetic-resin-in-arc-raiders/"],"version":"2.0"},"arc_thermo_lining":{"verdict":{"en":"Needed by three projects (6+10+15) and To The Skies; keep until they are done, then sell for 1,000.","zh":"三个项目共要 31 个（6+10+15）外加“飞向苍穹”，做完前别动，之后卖 1000。"},"obtain":{"en":"Dropped by The Queen, Sentinel and Pop. Pops usually sit in large indoor facilities next to Fireballs and are killed with a fast-firing weapon at close range.","zh":"女王、哨卫和爆爆掉落。爆爆多在大型室内设施里与火球同行，近距离用高射速武器解决。"},"tips":[{"en":"Running past a Pop at full speed wastes its detonation, so you can loot it without losing health.","zh":"全速跑过爆爆可让它空爆，之后安全摸尸。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Thermo_Lining","https://arcraiders.wiki/wiki/Pop","https://arcraiders.wiki/wiki/Sentinel"],"version":"2.0"},"assessor_matrix":{"verdict":{"en":"Nothing live needs it: sell for 5,000 coins, or recycle into 4 Advanced ARC Powercells.","zh":"没有进行中的需求：卖 5000 钱币，或拆成 4 个高级ARC能量电池。"},"obtain":{"en":"Only from Assessor containers during the Close Scrutiny map condition (not on Stella Montis). Assessors show three red beams; loot each breach platform when it activates and bring smoke.","zh":"只在“严密排查”地图条件下从评估者的容器里出（星辰山没有）。评估者会射出三道红光；每个平台激活就摸，带烟雾弹。"},"tips":[{"en":"Recycling also returns 1 Advanced Mechanical Components, so recycle only if you need those parts; otherwise the sale is simpler.","zh":"拆解还会多给 1 个高级机械元件；缺这些零件再拆，否则直接卖更省事。"}],"sources":["https://arcraiders.wiki/wiki/Assessor_Matrix","https://arcraiders.wiki/wiki/Assessor","https://www.destructoid.com/how-to-get-and-use-assessor-matrix-in-arc-raiders/"],"version":"2.0"},"bastion_cell":{"verdict":{"en":"Keep 12 for Gear Bench 3 (6), Settled in Full (1) and Trophy Display (5); extras are only 3 ARC Alloy.","zh":"装备工作台 3 级要 6 个，债务结清 1 个，战利品展示架 5 个（共约 12 个）；多余的只能拆出 3 个ARC合金。"},"obtain":{"en":"Only from scavenging a destroyed Bastion; it is not in containers. Bastions stand in open ground on every map: east of Water Treatment Control and Red Lakes Balcony (Dam), Marano Park (Buried City), Outer Gates (Blue Gate), under Cielo Sereno Observatory (Pendola Pass).","zh":"只能从击毁的堡垒身上摸，容器里没有。各图开阔地都有：大坝战场水处理控制中心东侧、红湖阳台，掩埋废城马拉诺公园，蓝门外部大门，彭多拉山口天文台下。"},"tips":[{"en":"Shoot the yellow knee joints and rear canister; destroying the canister exposes a weak spot. A Deadline mine placed near the canister kills it outright.","zh":"打黄色膝关节和后部罐体，罐体被毁会露出弱点。在罐体旁放“死线”地雷可直接秒杀。"}],"sources":["https://arcraiders.wiki/wiki/Bastion_Cell","https://arcraiders.wiki/wiki/Bastion","https://nerdschalk.com/arc-raiders-bastion-cell-location-use-guide/"],"version":"2.0"},"bombardier_cell":{"verdict":{"en":"Keep 6 for Refiner 3 plus the Bombing Run quest; Trophy Display phase 5 wants 8 more.","zh":"精加工机 3 级要 6 个，另有“以下犯上”任务；战利品展示架第 5 阶段还要 8 个。"},"obtain":{"en":"Salvage it from a destroyed Bombardier. Spots: Primary Facility at night (Dam), Marano Park and Plaza Rosa (Buried City), The Trench (Spaceport), Traffic Tunnel (Blue Gate), Dried Riverbed (Riven Tides).","zh":"从击毁的投弹手身上摸。位置：大坝战场主要设施（夜袭），掩埋废城马拉诺公园和玫瑰广场，太空港壕沟，蓝门交通隧道，裂潮镇干涸河床。"},"tips":[{"en":"Kill its Spotter drones first and attack right after it fires its mortar. A Deadline mine at its canister finishes it fast.","zh":"先打掉它的侦察员无人机，趁它刚发射迫击炮时输出。罐体旁的“死线”地雷能迅速解决它。"}],"sources":["https://arcraiders.wiki/wiki/Bombardier_Cell","https://arcraiders.wiki/wiki/Bombardier","https://nerdschalk.com/arc-raiders-bombardier-cell-location-use-guide/"],"version":"2.0"},"bully_fragmenter":{"verdict":{"en":"A 2.0 item you need 6 of for Research Station 3, plus one for Bait, Fetch, Blast; sell extras at 5,000.","zh":"研究站 3 级要 6 个，“诱饵、搜寻、爆破”再要 1 个；多余的卖 5000。"},"obtain":{"en":"Dropped by Bully (Pendola Pass, around Piazza della Rupe) and by Couriers. Bullies patrol, so check Railroad Junction, Almatera Station and the Northern Tracks snowfields.","zh":"恶霸（彭多拉山口，岩石广场一带）和 ARC运输机掉落。恶霸会巡逻，可去铁路枢纽、阿尔玛特拉站、北部轨道雪原找。"},"tips":[{"en":"Aim at its leg joints, and at the head while it fires. Body shots waste ammo.","zh":"打腿部关节，开火时打头部，打躯干浪费弹药。"},{"en":"Recycling returns just 1 ARC Alloy and 1 Explosive Compound, far below the 5,000 sale value.","zh":"拆解只得 1 个ARC合金和 1 个炸药混合物，远不如卖 5000。"}],"sources":["https://arcraiders.wiki/wiki/Bully_Fragmenter","https://arcraiders.wiki/wiki/Bully","https://www.keengamer.com/articles/guides/arc-raiders-bully-locations-how-to-defeat-them/"],"version":"2.0"},"burned_arc_circuitry":{"verdict":{"en":"Pure fodder: nothing needs it, so sell for 640 or recycle into 2 ARC Alloy only if you need alloy.","zh":"纯杂物，没有任何需求，卖 640；缺ARC合金才拆成 2 个。"},"obtain":{"en":"Found by scavenging ARC Couriers (breachable containers) and Baron Husks.","zh":"来自 ARC运输机（需破拆的容器）和“男爵”残骸。"},"tips":[{"en":"It weighs 1 and stacks to 3, so do not carry it just to sell unless the bag has room.","zh":"重量 1、堆叠 3，背包紧张就别专门带回去卖。"}],"sources":["https://arcraiders.wiki/wiki/Burned_ARC_Circuitry","https://arcraiders.wiki/wiki/Courier"],"version":"2.0"},"comet_igniter":{"verdict":{"en":"Worth hunting: 3 for Nothing Ventured, 1 for Collision Course and Deadline, plus two projects; extras sell for 1,000.","zh":"值得专门去打：“焉得虎子”3 个，“碰撞航线”和“死线”各 1 个，另有两个项目要。"},"obtain":{"en":"Only from a Comet killed before it self-destructs (the core piece). Comets roam open ground; Dam Battlegrounds standard raids lost them in an older patch. Seeker Grenades strip armor, then shoot the exposed core as it charges.","zh":"必须在彗星自爆前击毁才有（核心部分）。彗星在开阔地游荡，旧版本起大坝战场普通场次不再出现。用追踪手雷剥甲，在它蓄力暴露核心时射击。"},"tips":[{"en":"If it explodes first only the ring is lootable, and that gives common ARC parts. Back off before it detonates.","zh":"它先自爆就只能摸到环状部件，只有普通材料，蓄力时赶紧拉开距离。"}],"sources":["https://arcraiders.wiki/wiki/Comet_Igniter","https://arcraiders.wiki/wiki/Comet","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-the-comet-igniter/"],"version":"2.0"},"damaged_arc_motion_core":{"verdict":{"en":"Sell it for 640; recycling gives only 2 ARC Alloy and nothing needs it.","zh":"卖 640；拆只得 2 个ARC合金，也没人需要它。"},"obtain":{"en":"Common loot on mid and large ARC wrecks, such as Leapers, Bastions and Sentinels. Light at 0.25 weight, so grab it when passing.","zh":"常见于跳跃者、堡垒、哨卫等中大型 ARC 残骸。重量仅 0.25，顺手拿。"},"sources":["https://arcraiders.wiki/wiki/Damaged_ARC_Motion_Core","https://arcraiders.wiki/wiki/Sentinel"],"version":"2.0"},"damaged_arc_powercell":{"verdict":{"en":"Low-value junk: sell it for 293 or recycle for 1 ARC Alloy.","zh":"低价杂物：卖 293，或拆成 1 个ARC合金。"},"obtain":{"en":"Drops from almost every ARC wreck, so it does not need a dedicated trip.","zh":"几乎所有 ARC 残骸都会掉，不用专门去找。"},"tips":[{"en":"It stacks to 5 at 0.25 weight, so it is a fine filler when the bag has room, but leave it for a better pickup if space is tight.","zh":"堆叠 5、重量 0.25，有空位可以带；背包紧张时让位给更值钱的东西。"}],"sources":["https://arcraiders.wiki/wiki/Damaged_ARC_Powercell","https://arcraiders.wiki/wiki/Bastion"],"version":"2.0"},"damaged_fireball_burner":{"verdict":{"en":"Sell for 270 or recycle into 1 ARC Alloy; nothing needs it.","zh":"卖 270，或拆成 1 个ARC合金，没有需求。"},"obtain":{"en":"Left by wrecked Fireballs, which sit in bunkers, underground areas and Buried City metro entrances. Destroying one starts a fire, so step back.","zh":"火球残骸掉落，火球多在地堡、地下，以及掩埋废城地铁入口。击毁会引燃周围，注意后退。"},"tips":[{"en":"Throwing a full Fireball Burner leaves this item behind, so the intact one is the part to keep for Refiner 2.","zh":"投掷完好的“火球”燃烧炉后会留下这个受损版，精加工机 2 级要的是完好版。"}],"sources":["https://arcraiders.wiki/wiki/Damaged_Fireball_Burner","https://arcraiders.wiki/wiki/Fireball","https://arcraiders.wiki/wiki/Fireball_Burner"],"version":"2.0"},"damaged_heat_sink":{"verdict":{"en":"Keep 2 for Utility Station 2; sell the rest at 1,000 coins.","zh":"工具工作台 2 级要 2 个；其余卖 1000 钱币。"},"obtain":{"en":"Not from ARC. The wiki says Server Racks; player guides point to Launch Tower tops (Spaceport), Assembly Workshops (Stella Montis), Dam Research & Administration and Pilgrim's Peak (Blue Gate).","zh":"不是 ARC 掉的。维基说服务器机架；玩家攻略指向太空港发射塔顶、星辰山组装厂车间、大坝研究行政楼、蓝门朝圣峰。"},"tips":[{"en":"It weighs 2, the heaviest item here, so pick it up only when you need it or the sale is clearly worth the space.","zh":"重量 2，同类里最重，需要时再拿。"}],"sources":["https://arcraiders.wiki/wiki/Damaged_Heat_Sink","https://nerdschalk.com/damaged-heat-sink-arc-raiders-best-locations-on-stella-montis-spaceport-and-dam-battlegrounds-for-fast-farming/","https://metaforge.app/arc-raiders/where-to-find-damaged-heat-sinks-arc-raiders"],"version":"2.0"},"damaged_hornet_driver":{"verdict":{"en":"Sell for 640; recycling returns only 2 ARC Alloy.","zh":"卖 640；拆只得 2 个ARC合金。"},"obtain":{"en":"Dropped by wrecked Hornets, which patrol in small swarms with Wasps and Fireflies. Destroy their armored front thrusters with Medium or Heavy Ammo.","zh":"被击毁的马蜂掉落，马蜂与黄蜂、萤火虫成群巡逻。用中型或重型弹药打掉前部装甲推进器。"},"tips":[{"en":"Destroyed Hornets are also a good source of Medium Ammo.","zh":"击毁马蜂还能补充中型弹药。"}],"sources":["https://arcraiders.wiki/wiki/Damaged_Hornet_Driver","https://arcraiders.wiki/wiki/Hornet"],"version":"2.0"},"damaged_rocketeer_driver":{"verdict":{"en":"Sell it for 1,000, or recycle for 3 ARC Alloy; it is the best of the damaged drivers.","zh":"卖 1000，或拆成 3 个ARC合金；受损引擎里数它最值。"},"obtain":{"en":"From downed Rocketeers, which are posted at high-value spots. Knock out two thrusters to make it fall, or ground it with a Showstopper.","zh":"来自击落的火箭手，常驻高价值地点。打掉两个推进器使其坠落，或用“耀眼明星”手雷压地。"},"tips":[{"en":"A Rocketeer also drops Launcher Ammo, so the kill pays twice.","zh":"火箭手还掉榴弹发射器弹药，一次击杀两份收益。"}],"sources":["https://arcraiders.wiki/wiki/Damaged_Rocketeer_Driver","https://arcraiders.wiki/wiki/Rocketeer"],"version":"2.0"},"damaged_snitch_scanner":{"verdict":{"en":"Sell for 659: it cannot be recycled.","zh":"卖 659，它不能回收。"},"obtain":{"en":"Left by wrecked Snitches, which scout ahead and call reinforcements. Take it out quickly with Medium or Heavy Ammo.","zh":"告密者残骸掉落，它会先行侦察并叫援军，用中型或重型弹药迅速击落。"},"sources":["https://arcraiders.wiki/wiki/Damaged_Snitch_Scanner","https://arcraiders.wiki/wiki/Snitch"],"version":"2.0"},"damaged_tick_pod":{"verdict":{"en":"Sell for 270 or recycle into 1 ARC Alloy; no workshop use.","zh":"卖 270，或拆成 1 个ARC合金，没有工坊用途。"},"obtain":{"en":"Dropped by Ticks, which cling to walls and ceilings indoors and often come in groups. One melee hit kills one, which saves ammo.","zh":"跳蚤掉落，它们爬在室内墙壁和天花板上，常成群出现。近战一击可杀，省弹药。"},"tips":[{"en":"If one latches onto you, hold interact to shake it off before it lunges again.","zh":"被扑上身时按住交互键甩开，免得再次被扑。"}],"sources":["https://arcraiders.wiki/wiki/Damaged_Tick_Pod","https://arcraiders.wiki/wiki/Tick"],"version":"2.0"},"damaged_wasp_driver":{"verdict":{"en":"Sell for 270 or recycle into 1 ARC Alloy; this is the cheapest of the ARC parts.","zh":"卖 270，或拆成 1 个ARC合金；这是最便宜的 ARC 零件。"},"obtain":{"en":"Wasps patrol open outdoor areas and have only 110 health. Shoot their thrusters, and they crash into the ground and fall apart.","zh":"黄蜂在室外开阔地巡逻，只有 110 点生命。打推进器，它们会失控坠地损毁。"},"tips":[{"en":"Wasps also drop Light Ammo, a decent reason to take them down even though the part is cheap.","zh":"黄蜂还掉轻型弹药，零件虽便宜，击落也不亏。"}],"sources":["https://arcraiders.wiki/wiki/Damaged_Wasp_Driver","https://arcraiders.wiki/wiki/Wasp"],"version":"2.0"},"degraded_arc_rubber":{"verdict":{"en":"Sell it for 640, or recycle for 11 Rubber Parts if you are short on rubber.","zh":"卖 640；缺橡胶时可拆成 11 个橡胶零件。"},"obtain":{"en":"Found on ARC wrecks; the wiki gives no specific map. Large ARC machines on busy maps are the best bet.","zh":"ARC 残骸上常见，维基未给出具体地图，ARC 巡逻密集的地图更容易遇到。"},"tips":[{"en":"Recycling at the workshop gives 11 Rubber Parts versus 5 from salvaging in a raid.","zh":"工作台回收得 11 个橡胶零件，局内拆解只有 5 个。"}],"sources":["https://arcraiders.wiki/wiki/Degraded_ARC_Rubber","https://nerdschalk.com/arc-raiders-arc-flex-rubber-location-use-guide/"],"version":"2.0"},"dried_out_arc_resin":{"verdict":{"en":"No workshop or quest needs it; sell for 640 or recycle for 9 Plastic Parts.","zh":"没有工坊或任务需要，卖 640，或拆成 9 个塑料零件。"},"obtain":{"en":"Comes from scavenging old Baron Husks. The wiki gives no map.","zh":"来自搜刮旧的“男爵”残骸，维基未给出地图。"},"tips":[{"en":"Recycling at the workshop gives 9 Plastic Parts versus 4 from salvaging in a raid.","zh":"工作台回收得 9 个塑料零件，局内拆解只有 4 个。"}],"sources":["https://arcraiders.wiki/wiki/Dried-Out_ARC_Resin"],"version":"2.0"},"fireball_burner":{"verdict":{"en":"Keep 8 for Refiner 2 and 1 for Test Case; extras are worth little, so sell or recycle them.","zh":"精加工机 2 级要 8 个，“测试案例”要 1 个；多余的价值不高，卖掉或拆掉。"},"obtain":{"en":"Salvaged from a destroyed Fireball. They stay in bunkers and underground, such as Buried City metro entrances and the large Blue Gate bunker. Shoot the core when its front panel opens.","zh":"从击毁的火球身上摸。火球多在地堡和地下，如掩埋废城地铁入口、蓝门大地堡。等它前部面板打开时射击核心。"},"tips":[{"en":"Use Medium or Heavy Ammo on the shell; Light Ammo bounces off.","zh":"对外壳用中型或重型弹药，轻型弹药会弹开。"},{"en":"Throwing it makes a small fire but leaves a Damaged Fireball Burner, so save the intact one for the upgrade.","zh":"投掷会起小火，并留下受损的“火球”燃烧炉，完好的留给升级。"}],"sources":["https://arcraiders.wiki/wiki/Fireball_Burner","https://arcraiders.wiki/wiki/Fireball"],"version":"2.0"},"firefly_burner":{"verdict":{"en":"Keep 1 for Test Case; everything else sells for 1,000 coins.","zh":"“测试案例”要 1 个；其余全部卖 1000 钱币。"},"obtain":{"en":"Salvaged from destroyed Fireflies, which reinforce Wasp and Hornet patrols. Shoot the unarmored fuel tank and step away on death, since it ignites the area.","zh":"从击毁的萤火虫身上摸，它常加入黄蜂和马蜂的巡逻。射击无装甲的燃料罐，死亡会引燃周围，要立刻离开。"},"tips":[{"en":"Also an ingredient for the Trailblazer, but it needs the blueprint.","zh":"也是“开拓者”的材料，但需要蓝图。"}],"sources":["https://arcraiders.wiki/wiki/Firefly_Burner","https://arcraiders.wiki/wiki/Firefly"],"version":"2.0"},"glitched_arc_circuitry":{"verdict":{"en":"A 5,000-coin legendary with no live use: sell it.","zh":"5000 钱币的传说级，现在没有用途：卖掉。"},"obtain":{"en":"The wiki lists Erratic Wasps (most common), Leaper, Pop and Snitch. A guide recommends Transfer Depot in Riven Tides for solo farming and Buried City for teams. The project window may have closed, so check in game.","zh":"维基列出异常黄蜂（最常见）、跳跃者、爆爆和告密者。一份攻略推荐单人去裂潮镇转运站刷，组队去掩埋废城；该项目可能已结束，请自行确认。"},"tips":[{"en":"Recycling gives 6 ARC Alloy and an Exodus Module, which is less than the sale price.","zh":"拆解得 6 个ARC合金和 1 个离巢模块，不如直接卖。"}],"sources":["https://arcraiders.wiki/wiki/Glitched_ARC_Circuitry","https://www.mmoexp.com/News/arc-raiders-latest-glitched-wasps-farming-guide-best-locations-phantom-targets-part-2-rewards-anomalia-outfit.html"],"version":"2.0"},"glitched_arc_light_ring":{"verdict":{"en":"Event leftover: the Phantom Targets project it fed is over, so sell it for 3,000.","zh":"活动遗留品：它对应的“幻影目标”项目已结束，直接卖 3000。"},"obtain":{"en":"Only Erratic Wasps (the glitched Wasp variant) drop it, most often when you scavenge the wreck. Normal Wasps do not. Dam Battlegrounds' swampy approaches were the popular hunting ground during the event.","zh":"只有故障版黄蜂的残骸会出，普通黄蜂不出。活动期间大坝战场的沼泽一带曾是热门猎场。"},"tips":[{"en":"Recycling gives 1 Advanced Electrical Component and 3 ARC Alloy, which is worth less than the sale price.","zh":"拆解只得 1 个高级电子元件和 3 个ARC合金，不如直接卖。"}],"sources":["https://arcraiders.wiki/wiki/Glitched_ARC_Light_Ring","https://timesaver.gg/blog/arc-raiders-erratic-wasps-glitched-wasp-farm"],"version":"2.0"},"glitched_arc_phased_array":{"verdict":{"en":"Event leftover from the finished Phantom Targets project: sell it for 2,000.","zh":"已结束的“幻影目标”活动遗留品：卖 2000。"},"obtain":{"en":"Dropped by Erratic Wasps, the glitched Wasp variant, when you scavenge the wreck; it is the only listed source. Aim at the Wasp's central body so the wreck lands where you can reach it.","zh":"故障版黄蜂残骸掉落，是唯一已知来源。打中央机身，残骸才不会飘到够不着的地方。"},"tips":[{"en":"Recycling gives 3 ARC Alloy and 2 Sensors, which is worth less than selling.","zh":"拆解得 3 个ARC合金和 2 个传感器，不如卖。"}],"sources":["https://arcraiders.wiki/wiki/Glitched_ARC_Phased_Array","https://timesaver.gg/blog/arc-raiders-erratic-wasps-glitched-wasp-farm"],"version":"2.0"},"glitched_arc_power_converter":{"verdict":{"en":"Low-value event leftover: sell it, or recycle for 3 ARC Alloy if you need alloy.","zh":"低价值活动遗留品：卖掉，或缺ARC合金时拆成 3 个。"},"obtain":{"en":"Mostly from Erratic Wasps; the wiki also lists Fireballs, Hornets and Pops as sources. It is the easiest glitched part to come by.","zh":"主要来自故障版黄蜂；维基还列出火球、马蜂和爆爆。是最容易拿到的故障零件。"},"tips":[{"en":"The project that used these, Phantom Targets Part 2, is over, so there is no reason to hoard.","zh":"用到它的“幻影目标”第 2 部分已结束，没必要囤。"}],"sources":["https://arcraiders.wiki/wiki/Glitched_ARC_Power_Converter","https://timesaver.gg/blog/arc-raiders-erratic-wasps-glitched-wasp-farm"],"version":"2.0"},"glitched_arc_transmitter":{"verdict":{"en":"Sell it for 1,000; recycling gives one alloy and one electrical component, which is worth less.","zh":"卖 1000；拆出 1 合金 1 电子元件更不值。"},"obtain":{"en":"Mainly from Erratic Wasps, and occasionally from Pops. Kill glitched Wasps in open ground and scavenge the wreck.","zh":"主要来自故障版黄蜂，爆爆偶尔也出。在开阔地击落故障黄蜂并搜残骸。"},"tips":[{"en":"The Phantom Targets project that used these has ended, so sell rather than keep.","zh":"用到它的“幻影目标”项目已结束，直接卖，别留。"}],"sources":["https://arcraiders.wiki/wiki/Glitched_ARC_Transmitter","https://timesaver.gg/blog/arc-raiders-erratic-wasps-glitched-wasp-farm"],"version":"2.0"},"hornet_driver":{"verdict":{"en":"Keep 5 for the Gear Bench level 2 upgrade, plus one for Test Case; after that it sells for 1,000.","zh":"留 5 个升装备工作台 2 级，再留 1 个给“测试案例”，其余卖 1000。"},"use":{"en":"It doubles as a throwable: it stuns ARC for 7 seconds in a 6 m radius, and raiders for only half a second. Handy for freezing a Surveyor so it can't flee.","zh":"也能当投掷物：6 米内让 ARC 眩晕 7 秒，对奇袭者仅 0.5 秒。可以定住想逃跑的ARC勘测师。"},"obtain":{"en":"Kill Hornets and scavenge the wreck. Hit the unarmored rear thrusters; medium or heavy ammo punches through the front armor. Couriers can also drop it.","zh":"击落马蜂后搜残骸。打没有装甲的后推进器；中、重型弹药能破前装甲。ARC运输机也可能掉。"},"tips":[{"en":"The Trophy Display project phase 2 wants 15 more, and the Showstopper and Surge Coil recipes use one each, so don't recycle early.","zh":"战利品展示架第 2 阶段还要 15 个，耀眼明星和涌能线圈也各用 1 个，别急着拆。"}],"sources":["https://arcraiders.wiki/wiki/Hornet_Driver","https://arcraiders.wiki/wiki/Hornet","https://arcraiders.wiki/wiki/Courier"],"version":"2.0"},"impure_arc_coolant":{"verdict":{"en":"Recycle it if you need 12 Chemicals; otherwise sell it for 640. Nothing in the workshop needs it.","zh":"缺化学品就拆（12 个），否则卖 640。工作台不需要它。"},"obtain":{"en":"Comes from Baron Husk wrecks, which must be breached open. They are trapped and also hold other ARC scrap, so check the loot before leaving.","zh":"来自“男爵”残骸，需要破拆，且带陷阱。里面还有其他 ARC 废料，出来前看一眼。"},"tips":[{"en":"Recycling at the workshop gives 12 Chemicals, salvaging in a raid only 5, so carry it home.","zh":"工作台回收得 12 个化学品，局内拆解只有 5 个，带回基地再拆。"}],"sources":["https://arcraiders.wiki/wiki/Impure_ARC_Coolant","https://arcraiders.wiki/wiki/Baron_Husk"],"version":"2.0"},"leaper_pulse_unit":{"verdict":{"en":"Keep it: Utility Station level 3 and several late projects want it, and it sells for a solid 3,000.","zh":"留着：工具工作台 3 级和多个后期项目都要，卖也有 3000。"},"use":{"en":"It can be thrown for a 100-damage, 10 m blast that drags players in. Mostly, though, treat it as an upgrade material.","zh":"可当手雷扔出，10 米范围造成 100 点伤害并拉拽玩家。但主要还是升级材料。"},"obtain":{"en":"Leapers show up on Dam Battlegrounds, Buried City, The Spaceport, The Blue Gate and Riven Tides, not Stella Montis. On the Dam, patrol routes east of the Hydroponic Dome Complex and near the Water Treatment elevator work. Burn it with Blaze Grenades, then finish with heavy ammo.","zh":"跳跃者出没于大坝战场、掩埋废城、太空港、蓝门和裂潮镇，星辰山没有。大坝可去水培穹顶综合体以东和水处理电梯附近。燃烧手雷加重型弹药解决。"},"tips":[{"en":"Utility Station L3 needs 4, Into the Fray 1, and Trophy Display phase 3 another 10. Put it in your Safe Pocket.","zh":"工具工作台 3 级要 4 个，“投入战斗”1 个，展示架第 3 阶段 10 个。放进安全口袋。"}],"sources":["https://arcraiders.wiki/wiki/Leaper","https://allthings.how/leaper-pulse-unit-in-arc-raiders-where-it-drops-what-it-does-and-why-it-matters/"],"version":"2.0"},"matriarch_reactor":{"verdict":{"en":"Keep one for the Aphelion and the Nothing Gained quest; extras are 11,000 coins each, and the boss fight is the cost.","zh":"留 1 个做远日点和“不入虎穴”；多的每个卖 11000。"},"use":{"en":"Craft the Aphelion at Gunsmith level 3 with the blueprint. The Trophy Display project phase 5 also asks for 3.","zh":"武器工作台 3 级配合蓝图可制作远日点。战利品展示架第 5 阶段还要 3 个。"},"obtain":{"en":"The Matriarch only spawns while its map condition is active, then roams ARC territory. Fight from high ground or solid cover, break the faceplates, then shoot the exposed red core. The rocket barrage is the real danger. Loot fast: other raiders swarm the wreck.","zh":"族母只在对应地图条件开启时出现。占据高点或掩体，打碎面甲后射击暴露的红色核心。火箭齐射最危险。快速搜刮，别人会来抢。"},"tips":[{"en":"Ignore the legs and don't shoot into its energy shield; wait for it to drop. Without its escort, the fight gets easy.","zh":"别打腿，能量护盾开着时先别开火。护卫清掉后战斗会轻松很多。"}],"sources":["https://arcraiders.wiki/wiki/Matriarch","https://arcraiders.wiki/wiki/Matriarch_Reactor","https://noobfeed.com/articles/arc-raiders-legendary-queen-matriarch-reactors"],"version":"2.0"},"pop_trigger":{"verdict":{"en":"Keep 5 for Explosives Station level 2 and 1 for To The Skies; the rest sell for 640.","zh":"留 5 个升爆炸物工作台 2 级、1 个给“飞向苍穹”，其余卖 640。"},"obtain":{"en":"Pops are rolling kamikaze drones found mostly indoors in large facilities, usually next to Fireballs. Shoot them with a fast-firing weapon at close range, or just sprint past at full speed and they blow up harmlessly.","zh":"爆爆是滚动自爆机器，多在大型室内设施，常与火球同行。近距离用速射武器打，或全速跑过，它会无害引爆。"},"tips":[{"en":"Trophy Display phase 1 asks for 15 and Fireworks Box recipes use 3 each. Hold until those are done.","zh":"展示架第 1 阶段要 15 个，烟花箱配方各用 3 个。做完再处理多余的。"}],"sources":["https://arcraiders.wiki/wiki/Pop","https://arcraiders.wiki/wiki/Glitched_ARC_Power_Converter"],"version":"2.0"},"queen_reactor":{"verdict":{"en":"Keep one for the Equalizer or Jupiter and for Nothing Gained; any extra sells for 11,000.","zh":"留 1 个做制裁者或木星，并交“不入虎穴”；多的卖 11000。"},"use":{"en":"Used for crafting the Equalizer or Jupiter at Gunsmith level 3, with 3 Magnetic Accelerators and 3 Complex Gun Parts. Trophy Display phase 4 wants 3.","zh":"武器工作台 3 级配合 3 个磁力加速器、3 个复杂枪械零件，可造制裁者或木星。展示架第 4 阶段要 3 个。"},"obtain":{"en":"The Queen guards a Harvester, and only while that map condition is on; it shows up on Dam Battlegrounds, The Spaceport and The Blue Gate. Shoot off her leg armor segments: they drop containers, often with a reactor, before she dies. You can also skip her and do the Harvester puzzle.","zh":"女王只在“收割者”地图条件开启时守着收割者，出现在大坝战场、太空港和蓝门。打掉腿部装甲会掉容器，常带反应堆。也可绕开她只解谜。"},"tips":[{"en":"Aim at her Core and leg joints. Her laser can electrocute everyone looting the Harvester.","zh":"瞄核心和腿关节。她的激光会电到所有在搜收割者的人。"}],"sources":["https://arcraiders.wiki/wiki/Queen","https://arcraiders.wiki/wiki/Queen_Reactor","https://noobfeed.com/articles/arc-raiders-legendary-queen-matriarch-reactors"],"version":"2.0"},"radio_relay":{"verdict":{"en":"Pure sell-or-recycle part: nothing needs it, but 3,000 coins is a real payout.","zh":"纯卖或拆：没有任何用途，但 3000 的价格相当可观。"},"obtain":{"en":"Found on Stella Montis by scavenging, mostly inside buildings. The Lobby building is a reliable spot: look on shelves, in loot piles and small corner rooms.","zh":"在星辰山搜刮获得，多在建筑内。大厅建筑比较稳：看货架、散落物堆和角落小房间。"},"tips":[{"en":"Selling beats recycling: 2 Sensors and 2 Speaker Components are worth less than 3,000.","zh":"卖比拆划算：2 个传感器加 2 个扬声器零件不值 3000。"}],"sources":["https://arcraiders.wiki/wiki/Radio_Relay","https://nerdschalk.com/arc-raiders-radio-relay-location-guide/"],"version":"2.0"},"rocketeer_driver":{"verdict":{"en":"Keep 3 for Explosives Station level 3 plus 4 for quests; then Trophy Display wants 8 more.","zh":"留 3 个升爆炸物工作台 3 级，再留 4 个交任务；展示架还要 8 个。"},"use":{"en":"Needed for the Wolfpack grenade launcher recipe too. Beyond those needs it sells for 3,000.","zh":"狼群的配方也用到它。用不完的卖 3000。"},"obtain":{"en":"Kill Rocketeers, usually stationed in high-value areas. On the Dam, Hydroponic Dome Complex is mentioned. Take cover, shoot the unarmored thrusters (two down grounds it) and roll when the laser locks. Couriers may drop it too.","zh":"击杀火箭手，它们常驻高价值区域。大坝可去水培穹顶综合体。找掩体，打无装甲的推进器（毁两个就坠落），激光锁定时翻滚。ARC运输机也可能掉。"},"tips":[{"en":"Quests Nothing Ventured (3) and Out of the Shadows (1) both want it.","zh":"“焉得虎子”要 3 个，“走出阴影”要 1 个。"}],"sources":["https://arcraiders.wiki/wiki/Rocketeer","https://nerdschalk.com/rocketeer-driver-in-arc-raiders-location-and-unlock-guide/"],"version":"2.0"},"ruined_augment":{"verdict":{"en":"Junk: sell it for 270 or recycle for plastic and rubber; it weighs 3 and can't be equipped.","zh":"垃圾：卖 270 或拆成塑料和橡胶；重 3 且无法装备。"},"obtain":{"en":"The wiki lists knocked-out Raiders as the source: augments lose 30% durability per knockout, so one is ruined after four.","zh":"维基列出的来源是被击倒的奇袭者：强化每次被击倒损失 30% 耐久，四次后损毁。"},"tips":[{"en":"Weight 3 for 270 coins is poor; only carry it if you have the space.","zh":"重 3 只值 270，背包有空位再带。"}],"sources":["https://arcraiders.wiki/wiki/Ruined_Augment"],"version":"2.0"},"rusty_arc_steel":{"verdict":{"en":"Recycle for 8 Metal Parts at the workshop, or sell for 640 if you're swimming in metal.","zh":"回基地拆 8 个金属零件，金属够了就卖 640。"},"obtain":{"en":"Scavenged from old ARC husks. The Baron Husk's loot pool includes it; those wrecks must be breached and are trapped.","zh":"从旧 ARC 残骸中搜到。“男爵”残骸的战利品里有，需要破拆且有陷阱。"},"tips":[{"en":"Salvaging in a raid gives 3 Metal Parts versus 8 at the workshop, so carry it back.","zh":"局内拆解只有 3 个金属零件，工作台是 8 个，带回去再拆。"}],"sources":["https://arcraiders.wiki/wiki/Rusty_ARC_Steel","https://arcraiders.wiki/wiki/Baron_Husk"],"version":"2.0"},"sentinel_firing_core":{"verdict":{"en":"Keep 4 for Gunsmith level 3 and 1 for Wires Crossed; extras sell for 2,000.","zh":"留 4 个升武器工作台 3 级、1 个给“线路交错”，多的卖 2000。"},"obtain":{"en":"Sentinels sit in elevated overwatch spots, mostly under Hurricane conditions: north and south of the Breach on the Dam, Town Hall bell tower in Buried City, Spaceport South Trench Tower, Blue Gate Outer Gates beams, Stella Montis Atrium ceiling. Couriers can drop it too.","zh":"哨卫驻守高处，多在飓风天气：大坝裂口南北、掩埋废城市政厅钟楼、太空港南壕沟塔、蓝门外门横梁、星辰山中庭天花板。ARC运输机也可能掉。"},"tips":[{"en":"It has 300 health and reacts slowly; shoot the yellow canister on its swivel arm for extra damage.","zh":"它只有 300 血且反应慢；打转臂上的黄色罐体伤害更高。"}],"sources":["https://arcraiders.wiki/wiki/Sentinel","https://arcraiders.wiki/wiki/Courier"],"version":"2.0"},"shredder_gyro":{"verdict":{"en":"Keep a few for Trophy Display and the Dolabra; surplus sells for 2,000.","zh":"留几个给战利品展示架和錾斧，多的卖 2000。"},"obtain":{"en":"Stella Montis is the best bet, though the wiki says Shredders no longer stay there exclusively. Guides point to the main lobby ground floor and the Robotic Sandbox, where 2 to 4 may roam. Shoot the blue thrusters, ideally with a Hullcracker.","zh":"星辰山最稳，但维基称粉碎者已不限于此。攻略推荐主大厅一层和机器人沙盘，常有 2-4 只。打蓝色推进器，最好用裂甲者。"},"tips":[{"en":"Trophy Display phase 3 wants 5 and the Dolabra recipe uses 3. Extract once you carry a few, because dying loses them.","zh":"展示架第 3 阶段要 5 个，錾斧配方用 3 个。带够几个就撤离，死了会丢。"}],"sources":["https://arcraiders.wiki/wiki/Shredder","https://nerdschalk.com/fast-project-material-farming-shredder-gyros-in-arc-raiders/"],"version":"2.0"},"skulker_driver":{"verdict":{"en":"A new 2.0 Skulker part with no known use yet: hold or sell it for 1,000.","zh":"2.0 新增的潜伏者零件，暂无已知用途：留着或卖 1000。"},"obtain":{"en":"The in-game description says it drops from the Meerkat. Skulkers roam Pendola Pass around Almatera Station, but no source confirms the Driver's drop rate.","zh":"游戏内描述称掉自“潜伏者”。潜伏者在彭多拉山口阿尔玛特拉站一带活动，但没有来源确认引擎的掉率。"},"sources":["https://games.gg/arc-raiders/guides/arc-raiders-skulker-guide/","https://arcraiders.wiki/wiki/Skulker"],"version":"2.0"},"skulker_targeter":{"verdict":{"en":"Keep 5 for Research Station level 2 and 1 for Tracks of the Beast; also useful as a small turret.","zh":"留 5 个升研究站 2 级，再留 1 个交“巨兽踪迹”；也能当小炮台。"},"use":{"en":"It deploys as a turret hitting ARC and raiders within 25 m for 9 damage a shot. Weak, but fine as a distraction.","zh":"部署后为炮台，25 米内对 ARC 和奇袭者每发 9 点伤害。偏弱，但可以分散注意力。"},"obtain":{"en":"Destroy Skulkers on Pendola Pass, around Almatera Station and the snowfields, then loot the wreck. Shoot the thrusters to slow it, then hit the turret once exposed. Couriers can drop it too.","zh":"在彭多拉山口阿尔玛特拉站和雪原击毁潜伏者并搜刮。先打推进器减速，炮台露出后再打。ARC运输机也可能掉。"},"tips":[{"en":"The Canto Blueprint at Research Station 2 also asks for 10, so don't recycle yet.","zh":"研究站 2 级的颂歌蓝图还要 10 个，先别拆。"}],"sources":["https://arcraiders.wiki/wiki/Skulker_Targeter","https://www.keengamer.com/articles/guides/arc-raiders-tracks-of-the-beast-quest-walkthrough/","https://games.gg/arc-raiders/guides/arc-raiders-skulker-guide/"],"version":"2.0"},"snitch_scanner":{"verdict":{"en":"Keep 6 for Utility Station level 2 and 1 for Wires Crossed; extras sell for 1,000.","zh":"留 6 个升工具工作台 2 级、1 个给“线路交错”，多的卖 1000。"},"use":{"en":"Thrown, it calls ARC onto a target; during the Erratic Wasp event it was used to summon Wasps.","zh":"投出后可召 ARC 攻击目标；故障黄蜂活动时有人用它引黄蜂。"},"obtain":{"en":"Kill Snitches before they finish calling reinforcements. Medium or heavy ammo takes one down in a few shots; knocking out thrusters makes them crash. Hide in foliage to dodge the scanner.","zh":"在告密者叫来援军之前击杀。中、重型弹药几发即可；打掉推进器会坠毁。躲进植被避开扫描。"},"tips":[{"en":"Only Utility Station level 2 and Wires Crossed need it, so everything else can be sold.","zh":"只有工具工作台 2 级和“线路交错”需要，其余都可以卖。"}],"sources":["https://arcraiders.wiki/wiki/Snitch","https://timesaver.gg/blog/arc-raiders-erratic-wasps-glitched-wasp-farm"],"version":"2.0"},"spotter_relay":{"verdict":{"en":"Keep 2 for quests and 10 only if you're doing Trophy Display; otherwise sell for 1,000.","zh":"留 2 个交任务，做战利品展示架才留 10 个，其余卖 1000。"},"obtain":{"en":"Spotters are small 80 HP drones that accompany Bombardiers; shoot the thrusters. They respawn, so don't waste ammo repeatedly. Couriers drop it too.","zh":"侦察员是伴随投弹手的 80 血小型无人机，打推进器。会重生，别反复浪费弹药。ARC运输机也可能掉。"},"tips":[{"en":"Ruins and Reverberations and Combat Recon each take one.","zh":"“废墟和回响”与“战斗侦察”各要 1 个。"}],"sources":["https://arcraiders.wiki/wiki/Spotter","https://arcraiders.wiki/wiki/Courier"],"version":"2.0"},"surveyor_vault":{"verdict":{"en":"Keep 5 for Medical Lab level 3 and 2 for quests; Trophy Display phase 1 wants 5 more.","zh":"留 5 个升医疗实验室 3 级、2 个交任务；展示架第 1 阶段还要 5 个。"},"obtain":{"en":"Surveyors flee on sensing a threat, so hit them while transmitting. Stun with a Hornet Driver, then use heavy fuze grenades; heavy ammo strips the armor plates. Couriers during Electromagnetic Storm on the Dam (Scrapyard, Old Battleground) were reported as an easier source.","zh":"勘测师察觉威胁就逃，趁它传输时下手。先用“马蜂”引擎眩晕，再用重型引信手雷；重型弹药能打掉装甲板。大坝电磁风暴期间的ARC运输机据称更好刷。"},"tips":[{"en":"Don't recycle until Medical Lab L3 and both quests are done.","zh":"医疗实验室 3 级和两个任务完成前别拆。"}],"sources":["https://arcraiders.wiki/wiki/Surveyor","https://nerdschalk.com/where-to-find-surveyor-vault-in-arc-raiders-location-farming-guide/","https://arcraiders.wiki/wiki/Courier"],"version":"2.0"},"tattered_arc_lining":{"verdict":{"en":"Recycle at the workshop for 12 Fabric, or sell for 640. Nothing needs it directly.","zh":"回基地拆 12 个布料，或卖 640。没有直接用途。"},"obtain":{"en":"Scavenged from old ARC husks; Baron Husk wrecks list it (2 or more). They must be breached and are trapped.","zh":"从旧 ARC 残骸搜到；“男爵”残骸会出（2 个以上），需要破拆且有陷阱。"},"tips":[{"en":"Salvaging in a raid only returns 5 Fabric.","zh":"局内拆解只返还 5 个布料。"}],"sources":["https://arcraiders.wiki/wiki/Tattered_ARC_Lining","https://arcraiders.wiki/wiki/Baron_Husk"],"version":"2.0"},"tick_pod":{"verdict":{"en":"Keep 8 for Medical Lab level 2 plus 15 for Trophy Display phase 1; extras sell for 640.","zh":"留 8 个升医疗实验室 2 级，展示架第 1 阶段要 15 个，多的卖 640。"},"obtain":{"en":"Ticks live indoors, clinging to walls and ceilings and often dormant in rafters. Listen for a metallic clank. One Raider Tool hit kills them. Hold interact to pull one off you.","zh":"跳蚤在室内，趴在墙和天花板上，常在椽梁上休眠。留意金属摩擦声。近战一下即死；被扒上时按住互动甩掉。"},"tips":[{"en":"Vita Spray also uses one; recycling gives ARC Alloy and Chemicals.","zh":"补水喷雾也用 1 个；拆解得ARC合金和化学品。"}],"sources":["https://arcraiders.wiki/wiki/Tick","https://allthings.how/arc-raiders-tick-pods-where-to-find-ticks-and-farm-their-loot/"],"version":"2.0"},"turbine_compressor":{"verdict":{"en":"Keep it for the Powered Descender; surplus sells for a hefty 5,000.","zh":"留给动力下降器；多的能卖 5000。"},"obtain":{"en":"Destroy an ARC Turbine; it drifts in mid-raid, with guides saying around 15 minutes left. Hit the spinning yellow tanks once it lands, or use a Jupiter from 150 to 200 m. Sources conflict on the map (Riven Tides vs Rust Belt).","zh":"击毁 ARC涡轮；它在对局中段出现，攻略说约剩 15 分钟。落地后打黄色旋转罐体，或用木星从 150-200 米外射击。地图说法不一（裂潮镇或锈带）。"},"tips":[{"en":"The wiki says Couriers stopped dropping Turbine parts in patch 1.36, so Turbines are the source.","zh":"维基称 1.36 后ARC运输机不再掉涡轮零件，要靠击毁涡轮。"}],"sources":["https://arcraiders.wiki/wiki/Turbine","https://arcraiders.wiki/wiki/Turbine_Compressor","https://www.pcgamesn.com/arc-raiders/turbine"],"version":"2.0"},"wasp_driver":{"verdict":{"en":"Keep 8 for Gunsmith level 2, then Trophy Display wants 20; surplus is only worth 640.","zh":"留 8 个升武器工作台 2 级，展示架再要 20 个；多的只值 640。"},"obtain":{"en":"Wasps patrol large outdoor areas with Hornets and Fireflies. Knock out several thrusters so it crashes. A Lure Grenade helps escape a swarm. Couriers can drop it too.","zh":"黄蜂在开阔室外巡逻，常与马蜂和萤火虫同行。打掉多个推进器使其坠毁。诱捕手雷可摆脱蜂群。ARC运输机也可能掉。"},"tips":[{"en":"Recycling gives just 2 ARC Alloy, so selling at 640 is no worse.","zh":"拆解只有 2 个ARC合金，卖 640 也不亏。"}],"sources":["https://arcraiders.wiki/wiki/Wasp","https://arcraiders.wiki/wiki/Courier"],"version":"2.0"},"alarm_clock":{"verdict":{"en":"Nothing needs it: recycle it for a Processor and plastic, or just sell it for 1,000.","zh":"没有任何用途：拆成处理器和塑料，或直接卖 1000。"},"obtain":{"en":"Turns up in Residential-type loot while scavenging; the wiki names no specific map or container, so just check homes and apartments as you pass.","zh":"在住宅类搜刮点出现，社区维基未给出具体地图或容器，路过民居和公寓顺手翻即可。"},"tips":[{"en":"Recycling gives 6 Plastic Parts and 1 Processor, while salvaging in a raid gives only the Processor. Recycle at the workshop if you want both.","zh":"工作台回收可得 6 个塑料零件和 1 个处理器，局内拆解只有处理器。两样都要就回基地回收。"}],"sources":["https://arcraiders.wiki/wiki/Alarm_Clock"],"version":"2.0"},"bicycle_pump":{"verdict":{"en":"Keep one for the quest The League, then recycle the rest for Metal Parts.","zh":"留 1 个给任务“球队”，其余回收换金属零件。"},"obtain":{"en":"Residential loot. The wiki gives no exact spots, so search apartments and houses; it is a quest item you only need once.","zh":"住宅类战利品，社区维基没给具体点位，翻公寓和民居即可；任务只需要 1 个。"},"tips":[{"en":"Recycling returns 4 Canisters and 10 Metal Parts, far more than the 3 Canisters you get from salvaging in raid.","zh":"回收可得 4 个小罐和 10 个金属零件，比局内拆解的 3 个小罐划算得多。"}],"sources":["https://arcraiders.wiki/wiki/Bicycle_Pump"],"version":"2.0"},"broken_flashlight":{"verdict":{"en":"Pure salvage: no quest or upgrade needs it, so recycle it for Batteries or sell.","zh":"纯杂物：没有任务或升级需要，回收拿电池或直接卖。"},"obtain":{"en":"Listed under Security loot (guard posts, offices and the like). The wiki does not name a specific map or container.","zh":"归类为安保类战利品（岗哨、办公室一类），社区维基未指明具体地图或容器。"},"tips":[{"en":"Recycling gives 2 Batteries and 6 Metal Parts; salvaging in raid gives 7 Metal Parts and no Batteries. Pick by what you are short of.","zh":"回收得 2 个电池和 6 个金属零件，局内拆解只有 7 个金属零件。缺什么就选哪种。"}],"sources":["https://arcraiders.wiki/wiki/Broken_Flashlight"],"version":"2.0"},"broken_guidance_system":{"verdict":{"en":"Nothing live needs it: sell it for 2,000 coins, or recycle for 4 Processors.","zh":"没有进行中的需求：卖 2000 钱币，或拆成 4 个处理器。"},"use":{"en":"No live project, quest or workshop upgrade asks for it. It is worth 2,000 coins, or 4 Processors if you recycle it.","zh":"没有进行中的项目、任务或工作台升级需要它。值 2000 钱币，拆解可得 4 个处理器。"},"obtain":{"en":"Comes from Exodus-tagged loot. The community wiki lists no exact map or container, so expect it among tech and wreckage loot on late-game runs.","zh":"属于出走相关战利品，社区维基未给具体地图或容器，只能在后期局内的科技类搜刮点碰运气。"},"tips":[{"en":"Recycling yields 4 Processors, twice what in-raid salvaging gives. It weighs 3, so only carry it out if you will use it.","zh":"回收可得 4 个处理器，是局内拆解的两倍。重量 3，不打算用就别带出来。"}],"sources":["https://arcraiders.wiki/wiki/Broken_Guidance_System"],"version":"2.0"},"broken_handheld_radio":{"verdict":{"en":"No upgrade or quest uses it: recycle for Sensors and Wires, or sell it for 2,000.","zh":"没有升级或任务用得上：回收拿传感器和导线，或卖 2000。"},"obtain":{"en":"Security-type loot. No specific map or container is documented on the community wiki.","zh":"安保类战利品，社区维基没有记载具体地图或容器。"},"tips":[{"en":"Recycling returns 3 Sensors and 2 Wires; salvaging in raid gives just 2 Sensors, so recycle at the workshop.","zh":"回收得 3 个传感器和 2 个导线，局内拆解只有 2 个传感器，回基地回收更好。"}],"sources":["https://arcraiders.wiki/wiki/Broken_Handheld_Radio"],"version":"2.0"},"broken_taser":{"verdict":{"en":"Junk: nothing needs it, so recycle it for Batteries or sell it.","zh":"杂物：没有用途，回收拿电池或直接卖。"},"obtain":{"en":"Security loot. The community wiki gives no specific spots.","zh":"安保类战利品，社区维基未给具体位置。"},"tips":[{"en":"Recycling also returns 2 Wires on top of the 2 Batteries that in-raid salvaging gives.","zh":"回收除了 2 个电池，还多给 2 个导线，局内拆解则只有电池。"}],"sources":["https://arcraiders.wiki/wiki/Broken_Taser"],"version":"2.0"},"camera_lens":{"verdict":{"en":"Nothing live needs it; keep 1 only if you craft the Advanced Camera, and sell or recycle the rest.","zh":"没有进行中的需求；只有要做“高级相机”才留 1 个，其余卖掉或回收。"},"use":{"en":"Only the Advanced Camera recipe uses 1. Anything beyond that is 8 Plastic Parts of recycling, or a 640-coin sale.","zh":"只有“高级相机”配方要 1 个。除此之外可回收 8 个塑料零件，或卖 640 钱币。"},"obtain":{"en":"Security loot; the wiki does not list exact containers. Check offices and guard rooms.","zh":"安保类战利品，社区维基没列具体容器，多看办公室和岗哨。"},"tips":[{"en":"It weighs under 1 and stacks to 5, so carrying a few costs almost nothing.","zh":"重量不到 1，可叠 5 个，多带几个几乎没负担。"}],"sources":["https://arcraiders.wiki/wiki/Camera_Lens"],"version":"2.0"},"candle_holder":{"verdict":{"en":"Nothing live needs it: sell it for 640 coins, or recycle for 8 Metal Parts.","zh":"没有进行中的需求：卖 640 钱币，或回收 8 个金属零件。"},"obtain":{"en":"Residential loot containers. On Dam Battlegrounds try Pale Apartments and Ruby Residence; on Buried City try Plaza Rosa and Grandioso Apartments.","zh":"住宅类战利品容器。大坝战场去苍白公寓、红宝石宅邸；掩埋废城去玫瑰广场、奢华公寓。"},"tips":[{"en":"Recycling gives 8 Metal Parts, double what in-raid salvaging gives, so bring spares home.","zh":"回收得 8 个金属零件，是局内拆解的两倍，多余的带回基地回收。"}],"sources":["https://arcraiders.wiki/wiki/Candle_Holder"],"version":"2.0"},"coolant":{"verdict":{"en":"Nothing needs it: recycle for Chemicals and Oil, or sell for 1,000.","zh":"没有任何需求：回收拿化学品和油，或卖 1000。"},"obtain":{"en":"Mechanical-type loot (workshops, garages, machinery). The community wiki names no specific map or container.","zh":"机械类战利品（车间、车库、机器附近），社区维基未给具体地图或容器。"},"tips":[{"en":"Recycling returns 5 Chemicals and 2 Oil; salvaging in raid only gives the Oil.","zh":"回收得 5 个化学品和 2 个油，局内拆解只有油。"}],"sources":["https://arcraiders.wiki/wiki/Coolant"],"version":"2.0"},"cooling_coil":{"verdict":{"en":"Nothing live needs it: sell for 1,000 coins, or recycle for 6 Chemicals and 2 Steel Springs.","zh":"没有进行中的需求：卖 1000 钱币，或回收出 6 个化学品和 2 个钢质弹簧。"},"obtain":{"en":"Industrial loot. The wiki lists car hoods, buses, mobile generators, metal crates, car tool cabinets, industrial drawers and red lockers as containers worth checking.","zh":"工业类战利品。社区维基列出的容器有：汽车引擎盖、巴士、移动发电机、金属箱、汽车工具柜、工业抽屉和红色储物柜。"},"tips":[{"en":"The container list is mostly vehicles and garages, so check wrecks and depots on your route instead of making a special trip.","zh":"容器多为车辆和车库，顺路翻残骸和仓库就行，不必专程去。"}],"sources":["https://arcraiders.wiki/wiki/Cooling_Coil"],"version":"2.0"},"cooling_fan":{"verdict":{"en":"Nothing live needs it: sell for 2,000 coins, or recycle for 14 Plastic Parts and 4 Wires.","zh":"没有进行中的需求：卖 2000 钱币，或回收出 14 个塑料零件和 4 个导线。"},"obtain":{"en":"Search server racks in Technological areas; that is the container the wiki lists. No specific map is named.","zh":"在科技类区域翻服务器机柜，这是社区维基列出的容器，未指明具体地图。"},"tips":[{"en":"Recycling gives 14 Plastic Parts and 4 Wires, much better than the 4 Wires from salvaging in raid.","zh":"回收得 14 个塑料零件和 4 个导线，比局内拆解只有 4 个导线强很多。"}],"sources":["https://arcraiders.wiki/wiki/Cooling_Fan"],"version":"2.0"},"cracked_bioscanner":{"verdict":{"en":"Keep 2 for Medical Lab level 2, then recycle the rest.","zh":"留 2 个给医疗实验室 2 级，其余回收。"},"obtain":{"en":"Medical-type loot such as clinics and med rooms. The wiki gives no exact map or container.","zh":"医疗类战利品，如诊所和医疗室，社区维基没给具体地图或容器。"},"tips":[{"en":"The Medical Lab 2 upgrade also wants Tick Pods and Durable Cloth, so start collecting those alongside.","zh":"医疗实验室 2 级还需要“跳蚤”收纳舱和耐磨布料，可以一并攒起来。"},{"en":"Recycling gives 3 Batteries and 3 Rubber Parts, better than the 2 Batteries from in-raid salvage.","zh":"回收得 3 个电池和 3 个橡胶零件，比局内拆解的 2 个电池好。"}],"sources":["https://arcraiders.wiki/wiki/Cracked_Bioscanner"],"version":"2.0"},"crumpled_plastic_bottle":{"verdict":{"en":"Low-value trash: recycle it for 4 Plastic Parts, or leave it if your bag is full.","zh":"低价值垃圾：回收得 4 个塑料零件，背包满了就别捡。"},"obtain":{"en":"Residential loot. Nothing more specific is documented.","zh":"住宅类战利品，没有更具体的记载。"},"tips":[{"en":"At 270 coins it is not worth a bag slot unless you need plastic.","zh":"只值 270，除非缺塑料，否则不值得占格子。"}],"sources":["https://arcraiders.wiki/wiki/Crumpled_Plastic_Bottle"],"version":"2.0"},"deflated_football":{"verdict":{"en":"Keep 1 for the quest The League, then recycle for rubber and fabric.","zh":"留 1 个给任务“球队”，其余回收换橡胶和布料。"},"obtain":{"en":"Residential loot. The community wiki gives no exact containers.","zh":"住宅类战利品，社区维基没给具体容器。"},"tips":[{"en":"Recycling returns 9 Fabric and 9 Rubber Parts, a lot for a 0.8 weight item.","zh":"回收可得 9 个布料和 9 个橡胶零件，重量仅 0.8，很划算。"}],"sources":["https://arcraiders.wiki/wiki/Deflated_Football"],"version":"2.0"},"differential_microphone":{"verdict":{"en":"New in 2.0: keep 3 for the Research Station level 3 upgrade, then recycle.","zh":"2.0 新增：留 3 个给研究站 3 级，之后回收。"},"obtain":{"en":"Listed as a Technological/Electrical scavenge item. The wiki does not document specific spawn spots yet.","zh":"归类为科技/电子类搜刮物，社区维基尚未记载具体刷新点。"},"tips":[{"en":"The same Research Station upgrade also takes Exodus Technical Handbooks and Bully Fragmenters, so check you can get those before hoarding.","zh":"研究站该升级还需要“离巢”技术手册和“恶霸”破片弹，囤之前先确认能凑齐。"}],"sources":["https://arcraiders.wiki/wiki/Differential_Microphone"],"version":"2.0"},"diving_goggles":{"verdict":{"en":"No use beyond salvage: recycle for 12 Rubber Parts or sell.","zh":"除了回收没别的用：回收得 12 个橡胶零件，或直接卖。"},"obtain":{"en":"Residential loot. No exact map or container is listed.","zh":"住宅类战利品，未列出具体地图或容器。"},"tips":[{"en":"Recycling gives 12 Rubber Parts versus 5 from salvaging in raid.","zh":"回收可得 12 个橡胶零件，局内拆解只有 5 个。"}],"sources":["https://arcraiders.wiki/wiki/Diving_Goggles"],"version":"2.0"},"dog_collar":{"verdict":{"en":"Keep one: it is the Scrappy level 2 upgrade item. Recycle the rest for Fabric.","zh":"留 1 个：废品仔 2 级升级要用。多余的回收拿布料。"},"obtain":{"en":"Residential loot; no precise containers are documented.","zh":"住宅类战利品，没有记载精确容器。"},"tips":[{"en":"If you already upgraded Scrappy, treat it as plain junk: 8 Fabric and 1 Metal Parts on recycling.","zh":"废品仔已升级的话就当杂物，回收得 8 个布料和 1 个金属零件。"}],"sources":["https://arcraiders.wiki/wiki/Dog_Collar"],"version":"2.0"},"epoxy_bucket":{"verdict":{"en":"New in 2.0 and unused so far: recycle for Chemicals or sell for 1,000.","zh":"2.0 新增，目前没有用途：回收拿化学品，或卖 1000。"},"obtain":{"en":"The wiki only lists scavenging as the source, with no map or container named yet.","zh":"社区维基只写了搜刮，尚未标明地图或容器。"},"tips":[{"en":"It stacks to 5 and weighs 0.5, so it is easy to carry a few home for recycling.","zh":"可叠 5 个、重量 0.5，带几个回家回收很轻松。"}],"sources":["https://arcraiders.wiki/wiki/Epoxy_Bucket"],"version":"2.0"},"expired_respirator":{"verdict":{"en":"Keep 3 for the Trophy Display project, then recycle for rubber and fabric.","zh":"留 3 个给“战利品展示架”项目，之后回收换橡胶和布料。"},"obtain":{"en":"Medical-type loot; the wiki names no specific map or container.","zh":"医疗类战利品，社区维基未指明具体地图或容器。"},"tips":[{"en":"It is a phase 2 item, so you can ignore it until you reach that stage.","zh":"这是第 2 阶段的材料，没做到那一步前可以先不管。"}],"sources":["https://arcraiders.wiki/wiki/Expired_Respirator"],"version":"2.0"},"flow_controller":{"verdict":{"en":"Keep 1 for Snap and Salvage; otherwise it is a good 3,000-coin sale.","zh":"留 1 个给“拍照并拆解回收”，否则卖 3000 很划算。"},"obtain":{"en":"The wiki lists scavenging on Stella Montis, and it is tagged Exodus. No specific room or container is named.","zh":"社区维基列为星辰山搜刮，并带出走标签，未指明房间或容器。"},"tips":[{"en":"Recycling gives one Advanced Mechanical Component and one Sensor, so only recycle if you need those parts.","zh":"回收得 1 个高级机械元件和 1 个传感器，缺这些零件时再回收。"}],"sources":["https://arcraiders.wiki/wiki/Flow_Controller"],"version":"2.0"},"frequency_modulation_box":{"verdict":{"en":"Nothing live needs it: sell for 3,000 coins each.","zh":"没有进行中的需求：每个卖 3000 钱币。"},"obtain":{"en":"Scavenged on Stella Montis according to the wiki, and tagged Exodus. No exact container is given.","zh":"社区维基称在星辰山搜刮，并带出走标签，未给具体容器。"},"tips":[{"en":"It sells for far more than its parts: recycling only gives an Advanced Electrical Component and a Speaker Component.","zh":"卖价远高于拆解所得：回收只有高级电子元件和扬声器零件各 1 个。"}],"sources":["https://arcraiders.wiki/wiki/Frequency_Modulation_Box"],"version":"2.0"},"fried_motherboard":{"verdict":{"en":"Keep 3 for the Utility Station level 3 upgrade; after that, recycling or selling at 2000 coins are both fine.","zh":"留 3 个升级工具工作台 3 级，之后可回收，也可按 2000 钱币出售。"},"obtain":{"en":"It comes out of tech containers: Server Racks and Recording Panels. Stella Montis Assembly Workshops is the most cited farm; Research and Administration on Dam Battlegrounds and the Space Travel building in Buried City also work. Spaceport is dense with tech zones.","zh":"出自科技类容器：服务器机架和录音面板。最常被推荐的刷点是星辰山的组装厂车间；大坝战场的研究与行政楼、掩埋废城的航天大楼也行，太空港的科技区域很密。"},"tips":[{"en":"Expect roughly one per raid. Entering with an empty loadout lets you secure it in your safe pocket and leave early.","zh":"通常一局约一个。空装备入场，放进安全口袋后即可提前撤离。"}],"sources":["https://arcraiders.wiki/wiki/Fried_Motherboard","https://www.shacknews.com/article/149118/where-to-find-fried-motherboards-in-arc-raiders","https://www.fdaytalk.com/where-to-find-fried-motherboard-in-arc-raiders/"],"version":"2.0"},"frying_pan":{"verdict":{"en":"Nothing live needs it: sell for 640 coins, or recycle for 8 Metal Parts.","zh":"没有进行中的需求：卖 640 钱币，或回收 8 个金属零件。"},"obtain":{"en":"Residential loot only, with no fixed spot. Buried City has the most residential areas; Grandioso Apartments there, Ruby Residence and Pale Apartments on Dam Battlegrounds, and the Village on The Blue Gate are named. Popular buildings get looted early.","zh":"只在居住区刷新，没有固定点。掩埋废城居住区最多，奢华公寓是常提的点；大坝战场的红宝石宅邸、苍白公寓和蓝门的村庄也可去。热门建筑常被早早搜空。"},"tips":[{"en":"It weighs 2, so leave it behind unless you have spare room; recycling at home gives 8 Metal Parts, double the in-raid yield.","zh":"重量 2，背包有空位再拿；回基地回收得 8 个金属零件，是局内拆解的两倍。"}],"sources":["https://arcraiders.wiki/wiki/Frying_Pan","https://1v9.gg/blog/arc-raiders-how-to-find-frying-pan","https://insider-gaming.com/arc-raiders-flickering-flames-project/"],"version":"2.0"},"garlic_press":{"verdict":{"en":"Nothing needs it, so the choice is 1000 coins from a trader or 12 Metal Parts from recycling.","zh":"没有任何升级或任务需要它，卖 1000 钱币或回收得 12 个金属零件，二选一。"},"obtain":{"en":"Common residential and commercial clutter, found in kitchens, shops and shelves with no special container.","zh":"常见的居住区和商业区杂物，厨房、商店货架里都会有，没有特殊容器。"},"tips":[{"en":"Sell it if you need coins; its sell price is high for a 0.8 weight item. Recycle only when you are short on Metal Parts.","zh":"缺钱币就卖，它重量只有 0.8，卖价相当高；只有缺金属零件时才回收。"}],"sources":["https://arcraiders.wiki/wiki/Garlic_Press","https://beebom.com/arc-raiders-loot-cheat-sheet/"],"version":"2.0"},"geiger_counter":{"verdict":{"en":"Keep 3 for Trophy Display phase 5, then recycle extras for Exodus Modules or sell at 3500.","zh":"留 3 个给“战利品展示架”第 5 阶段，多余的回收换离巢模块，或卖 3500。"},"obtain":{"en":"Exodus loot, tied to Stella Montis: the Assembly workshops and server rooms are the usual farm, and Medical Research on the lower level has many containers. Rocket Assembly on The Spaceport is also reported.","zh":"属于离巢类战利品，主要在星辰山：组装厂车间和服务器室是常规刷点，下层医学研究部容器多。太空港的火箭组装区也有人遇到。"},"tips":[{"en":"Recycle it at home, not in the raid: only the home recycler returns the Exodus Module; salvaging gives 3 Batteries.","zh":"要回家回收：只有回收机才能拿到离巢模块，局内拆解只有 3 个电池。"}],"sources":["https://arcraiders.wiki/wiki/Geiger_Counter","https://metaforge.app/arc-raiders/where-to-find-geiger-counters-in-arc-raiders","https://allthings.how/geiger-counter-arc-raiders-guide-what-it-is-where-it-drops-and-why-it-matters/"],"version":"2.0"},"headphones":{"verdict":{"en":"Nothing live needs it: sell for 1,000 coins, or recycle for 7 Rubber Parts and a Speaker Component.","zh":"没有进行中的需求：卖 1000 钱币，或回收出 7 个橡胶零件和 1 个扬声器零件。"},"obtain":{"en":"General residential and commercial loot with no fixed spawn. Buried City is the usual pick because of its many residential containers. If you only need two, extract as soon as you have them.","zh":"居住区和商业区的普通战利品，没有固定刷新点。掩埋废城居住区容器多，最常被推荐。只需 2 个，拿到就撤。"},"tips":[{"en":"Recycling at home gives 7 Rubber Parts plus a Speaker Component; in-raid salvaging gives only the Speaker Component.","zh":"回基地回收可得 7 个橡胶零件和 1 个扬声器零件；局内拆解只有扬声器零件。"}],"sources":["https://arcraiders.wiki/wiki/Headphones","https://www.mmoexp.com/News/arc-raiders-headphones-guide-where-to-find-headphones-for-ascending-the-mountain.html","https://allthings.how/arc-raiders-ascending-the-mountain-project-guide-all-stages-and-rewards/"],"version":"2.0"},"household_cleaner":{"verdict":{"en":"Recycle it for 11 Chemicals; no upgrade needs it, and the 640 coin sale is poor value.","zh":"直接回收得 11 个化学品；没有升级需要它，卖 640 钱币不划算。"},"obtain":{"en":"Residential areas only, mostly under sinks and on shelves in apartment buildings.","zh":"只在居住区刷新，多见于公寓里的水槽下和货架。"},"tips":[{"en":"Only recycle when you actually need Chemicals; otherwise sell it and skip the weight.","zh":"缺化学品时才回收，否则卖掉省负重。"}],"sources":["https://arcraiders.wiki/wiki/Household_Cleaner","https://keengamer.com/articles/guides/arc-raiders-recycling-guide-what-to-loot-sell-and-recycle/"],"version":"2.0"},"humidifier":{"verdict":{"en":"Nothing live needs it: sell for 1,000 coins, or recycle for 2 Canisters and 2 Wires.","zh":"没有进行中的需求：卖 1000 钱币，或回收出 2 个小罐和 2 个导线。"},"obtain":{"en":"Guaranteed in the Red Tower lockers in Buried City, northeast of Plaza Rosa. Other Buried City options are Grandioso Apartments and the hospital cabinets; on Dam Battlegrounds try Pale Apartments, Ruby Residence and Pattern House.","zh":"掩埋废城玫瑰广场东北的红塔储物柜必出。掩埋废城还可去奢华公寓和医院柜子；大坝战场可去苍白公寓、红宝石宅邸和图案之家。"},"tips":[{"en":"It weighs 2 and is worth only a modest 1,000, so grab it only when there is room.","zh":"重量 2，只值 1000，背包有空位再拿。"}],"sources":["https://arcraiders.wiki/wiki/Humidifier","https://allthings.how/humidifier-location-in-arc-raiders-the-red-tower-lockers-route/","https://prodigygamers.com/2025/11/10/arc-raiders-humidifier-farming-location-guide-project-expedition/"],"version":"2.0"},"ice_cream_scooper":{"verdict":{"en":"Plain junk: 640 coins or 7 Metal Parts, and nothing in the workshop needs it.","zh":"普通杂物：卖 640 钱币或回收 7 个金属零件，工坊不需要它。"},"obtain":{"en":"Commercial areas only, so shops and food counters on any map.","zh":"只在商业区刷新，各地图的商店和餐饮柜台里都有。"},"tips":[{"en":"Recycle only when short on Metal Parts; the sell price is similar to other 640 coin junk.","zh":"缺金属零件才回收，卖价和其他 640 钱币的杂物差不多。"}],"sources":["https://arcraiders.wiki/wiki/Ice_Cream_Scooper","https://nerdschalk.com/arc-raiders-ice-cream-scooper-location-use-guide/"],"version":"2.0"},"industrial_battery":{"verdict":{"en":"Keep 3 for Gear Bench level 3 and 3 more for Taking Stock; spares recycle or sell.","zh":"留 3 个升级装备工作台 3 级，“清点物资”再要 3 个；多余的回收或卖掉。"},"obtain":{"en":"Dam Battlegrounds is best: Hydroponic Dome Complex lockers and shelves, and the Power Generation Complex. Industrial zones on Spaceport, The Blue Gate and Stella Montis also drop it, in rusty containers and red lockers.","zh":"大坝战场最好：水培穹顶综合体的储物柜和货架，以及发电厂综合体。太空港、蓝门和星辰山的工业区也会掉，在生锈容器和红色储物柜里。"},"tips":[{"en":"Surplus recycles into 7 Chemicals and 2 Batteries, so it is better to recycle than to salvage in the raid.","zh":"多余的回收可得 7 个化学品和 2 个电池，比局内拆解划算。"}],"sources":["https://arcraiders.wiki/wiki/Industrial_Battery","https://www.shacknews.com/article/147473/where-to-find-industrial-batteries-in-arc-raiders","https://nerdschalk.com/how-to-find-and-farm-industrial-batteries-in-arc-raiders/"],"version":"2.0"},"industrial_charger":{"verdict":{"en":"Nothing live needs it: sell for 1,000 coins, or recycle for a Voltage Converter and 5 Metal Parts.","zh":"没有进行中的需求：卖 1000 钱币，或回收出 1 个变电器和 5 个金属零件。"},"obtain":{"en":"Industrial and Electrical zones: toolboxes, lockers and power cases. Research and Administration, the Power Generation Complex and Loading Bay are the recommended Dam and Stella spots; Spaceport is another suggestion.","zh":"工业和电气区域：工具箱、储物柜和电源箱。推荐大坝战场的研究与行政楼、发电厂综合体，以及星辰山的装卸区；太空港也有人推荐。"},"tips":[{"en":"Recycling at home beats salvaging in a raid, which gives only the Voltage Converter, but the 1,000 sale is usually simpler.","zh":"回基地回收比局内拆解（只有变电器）多得金属零件，但直接卖 1000 通常更省事。"}],"sources":["https://arcraiders.wiki/wiki/Industrial_Charger","https://nerdschalk.com/arc-raiders-industrial-charger-location-use-guide/","https://www.destructoid.com/all-arc-raiders-expedition-3-project-requirements-and-how-to-complete-them/"],"version":"2.0"},"industrial_magnet":{"verdict":{"en":"No workshop or quest uses it, so recycle for 2 Magnets and 4 Metal Parts, or sell at 1000.","zh":"没有升级或任务需要，回收得 2 个磁铁和 4 个金属零件，或卖 1000。"},"obtain":{"en":"Industrial points of interest: Research and Administration, Loading Bay and Power Generation Complex on Dam Battlegrounds, Loading Bay on Stella Montis, and the Shipping Warehouse at Spaceport.","zh":"工业类地点：大坝战场的研究与行政楼、装卸区、发电厂综合体，星辰山的装卸区，以及太空港的货运仓库。"},"sources":["https://arcraiders.wiki/wiki/Industrial_Magnet","https://www.altchar.com/guides/arc-raiders-how-to-find-industrial-magnet-aU96l3b8bn4O"],"version":"2.0"},"insulation_roll":{"verdict":{"en":"A new 2.0 Pendola Pass item that sells for 3000; recycling only gives 2 Durable Cloth.","zh":"2.0 新增、彭多拉山口的物品，卖 3000；回收只得 2 个耐磨布料。"},"obtain":{"en":"Reported only on Pendola Pass, in any container but rarely: the Storm Hut market shelves, Railyard, Almatera Station and the Commissary Supermarket. The Observatory is busy. The Outpost's Room 4 reportedly needs three.","zh":"据报道只在彭多拉山口，任何容器都可能出但很少：风暴小屋的商铺货架、铁路站场、阿尔马特拉车站和商品超市。天文台人多。据称前哨站第 4 间房需要 3 个。"},"tips":[{"en":"Sell price beats recycling by a lot, but the Outpost room needs may change; check the upgrade screen before selling.","zh":"卖价远高于回收，但前哨站需求可能变，卖之前先看升级界面。"}],"sources":["https://arcraiders.wiki/wiki/Insulation_Roll","https://www.altchar.com/guides/arc-raiders-how-to-find-insulation-rolls-aHgLC7L9mucs","https://virtgold.com/blog/how-to-get-insulation-roll-in-arc-raiders-best-farming-locations"],"version":"2.0"},"ion_sputter":{"verdict":{"en":"Keep 1 for With a View; spares are worth 6,000 coins each.","zh":"留 1 个给“风景如画”，多余的每个值 6000 钱币。"},"obtain":{"en":"Exodus loot from Stella Montis. The Assembly area spawns the most, and Geiger Counters and Spectrum Analyzers appear in the same places.","zh":"离巢类战利品，来自星辰山。组装厂刷新最多，盖革计数器和频谱分析仪也在同一带。"},"tips":[{"en":"It cannot be made by recycling anything, so hold your 1 for the quest before selling spares.","zh":"没有任何回收途径能得到它，先留好任务要的 1 个再卖多余的。"}],"sources":["https://arcraiders.wiki/wiki/Ion_Sputter","https://www.shacknews.com/article/147890/where-to-find-magnetrons-in-arc-raiders","https://allthings.how/geiger-counter-arc-raiders-guide-what-it-is-where-it-drops-and-why-it-matters/"],"version":"2.0"},"laboratory_reagents":{"verdict":{"en":"Keep 3 for Explosives Station level 3, then recycle the extras for 16 Chemicals and 3 Crude Explosives.","zh":"留 3 个升级爆炸物工作台 3 级，多余的回收得 16 个化学品和 3 个粗制炸药。"},"obtain":{"en":"Medical zones only: cabinets, shelves and crates. The Pharmacy at Plaza Rosa in Buried City is the top pick; Testing Annex back storage on Dam Battlegrounds is calmer than the Hospital.","zh":"只在医疗区域：柜子、货架和箱子。掩埋废城玫瑰广场的药房最佳；大坝战场测试附楼的后部储藏室比医院安静。"},"sources":["https://arcraiders.wiki/wiki/Laboratory_Reagents","https://metaforge.app/arc-raiders/where-to-find-laboratory-reagents-arc-raiders","https://deltiasgaming.com/arc-raiders-how-to-find-laboratory-reagent"],"version":"2.0"},"magnetron":{"verdict":{"en":"Keep 1 for Snap and Salvage, then sell the rest for 6000; it is also a Line in the Sand reward.","zh":"留 1 个给“拍照并拆解回收”，其余卖 6000；它也是“沙滩防线”的奖励。"},"obtain":{"en":"Stella Montis Exodus loot, mostly Assembly and its workshops, though some players report Medical Research. Spawns are random, and shredders patrol the area.","zh":"星辰山的离巢类战利品，多在组装厂和车间，也有人在医学研究部遇到。刷新随机，附近有碎纸机类敌人巡逻。"},"tips":[{"en":"Recycling gives a Magnetic Accelerator and Steel Spring; check if you need them before taking 6000 coins.","zh":"回收得磁力加速器和钢质弹簧，先看是否需要，再决定是否换 6000 钱币。"}],"sources":["https://arcraiders.wiki/wiki/Magnetron","https://www.shacknews.com/article/147890/where-to-find-magnetrons-in-arc-raiders","https://gamesfuze.com/locations/arc-raiders-magnetron-geiger-counter-locations/"],"version":"2.0"},"metal_brackets":{"verdict":{"en":"Nothing live needs it: sell for 640 coins, or recycle for 8 Metal Parts.","zh":"没有进行中的需求：卖 640 钱币，或回收 8 个金属零件。"},"obtain":{"en":"Mechanical and Electrical areas, with no fixed container. Look in workshops, garages and utility rooms.","zh":"机械和电气区域，没有固定容器，车间、车库和设备间里都能翻到。"},"sources":["https://arcraiders.wiki/wiki/Metal_Brackets","https://nerdschalk.com/arc-raiders-metal-brackets-location-use-guide/"],"version":"2.0"},"microscope":{"verdict":{"en":"A 3000 coin item; recycle only if you want the Advanced Mechanical Components and Magnets.","zh":"值 3000 钱币；只有想要高级机械元件和磁铁时才回收。"},"obtain":{"en":"Exodus loot on Stella Montis, mostly in laboratory, research and medical areas such as Medical Research. No fixed container is documented.","zh":"星辰山的离巢类战利品，多在实验室、研究和医疗区域，如医学研究部。没有记录固定容器。"},"tips":[{"en":"Nothing in the workshop needs it, so choose coins or crafting parts based on what you are short of.","zh":"工坊不需要它，缺钱币还是缺制作材料，自己决定。"}],"sources":["https://arcraiders.wiki/wiki/Microscope","https://nerdschalk.com/arc-raiders-microscope-location-guide-where-to-find-it/"],"version":"2.0"},"mini_centrifuge":{"verdict":{"en":"A 3000 coin Stella Montis item; recycling gives Advanced Mechanical Components, which makes it worth keeping for crafting.","zh":"星辰山 3000 钱币的物品；回收得高级机械元件，适合留着做制作材料。"},"obtain":{"en":"Rare Exodus item found only on Stella Montis, mainly in lab and research zones. Market median can sit below the 3000 base value.","zh":"仅在星辰山出现的稀有离巢物品，多在实验和研究区域。市场成交中位价可能低于 3000。"},"tips":[{"en":"Sell it to a trader for the full 3000 if you want coins; the market may pay less.","zh":"想换钱币就卖给商人拿满 3000，玩家市场可能更低。"}],"sources":["https://arcraiders.wiki/wiki/Mini_Centrifuge","https://nerdschalk.com/how-to-get-mini-centrifuge-in-arc-raiders-location-farming-and-recycling-guide/","https://www.ofzenandcomputing.com/arc-raiders-mini-centrifuge-guide/"],"version":"2.0"},"mini_pump":{"verdict":{"en":"Keep 3 for Research Station level 1, then sell or recycle the rest.","zh":"留 3 个升级研究站 1 级，其余出售或回收。"},"obtain":{"en":"Electrical and Technological loot. Guides suggest Port Authority on Riven Tides, Cielo Sereno Observatory and the Seed Vault industrial areas on Pendola Pass, and the Power Generation Complex on Dam Battlegrounds.","zh":"电气和科技类战利品。推荐裂潮镇的港务局大楼、彭多拉山口的晴空天文台和种子库工业区，以及大坝战场的发电厂综合体。"},"tips":[{"en":"Pumps are often left lying on open surfaces, so scan desks and shelves before opening containers.","zh":"水泵常放在外面的台面上，先看桌面和货架，别急着开容器。"}],"sources":["https://arcraiders.wiki/wiki/Mini_Pump","https://www.izoate.com/blog/where-to-find-mini-pumps-in-arc-raiders-5-best-loot-spots/","https://fandomwire.com/where-to-find-mini-pump-sheet-metal-arc-raiders/"],"version":"2.0"},"motor":{"verdict":{"en":"Keep 3 for Refiner level 3, then recycle spares for Oil and Mechanical Components or sell at 2000.","zh":"留 3 个升级精加工机 3 级，多余的回收得油和机械元件，或卖 2000。"},"obtain":{"en":"Mostly from breaching cars and vehicle wrecks. Dam Battlegrounds Water Treatment, the Buried City highway and The Blue Gate checkpoint and tunnel are recommended; the checkpoint is fastest, the highway safer.","zh":"主要来自撬开汽车和车辆残骸。推荐大坝战场水处理厂、掩埋废城的公路，以及蓝门的检查站和隧道；检查站最快，公路更安全。"},"tips":[{"en":"Three motors fit in one run if you sweep a vehicle-heavy route.","zh":"沿车辆多的路线走，一局就能凑齐 3 个。"}],"sources":["https://arcraiders.wiki/wiki/Motor","https://nerdschalk.com/arc-raiders-motor-location-use-guide/","https://gladiatorboost.com/news/arc-raiders-best-locations-to-find-motors-for-the-refiner-level-3-upgrade/"],"version":"2.0"},"number_plate":{"verdict":{"en":"Worth 270 coins or 3 Metal Parts, so it is junk; drop it unless your inventory has space.","zh":"只值 270 钱币或 3 个金属零件，属于垃圾，背包有空位再带。"},"obtain":{"en":"Mechanical zones, mostly on vehicles and in garages.","zh":"机械区域，多见于车辆和车库。"},"sources":["https://arcraiders.wiki/wiki/Number_Plate","https://www.dexerto.com/wikis/arc-raiders/items/recyclable/number-plate/"],"version":"2.0"},"polluted_air_filter":{"verdict":{"en":"Nothing needs it: sell it for 1000 coins, or recycle it only if you are short on Fabric.","zh":"没有任何升级或任务需要它：直接卖1000钱币，缺布料时再拆解。"},"obtain":{"en":"Tagged Industrial loot, so check factory-style buildings and workshop containers. The wiki names no fixed spot; it is a random scavenge find.","zh":"属于工业类战利品，去厂房和车间类建筑的容器里翻。社区没有固定刷新点，纯随机。"},"tips":[{"en":"Recycling gives 6 Fabric and 2 Oil, while salvaging in raid gives only 2 Oil, so wait until you are back at the workshop to break it down.","zh":"拆解得6布料和2油，战局内分解只有2油，回营地再拆更划算。"}],"sources":["https://arcraiders.wiki/wiki/Polluted_Air_Filter"],"version":"2.0"},"portable_tv":{"verdict":{"en":"Keep 1 for Movie Night; any other is a 2,000-coin sell.","zh":"留 1 台给“电影之夜”，其余卖 2000 钱币。"},"obtain":{"en":"Residential loot with no fixed spawn. Buried City is the usual pick because of its many apartments (Grandioso Apartments is a popular stop, dressers especially). Stella Montis Cultural Archives crates and Dam Ruby Residence are also suggested.","zh":"住宅类战利品，没有固定刷新点。掩埋废城公寓多，最常被推荐（奢华公寓、梳妆台）；星辰山文化档案馆的木箱和大坝红宝石宅邸也有人去。"},"tips":[{"en":"Movie Night needs 1, so extract with it in your Safe Pocket to hand it in.","zh":"“电影之夜”要 1 台，记得放进安全口袋带出去交。"},{"en":"Recycling (2 Battery, 6 Wires) beats salvaging (4 Wires), but sell value is higher if you need coins.","zh":"拆解得2电池6导线，比分解的4导线多；缺钱的话直接卖更值。"}],"sources":["https://arcraiders.wiki/wiki/Portable_TV","https://www.destructoid.com/how-to-complete-movie-night-in-arc-raiders/","https://insider-gaming.com/movie-night-quest-in-arc-raiders-portable-tv-explained/"],"version":"2.0"},"power_bank":{"verdict":{"en":"Pure salvage: recycle it for Batteries or sell it for 1000; no upgrade or quest asks for it.","zh":"纯杂物：拆成电池或卖1000钱币，没有升级和任务需要。"},"obtain":{"en":"Electrical, Residential and Commercial loot; offices, shops and apartments all roll it. No fixed spawn.","zh":"电气、住宅、商业类战利品，办公室、商店、公寓都可能出。没有固定刷新点。"},"tips":[{"en":"Recycling returns 2 Battery and 2 Wires, salvaging in raid only 2 Battery.","zh":"拆解得2电池和2导线，战局内分解只有2电池。"}],"sources":["https://arcraiders.wiki/wiki/Power_Bank"],"version":"2.0"},"power_cable":{"verdict":{"en":"Keep 3 for the Gear Bench level 2 upgrade, then recycle or sell the rest.","zh":"留3根给装备工作台2级升级，多余的拆解或卖掉。"},"obtain":{"en":"Electrical, Commercial and Residential loot; it cannot be crafted. Guides rate the Spaceport Departure Building (stacked computer rooms) and Dam's Power Generation Complex and Field Depot (drawers, desks, lockers) highly. A Path Not Yours also rewards 2.","zh":"电气、商业、住宅类战利品，无法制作。太空港候机楼（多层机房）和大坝发电厂综合体、前线仓库（抽屉、桌子、储物柜）评价最高。完成“非你之路”也奖励2根。"},"tips":[{"en":"Gear Bench 2 also wants 5 Electrical Components and 5 Hornet Drivers, so collect those in the same runs.","zh":"装备工作台2级还要5个电子元件和5个“马蜂”引擎，可以同一趟一起凑。"},{"en":"Spare cables recycle into 4 Wires, one more than salvaging.","zh":"多余的拆解得4导线，比分解多1个。"}],"sources":["https://arcraiders.wiki/wiki/Power_Cable","https://allthings.how/arc-raiders-power-cables-where-to-find-them-and-how-to-use-them/","https://nerdschalk.com/arc-raiders-power-cables-location-and-usage-guide/"],"version":"2.0"},"projector":{"verdict":{"en":"No upgrade or quest uses it: recycle for a Processor, or sell for 1000.","zh":"没有升级或任务需要：拆出处理器，或直接卖1000钱币。"},"obtain":{"en":"Residential loot only, so apartment blocks and homes. No named spawn point on the wiki.","zh":"只出在住宅类区域，公寓和民宅里找。社区没有固定刷新点。"},"tips":[{"en":"Recycling gives 1 Processor and 2 Wires; salvaging gives just the Processor. Processors are the useful part.","zh":"拆解得1处理器和2导线，分解只有处理器，处理器才是重点。"}],"sources":["https://arcraiders.wiki/wiki/Projector"],"version":"2.0"},"radio":{"verdict":{"en":"Nothing live needs it: sell for 1,000 coins, or recycle for a Sensors and a Speaker Component.","zh":"没有进行中的需求：卖 1000 钱币，或回收出传感器和扬声器零件各 1 个。"},"obtain":{"en":"Commercial and Residential loot: shops, offices and apartments. Electronics-heavy buildings such as Buried City's Space Travel are suggested for electronics in general.","zh":"商业和住宅类战利品，商店、办公室、公寓里找。电子设备多的建筑（如掩埋废城航天大楼）也值得一搜。"},"tips":[{"en":"Recycling at home returns a Sensors and a Speaker Component; salvaging in raid gives only the Speaker Component.","zh":"回基地回收得传感器和扬声器零件各 1 个；局内拆解只有扬声器零件。"}],"sources":["https://arcraiders.wiki/wiki/Radio","https://www.ezg.com/blog/arc-raiders-expedition-5-complete-preparation-materials-rewards-and-damage-challenge","https://xboxplay.games/arc-raiders/where-to-find-speaker-components-in-arc-raiders-68639"],"version":"2.0"},"remote_control":{"verdict":{"en":"Recycle it for 7 Plastic Parts and a Sensor, or sell for 1000; nothing needs it.","zh":"拆成7个塑料零件和1个传感器，或卖1000钱币，没有任何需求。"},"obtain":{"en":"Residential loot, so living rooms and apartments. No fixed spawn on the wiki.","zh":"住宅类战利品，在客厅和公寓里找。社区没有固定刷新点。"},"tips":[{"en":"Light at 0.8 weight, so it is cheap to carry. Salvaging in raid only gives 1 Sensors, so recycle at the workshop.","zh":"重量仅0.8，带着不占负担。战局内分解只有1传感器，回营地拆解更划算。"}],"sources":["https://arcraiders.wiki/wiki/Remote_Control"],"version":"2.0"},"ripped_safety_vest":{"verdict":{"en":"Low-value junk: sell it, or salvage it in raid for 8 Fabric if you need cloth.","zh":"低价值杂物：卖掉；缺布料时战局内分解可得8布料。"},"obtain":{"en":"The wiki tags it Industrial but names no spawn point. Treat it as a random find in factory-style areas.","zh":"社区标注为工业类，没有具体刷新点，当作工业区域的随机掉落即可。"},"tips":[{"en":"Unusual item: salvaging (8 Fabric) returns far more than recycling (1 Durable Cloth, 1 Magnet). Choose by what you need.","zh":"这件反常：分解得8布料，比拆解（1耐磨布料、1磁铁）多得多，按需选择。"}],"sources":["https://arcraiders.wiki/wiki/Ripped_Safety_Vest"],"version":"2.0"},"rocket_thruster":{"verdict":{"en":"Nothing live needs it: it is a good 2,000-coin sell.","zh":"没有进行中的需求：值 2000 钱币，直接卖。"},"obtain":{"en":"Exodus loot. The Spaceport's Rocket Assembly is the best-rated spot (breachable panels on the thruster sections, the big rack by the loading dock). Stella Montis also works (thruster panels, luggage rack by the Lobby to Atrium battery door), and Riven Tides' Port Authority is listed.","zh":"出在“出埃及”类区域。太空港火箭组装区评价最高（推进器部位的可破拆面板、装卸口旁的大货架）；星辰山（推进器面板、大厅通往中庭电池门旁的行李架）和裂潮镇港务局也有。"},"tips":[{"en":"Recycling gives 6 Metal Parts and 2 Synthesized Fuel, double the fuel of salvaging, but the sale pays more.","zh":"回收得 6 个金属零件和 2 个合成燃料，燃料比局内拆解多一倍，但卖掉更赚。"},{"en":"Recycling gives 6 Metal Parts and 2 Synthesized Fuel, double the fuel of salvaging.","zh":"拆解得6金属零件和2合成燃料，燃料比分解多一倍。"}],"sources":["https://arcraiders.wiki/wiki/Rocket_Thruster","https://www.altchar.com/guides/arc-raiders-how-to-find-rocket-thrusters-asQsv7f2uFML","https://allthings.how/arc-raiders-ascending-the-mountain-project-guide-all-stages-and-rewards/"],"version":"2.0"},"rotary_encoder":{"verdict":{"en":"Keep one for the With a View quest, then it is a 3000-coin sell or a Processor recycle.","zh":"留1个做“风景如画”，之后卖3000钱币或拆处理器。"},"obtain":{"en":"Stella Montis only, as random container loot. The Assembly Workshops are the usual safest pick; the Medical area, Business Center and Lobby security office are also named. It does not drop from enemies and cannot be bought.","zh":"只在星辰山的容器里随机刷新。组装厂车间通常最安全，医疗区、商务中心和大厅安保室也被提到。敌人不掉落，也买不到。"},"tips":[{"en":"Put it in your Safe Pocket as soon as you find it; the quest needs it at an Assembly control room, and a friend can hand it to you.","zh":"拿到后立刻放进安全口袋；任务要在组装区控制室使用，队友也可以转交。"},{"en":"The quest also needs an Ion Sputter from an Exodus-type spot, so plan both.","zh":"这个任务还需要一个离子溅射仪，需到“出埃及”类区域找，一并规划。"}],"sources":["https://arcraiders.wiki/wiki/Rotary_Encoder","https://insider-gaming.com/how-to-complete-with-a-view-quest-in-arc-raiders-ion-sputter-rotary-encoder-explained/","https://nerdschalk.com/where-to-find-rotary-encoder-in-arc-raiders-location-and-how-to-use-it/"],"version":"2.0"},"rubber_pad":{"verdict":{"en":"Recycle it only if you need Rubber Parts (18 per pad); otherwise sell for 1000.","zh":"只有缺橡胶零件时才拆（每块18个），否则卖1000钱币。"},"obtain":{"en":"Electrical loot, found around machinery and power facilities. No named spawn on the wiki.","zh":"电气类战利品，机械和供电设施周围。社区没有固定刷新点。"},"tips":[{"en":"Salvaging in raid gives 12 Rubber Parts, recycling 18. At 2.0 weight, do not haul several out unless you are crafting.","zh":"战局内分解12个橡胶零件，拆解18个。重量2.0，不做制作就别带多块。"}],"sources":["https://arcraiders.wiki/wiki/Rubber_Pad"],"version":"2.0"},"ruined_accordion":{"verdict":{"en":"A bulky 2000-coin sell; recycle only if you want lots of Rubber Parts.","zh":"体积大的2000钱币卖品；要大量橡胶零件才拆。"},"obtain":{"en":"Residential loot: homes and apartments. No specific spawn point is documented.","zh":"住宅类战利品，民宅和公寓里。没有具体刷新点记录。"},"tips":[{"en":"Recycling gives 18 Rubber Parts and 3 Steel Spring. At weight 3, free the slot if it is not worth the coins.","zh":"拆解得18橡胶零件和3钢质弹簧。重量3，不值得就别占格子。"}],"sources":["https://arcraiders.wiki/wiki/Ruined_Accordion"],"version":"2.0"},"ruined_baton":{"verdict":{"en":"Cheap junk: recycle for Metal Parts, or sell for 640.","zh":"廉价杂物：拆成金属零件，或卖640钱币。"},"obtain":{"en":"Security loot: checkpoints, guard rooms and police-style areas. No fixed spot documented.","zh":"安保类战利品，检查站、警卫室一类地点。没有固定刷新点记录。"},"tips":[{"en":"Recycling returns 6 Metal Parts and 3 Rubber Parts, more than the 4 Metal Parts from salvaging.","zh":"拆解得6金属零件和3橡胶零件，比分解的4金属零件多。"}],"sources":["https://arcraiders.wiki/wiki/Ruined_Baton"],"version":"2.0"},"ruined_emperor_beacon":{"verdict":{"en":"A 1000-coin sell: it cannot be recycled or used for anything.","zh":"只能卖1000钱币，既不能拆解也没有用途。"},"obtain":{"en":"Not found in containers: an unused Emperor Beacon turns into this when you extract with it. Use the beacon in the same run (on Pendola Pass during Redirection) or you only get this.","zh":"不会在容器里刷出：带着未使用的“帝王”信标撤离时会变成它。想要正经收益，就在本局用掉信标（航向重定向期间的彭多拉山口）。"},"tips":[{"en":"Stacks to 8 at 0.5 weight, so selling a batch is easy.","zh":"可堆叠8个，重量0.5，攒一批再卖很方便。"}],"sources":["https://arcraiders.wiki/wiki/Ruined_Emperor_Beacon","https://powerupgaming.co.uk/2026/10/09/arc-raiders-emperor-modulator-best-farming-locations/","https://metaforge.app/arc-raiders/arc-raiders-redirection-map-condition-guide-emperor-relays-beacons-and-payload-loot"],"version":"2.0"},"ruined_handcuffs":{"verdict":{"en":"Cheap junk: recycle for 8 Metal Parts, or sell for 640.","zh":"廉价杂物：拆成8个金属零件，或卖640钱币。"},"obtain":{"en":"Security loot such as checkpoints and guard posts. No fixed spawn documented.","zh":"安保类战利品，检查站和警卫岗一类。没有固定刷新点记录。"},"tips":[{"en":"Salvaging in raid gives only 4 Metal Parts; recycle at the workshop for double.","zh":"战局内分解只有4金属零件，回营地拆解翻倍。"}],"sources":["https://arcraiders.wiki/wiki/Ruined_Handcuffs"],"version":"2.0"},"ruined_parachute":{"verdict":{"en":"Nothing live needs it: sell for 640 coins, or recycle for 10 Fabric.","zh":"没有进行中的需求：卖 640 钱币，或回收 10 个布料。"},"obtain":{"en":"Exodus loot, so look where other Exodus items spawn, such as the Spaceport's Rocket Assembly or Stella Montis. No parachute-specific spot is documented.","zh":"出在“出埃及”类区域，去其他同类物品刷新的地方找，如太空港火箭组装区或星辰山。没有降落伞专属刷新点的记录。"},"tips":[{"en":"Recycling at home returns 10 Fabric against 5 from salvaging in a raid.","zh":"回基地回收得 10 个布料，局内拆解只有 5 个。"},{"en":"Recycling returns 10 Fabric against 5 from salvaging.","zh":"拆解得10布料，分解只有5。"}],"sources":["https://arcraiders.wiki/wiki/Ruined_Parachute","https://allthings.how/arc-raiders-ascending-the-mountain-project-guide-all-stages-and-rewards/"],"version":"2.0"},"ruined_riot_shield":{"verdict":{"en":"Recycle for Plastic and Rubber Parts if you craft; otherwise a plain 1000-coin sell.","zh":"做制作才拆塑料和橡胶零件；否则直接卖1000钱币。"},"obtain":{"en":"Security loot: guard rooms and checkpoints. No fixed spawn on the wiki.","zh":"安保类战利品，警卫室和检查站。社区没有固定刷新点。"},"tips":[{"en":"Recycling adds 6 Rubber Parts on top of the 10 Plastic Parts that salvaging gives.","zh":"拆解比分解多出6个橡胶零件，塑料零件两者都是10个。"}],"sources":["https://arcraiders.wiki/wiki/Ruined_Riot_Shield"],"version":"2.0"},"ruined_tactical_vest":{"verdict":{"en":"Cheap junk: sell for 640, or recycle if you want Fabric and a Magnet.","zh":"廉价杂物：卖640钱币，需要布料和磁铁时再拆。"},"obtain":{"en":"Security loot such as guard rooms and checkpoints. No named spawn point.","zh":"安保类战利品，警卫室和检查站等。没有具体刷新点。"},"tips":[{"en":"Recycling is the only way to get the Magnet; salvaging yields Fabric alone.","zh":"想要磁铁只能拆解；分解只得布料。"}],"sources":["https://arcraiders.wiki/wiki/Ruined_Tactical_Vest"],"version":"2.0"},"rusted_bolts":{"verdict":{"en":"Keep 3 for Trophy Display phase 1; recycle or sell the rest.","zh":"留 3 个给战利品展示架第 1 阶段，其余回收或卖掉。"},"obtain":{"en":"Industrial and Mechanical loot: cabinets, shipping container drawers and lockers rather than open shelves. Stella Montis' Assembly Workshops and Loading Bay are the most recommended farm.","zh":"工业和机械类战利品，常在柜子、集装箱抽屉和储物柜里，而不是开放货架。星辰山的组装厂车间和装卸区最常被推荐。"},"tips":[{"en":"Recycling gives 8 Metal Parts, salvaging 4, so only break down extras.","zh":"拆解8金属零件，分解4个，多余的才拆。"}],"sources":["https://arcraiders.wiki/wiki/Rusted_Bolts","https://www.gfinityesports.com/article/where-to-find-rusted-bolts-in-arc-raiders","https://www.shacknews.com/article/147654/trophy-display-project-items-arc-raiders"],"version":"2.0"},"rusted_gear":{"verdict":{"en":"Keep 3 for the Gunsmith level 3 upgrade, then it is a 2000-coin sell.","zh":"留3个给武器工作台3级升级，之后卖2000钱币。"},"obtain":{"en":"Spawns on most maps in car hoods, bus rear trunks and panels, car tool cabinets, control panels, metal crates, generators and industrial drawers. Blue Gate (Checkpoint, Warehouse), Dam (Scrap Yard, Water Treatment Control), Spaceport (Rocket Assembly, Vehicle Maintenance) and Buried City (Parking Garage, Warehouse) are listed. Divided also rewards 1.","zh":"多数地图都有：汽车引擎盖、大巴后备箱和面板、汽车工具柜、控制面板、金属箱、发电机、工业抽屉。蓝门（检查站、仓库）、大坝（废料场、水处理控制室）、太空港（火箭组装区、车辆维护区）、掩埋废城（停车场、仓库）。完成“分歧”也奖励1个。"},"tips":[{"en":"Blue Gate has the most cars and buses but is busy; bring fast exits and a Safe Pocket item so a knockout does not cost you the gear.","zh":"蓝门车多大巴多但人也多；带好快速脱身手段，并用安全口袋保住它。"},{"en":"Gunsmith 3 also needs 5 Advanced Mechanical Components and 4 Sentinel Firing Cores.","zh":"武器工作台3级还要5个高级机械元件和4个“哨卫”发射核心。"}],"sources":["https://arcraiders.wiki/wiki/Rusted_Gear"],"version":"2.0"},"rusted_shut_medical_kit":{"verdict":{"en":"Keep 3 for the Medical Lab level 3 upgrade, and don't recycle early; afterwards it is a 2000-coin sell.","zh":"留3个给医疗实验室3级升级，别提前拆；之后卖2000钱币。"},"obtain":{"en":"Medical loot (cabinets, shelves, medical boxes). Dam's Testing Annex is the best-supported farm, Buried City's Hospital is the other pick but is often contested and looted early. Expect the odd hostile inside.","zh":"医疗类战利品（药柜、货架、医药箱）。大坝测试附楼最被推荐，掩埋废城医院是另一选择，但常有人抢，容易被早早搜空。里面偶尔会有敌人。"},"tips":[{"en":"Medical Lab 3 also needs 8 Antiseptic and 5 ARC Surveyor Vaults; Antiseptic tends to be found in the same places.","zh":"医疗实验室 3 级还要 8 个防腐剂和 5 个ARC勘测师保险库，防腐剂通常在同一批地点能找到。"},{"en":"After the upgrade, recycling gives 2 Syringe plus 1 Antiseptic; salvaging gives only the Syringes.","zh":"升级后拆解得2注射器加1防腐剂，分解只有注射器。"}],"sources":["https://arcraiders.wiki/wiki/Rusted_Shut_Medical_Kit","https://allthings.how/rusted-shut-medical-kit-farming-routes-for-arc-raiders/","https://patchcrazy.co.uk/how-to-unlock-medical-lab-3-rusted-shut-medical-kit-antiseptic-surveyor-vault-location-arc-raiders/"],"version":"2.0"},"rusted_tools":{"verdict":{"en":"Keep 3 for the Gunsmith level 2 upgrade; after that it is just a heavy 1,000-coin sell.","zh":"留3个升武器工作台2级，之后当1000金币的卖品即可。"},"obtain":{"en":"Rolls in Mechanical loot on every map. Dam Battlegrounds is best documented: Power Generation Complex, Scrap Yard cars, and the lockers in the Field Depot and the building next to it. Bus trunks and Metal Crates also drop it.","zh":"各地图的机械类战利品里都有。大坝战场最稳：发电厂综合体、废料场的车辆，以及前线仓库和旁边建筑的储物柜；公交车后备箱和金属箱也会出。"},"tips":[{"en":"It is Rare and the drop rate is low, so start collecting before you are ready to upgrade.","zh":"掉率不高，别等到要升级才开始攒。"},{"en":"Recycling gives 8 Metal Parts and a Steel Spring, which is worth less than the 1,000 sell price unless you are short on Metal Parts.","zh":"回收只得8个金属零件和1个钢质弹簧，除非缺金属零件，否则不如直接卖1000金币。"}],"sources":["https://arcraiders.wiki/wiki/Rusted_Tools","https://www.destructoid.com/how-to-find-and-use-rusted-tools-in-arc-raiders/"],"version":"2.0"},"sample_cleaner":{"verdict":{"en":"A 3,000-coin lab trinket; sell it, or recycle it only if you want Electrical Components or seeds.","zh":"3000金币的实验室杂物，直接卖；缺电子元件或种子时再回收。"},"obtain":{"en":"Scavenged only, no fixed spawn. The community wiki lists Stella Montis; guides say to sweep indoor lab, medical and workshop rooms, checking tables and shelves.","zh":"只能搜刮，没有固定刷新点。社区维基记在星辰山；攻略建议扫室内的实验室、医疗和车间，翻桌面和货架。"},"tips":[{"en":"Recycling yields 14 Assorted Seeds and 2 Electrical Components. In a raid, salvaging gives only seeds, so recycle at the workshop instead.","zh":"回收得14个混合种子和2个电子元件；局内拆解只有种子，回基地再回收更划算。"}],"sources":["https://arcraiders.wiki/wiki/Sample_Cleaner","https://nerdschalk.com/arc-raiders-sample-cleaner-location-guide-where-to-find-it/"],"version":"2.0"},"signal_amplifier":{"verdict":{"en":"Pure sell-or-recycle loot: 3,000 coins, nothing in the workshop needs it.","zh":"纯卖或回收的战利品，3000金币，工作台和任务都不需要。"},"obtain":{"en":"Stella Montis, Exodus-tagged loot. Guides point to Medical Research, the Assembly Workshop, Sandbox and Seed Vault, and the red lockers in the small server room beside the Auditorium and Business Lounge.","zh":"星辰山的离巢类战利品。攻略推荐医学研究部、组装厂车间、机器人沙盘和种子库，以及礼堂与商务休息室旁小服务器间的红色储物柜。"},"tips":[{"en":"Recycling gives 2 Electrical Components and 2 Voltage Converter; sell it if you only want coins.","zh":"回收得2个电子元件和2个变电器；只要钱就直接卖。"}],"sources":["https://arcraiders.wiki/wiki/Signal_Amplifier","https://nerdschalk.com/arc-raiders-signal-amplifier-location-guide-where-to-find-it/"],"version":"2.0"},"spectrometer":{"verdict":{"en":"Sell it for 3,000, or recycle for Advanced Electrical Components when you need them.","zh":"卖3000金币；需要高级电子元件时再回收。"},"obtain":{"en":"Stella Montis scavenging, in the same Exodus-tagged tech rooms as the Spectrum Analyzer: Medical Research, Assembly and Sandbox. No fixed container.","zh":"星辰山搜刮，与频谱分析仪同属离巢类科技房间：医学研究部、组装厂和机器人沙盘，没有固定容器。"},"tips":[{"en":"Recycling returns 1 Advanced Electrical Components and 1 Sensors, better than salvaging in a raid (2 Electrical Components).","zh":"回收得1个高级电子元件和1个传感器，比局内拆解（2个电子元件）更好。"}],"sources":["https://arcraiders.wiki/wiki/Spectrometer","https://nerdschalk.com/arc-raiders-spectrum-analyzer-location-use-guide/"],"version":"2.0"},"spectrum_analyzer":{"verdict":{"en":"Epic and worth 3,500, but recycle it if you need Exodus Modules.","zh":"史诗品质卖3500，但缺离巢模块时应回收。"},"obtain":{"en":"Stella Montis only, scavenged. Players report Medical Research, Assembly, Lobby Metro and Sandbox; try shelves, lockers and equipment piles in labs and server rooms near the Auditorium.","zh":"仅星辰山，靠搜刮。玩家常在医学研究部、组装厂、大厅地铁站和机器人沙盘找到；实验室和礼堂附近服务器间的货架、储物柜值得翻。"},"tips":[{"en":"Recycling gives 1 Exodus Modules and 1 Sensors. Salvaging in a raid gives 2 Processors, handy if you need those mid-run.","zh":"回收得1个离巢模块和1个传感器；局内拆解得2个处理器。"}],"sources":["https://arcraiders.wiki/wiki/Spectrum_Analyzer","https://nerdschalk.com/arc-raiders-spectrum-analyzer-location-use-guide/","https://metaforge.app/arc-raiders/where-to-find-exodus-modules-in-arc-raiders"],"version":"2.0"},"spring_cushion":{"verdict":{"en":"Sell it for 2,000; the recycle output is not worth more.","zh":"卖2000金币，回收产出不比这值钱。"},"obtain":{"en":"Found in Residential and Commercial areas. The wiki gives no specific container, so loot apartments and shops.","zh":"出现在住宅和商业区域，维基未给具体容器，多搜公寓和商店。"},"tips":[{"en":"Recycling returns 2 Durable Cloth and 2 Steel Spring. Nothing in the workshop or projects uses it.","zh":"回收得2个耐磨布料和2个钢质弹簧；工作台和项目都不需要它。"}],"sources":["https://arcraiders.wiki/wiki/Spring_Cushion","https://wzstats.gg/arc-raiders/wiki/items/materials/spring-cushion"],"version":"2.0"},"steel_cable":{"verdict":{"en":"A 2.0 crafting part: keep a few for gadget blueprints and the Tether Launcher, otherwise it barely sells.","zh":"2.0新增的制作材料：留几根给装置蓝图和系索发射器，卖不了几个钱。"},"use":{"en":"Steel Cable feeds the Yank Grenade Blueprint (8 cables, Research Station 1), the Tether Launcher Blueprint and craft, and the Zipline. Unlock the blueprints first, then spend cables on crafting.","zh":"钢缆用于系索弹蓝图（研究站1级，需8根）、系索发射器蓝图及其制作，还有滑索。先解锁蓝图，再拿钢缆制作。"},"obtain":{"en":"Scavenged with no named spawn on the community wiki. Celeste sells it for 20 Assorted Seeds each, limit 5, which is the reliable route.","zh":"社区维基未列出具体刷新点。塞莱斯特用20个混合种子出售一根，限购5根，这是稳定来源。"},"tips":[{"en":"At 270 coins it is not worth selling or recycling for 1 Wires.","zh":"只值270金币，回收也只得1个导线，不值得卖或拆。"}],"sources":["https://arcraiders.wiki/wiki/Steel_Cable","https://arcraiders.wiki/wiki/Tether_Launcher","https://arcraiders.wiki/wiki/Yank_Grenade"],"version":"2.0"},"tattered_clothes":{"verdict":{"en":"Low-value fabric filler; sell it for 640, or recycle it for Fabric if you need healing supplies.","zh":"低价值的布料来源，卖640金币；需要布料时再回收。"},"obtain":{"en":"Found in Residential areas by scavenging; the wiki lists no specific container.","zh":"在住宅区域搜刮获得，维基未列具体容器。"},"tips":[{"en":"Recycling gives 11 Fabric, but guides put Fabric near 50 coins each, so selling is usually equal or better.","zh":"回收得11个布料，但攻略里布料单价约50金币，卖通常更好或持平。"}],"sources":["https://arcraiders.wiki/wiki/Tattered_Clothes","https://www.dexerto.com/wikis/arc-raiders/items/recyclable/tattered-clothes/"],"version":"2.0"},"telemetry_transceiver":{"verdict":{"en":"Recycle it for Advanced Electrical Components and a Processor; sell only when you are cash-poor.","zh":"回收取高级电子元件和处理器，缺钱时才卖3000。"},"obtain":{"en":"Stella Montis. Guides rate the Workshops (white and blue crates, north rooms), the Assembly Workshop, Medblock and the Lobby east stairs. Lobby and Assembly are busy PvP zones.","zh":"星辰山。攻略推荐车间（北侧房间的白色和蓝色箱子）、组装厂车间、医疗区和大厅东侧楼梯；大厅和组装厂PvP很多。"},"tips":[{"en":"Advanced Electrical Components are needed for Raider Hatch Keys, and Processors for Trigger Grenades, so the parts beat the sell price.","zh":"高级电子元件用于造奇袭者暗门钥匙，处理器用于造触发手雷，拆件通常比卖划算。"}],"sources":["https://arcraiders.wiki/wiki/Telemetry_Transceiver","https://rutab.net/b/games/2026/01/12/luchshie-mesta-dlya-farma-telemetricheskih-peredatchikov-v-arc-raiders.html"],"version":"2.0"},"thermal_shaker":{"verdict":{"en":"Keep 3 for the Research Station level 4 upgrade; they are scarce, so do not recycle.","zh":"留3个升研究站4级，数量稀少，别拿去回收。"},"obtain":{"en":"New in 2.0. Best reported spot is the Observatory on Pendola Pass (kitchen, tables, storage lockers), close to an extract, but only about one per visit. It can also drop in other Technological and Electrical containers.","zh":"2.0新物品。目前最推荐彭多拉山口的天文台（厨房、桌椅、储物间柜子），离撤离点近，但每趟通常只有一个；其他科技和电气类容器也可能出。"},"tips":[{"en":"The upgrade also needs 3 ARC Data Modules and a Frigate Inductor, so start the Shaker hunt early.","zh":"该升级还需要3个ARC数据模块和1个护卫者感应器，所以要早点开始凑摇铃（恒温振荡仪）。"}],"sources":["https://arcraiders.wiki/wiki/Thermal_Shaker","https://metaforge.app/arc-raiders/where-to-find-the-thermal-shaker-in-arc-raiders","https://ingamenews.com/gaming-news/arc-raiders-how-to-locate-thermal-shakers-in-the-frozen-trail-update/"],"version":"2.0"},"thermostat":{"verdict":{"en":"Sell it for 1,000; recycling gives rubber and a sensor worth less.","zh":"卖1000金币，回收的橡胶和传感器价值更低。"},"obtain":{"en":"Residential areas, by scavenging; no specific container is documented.","zh":"住宅区域搜刮获得，没有记录具体容器。"},"tips":[{"en":"MetaForge shows a recycle value below the sell price. Recycle only if you want the 7 Rubber Parts or the Sensors.","zh":"第三方数据站显示回收价值低于卖价；只有想要7个橡胶零件或传感器时才回收。"}],"sources":["https://arcraiders.wiki/wiki/Thermostat","https://metaforge.app/arc-raiders/database/item/thermostat"],"version":"2.0"},"toaster":{"verdict":{"en":"Keep 3 for the Refiner level 2 upgrade, then sell the rest.","zh":"留3个升精加工机2级，其余卖掉。"},"obtain":{"en":"Residential interiors. Destructoid rates the Spaceport Departure and Arrival buildings best (tables upstairs), others cite Blue Gate's village and Dam's Pale Apartments, Ruby Residence and Pattern House. Reports disagree on whether it sits in cabinets or lies loose.","zh":"住宅内部。太空港的候机楼和到达楼最被看好（楼上桌面），也有人提蓝门村落，以及大坝的苍白公寓、红宝石宅邸和壁画屋。关于是否在柜子里，各来源说法不一。"},"tips":[{"en":"The upgrade also needs ARC Motion Cores and Fireball Burners from ARC, so gather Toasters on the way.","zh":"升级还需要ARC掉落的运动核心和火球燃烧器，可顺路收集烤面包机。"}],"sources":["https://arcraiders.wiki/wiki/Toaster","https://www.destructoid.com/how-to-get-toaster-in-arc-raiders/","https://nerdschalk.com/arc-raiders-toaster-location-use-guide/"],"version":"2.0"},"torn_blanket":{"verdict":{"en":"Low-value fabric; sell it for 640 unless you want 12 Fabric.","zh":"低价值布料，卖640金币，除非你要12个布料。"},"obtain":{"en":"Residential and Medical areas, by scavenging. The wiki lists no specific container.","zh":"住宅和医疗区域搜刮获得，维基未列具体容器。"},"tips":[{"en":"Recycling returns 12 Fabric versus 5 from in-raid salvage, so recycle at the workshop if you do.","zh":"回收得12个布料，局内拆解只有5个，要拆就回基地回收。"}],"sources":["https://arcraiders.wiki/wiki/Torn_Blanket","https://www.dexerto.com/wikis/arc-raiders/items/recyclable/torn-blanket/"],"version":"2.0"},"turbo_pump":{"verdict":{"en":"Heavy and only worth 2,000; sell it or recycle for Oil and a Mechanical Component.","zh":"又重又只值2000，卖掉，或回收取机油和机械元件。"},"obtain":{"en":"Exodus-tagged. One 2026 guide names Dam's Hydroponic Dome Complex and Water Treatment Control, Spaceport's Vehicle Maintenance and Container Storage, and Stella Montis assembly workshops. Treat these as a single source.","zh":"离巢类。有攻略提到大坝的水培穹顶综合体和水处理控制中心、太空港的载具维护区和集装箱仓库，以及星辰山组装厂车间；仅为单一来源。"},"tips":[{"en":"At 3 weight it eats space fast. Salvaging in a raid gives 3 Steel Spring, but nothing needs the pump itself.","zh":"重量3，很占背包。局内拆解得3个钢质弹簧，但没有任何升级或任务需要它。"}],"sources":["https://arcraiders.wiki/wiki/Turbo_Pump","https://rutab.net/b/games/2026/01/09/luchshie-mesta-dlya-farma-turbo-pumps-v-arc-raiders.html"],"version":"2.0"},"unusable_weapon":{"verdict":{"en":"Recycle it for 5 Simple Gun Parts if you craft, otherwise sell for 2,000.","zh":"要造东西就回收取5个简易枪械零件，否则卖2000。"},"obtain":{"en":"Listed under Security containers; the sources do not name maps or areas, and Security containers need the Security Breach skill to open.","zh":"记在安保类容器下，来源没写具体地图或区域；安保容器需要解锁“安保破拆”技能才能打开。"},"tips":[{"en":"Also needed for the Tether Launcher Blueprint (1 piece plus cables). Otherwise 2,000 coins beats the recycle output unless you lack Simple Gun Parts.","zh":"系索发射器蓝图需要1个。其他情况下2000金币高于回收产出，除非你缺简易枪械零件。"}],"sources":["https://arcraiders.wiki/wiki/Unusable_Weapon","https://www.dexerto.com/wikis/arc-raiders/items/recyclable/unusable-weapon/","https://arcraiders.wiki/wiki/Steel_Cable"],"version":"2.0"},"vaporizer_regulator":{"verdict":{"en":"Keep 2 for the Dolabra; any extras sell for 6,000 each.","zh":"留2个做“錾斧”，多余的每个可卖6000钱币。"},"use":{"en":"Two go into the Dolabra at Gunsmith 3. No live project asks for it, so anything beyond those 2 is better sold or recycled into ARC Circuitry and Advanced Electrical Components.","zh":"“錾斧”在武器工作台3级需要2个。目前没有进行中的项目要它，多出来的卖掉，或回收成ARC线圈和高级电子元件。"},"obtain":{"en":"Kill a Vaporizer, which appears only in the Close Scrutiny map condition around the Assessor probe. Beebom says the Regulator is guaranteed. ARC Couriers rarely carry one.","zh":"击杀“汽化者”，它只在“严密排查”地图条件下出现，守在评估探针旁。有攻略称调节器必掉；ARC运输机偶尔也带。"},"tips":[{"en":"Vaporizers have an energy shield that blocks thrown grenades, so bring a full loadout and look at the Close Scrutiny probe location first.","zh":"“汽化者”的能量护盾能挡投掷物，装备要带足，先看“严密排查”探针位置。"}],"sources":["https://arcraiders.wiki/wiki/Vaporizer_Regulator","https://beebom.com/arc-raiders-vaporizer-location-vaporizer-regulator/amp/","https://insider-gaming.com/how-to-get-vaporizer-regulator-in-arc-raiders-vaporizer-location-explained/"],"version":"2.0"},"water_filter":{"verdict":{"en":"Sell it for 1,000; no live project or upgrade needs it.","zh":"卖1000钱币，目前没有项目或升级需要它。"},"obtain":{"en":"Industrial loot, mostly Metal Crates. Dam Battlegrounds' Research and Administration west tunnels and Power Generation Complex, and the Spaceport Shipping Warehouse are listed. One guide suggests Buried City.","zh":"工业类战利品，多在金属箱里。大坝战场的研究与行政区西侧隧道、发电厂综合体，以及太空港货运仓库有记录；有攻略推荐掩埋废城。"},"tips":[{"en":"Recycle only if you need Canisters or Rubber Parts; selling for 1,000 usually pays more.","zh":"只在缺小罐或橡胶零件时回收，卖1000通常更划算。"}],"sources":["https://arcraiders.wiki/wiki/Water_Filter","https://www.keengamer.com/articles/guides/arc-raiders-avian-alarm-project-guide-and-rewards/"],"version":"2.0"},"water_pump":{"verdict":{"en":"Sell it for 1,000; no live project or upgrade needs it.","zh":"卖1000钱币，目前没有项目或升级需要它。"},"obtain":{"en":"Metal Crates in industrial areas: Dam Battlegrounds Research and Administration west tunnels and Power Generation Complex, and Spaceport Shipping Warehouse. Carts and shelves too.","zh":"工业区域的金属箱：大坝战场研究与行政区西侧隧道、发电厂综合体，以及太空港货运仓库；推车和货架上也会出现。"},"tips":[{"en":"Recycle only if you need Metal Parts or Oil; selling for 1,000 usually pays more.","zh":"只在缺金属零件或油时回收，卖1000通常更划算。"}],"sources":["https://arcraiders.wiki/wiki/Water_Pump","https://nerdschalk.com/arc-raiders-water-pump-location-use-guide/"],"version":"2.0"},"air_freshener":{"verdict":{"en":"Nothing current needs it, so sell it for a fat 2,000 coins each.","zh":"没有现行用途，直接卖，一个值 2000 钱币。"},"obtain":{"en":"Spawns in Mechanical areas. A July guide points to the car-filled highway near Checkpoint on The Blue Gate, the Robotic Sandbox on Stella Montis and the Power Generation Complex on Dam Battlegrounds. The Stench of Corruption also pays one.","zh":"出现在机械类区域。有攻略提到蓝门检查点附近堵满车的高速路、星辰山的机器人沙盒和大坝战场的发电厂综合体；完成“腐败的恶臭”也送 1 个。"},"tips":[{"en":"It is also an ingredient for the Flame Spray, crafted in-round with a Fireball Burner. Only worth it if you actually want that gadget.","zh":"也是“火焰喷涂”的材料，局内配合火球燃烧炉合成；除非你真想要这个道具，否则不必留。"}],"sources":["https://arcraiders.wiki/wiki/Air_Freshener","https://www.altchar.com/guides/arc-raiders-how-to-find-air-fresheners-aQXYp9B93Uhn","https://metaforge.app/arc-raiders/database/quest/the-stench-of-corruption"],"version":"2.0"},"alien_duck":{"verdict":{"en":"Pure sell item at 1,000 coins, or keep one as Raider Den decoration.","zh":"纯卖钱的物品，一只 1000；想装饰奇袭者巢穴可留一只。"},"obtain":{"en":"Only inside rooftop chimneys on Buried City while the Bird City condition is active. Nests seem limited to Italian-style buildings, so check those roofs.","zh":"只在“鸟城”条件生效时的掩埋废城屋顶烟囱里出现，似乎只有意式建筑才有鸟巢，优先搜这些屋顶。"},"tips":[{"en":"Throwing it makes a squeak that works as a cheap distraction, but you would be tossing 1,000 coins away.","zh":"扔出去会发出吱吱声，可当廉价的声东击西，但等于扔掉 1000 钱币。"}],"sources":["https://arcraiders.wiki/wiki/Alien_Duck","https://nerdschalk.com/alien-duck-locations-arc-raiders/","https://www.dexerto.com/wikis/arc-raiders/bird-city-event/"],"version":"2.0"},"arcade_duck":{"verdict":{"en":"A 7,000-coin chimney duck: always take it, always sell it.","zh":"7000 钱币的烟囱鸭，捡到必带，回去就卖。"},"obtain":{"en":"Scavenge rooftop chimneys on Buried City while Bird City is active. It is a rare roll, so do not plan a run around it; just check every chimney you pass.","zh":"在“鸟城”条件下搜掩埋废城屋顶烟囱。掉率不高，别专门为它开局，路过的烟囱顺手搜即可。"},"tips":[{"en":"Ducks stack 15 and weigh little, so they cost almost no backpack space.","zh":"鸭子可堆叠 15 个且很轻，几乎不占背包。"}],"sources":["https://arcraiders.wiki/wiki/Arcade_Duck","https://allthings.how/arc-raiders-familiar-duck-is-the-most-valuable-trinket-you-can-find-in-bird-city/","https://www.dexerto.com/wikis/arc-raiders/bird-city-event/"],"version":"2.0"},"archive_desk_lamp":{"verdict":{"en":"Sell it: 5,000 coins and no project, quest or recycle use.","zh":"直接卖：值 5000，没有任何任务、项目或回收用途。"},"obtain":{"en":"Added in 2.0. Scavenged from Commercial, Residential and Old World buildings; the wiki names no specific containers yet.","zh":"2.0 新增，可在商业、居住和旧世界建筑里搜到，社区还没整理出具体容器。"},"tips":[{"en":"It cannot be recycled and stacks only 1, so sell it on the way out rather than carrying several.","zh":"不可回收且不能堆叠，别囤着，出局就卖。"}],"sources":["https://arcraiders.wiki/wiki/Archive_Desk_Lamp"],"version":"2.0"},"bloated_tuna_can":{"verdict":{"en":"Barely worth the slot: 1,000 coins, or eat it for 25 stamina in a pinch.","zh":"勉强值得占位：卖 1000，紧急时吃掉回 25 体力。"},"obtain":{"en":"Common loot in Residential and Commercial containers, so you will pick it up without trying.","zh":"居住和商业区域容器里的常见战利品，不用刻意找。"},"sources":["https://arcraiders.wiki/wiki/Bloated_Tuna_Can","https://nerdschalk.com/bloated-tuna-can-locations-and-uses-in-arc-raiders/","https://beebom.com/arc-raiders-loot-cheat-sheet/"],"version":"2.0"},"breathtaking_snow_globe":{"verdict":{"en":"Nothing current needs it; sell it for 7,000 coins, or keep one as decoration.","zh":"目前没有项目需要它，直接卖 7000 钱币，或留一个当摆设。"},"obtain":{"en":"Epic and low spawn rate, in Residential, Old World and Commercial buildings. Buried City is the usual farm (Grandioso Apartments, Plaza Rosa, Town Hall, Santa Maria Houses, Library). Red secure lockers have the best odds. Exploring Pendola Pass also pays one.","zh":"史诗品质，掉率低，出现在居住、旧世界和商业建筑。常见刷点是掩埋废城（奢华公寓、玫瑰广场、市政厅、圣玛丽亚住宅、图书馆），红色保险柜机会最高。“探索彭多拉山口”也送 1 个。"},"tips":[{"en":"A Security Breach perk helps, since many of the best containers are locked.","zh":"带上“破门”类天赋更好，不少高价值容器是上锁的。"},{"en":"Exploring Pendola Pass pays one for free, so finish that quest before you farm.","zh":"“探索彭多拉山口”会白送 1 个，刷之前先把任务做了。"}],"sources":["https://arcraiders.wiki/wiki/Breathtaking_Snow_Globe","https://nerdschalk.com/breathtaking-snowglobe-in-arc-raiders-location-use-guide/","https://allthings.how/arc-raiders-breathtaking-snow-globe-value-spawns-keep-or-sell/"],"version":"2.0"},"broken_compass":{"verdict":{"en":"Quest item for A Path Not Yours; it has no sell value, so just hand it in.","zh":"“非你之路”的任务物品，不能换钱，交了就行。"},"obtain":{"en":"Follow the Nomad trail from under the Highway Collapse to the hideout, then dig up Bilguun's gift from the buried cache beneath it. Deliver it to the Nomadic Envoy.","zh":"从高速公路崩塌区下方沿游牧人的路标走到藏身处，在下方的埋藏箱里挖出比尔贡的礼物，再交给游牧使团。"},"sources":["https://arcraiders.wiki/wiki/Broken_Compass","https://arcraiders.wiki/wiki/A_Path_Not_Yours"],"version":"2.0"},"bronze_statuette":{"verdict":{"en":"A legendary 10,000-coin payout; sell it, or spend it on Nomadic Envoy trades.","zh":"传奇级 10000 的补偿物品：可以卖，也可以拿去游牧使团换货。"},"obtain":{"en":"You do not find it in raids. It was mailed to your account as compensation for resources put into an earlier project.","zh":"局内找不到，是对此前项目所投入资源的补偿，直接发到账号。"},"tips":[{"en":"It stacks to 25 but weighs 6 each, so a full stack is heavy. Use it from the stash, do not carry it into a raid.","zh":"可堆叠 25 个，但每个重 6，满叠很重，在储备箱里用，别带进局。"},{"en":"Players report Envoys accept it toward any item category in trades. The number you get depends on how much you invested.","zh":"据玩家反馈，使团交易中它可抵任意品类；拿到的数量取决于你投入了多少。"}],"sources":["https://arcraiders.wiki/wiki/Bronze_Statuette","https://www.pcgamesn.com/arc-raiders/nomadic-envoy-stock"],"version":"2.0"},"bureau_desk_lamp":{"verdict":{"en":"Sell it for 1,000; nothing else wants it.","zh":"卖掉，一个 1000，别处用不上。"},"obtain":{"en":"New in 2.0, found in Commercial, Residential and Old World buildings.","zh":"2.0 新增，出现在商业、居住和旧世界建筑。"},"sources":["https://arcraiders.wiki/wiki/Bureau_Desk_Lamp"],"version":"2.0"},"burnt_out_candles":{"verdict":{"en":"Low-value filler at 640 coins; sell it and do not make room for it.","zh":"价值低的杂物，只值 640，卖了就行，别特意腾位置。"},"obtain":{"en":"Common loot in Residential and Old World buildings.","zh":"居住和旧世界建筑里的常见战利品。"},"sources":["https://arcraiders.wiki/wiki/Burnt-Out_Candles","https://www.dexerto.com/wikis/arc-raiders/items/trinket/"],"version":"2.0"},"cat_bed":{"verdict":{"en":"Keep one for Scrappy level 4, then sell the rest for 1,000.","zh":"留 1 个给废品仔 4 级升级，多的卖 1000。"},"obtain":{"en":"Most guides say Buried City: the plastic containers on the Red Tower's outer ledge are the most reliable, and its red lockers also work. On Dam, try Ruby Residence and Pale Apartments; on The Blue Gate, the Village shelves.","zh":"多数攻略推荐掩埋废城：红塔外沿的白色塑料箱最稳，塔内红色柜也行。大坝战场去红宝石宅邸和苍白公寓，蓝门去村庄的货架。"},"tips":[{"en":"Put it in your Safe Pocket the moment you find it, since it looks like a sell item and is easy to lose.","zh":"捡到立刻放进安全口袋，它看着像卖钱货，死一次就没了。"},{"en":"The upgrade also takes 6 Prickly Pear and 6 Olives.","zh":"升级同时还要 6 个仙人掌果和 6 个橄榄。"}],"sources":["https://arcraiders.wiki/wiki/Cat_Bed","https://www.shacknews.com/article/146783/where-to-find-cat-beds-in-arc-raiders","https://metaforge.app/arc-raiders/database/item/cat-bed","https://keengamer.com/articles/guides/arc-raiders-how-to-upgrade-scrappy-to-max-level/"],"version":"2.0"},"celeste_journal":{"verdict":{"en":"Quest item for Celeste's Journals; worthless otherwise, so deliver it.","zh":"“塞莱斯特的日记”的任务物品，别无他用，交了就好。"},"obtain":{"en":"Both are on Dam Battlegrounds, in one round: the South Swamp Outpost and the northern outpost overlooking the Red Lakes. Deliver both to Celeste.","zh":"两本都在大坝战场，需在同一局拿齐：南部沼泽哨站和俯瞰红湖的北部哨站，然后交给塞莱斯特。"},"sources":["https://arcraiders.wiki/wiki/Celeste%27s_Journal","https://arcraiders.wiki/wiki/Celeste%27s_Journals"],"version":"2.0"},"coffee_pot":{"verdict":{"en":"Sell it for 1,000 coins; nothing current needs it.","zh":"卖掉，1000 钱币；目前没有需求。"},"obtain":{"en":"Residential kitchens and apartments: Pale Apartments and Ruby Residence on Dam, Plaza Rosa E Apartment and Grandioso Apartments in Buried City. The Espresso quest also rewards one.","zh":"居住区的厨房和公寓：大坝战场的苍白公寓和红宝石宅邸，掩埋废城的玫瑰广场东公寓和奢华公寓。完成“浓缩咖啡”任务也送 1 个。"},"tips":[{"en":"It cannot be recycled, so selling is the only way to cash it in.","zh":"它不能回收，只能卖掉换钱。"}],"sources":["https://arcraiders.wiki/wiki/Coffee_Pot","https://www.destructoid.com/all-arc-raiders-flickering-flames-project-requirements-and-how-to-complete-them/","https://arcraiders.wiki/wiki/Espresso"],"version":"2.0"},"dart_board":{"verdict":{"en":"Sell it. 2,000 coins, but it weighs 1 and has no use.","zh":"直接卖。能值 2000，但重 1 又没用。"},"obtain":{"en":"Uncommon loot in Residential and Commercial buildings.","zh":"居住和商业建筑里的少见战利品。"},"sources":["https://arcraiders.wiki/wiki/Dart_Board","https://beebom.com/arc-raiders-loot-cheat-sheet/"],"version":"2.0"},"desk_lamp":{"verdict":{"en":"Sell it for 2,000; no quest, project or recycle use.","zh":"卖掉，2000 一个，没有任务、项目或回收用途。"},"obtain":{"en":"New in 2.0, in Commercial and Residential buildings; no specific containers are documented yet.","zh":"2.0 新增，出现在商业和居住建筑，暂无具体容器信息。"},"sources":["https://arcraiders.wiki/wiki/Desk_Lamp"],"version":"2.0"},"dodgers_note":{"verdict":{"en":"Quest item for Outstanding Balance; hand it to Tian Wen and forget it.","zh":"“未结债务”的任务物品，交给天玟即可。"},"obtain":{"en":"Search Dodger's stash in the underground Traffic Tunnel, then his deal spot by the Pilgrim's Peak antenna, all in one round.","zh":"同一局内先搜通行隧道（地下）里道奇的藏匿点，再去朝圣峰天线旁的交易点。"},"sources":["https://arcraiders.wiki/wiki/Dodger%27s_Note","https://arcraiders.wiki/wiki/Outstanding_Balance"],"version":"2.0"},"doodly_duck":{"verdict":{"en":"A 3,000-coin chimney duck; take it, sell it.","zh":"3000 钱币的烟囱鸭，捡了就卖。"},"obtain":{"en":"Only in Buried City rooftop chimneys during Bird City. Rare, so it is a bonus rather than a farming goal.","zh":"只在“鸟城”条件下的掩埋废城屋顶烟囱里出现，掉率偏低，属于顺手收获。"},"sources":["https://arcraiders.wiki/wiki/Doodly_Duck","https://www.dexerto.com/wikis/arc-raiders/bird-city-event/","https://allthings.how/arc-raiders-familiar-duck-is-the-most-valuable-trinket-you-can-find-in-bird-city/"],"version":"2.0"},"dusty_film_reel":{"verdict":{"en":"Quest item for A Dead End; deliver it to Shani.","zh":"“死路一条”的任务物品，交给萨尼即可。"},"obtain":{"en":"The quest sits on The Blue Gate. Power the locked door in MANTIKOR's underground with batteries, play the recording, then search beside the monitors.","zh":"任务在蓝门：用电池给 地下设施的锁门供电，播放录音，再在监视器旁搜索。"},"sources":["https://arcraiders.wiki/wiki/Dusty_Film_Reel","https://arcraiders.wiki/wiki/A_Dead_End"],"version":"2.0"},"elephant_obelisk":{"verdict":{"en":"Nothing current needs it; sell it for 10,000 coins.","zh":"目前没有需求，直接卖 10000 钱币。"},"obtain":{"en":"Legendary and very scarce. The guides name no container or map, so check high-value containers on whatever route you run; expect several raids.","zh":"传奇品质且很稀有，攻略没给出具体地图或容器，只能在日常路线上多搜高价值容器，可能要跑好几局。"},"tips":[{"en":"Stack of 1 and weight 0.5: it takes a slot but little weight, so sell it right after the raid.","zh":"堆叠 1、重 0.5，只占一格几乎不占重量，局后尽快卖掉。"}],"sources":["https://arcraiders.wiki/wiki/Elephant_Obelisk","https://pcgamer.com/games/third-person-shooter/arc-raiders-converging-paths-project/","https://beebom.com/arc-raiders-converging-paths-project-guide/amp/"],"version":"2.0"},"empty_wine_bottle":{"verdict":{"en":"Sell it for 1,000 coins each; nothing current needs it.","zh":"每个卖 1000 钱币，目前没有需求。"},"obtain":{"en":"Search Residential and Commercial containers; rows of metal lockers are a good bet. It is also an ingredient for Agave Juice with an Agave.","zh":"搜居住和商业区域的容器，成排的金属柜不错。它还能与龙舌兰叶一起合成龙舌兰汁。"},"sources":["https://arcraiders.wiki/wiki/Empty_Wine_Bottle","https://www.destructoid.com/how-to-get-empty-wine-bottle-in-arc-raiders/","https://allthings.how/arc-raiders-empty-wine-bottles-best-locations-farming-tips-and-uses/"],"version":"2.0"},"equatorial_sundial":{"verdict":{"en":"Keep 1 if you still need Clean Hands; sell the rest for 3,000 each.","zh":"若还没做“清理指针”留 1 个，其余每个卖 3000。"},"obtain":{"en":"Rare, in Residential and Commercial containers, often on shelves and in drawers. Guides suggest Grandioso Apartments, Santa Maria Houses and the plazas in Buried City, plus chimneys during Bird City. Clean Hands is on Pendola Pass.","zh":"稀有，出现在居住和商业区域的货架与抽屉。攻略推荐掩埋废城的奢华公寓、圣玛丽亚住宅和各广场，以及“鸟城”期间的烟囱。“清理指针”任务在彭多拉山口。"},"sources":["https://arcraiders.wiki/wiki/Equatorial_Sundial","https://arcraiders.wiki/wiki/Clean_Hands","https://pcgamer.com/games/third-person-shooter/arc-raiders-converging-paths-project/"],"version":"2.0"},"espresso_machine_parts":{"verdict":{"en":"Quest item for Espresso; take one back to Apollo.","zh":"“浓缩咖啡”的任务物品，带 1 个回去给阿波罗。"},"obtain":{"en":"Salvage an espresso machine in one round. Dam: top-floor kitchens in Ruby Residence and Pale Apartments, or the Research and Administration cafeteria. Buried City: the Il Maiale Dorato trattoria south of the highway.","zh":"同一局内拆一台咖啡机。大坝战场：红宝石宅邸和苍白公寓顶层厨房，或研究与行政楼的自助餐厅；掩埋废城：高速路南侧的 脚手架餐馆（招牌为金猪）。"},"sources":["https://arcraiders.wiki/wiki/Espresso_Machine_Parts","https://arcraiders.wiki/wiki/Espresso"],"version":"2.0"},"esr_analyzer":{"verdict":{"en":"Quest-only: grab one for A Reveal in Ruins, and don't expect to sell it.","zh":"纯任务物品：只为“废墟中的揭示”拿一个。"},"obtain":{"en":"It sits in Buried City pharmacies. The wiki suggests the one in Piazza Arbusto, east of the Town Hall, and says to check behind the counters, where boxes are often hidden. Finish the quest in one raid.","zh":"在掩埋废城的药店里找。可以去市政厅东边的阿布斯托广场药店，柜台后面常藏着箱子。需在同一局内完成。"},"tips":[{"en":"Put it in a Safe Pocket so a death doesn't cost you the trip.","zh":"放进安全口袋，死亡也不会丢。"}],"sources":["https://arcraiders.wiki/wiki/ESR_Analyzer","https://arcraiders.wiki/wiki/A_Reveal_In_Ruins"],"version":"2.0"},"experimental_seed_sample":{"verdict":{"en":"A one-off quest item for The Root of the Matter; there is nothing else to do with it.","zh":"“源头之种”的一次性任务物品，没有别的用途。"},"obtain":{"en":"It is in the seed vault of the Research Building in Buried City, the room with the great view over the park on the north side. Hand it to Celeste in the same raid.","zh":"在掩埋废城研究楼的种子库里，即北侧朝向公园、视野很好的那个房间。需在同一局内交给塞莱斯特。"},"tips":[{"en":"The quest pays a Succulent backpack charm and 1,000 coins, so it is worth one dedicated run.","zh":"任务奖励多肉背包挂饰和1000钱币，值得专门跑一趟。"}],"sources":["https://arcraiders.wiki/wiki/Experimental_Seed_Sample","https://arcraiders.wiki/wiki/The_Root_Of_The_Matter"],"version":"2.0"},"expired_pasta":{"verdict":{"en":"Sell it: 1,000 coins for a 0.1 weight slot beats the tiny heal.","zh":"卖掉：0.1重量就值1000钱币，比那点治疗划算。"},"use":{"en":"It heals 15 and, per one guide, makes no noise, so it works as an emergency stealth heal. A real healing item is still better for the slot.","zh":"能回15点生命，据一份攻略所说使用时没有声音，可当应急的静音治疗。但占格子不如正经的治疗物品。"},"obtain":{"en":"Common loot in Residential and Commercial areas, mostly kitchens, trash cans and cases. No nearby quest or project needs it.","zh":"住宅区和商业区的常见战利品，多在厨房、垃圾桶和箱子里。没有任务或项目需要它。"},"sources":["https://arcraiders.wiki/wiki/Expired_Pasta","https://nerdschalk.com/arc-raiders-expired-pasta-location-use-guide/"],"version":"2.0"},"faded_photograph":{"verdict":{"en":"Plain filler at 640 coins; sell it when you have space, skip it when you don't.","zh":"640钱币的普通杂物，有空位就卖，没空位就别捡。"},"obtain":{"en":"Turns up in Residential loot containers. The wiki gives no specific spots, and no quest or workshop upgrade uses it.","zh":"出现在住宅区的容器里。维基没给具体地点，也没有任务或工坊升级需要它。"},"sources":["https://arcraiders.wiki/wiki/Faded_Photograph","https://www.dexerto.com/wikis/arc-raiders/items/trinket/faded-photograph/"],"version":"2.0"},"familiar_duck":{"verdict":{"en":"The best duck: 7,000 coins per slot, but only if Bird City is running on Buried City.","zh":"最值钱的鸭子，一格7000钱币，但要赶上掩埋废城的鸟城事件。"},"obtain":{"en":"Search rooftop chimneys on Buried City while the Bird City condition is active. Chimneys are tiled-roof residential buildings, with Old Town and West Village recommended, and they spawn randomly, so there is no fixed farm spot.","zh":"在鸟城事件期间搜索掩埋废城屋顶的烟囱。烟囱多在瓦屋顶的住宅楼上，推荐老城区和西村，每局随机刷新，没有固定刷点。"},"tips":[{"en":"Stacks of 15 mean a full stack is a big payday, but a thrown duck also makes a decent noise distraction.","zh":"一组能叠15个，整组很值钱；也可以扔出去制造噪音分散注意。"},{"en":"Ducks can sit on your Raider Den shelves, but selling one removes its display.","zh":"鸭子可摆在奇袭者巢穴的架子上，但卖掉后展示也会消失。"}],"sources":["https://arcraiders.wiki/wiki/Familiar_Duck","https://www.dexerto.com/wikis/arc-raiders/bird-city-event/","https://allthings.how/arc-raiders-familiar-duck-is-the-most-valuable-trinket-you-can-find-in-bird-city/"],"version":"2.0"},"film_reel":{"verdict":{"en":"Sell it for 2,000 coins each; nothing current needs it.","zh":"每个卖 2000 钱币，目前没有需求。"},"obtain":{"en":"Residential drawers and cabinets. The wiki names Pale Apartments and Ruby Residence on Dam Battlegrounds, Plaza Rosa and Grandioso Apartments in Buried City, and the Village on The Blue Gate.","zh":"住宅区的抽屉和柜子里。维基列出大坝战场的苍白公寓、红宝石宅邸，掩埋废城的玫瑰广场、奢华公寓，以及蓝门的村庄。"},"tips":[{"en":"It can't be recycled, so selling is the only way to cash it in.","zh":"无法回收，只能卖掉换钱。"}],"sources":["https://arcraiders.wiki/wiki/Film_Reel","https://timesaver.gg/blog/arc-raiders-best-items-to-sell"],"version":"2.0"},"fine_wristwatch":{"verdict":{"en":"Sell it for 3,000 coins each; nothing current needs it.","zh":"每个卖 3000 钱币，目前没有需求。"},"obtain":{"en":"Found in Residential and Commercial loot. The wiki has no named spots, so just check drawers and shelves in any apartment or shop area.","zh":"出现在住宅区和商业区的战利品中。维基没有具体地点，翻公寓和商店区的抽屉与货架即可。"},"tips":[{"en":"At 0.2 weight and 3,000 coins it is a better slot than most trinkets, so pick it up.","zh":"重0.2却值3000钱币，比大多数饰品划算，见到就拿。"}],"sources":["https://arcraiders.wiki/wiki/Fine_Wristwatch","https://timesaver.gg/blog/arc-raiders-best-items-to-sell"],"version":"2.0"},"first_wave_compass":{"verdict":{"en":"Broken Monument quest item; deliver it to Tian Wen.","zh":"“破败的纪念”任务物品，交给天玟。"},"obtain":{"en":"Dam Battlegrounds, around the broken-down vehicles near the Scrap Yard's hallowed grounds. Collect it together with the tape and rations in one raid.","zh":"大坝战场，废料场圣地附近的报废车辆旁。需与录像带和口粮在同一局内集齐。"},"sources":["https://arcraiders.wiki/wiki/First_Wave_Compass","https://arcraiders.wiki/wiki/Broken_Monument"],"version":"2.0"},"first_wave_rations":{"verdict":{"en":"Broken Monument quest item with no other use.","zh":"“破败的纪念”任务物品，别无他用。"},"obtain":{"en":"Dam Battlegrounds, in the Raider camp by the Scrap Yard. Tian Wen asks you not to break the items, and there may be junk lying around, so look for what stands out.","zh":"大坝战场，废料场旁的奇袭者营地里。天玟叮嘱别弄坏物品，周围可能有杂物，找显眼的那个。"},"sources":["https://arcraiders.wiki/wiki/First_Wave_Rations","https://arcraiders.wiki/wiki/Broken_Monument"],"version":"2.0"},"first_wave_tape":{"verdict":{"en":"Third Broken Monument pickup; the quest rewards an Arpeggio I.","zh":"“破败的纪念”的第三件物品，任务奖励一把三连奏 I。"},"obtain":{"en":"Dam Battlegrounds, near the cylindrical containers in the Scrap Yard area. The tape is labeled THE LAST BARON.","zh":"大坝战场废料场一带，圆柱形容器附近。磁带标签上写着最后的男爵。"},"sources":["https://arcraiders.wiki/wiki/First_Wave_Tape","https://arcraiders.wiki/wiki/Broken_Monument"],"version":"2.0"},"flashy_duck":{"verdict":{"en":"A 3,000-coin Bird City duck; sell it or shelve it in your den.","zh":"鸟城事件的3000钱币鸭子，卖掉或摆在巢穴里。"},"obtain":{"en":"Open rooftop chimneys on Buried City while Bird City is active. Spawns are random, so keep moving between chimneys.","zh":"鸟城事件期间在掩埋废城打开屋顶烟囱。刷新随机，多换几个烟囱找。"},"sources":["https://arcraiders.wiki/wiki/Flashy_Duck","https://www.dexerto.com/wikis/arc-raiders/bird-city-event/"],"version":"2.0"},"flushing_terminal_key":{"verdict":{"en":"A quest key for the Spaceport tunnels; use it and forget it.","zh":"太空港地下通道的任务钥匙，用完就丢。"},"obtain":{"en":"The wiki puts it in the staff locker room in the southwest of the Departure Building, near the parking lot. Then use it on any Flushing Terminal in the tunnels below the Spaceport, in the same raid.","zh":"维基说在候机楼西南角靠近停车场的员工更衣室。随后在同一局内于太空港地下通道的任意冲洗终端上使用。"},"tips":[{"en":"It belongs to The Stench of Corruption, a Shani quest.","zh":"它属于萨尼的任务“腐败的恶臭”。"}],"sources":["https://arcraiders.wiki/wiki/Flushing_Terminal_Key","https://arcraiders.wiki/wiki/The_Stench_Of_Corruption"],"version":"2.0"},"football_shoes_green":{"verdict":{"en":"Colorful Shoes (Red): nothing current needs them; sell for 3,000 each.","zh":"彩纹鞋子（红）：目前没有需求，每双卖 3000。"},"obtain":{"en":"Furnished Residential and Commercial buildings. AltChar names Grandioso Apartments, Space Travel and Santa Maria Houses in Buried City, the Village on Blue Gate, Ruby Residence and Pale Apartments on Dam, plus the Spaceport Arrival and Departure buildings and the Hotel Complex in Riven Tides.","zh":"有家具的住宅和商业建筑。攻略列出掩埋废城的奢华公寓、航天大楼、圣玛利亚住宅，蓝门的村庄，大坝的红宝石宅邸、苍白公寓，太空港的到达楼和候机楼，以及裂潮镇的酒店综合体。"},"tips":[{"en":"Stacks to 3 at 0.5 weight each, so sell them in batches.","zh":"一格可叠 3 双，每双重 0.5，攒几双一起卖。"}],"sources":["https://arcraiders.wiki/wiki/Colorful_Shoes_(Rare)","https://www.altchar.com/guides/arc-raiders-how-to-find-colorful-shoes-ajfv34s2actl","https://pcgamer.com/games/third-person-shooter/arc-raiders-converging-paths-project/"],"version":"2.0"},"football_shoes_red":{"verdict":{"en":"Colorful Shoes (Green): nothing current needs them; sell for 7,000 each.","zh":"彩纹鞋子（绿）：目前没有需求，每双卖 7000。"},"obtain":{"en":"Same loot zones as the other pairs: shelves and cupboards in Residential and Commercial buildings. Buried City is rated the best overall trinket area, with chimneys during Bird City also recommended.","zh":"与其他颜色相同：住宅和商业建筑的架子、柜子。掩埋废城被评为饰品最佳区域，鸟城期间的烟囱也值得翻。"},"tips":[{"en":"Stack size is 1, so each pair takes a slot; sell right after the raid.","zh":"堆叠上限为 1，每双占一格，局后尽快卖掉。"}],"sources":["https://arcraiders.wiki/wiki/Colorful_Shoes_(Epic)","https://nerdschalk.com/arc-raiders-train-model-colorful-shoes-location/"],"version":"2.0"},"football_shoes_silver":{"verdict":{"en":"Colorful Shoes (Silver): the scarcest pair, and nothing current needs it; sell for 10,000.","zh":"彩纹鞋子（银）：最稀有的一双，目前没有需求，卖 10000。"},"obtain":{"en":"Furnished Residential and Commercial buildings. The wiki lists no specific spots, so lean on the Buried City apartment and plaza areas that guides recommend for trinkets.","zh":"有家具的住宅和商业建筑。维基没有具体地点，可去攻略推荐的掩埋废城公寓和广场一带。"},"tips":[{"en":"Legendary and stack 1: put it in a Safe Pocket once you find one, then sell it after the raid.","zh":"传说级且不可叠加，找到后放进安全口袋，局后再卖。"}],"sources":["https://arcraiders.wiki/wiki/Colorful_Shoes_(Legendary)","https://www.keengamer.com/articles/guides/arc-raiders-converging-paths-project-guide-and-rewards/"],"version":"2.0"},"frosty_duck":{"verdict":{"en":"A rare duck worth 3,000 coins; sell it unless you want the display.","zh":"3000钱币的稀有鸭子，不要展示就卖。"},"obtain":{"en":"Chimneys on Buried City rooftops during Bird City. It was added in patch 1.45.0.","zh":"鸟城事件期间掩埋废城屋顶的烟囱。该物品在1.45.0版本加入。"},"sources":["https://arcraiders.wiki/wiki/Frosty_Duck","https://www.dexerto.com/wikis/arc-raiders/bird-city-event/"],"version":"2.0"},"gentle_duck":{"verdict":{"en":"A 1,000-coin duck: fine as a throwable distraction, not worth a farming trip.","zh":"1000钱币的鸭子，可当投掷干扰物，不值得专门去刷。"},"obtain":{"en":"Bird City chimneys on Buried City, the same source as the other ducks. Old Town is a good first stop.","zh":"掩埋废城鸟城事件的烟囱，来源与其他鸭子相同。可先去老城区。"},"sources":["https://arcraiders.wiki/wiki/Gentle_Duck","https://www.dexerto.com/wikis/arc-raiders/bird-city-event/"],"version":"2.0"},"lances_mixtape_5th_edition":{"verdict":{"en":"Sell it: 10,000 coins at only 0.2 weight, and nothing current needs it.","zh":"卖掉：重量仅 0.2 却值 10000 钱币，目前没有需求。"},"obtain":{"en":"Scavenge Residential and Commercial loot. The wiki names no spots, so it is luck of the draw while looting apartments and shops.","zh":"搜刮住宅区和商业区。维基没有具体地点，翻公寓和商店时看运气。"},"tips":[{"en":"It stacks to 3, making it one of the best coins per slot, so grab every copy you see.","zh":"一格可叠3个，单格收益极高，见到就拿。"}],"sources":["https://arcraiders.wiki/wiki/Lance%27s_Mixtape_(5th_Edition)","https://allthings.how/arc-raiders-lances-mixtape-5th-edition-sell-it-or-stash-it/"],"version":"2.0"},"leviathans_crown_ship_model":{"verdict":{"en":"Nothing current needs it; sell it for 10,000 coins.","zh":"目前没有需求，直接卖 10000 钱币。"},"obtain":{"en":"It is a Riven Tides trinket. Guides point to blue luggage bags on beachside areas and say the Dockmaster's Detector helps you find hidden loot.","zh":"裂潮镇的饰品。攻略指向海滩区域的蓝色行李袋，并称码头主管探测器有助于找到隐藏战利品。"},"tips":[{"en":"One guide lists the value in Merits, not coins. Trust the in-game price here; the item page lists 10,000 coins.","zh":"有攻略把价值写成功勋而非钱币，以游戏内价格为准，本站数据为10000钱币。"}],"sources":["https://arcraiders.wiki/wiki/Leviathan%27s_Crown_Ship_Model","https://nerdschalk.com/arc-raiders-how-to-find-leviathans-crown-ship-model-quickly-locations-and-tips/"],"version":"2.0"},"library_book":{"verdict":{"en":"Quest-only: take three from the Buried City library for Building a Library.","zh":"纯任务物品：为“丰富图书室”从掩埋废城图书馆拿3本。"},"obtain":{"en":"The library is in Buried City's City Center. You need a romance, a detective and an adventure book from its yellow-highlighted shelves across two floors, then extract with all three in one raid. Expect fights and use a Looting Mk. 2 for spare Safe Pockets.","zh":"图书馆在掩埋废城市中心。需要在两层楼的黄色高亮书架上找到爱情、侦探、冒险各一本，并在同一局内带着三本撤离。这里常有战斗，可用“搜刮 Mk. 2”多腾几个安全口袋。"},"tips":[{"en":"The quest comes from Apollo and rewards an Explosive Mine, a Jolt Mine and a Heavy Fuze Grenade.","zh":"任务来自阿波罗，奖励爆炸地雷、电击地雷和重型引信手雷各一。"}],"sources":["https://arcraiders.wiki/wiki/Building_A_Library","https://www.shacknews.com/article/147717/how-to-complete-building-a-library-in-arc-raiders","https://nerdschalk.com/arc-raiders-building-a-library-walkthrough-location-rewards-guide-to-acquire-the-books/"],"version":"2.0"},"lidar_scanner":{"verdict":{"en":"A Spaceport quest item for A Lay of the Land, and unsellable.","zh":"太空港“地形勘查”的任务物品，无法出售。"},"obtain":{"en":"The scanners are on the upper floor of Control Tower A6 in the Spaceport. Check the foreman's office in the Jiangsu Warehouse, northwest, for the shipping notes first, all in one raid.","zh":"扫描仪在太空港控制塔A6的上层。先去西北的江苏仓库工头办公室找运货单，需在同一局内完成。"},"tips":[{"en":"Quest rewards are a Dam Testing Annex Key, 3 Ziplines and 2 Smoke Grenades.","zh":"任务奖励大坝测试附楼钥匙、3个滑索和2枚烟雾弹。"}],"sources":["https://arcraiders.wiki/wiki/LiDAR_Scanner","https://arcraiders.wiki/wiki/A_Lay_Of_The_Land"],"version":"2.0"},"light_bulb":{"verdict":{"en":"Sell them for 2,000 coins each; nothing current needs them.","zh":"每个卖 2000 钱币，目前没有需求。"},"use":{"en":"No live project, quest or workshop upgrade asks for it, so it is purely a sale item. At 0.2 weight and stack 3 it is cheap to carry out.","zh":"现行项目、任务和工坊升级都不需要它，纯粹是卖钱的物品。重 0.2、可叠 3 个，带出局很轻松。"},"obtain":{"en":"On Dam Battlegrounds, breach the car hood at the Electrical Substation or the Generator Hall; guides call the substation car nearly guaranteed. Pilgrim's Peak on The Blue Gate also has a breachable container.","zh":"在大坝战场的变电站或发电机大厅破开汽车引擎盖，攻略称变电站的车几乎必出。蓝门朝圣峰也有可破开的容器。"},"tips":[{"en":"It can't be recycled, and the Power Generation Complex route is often watched by a Rocketeer.","zh":"无法回收；发电综合体那条路线常有火箭手巡逻。"}],"sources":["https://arcraiders.wiki/wiki/Light_Bulb","https://www.shacknews.com/article/146811/find-light-bulbs-arc-raiders","https://nerdschalk.com/arc-raiders-light-bulbs-locations-where-to-find-them-all/"],"version":"2.0"},"major_aivas_mementos":{"verdict":{"en":"Quest-only: one copy for The Major's Footlocker, and the reward is a Hullcracker Blueprint.","zh":"任务专用：只需 1 个，交付“少校的储物柜”可得“裂甲者”蓝图。"},"obtain":{"en":"Dam Battlegrounds, in the apartments northwest of the Dam; Tian Wen's hints point at the Ruby Residence and the Pale Apartments. Search and turn it in within the same raid, and carry it in a Safe Pocket if you can.","zh":"大坝战场，大坝西北方的公寓楼；天玟的线索指向红宝石宅邸和苍白公寓。同一局内找到并交付，有安全口袋就放进去。"},"tips":[{"en":"Do not sell it: selling gains you 100 coins and the quest stalls.","zh":"别卖，只值 100 钱币，卖了任务就卡住了。"}],"sources":["https://arcraiders.wiki/wiki/Major's_Mementos","https://arcraiders.wiki/wiki/The_Major's_Footlocker"],"version":"2.0"},"major_aivas_patch":{"verdict":{"en":"Quest-only: hand one to Celeste for Echoes of Victory Ridge, which also pays out a Music Box.","zh":"任务专用：交给塞莱斯特完成“凯旋岭的回声”，还送音乐盒。"},"obtain":{"en":"Dam Battlegrounds, around Victory Ridge. The quest sends you to a hideout under the broken highway for the battle plans, so look around there. Everything is done in one raid.","zh":"大坝战场，凯旋岭一带。任务要你去断裂高架桥下的藏身处，在那附近找。整个任务需在同一局内完成。"},"tips":[{"en":"The Music Box reward sells for 5,000, so this quest is worth finishing.","zh":"奖励的音乐盒能卖 5000，这个任务值得做完。"}],"sources":["https://arcraiders.wiki/wiki/Major_Aiva's_Patch","https://arcraiders.wiki/wiki/Echoes_Of_Victory_Ridge"],"version":"2.0"},"marano_market_business_card":{"verdict":{"en":"A 100-coin quest clue from Line in the Sand; nothing in the workshop needs it, so sell it when the quest is done.","zh":"“沙滩防线”的线索物品，只值 100 钱币，任务后可卖。"},"obtain":{"en":"Buried City, in a small tower near Piazza Roma, east of the derailed train. Inspect the corner where a bush is growing and a container holds the card.","zh":"掩埋废城罗马广场附近的小塔楼，位于脱轨列车东侧。检查长着灌木的角落，旁边容器里有名片。"},"tips":[{"en":"Line in the Sand pays 2 Exodus Modules, 2 Magnetic Accelerators and 2 Magnetrons, so it is worth doing.","zh":"“沙滩防线”奖励 2 个离巢模块、2 个磁力加速器和 2 个磁电管，值得做。"}],"sources":["https://arcraiders.wiki/wiki/Marano_Market_Business_Card","https://arcraiders.wiki/wiki/Line_in_the_Sand","https://allthings.how/line-in-the-sand-quest-walkthrough-in-arc-raiders/"],"version":"2.0"},"moisture_meter":{"verdict":{"en":"Quest-only: keep it for Unexpected Initiative, together with the Nutrient Meter.","zh":"任务专用：留给“计划不如变化快”，要和营养测量仪一起交。"},"obtain":{"en":"Buried City, on the rooftop of the Grandioso Apartments. Do both meters in one raid, then deliver them to Tian Wen.","zh":"掩埋废城奢华公寓的屋顶。两个测量仪需在同一局内取得，再交给天玟。"},"tips":[{"en":"The reward is an Il Toro I, 40 Shotgun Ammo and a Shotgun Choke II.","zh":"奖励是“公牛” I、40 发霰弹枪弹药和霰弹枪收束器 II。"}],"sources":["https://arcraiders.wiki/wiki/Moisture_Meter","https://arcraiders.wiki/wiki/Unexpected_Initiative"],"version":"2.0"},"nutrient_meter":{"verdict":{"en":"Quest-only: the second item for Unexpected Initiative, so keep it.","zh":"任务专用：“计划不如变化快”的第二件物品，留着。"},"obtain":{"en":"Buried City, in the broken rooftop gardens of Piazza Roma. Grab it in the same raid as the Moisture Meter and turn both in to Tian Wen.","zh":"掩埋废城罗马广场破损的屋顶花园。与水分测量仪在同一局拿，一起交给天玟。"},"sources":["https://arcraiders.wiki/wiki/Nutrient_Meter","https://arcraiders.wiki/wiki/Unexpected_Initiative"],"version":"2.0"},"mri_duck":{"verdict":{"en":"Sell it: a Legendary duck worth 10,000 coins for 0.3 weight, and nothing in the game needs it.","zh":"直接卖：传说级鸭子，0.3 重量值 10000 钱币，游戏里没有任何需求。"},"use":{"en":"You can throw it as a noise distraction or keep it on a display shelf, but at this price selling is almost always better.","zh":"可以扔出去制造噪音，或摆在展示架上，但这个价格还是卖掉更划算。"},"obtain":{"en":"Only in Buried City while the Bird City condition is active: search the rooftop chimneys. Every nest rolls from a shared pool, so it is pure luck. Rubber ducks are reported mostly on Italian-style terracotta roofs, with Old Town the usual pick.","zh":"仅在掩埋废城“鸟城”条件开启时出现：搜屋顶烟囱。每个鸟巢都从同一奖池抽取，全看运气。据说多在意式陶土屋顶的建筑上，旧城区较常见。"},"tips":[{"en":"It stacks to 15, but the 0.3 weight means a few copies cost almost no space.","zh":"可堆叠 15 个，重量只有 0.3，带几个几乎不占空间。"}],"sources":["https://arcraiders.wiki/wiki/MRI_Duck","https://arcraiders.wiki/wiki/Bird_City","https://nerdschalk.com/familiar-duck-locations-in-arc-raiders-bird-city/"],"version":"2.0"},"music_album":{"verdict":{"en":"Sell it for 3,000 coins unless you are decorating: it takes little space and nothing current needs it.","zh":"不装饰就卖，3000 钱币，占位小，目前没有需求。"},"use":{"en":"The Raider Den has a shelf spot that only fits a Music Album. It cannot be recycled.","zh":"奇袭者巢穴里有个只能放音乐专辑的展示位。它不能回收。"},"obtain":{"en":"Scavenged in Residential and Commercial areas with no fixed spawn. Guides name the Arrival Building on The Spaceport, the Abandoned Highway Camp residence in Buried City, and the Ruby Residence on Dam Battlegrounds.","zh":"在住宅区和商业区搜刮，没有固定刷新点。攻略提到太空港到达大楼、掩埋废城废弃公路营地的住宅，以及大坝战场红宝石宅邸。"},"tips":[{"en":"The Arrival and Departure buildings on The Spaceport often have ARC nearby, so expect a fight.","zh":"太空港的到达和出发大楼常有 ARC 出没，做好战斗准备。"}],"sources":["https://arcraiders.wiki/wiki/Music_Album","https://arcraiders.wiki/wiki/Flickering_Flames","https://www.shacknews.com/article/147377/music-albums-arc-raiders"],"version":"2.0"},"music_box":{"verdict":{"en":"A 5,000-coin trinket: sell it, since nothing needs it.","zh":"5000 钱币的饰品：没有需求，直接卖。"},"obtain":{"en":"Scavenged in Old World, Residential and Commercial areas. You also receive one from the Divided and Echoes of Victory Ridge quests.","zh":"在旧世界、住宅区和商业区搜刮。完成“分歧”和“凯旋岭的回声”任务也会各给 1 个。"},"tips":[{"en":"Those quest rewards are an easy 10,000 coins in total.","zh":"这两个任务奖励的音乐盒合计约 10000 钱币。"}],"sources":["https://arcraiders.wiki/wiki/Music_Box","https://arcraiders.wiki/wiki/Echoes_Of_Victory_Ridge"],"version":"2.0"},"nomad_tech_item":{"verdict":{"en":"A new 2.0 item tied to Celeste, with no sell value: hold it until we know its use.","zh":"2.0 新增物品，与塞莱斯特有关，无售价：先留着，看用途再定。"},"obtain":{"en":"No community guide covers it yet and its spawn is unconfirmed. Its description says Celeste would be interested, so check her quests.","zh":"目前没有社区攻略，刷新位置未确认。描述提到塞莱斯特会感兴趣，可留意她的任务。"},"sources":["https://arcraiders.wiki/wiki/Nomad_Tech_Item"],"version":"2.0"},"official_shutdown_documentation":{"verdict":{"en":"Quest-only: it finishes Shani's Last Entry quest, so keep it.","zh":"任务专用：用来完成萨尼的“最后条目”，留着。"},"obtain":{"en":"Stella Montis, in the Seed Vault. Use the right workstation for clues, find a hidden key in the adjacent room, then open the seed deposit box.","zh":"星辰山种子库。先在正确的工作站找线索，在相邻房间找到隐藏钥匙，再打开种子保管箱。"},"tips":[{"en":"The reward is the White Indigo outfit and a Yellow Light Stick Blueprint.","zh":"奖励是“白靛”服装和黄色荧光棒蓝图。"}],"sources":["https://arcraiders.wiki/wiki/Official_Shutdown_Documentation","https://arcraiders.wiki/wiki/Last_Entry"],"version":"2.0"},"old_world_books":{"verdict":{"en":"Quest-only: Cold Storage needs one, and it pays out 3 Gas Mines and a Raider Hatch Key.","zh":"任务专用：“冷冻储藏”需要 1 本，奖励 3 颗跳雷：持续流失耐力和奇袭者暗门钥匙。"},"obtain":{"en":"Stella Montis. Search any J Kozma Ventures container; one example is a loading bay container near the wind tunnel extract, reached by dropping down from the second floor.","zh":"星辰山。搜索任意 J·科兹马创投公司容器，例如风洞撤离点附近装卸区的容器，需从二楼跳下去。"},"sources":["https://arcraiders.wiki/wiki/Old_World_Books","https://arcraiders.wiki/wiki/Cold_Storage"],"version":"2.0"},"painted_box":{"verdict":{"en":"A plain 2,000-coin sell item with no other use.","zh":"纯卖钱物品，2000 钱币，别无他用。"},"obtain":{"en":"Scavenged in Old World areas. The wiki lists no specific containers.","zh":"在旧世界区域搜刮，维基未列出具体容器。"},"sources":["https://arcraiders.wiki/wiki/Painted_Box"],"version":"2.0"},"playing_cards":{"verdict":{"en":"A good pocket sell: 5,000 coins at only 0.2 weight.","zh":"很划算的小物件：重量仅 0.2，却能卖 5000 钱币。"},"obtain":{"en":"Scavenged in Residential and Commercial areas, with no named container. It also sits in the Raider Den as a display item.","zh":"在住宅区和商业区搜刮，没有指定容器。也可作为奇袭者巢穴的展示品。"},"tips":[{"en":"Nothing needs it, so sell it unless you want it on display.","zh":"没有任何需求，不想展示就卖掉。"}],"sources":["https://arcraiders.wiki/wiki/Playing_Cards"],"version":"2.0"},"possibly_toxic_plant":{"verdict":{"en":"Quest-only: Lance wants one for A New Type of Plant.","zh":"任务专用：兰斯的“新型植物”需要 1 株。"},"obtain":{"en":"Dam Battlegrounds, growing on the Baron Husk in the Old Battleground. Collect it in the same raid and take it to Lance.","zh":"大坝战场旧战场的“男爵”残骸上。同一局内采集，再交给兰斯。"},"tips":[{"en":"Rewards are a Vita Shot and 5 Antiseptic.","zh":"奖励是 1 支生命针剂和 5 个防腐剂。"}],"sources":["https://arcraiders.wiki/wiki/Possibly_Toxic_Plant","https://arcraiders.wiki/wiki/A_New_Type_Of_Plant"],"version":"2.0"},"poster_of_natural_wonders":{"verdict":{"en":"A 2,000-coin sell item with no other use.","zh":"纯卖钱物品，2000 钱币，别无他用。"},"obtain":{"en":"Scavenged in Residential and Commercial areas, with no specific container listed.","zh":"在住宅区和商业区搜刮，没有指定容器。"},"sources":["https://arcraiders.wiki/wiki/Poster_Of_Natural_Wonders"],"version":"2.0"},"potted_plant":{"verdict":{"en":"A 1,000-coin sell item added in 2.0, with no known use.","zh":"2.0 新增的卖钱物品，1000 钱币，暂无其他用途。"},"obtain":{"en":"No community source covers its spawn yet, so I can't say where to look.","zh":"目前没有社区资料说明刷新位置。"},"sources":["https://arcraiders.wiki/wiki/Potted_Plant"],"version":"2.0"},"pottery":{"verdict":{"en":"A 2,000-coin sell item. The wiki calls it fragile, so don't bring it into a fight.","zh":"卖钱物品，2000 钱币。维基称它很易碎，别带着打架。"},"obtain":{"en":"Scavenged in Old World and Residential areas, with no specific container listed.","zh":"在旧世界和住宅区搜刮，没有指定容器。"},"sources":["https://arcraiders.wiki/wiki/Pottery"],"version":"2.0"},"precision_gimbal":{"verdict":{"en":"Quest-only: it finishes Tian Wen's Safe Harbor, so keep it and carry it in a Safe Pocket.","zh":"任务专用：用来完成天玟的“安全港湾”，放进安全口袋。"},"obtain":{"en":"Riven Tides. Photograph the clue near the kitchen in Hotel Panorama Azzurro, then dig it up at the Tennis Court to the south. Guides disagree on the exact spot, with one saying behind a bench and another saying the northwest corner. A Bombardier may be nearby.","zh":"裂潮镇。先在蔚蓝全景酒店厨房附近拍下线索，再到南边网球场挖掘。攻略对具体位置说法不一，有说长椅后面，有说西北角。附近可能有投弹手。"},"tips":[{"en":"Complete everything in a single raid. The rewards are a Surge Coil, Heavy Gun Parts and a Horizontal Grip.","zh":"需在同一局内完成。奖励是涌能线圈、重型枪械零件和水平握把。"}],"sources":["https://arcraiders.wiki/wiki/Precision_Gimbal","https://arcraiders.wiki/wiki/Safe_Harbor","https://www.destructoid.com/how-to-complete-safe-harbor-in-arc-raiders/"],"version":"2.0"},"project_heartwood_blueprints":{"verdict":{"en":"Quest-only: Stable Housing needs one, and it pays out 5 Seeker Grenades, 5 Lure Grenades and a Snap Hook.","zh":"任务专用：“稳固住宅”需要 1 份，奖励 5 颗追踪手雷、5 颗诱捕手雷和安全钩。"},"obtain":{"en":"Stella Montis, from the safe in a side room by the Security Bridge's third-floor stairs. Print a key at the Access Card Printer in the fourth-floor control room, or find the numeric code on the third floor. Do it all in one raid.","zh":"星辰山，位于安保区过道桥三楼楼梯旁侧室的保险箱。在四楼控制室的门禁卡打印机制作钥匙，或在三楼找数字密码。需在同一局内完成。"},"sources":["https://arcraiders.wiki/wiki/Project_Heartwood_Blueprints","https://arcraiders.wiki/wiki/Stable_Housing"],"version":"2.0"},"project_pathos_empathy_core":{"verdict":{"en":"Quest-only: it finishes Lance's Empathetic Prototypes and has no sell price.","zh":"任务专用：用来完成兰斯的“共情原型机”，无售价。"},"obtain":{"en":"The Spaceport, in the North Trench Tower at the northern edge. Grapple up, go down the stairs, drop onto the crane's cargo crate and release it, then take the core. Bring a Safe Pocket augment for the grappling hook and the core.","zh":"太空港北端的北壕沟塔。用抓钩上塔、下楼梯、跳上吊臂货箱并解除锁定，然后取走核心。带有安全口袋的增强件，用来放抓钩和核心。"},"tips":[{"en":"The reward is a Canto I and 5,000 XP.","zh":"奖励是“颂歌” I 和 5000 经验。"}],"sources":["https://arcraiders.wiki/wiki/Project_Pathos_Empathy_Core","https://www.destructoid.com/how-to-complete-empathetic-prototypes-in-arc-raiders/","https://games.gg/arc-raiders/guides/arc-raiders-how-to-complete-empathetic-prototypes-quest/"],"version":"2.0"},"purification_system_blueprint":{"verdict":{"en":"Quest-only: it finishes Apollo's The Clean Dream, and has no sell price.","zh":"任务专用：用来完成阿波罗的“净梦计划”，无售价。"},"obtain":{"en":"The Blue Gate, in the Maintenance Bunker near the centre of the map. After monitoring the Purification System, crawl through the vent in the back-left corner, climb the ladder, and photograph the folders on the desk. The quest also needs a Spaceport step, so it takes two raids.","zh":"蓝门中部的维护区地堡。监控净化系统后，从左后角通风口爬进去，上梯子，拍下桌上的文件夹。任务还有太空港的步骤，需要两局。"},"tips":[{"en":"Rewards are 2 Deadline, 3 Showstopper and 3 Heavy Fuze Grenades.","zh":"奖励是 2 把“死线”、3 把“耀眼明星”和 3 颗重型引信手雷。"}],"sources":["https://arcraiders.wiki/wiki/Purification_System_Blueprint","https://arcraiders.wiki/wiki/The_Clean_Dream","https://primagames.com/tips/how-to-finish-the-clean-dream-quest-in-arc-raiders"],"version":"2.0"},"raider_flag":{"verdict":{"en":"Quest-only: raise it for A Symbol of Unification; otherwise it is a 100-coin sell.","zh":"任务专用：用于“团结的象征”，不做任务只值 100 钱币。"},"obtain":{"en":"Dam Battlegrounds, at the Formicai Outpost, in a bag on the medical bed. Raise it on the small platform overlooking the Red Lakes, all in one raid.","zh":"大坝战场蚁丘山哨站，医疗床上的一个包里。在俯瞰红湖的小平台升起，需在同一局内完成。"},"tips":[{"en":"Rewards are the Aviator outfit, 3 Mod Components and 5 Duct Tape.","zh":"奖励是飞行员服装、3 个改装零件和 5 卷胶带。"}],"sources":["https://arcraiders.wiki/wiki/Raider_Flag","https://arcraiders.wiki/wiki/A_Symbol_Of_Unification"],"version":"2.0"},"red_coral_jewelry":{"verdict":{"en":"The best-paying of the plain valuables: nothing current needs it, so sell it.","zh":"这类普通贵重品里卖价最高的一件：目前没有需求，直接卖。"},"use":{"en":"No live project, quest or workshop upgrade asks for it, so it is purely a 5,000-coin sale item.","zh":"现行项目、任务和工坊升级都不需要它，纯粹是卖 5000 钱币的物品。"},"obtain":{"en":"Scavenged from loot in Residential, Old World and Commercial areas. The wiki names no fixed container, so check shelves, drawers and cabinets in houses and shops.","zh":"在住宅、旧世界和商业类区域的搜刮点出现，社区没有固定容器的记录，进屋翻柜子和抽屉即可。"},"tips":[{"en":"It cannot be recycled and weighs only 0.3, so it costs almost no space for the money.","zh":"无法回收，重量仅 0.3，占背包很少，却很值钱。"}],"sources":["https://arcraiders.wiki/wiki/Red_Coral_Jewelry"],"version":"2.0"},"rosary":{"verdict":{"en":"Sell it unless you still need the one from A Warm Place To Rest; it is a mid-value pickup.","zh":"中等价值的拾取物，除非还要交温暖的休憩之地，否则直接卖。"},"obtain":{"en":"Spawns as loot in Old World and Residential areas. You also get one as a reward for the Buried City quest A Warm Place To Rest (Apollo).","zh":"出现在旧世界和住宅类区域的搜刮点。掩埋废城任务“温暖的休憩之地”（阿波罗）也会送你 1 个。"},"tips":[{"en":"Nothing in the workshop or projects needs it. A displayed copy in the Raider Den is the only reason to keep one.","zh":"工坊和项目都不需要它，留一个只可能是为了摆在奇袭者巢穴里。"}],"sources":["https://arcraiders.wiki/wiki/Rosary","https://arcraiders.wiki/wiki/A_Warm_Place_To_Rest"],"version":"2.0"},"rubber_duck":{"verdict":{"en":"A cheap, harmless noisemaker: keep one for the Raider Den or distraction, sell the extras.","zh":"便宜好玩的噪音道具：留一只摆放或引开敌人，多的卖掉。"},"use":{"en":"Throw it to make noise and pull attention away. Since 2.0 you can also squeeze it while holding it, so you do not lose the duck.","zh":"可以扔出去制造声响分散注意力；2.0 起手持时直接捏一下就会响，不用丢掉它。"},"obtain":{"en":"Found in rooftop chimneys on Buried City while the Bird City condition is active. Without that condition it is far rarer.","zh":"掩埋废城出现“鸟城”条件时，在屋顶烟囱里能找到；没有该条件时很难遇到。"},"tips":[{"en":"It stacks to 15 and fits an Augment trinket slot, so one duck costs you nothing to carry.","zh":"可叠加 15 个，也能放进增强装置的饰品槽，带一只几乎没成本。"}],"sources":["https://arcraiders.wiki/wiki/Rubber_Duck","https://arcraiders.wiki/wiki/Bird_City"],"version":"2.0"},"scout_patrol_note":{"verdict":{"en":"Quest item for Dust on the Wires; not worth carrying for any other reason.","zh":"仅用于“线路积尘”的任务物品，别的用途没有。"},"obtain":{"en":"Take the quest from Shani, then search the scouts' remains near the Maintenance Hangar on The Spaceport. Start at an eastern Field Depot to follow their trail.","zh":"向萨尼接任务，到太空港维护区机库附近搜查侦察兵的遗骸即可拿到。可从东侧的前线仓库开始顺着踪迹找。"},"tips":[{"en":"Do the radio and terminal steps first; the note only matters once you hand it in.","zh":"先完成电台和终端的步骤，笔记交付才有意义。"}],"sources":["https://arcraiders.wiki/wiki/Scout_Patrol_Note","https://arcraiders.wiki/wiki/Dust_on_the_Wires"],"version":"2.0"},"secret_meeting_info":{"verdict":{"en":"Quest item for Furtive Meetings; pick it up on Stella Montis and hand it to Shani.","zh":"“秘密集会”的任务物品，在星辰山拿到后交给萨尼。"},"obtain":{"en":"Stella Montis. The quest marks three meeting spots: under a staircase in the Medical Research Area, by the vent shaft between Robotic Sandbox B and the Seed Vault, and at the foot of the stairs linking the Cultural Archives and the Seed Vault. The wiki does not say which one holds it, so check them all in one raid.","zh":"星辰山。任务标出三处集会点：医学研究部楼梯下、机器人沙盘B 与种子库之间的通风井旁，以及文化档案馆与种子库之间的楼梯底部。社区未说明具体在哪一处，一局内全部查一遍最稳。"},"tips":[{"en":"The reward is an Aphelion and 5 Energy Clips, so it is worth finishing once.","zh":"奖励是一把“远日点”和 5 个能量弹匣，值得做完。"}],"sources":["https://arcraiders.wiki/wiki/Secret_Meeting_Info","https://arcraiders.wiki/wiki/Furtive_Meetings"],"version":"2.0"},"sextant":{"verdict":{"en":"Plain 2,000-coin sale item now; Clean Hands is the only free copy you will get.","zh":"现在只是个卖 2000 钱币的物品，“清理指针”送的那个是唯一的免费来源。"},"use":{"en":"No live project, quest or workshop upgrade asks for it, so it is purely a sale item.","zh":"现行项目、任务和工坊升级都不需要它，纯粹是卖钱的物品。"},"obtain":{"en":"Plain scavenged loot; the wiki gives no fixed spawn spots. Clean Hands gives you one.","zh":"属于普通搜刮物，社区没有固定刷新点。“清理指针”任务会送你 1 个。"},"tips":[{"en":"Stack size is 5 and it cannot be recycled, so sell in batches.","zh":"一组可叠 5 个，无法回收，攒几个一起卖。"}],"sources":["https://arcraiders.wiki/wiki/Sextant","https://arcraiders.wiki/wiki/Converging_Paths"],"version":"2.0"},"silver_teaspoon_set":{"verdict":{"en":"Rare household valuable worth 3000: light, unrecyclable, just sell it.","zh":"3000 的稀有家居贵重品，轻便又不能回收，直接卖。"},"obtain":{"en":"Found in houses and shops across Residential, Old World and Commercial areas; look in cupboards and drawers.","zh":"分布在住宅、旧世界和商业类区域，翻橱柜和抽屉就有机会遇到。"},"tips":[{"en":"Nothing needs it, so it only ever earns coins.","zh":"没有任何任务或项目需要，只能换钱。"}],"sources":["https://arcraiders.wiki/wiki/Silver_Teaspoon_Set"],"version":"2.0"},"sirena_dorata_ship_model":{"verdict":{"en":"Epic ship model worth 7,000 coins: nothing current needs it, so sell it.","zh":"7000 钱币的史诗级舰船模型：目前没有需求，卖掉。"},"use":{"en":"No live project, quest or workshop upgrade asks for it, so the sale price is its whole value.","zh":"现行项目、任务和工坊升级都不需要它，售价就是它的全部价值。"},"obtain":{"en":"Mostly Riven Tides: shipping containers, suitcases, trash bins and control panels in the stacking yard. These are community-recorded spawns; I could not confirm them for other maps.","zh":"主要在裂潮镇：集装箱、行李箱、垃圾桶，以及堆料场的控制面板。以上为社区记录的刷新点，其他地图未能确认。"},"tips":[{"en":"It stacks to 3 and cannot be recycled, so the sale price is its whole value.","zh":"可叠加 3 个且不能回收，售价就是它的全部价值。"}],"sources":["https://arcraiders.wiki/wiki/Sirena_Dorata_Ship_Model","https://arcraidershub.com/guides/ship-model-locations-guide"],"version":"2.0"},"stack_of_movie_tapes":{"verdict":{"en":"Quest item for Movie Night: grab it in the Cultural Archives and hand it to Apollo.","zh":"“电影之夜”的任务物品，在文化档案馆拿到后交给阿波罗。"},"obtain":{"en":"Stella Montis, Cultural Archives. The area is well guarded. Apollo wants intact tapes, not torn ones. First deliver a Portable TV to him.","zh":"星辰山文化档案馆，守卫较多。阿波罗要的是完好的录像带，破损的不行。需先给他交一台便携电视。"},"tips":[{"en":"Rewards are 3 Showstoppers, 3 Smoke Grenades and a Fireworks Box. Requires finishing With A View first.","zh":"奖励为 3 个“耀眼明星”、3 枚烟雾手雷和 1 个烟花箱，需先完成“美景在望”。"}],"sources":["https://arcraiders.wiki/wiki/Stack_of_Movie_Tapes","https://arcraiders.wiki/wiki/Movie_Night"],"version":"2.0"},"statuette":{"verdict":{"en":"Sell it: 3000 coins for 0.3 weight and nothing else needs it.","zh":"直接卖：重量 0.3 就值 3000，没有任何其他用途。"},"obtain":{"en":"Appears in Old World and Residential areas as ordinary loot. No fixed container is known.","zh":"出现在旧世界和住宅类区域，属于普通搜刮物，没有固定容器的记录。"},"tips":[{"en":"Stacks to 3 and cannot be recycled.","zh":"可叠加 3 个，不能回收。"}],"sources":["https://arcraiders.wiki/wiki/Statuette"],"version":"2.0"},"tellurion":{"verdict":{"en":"Epic trinket worth 7,000 coins: nothing current needs it, so sell it.","zh":"7000 钱币的史诗级饰品，目前没有需求，卖掉。"},"use":{"en":"No live project, quest or workshop upgrade asks for it, so it is purely a sale item.","zh":"现行项目、任务和工坊升级都不需要它，纯粹是卖钱的物品。"},"obtain":{"en":"No fixed spawn is documented; it is scavenged loot, and A Path Not Yours gives one as a reward.","zh":"没有固定刷新点记录，属于搜刮物，“非你之路”任务也会奖励 1 个。"},"tips":[{"en":"It stacks only to 1, so each one takes a full slot; sell right after the raid.","zh":"一格只能放 1 个，局后尽快卖掉。"}],"sources":["https://arcraiders.wiki/wiki/Tellurion","https://arcraiders.wiki/wiki/Converging_Paths"],"version":"2.0"},"torn_book":{"verdict":{"en":"A 1000-coin common book: sell it if there is spare space, skip it otherwise.","zh":"1000 的普通旧书，有空位就捡来卖，没空位别管。"},"obtain":{"en":"Residential and Old World loot spots, mostly shelves and furniture.","zh":"在住宅和旧世界区域的搜刮点，多在书架和家具上。"},"tips":[{"en":"It is low value per slot compared to the rare trinkets, so do not make room for it.","zh":"相比稀有饰品性价比低，不用特意腾位置。"}],"sources":["https://arcraiders.wiki/wiki/Torn_Book"],"version":"2.0"},"train_model":{"verdict":{"en":"Sell it: 1,000 coins, stacks to 10, and nothing current needs it.","zh":"卖掉：1000 钱币，可叠 10 个，目前没有需求。"},"obtain":{"en":"General scavenged loot; no fixed spawn spots are known.","zh":"普通搜刮物，没有固定刷新点。"},"tips":[{"en":"A stack of 10 sells in one go, so wait until you have a few.","zh":"一组可叠 10 个，攒几个再一起卖。"}],"sources":["https://arcraiders.wiki/wiki/Train_Model","https://arcraiders.wiki/wiki/Converging_Paths"],"version":"2.0"},"tropical_duck":{"verdict":{"en":"A Bird City chimney find: keep one for the Raider Den, sell the rest.","zh":"鸟城条件下烟囱里的收获：留一只装饰，其余卖掉。"},"obtain":{"en":"Buried City only, in rooftop chimneys while Bird City is active.","zh":"仅限掩埋废城，出现“鸟城”条件时在屋顶烟囱中。"},"tips":[{"en":"It can be thrown to make noise, like other ducks.","zh":"和其他鸭子一样，可扔出制造声响。"}],"sources":["https://arcraiders.wiki/wiki/Tropical_Duck","https://arcraiders.wiki/wiki/Bird_City"],"version":"2.0"},"twilight_compass_ship_model":{"verdict":{"en":"A 1,000-coin sale item with no remaining use. Dump it after the raid.","zh":"1000 钱币的卖钱物品，已无其他用途，局后卖掉。"},"obtain":{"en":"Riven Tides, with chairs in the Panorama Azzurro Hotel the most mentioned spot; other spawns across the map.","zh":"裂潮镇，被提到最多的是蔚蓝全景酒店的椅子，地图其他地方也有。"},"tips":[{"en":"Stacks to 5 and cannot be recycled.","zh":"可叠 5 个，不能回收。"}],"sources":["https://arcraiders.wiki/wiki/Twilight_Compass_Ship_Model","https://arcraidershub.com/guides/ship-model-locations-guide"],"version":"2.0"},"unknown_arc_circuitry":{"verdict":{"en":"New in 2.0 with no sell price: community pages say nothing yet, so check it in game.","zh":"2.0 新增，无售价，社区暂无资料，请以游戏内为准。"},"tips":[{"en":"I found no wiki page for this item; do not assume it works like ARC Circuitry.","zh":"我没找到该物品的社区页面，别默认它和 ARC线圈相同。"}],"sources":["https://arcraiders.wiki/wiki/ARC_Circuitry"],"version":"2.0"},"vase":{"verdict":{"en":"Sell it for 3000, but handle it carefully because it is fragile.","zh":"卖 3000，但它很易碎，要小心。"},"obtain":{"en":"Old World, Residential and Commercial loot spots.","zh":"旧世界、住宅和商业类区域的搜刮点。"},"tips":[{"en":"The wiki warns the vase is super fragile; don't take hits while carrying it.","zh":"社区提示花瓶极易碎，携带时尽量别挨打。"}],"sources":["https://arcraiders.wiki/wiki/Vase"],"version":"2.0"},"velocity_ship_model":{"verdict":{"en":"Cash it in at 3,000 coins; no quest or project wants it now.","zh":"直接兑现 3000 钱币，现在没有任务或项目要它。"},"obtain":{"en":"Chairs and furniture on Riven Tides, plus suitcases and trash; also Grandioso Apartments (Buried City), Ruby Residents and Pale Apartments (Dam Battlegrounds).","zh":"裂潮镇的椅子和家具、行李箱与垃圾堆；掩埋废城的奢华公寓、大坝战场的红宝石宅邸和苍白公寓也有记录。"},"tips":[{"en":"3000 coins and stacks to 3.","zh":"3000，可叠 3 个。"}],"sources":["https://arcraiders.wiki/wiki/Velocity_Ship_Model","https://arcraidershub.com/guides/ship-model-locations-guide"],"version":"2.0"},"very_comfortable_pillow":{"verdict":{"en":"Keep 3 for the Scrappy level 5 upgrade, then sell the rest.","zh":"为废品仔 5 级升级留 3 个，其余卖掉。"},"obtain":{"en":"Residential and Commercial loot spots, usually furniture and beds.","zh":"在住宅和商业类区域的搜刮点，通常在家具和床上。"},"tips":[{"en":"Scrappy level 5 also needs 12 Mushrooms and 12 Apricots.","zh":"废品仔 5 级还需要 12 个蘑菇和 12 个杏子。"}],"sources":["https://arcraiders.wiki/wiki/Very_Comfortable_Pillow","https://arcraiders.wiki/wiki/Scrappy"],"version":"2.0"},"vintage_steering_wheel":{"verdict":{"en":"Worth 2,000 coins and nothing more; sell it when you extract.","zh":"只值 2000 钱币，别无他用，撤离后卖掉。"},"obtain":{"en":"General scavenged loot; no fixed spots known.","zh":"普通搜刮物，没有固定刷新点。"},"tips":[{"en":"Stacks to 5, cannot be recycled.","zh":"可叠 5 个，不能回收。"}],"sources":["https://arcraiders.wiki/wiki/Vintage_Steering_Wheel","https://arcraiders.wiki/wiki/Converging_Paths"],"version":"2.0"},"wind_sprite_ship_model":{"verdict":{"en":"The cheapest ship model: sell it for 1,000 coins or display it.","zh":"最便宜的舰船模型：卖 1000 钱币或摆放。"},"obtain":{"en":"A chair in the Panorama Azzurro Hotel on Riven Tides is the documented spot.","zh":"有记录的位置是裂潮镇蔚蓝全景酒店的一把椅子。"},"tips":[{"en":"Stacks to 10 and cannot be recycled.","zh":"可叠 10 个，不能回收。"}],"sources":["https://arcraiders.wiki/wiki/Wind_Sprite_Ship_Model","https://arcraidershub.com/guides/ship-model-locations-guide"],"version":"2.0"},"arpeggio":{"verdict":{"en":"A cheap, forgiving burst rifle that is fine against raiders, mediocre against ARC, and not worth chasing as an endgame gun.","zh":"便宜好上手的三连发步枪，打玩家够用，打 ARC 一般，别当终局武器。"},"use":{"en":"It is the only burst-fire rifle, so it rewards short, aimed bursts at mid to long range and punishes spraying. Community tier lists put it around B in PvP and C in PvE: armor penetration is only moderate, so aim at the weak spots on the back of ARC. Players commonly run a Compensator, Vertical Grip, Extended Medium Mag and Padded Stock; the grip and stock trade away ADS speed.","zh":"它是唯一的三连发步枪，适合中远距离短点射，乱扫很吃亏。社区评级大致是 PvP 为 B、PvE 为 C：对 ARC 的穿甲只有中等，要打 ARC 背面的弱点。常见配件是补偿器、垂直握把、中型扩容弹匣和减震枪托，握把与枪托会拖慢开镜。"},"obtain":{"en":"Craft Arpeggio I at the Gunsmith (level 2) from common Mechanical Components and Simple Gun Parts, or take the one from the Broken Monument quest. Tian Wen also sells it, but at 16,500 coins and limited stock, crafting is far cheaper.","zh":"在武器工作台（2 级）制作“三连奏 I”，材料是常见的机械元件和简易枪械零件制作，或领取任务“破败的纪念”的奖励。天玟也卖，但要 16500 钱币且限购，自己做便宜得多。"},"tips":[{"en":"Tier III is the sweet spot if materials are tight; Tier IV costs a Medium Gun Parts to reach and gives the biggest fire-rate and reload jump.","zh":"材料紧张时升到 III 级就够用；IV 级要多花中型枪械零件，但射速和换弹提升最大。"},{"en":"Repairs cost the same part types as the gun is worth in recycling, so keep it as a throwaway mid-tier loadout rather than a gun you baby.","zh":"修理耗材与回收所得同类，适合当随便带的中档配装，不必太心疼。"}],"sources":["https://arcraiders.wiki/wiki/Arpeggio","https://nerdschalk.com/arc-raiders-arpeggio-location-crafting-usage-guide/","https://www.iggm.com/news/arc-raiders-why-arpeggio-is-dominating-headwinds-update-meta","https://www.dexerto.com/wikis/arc-raiders/arpeggio"],"version":"2.0"},"bettina":{"verdict":{"en":"An armor-breaking heavy-ammo rifle: excellent against big ARC and bosses, but a poor PvP pick that burns expensive ammo.","zh":"重型弹破甲步枪：打大型 ARC 和首领很强，PvP 表现差且费弹。"},"use":{"en":"Its job is armored ARC. After the 1.26.0 buff it hits Rocketeers, Shredders and Bombardiers hard, and is only okay against Hornets and Wasps where heavy ammo is wasted. In PvP its time-to-kill trails Anvil and Venator, and the same buff slightly raised light-shield TTK, so most players use a medium-ammo rifle for duels. Common builds are a Muzzle Brake or Compensator, Angled Grip and Padded Stock. Ammo supply, not durability, is the limit: bring a full heavy stack.","zh":"它的定位是对付带装甲的 ARC。1.26.0 加强后，打火箭手、粉碎者和投弹手很猛，打马蜂和黄蜂则浪费重型弹。PvP 里击杀速度不如铁砧和“复仇者”，多数人对枪会换成中型弹步枪。常见配置是枪口制退器或补偿器、直角握把和减震枪托。限制你的是弹药而非耐久，出发前备满一组重型弹。"},"obtain":{"en":"Learn the Bettina blueprint, then craft it at the Gunsmith (level 3); it is not sold by traders. Bettina I is also a reward from the quest Sizing Things Up, and Bettina III from Nothing Gained, so quest players can skip the build.","zh":"先学会贝蒂娜蓝图，再在武器工作台（3 级）制作，商人不出售。任务“审时度势”奖励贝蒂娜 I，“不入虎穴”奖励贝蒂娜 III，做这些任务可以省掉制作。"},"amplified":{"en":"Amplifying needs a Mk. IV (Epic) Amplification Module and a Tier IV gun, and the choice is permanent. Players rate Semi-Auto into X-Rounds highest for armored ARC (explosive rounds, extra armor damage). Bigger Mag keeps full-auto and raises the mag from 22 to 37 for boss dumps. Repairs run on Amplified Fragments and get steep: 17 for the base, 27 for Bigger Mag or Semi-Auto, 35 for X-Rounds.","zh":"增强需要 Mk. IV（史诗）增强模块和 IV 级枪，选择不可更改。玩家最看好“半自动改装 + 爆裂弹”用来打装甲 ARC（爆裂弹对装甲伤害更高）。“扩容弹匣”保持全自动，弹匣由 22 发升到 37 发，适合对首领倾泻。修理要消耗增强碎片，价格很高：基础款 17，扩容或半自动款 27，爆裂弹款 35。"},"tips":[{"en":"Solo, save it for confirmed heavy ARC fights; in a squad let one player carry the armor-breaking gun.","zh":"单人时只在确认遇到重型 ARC 时再带；组队时让一人负责破甲即可。"},{"en":"Repair needs Advanced Mechanical Components and Heavy Gun Parts every time, so unamplified Tier IV is far cheaper to run than any Amplified version.","zh":"每次修理都要高级机械元件和重型枪械零件；未增强的 IV 级运营成本比任何增强版低得多。"}],"sources":["https://arcraiders.wiki/wiki/Bettina","https://allthings.how/buffed-bettina-vs-every-arc-enemy-in-arc-raiders/","https://finalboss.io/game/arc-raiders/weapon/bettina","https://www.dexerto.com/wikis/arc-raiders/weapons/assault-rifle/bettina/","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://powerupgaming.co.uk/2026/10/09/arc-raiders-frozen-trail-best-amplified-weapon-paths/"],"version":"2.0"},"kettle":{"verdict":{"en":"A cheap, accurate light-ammo PvP starter that is useless against armored ARC; the Amplified Full-Auto version is its best upgrade.","zh":"便宜准确的轻型弹 PvP 入门枪，打装甲 ARC 基本没用；增强后的全自动版最值得升。"},"use":{"en":"Quick, stable and light-ammo efficient, it suits close to medium-range duels with controlled shots. Armor penetration is Very Weak, so carry something else for ARC. Its fire rate was capped at 450 RPM in 1.11.0 after macro abuse, and base damage dropped from 10 to 8.5 in 1.17.0, so it is viable but no longer automatic. Guides suggest angled grips, muzzle brakes and bigger mags.","zh":"射击快、稳定、轻型弹省，适合近中距离控制点射对枪。对 ARC 的穿甲极弱，打 ARC 要另带枪。1.11.0 因宏滥用把射速上限砍到 450 RPM，1.17.0 又把基础伤害从 10 降到 8.5，所以仍可用，但不再是无脑之选。攻略常推荐斜握把、制退器和扩容弹匣。"},"obtain":{"en":"It is the easiest rifle to access: craft it at Gunsmith or Workbench level 1, buy it from Tian Wen for 2,520 coins, or find it in raids. Some raiders also spawn with it in a free loadout.","zh":"这是最容易拿到的步枪：武器工作台或工作台 1 级即可制作，天玟处 2520 钱币可买，局内也能捡到，部分免费配装也会带。"},"amplified":{"en":"Needs only a cheap Mk. I (Common) module. Full-Auto, or Anti-Shield plus Full-Auto, is the PvP pick players name; X-Rounds is the PvE option and lifts armor penetration to Moderate. Repairs are costly for such a cheap gun: 17 Amplified Fragments for Full-Auto or Anti-Shield, 27 for both, 15 for X-Rounds.","zh":"只需便宜的 Mk. I（普通）模块。玩家推荐的 PvP 路线是全自动，或破盾强化加全自动；爆裂弹偏 PvE，会把穿甲提升到中等。对一把便宜枪来说修理很贵：全自动或破盾款 17 个增强碎片，两者兼备 27，爆裂弹款 15。"},"tips":[{"en":"Tier IV Kettle sells for 5,000 but recycles into only Mechanical Components and Simple Gun Parts, so sell spare ones.","zh":"水壶 IV 售价 5000，回收只得机械元件和简易枪械零件，多余的直接卖掉。"},{"en":"Do not amplify it unless you will really use it: a single repair of the best variant costs more than the base rifle is worth to most players.","zh":"除非真会常用，不要增强：最高档变体修一次的成本，对多数玩家来说比整把基础枪还贵。"}],"sources":["https://arcraiders.wiki/wiki/Kettle","https://nerdschalk.com/arc-raiders-kettle-assault-rifle-location-upgrade-guide/","https://nerdschalk.com/arc-raiders-pvp-balance-update-why-the-kettle-and-trigger-nade-were-nerfed/","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/"],"version":"2.0"},"rattler":{"verdict":{"en":"A cheap, cheerful budget rifle that is fine to learn on, but outclassed in PvP and awkward to reload.","zh":"便宜好用的入门步枪，PvP里吃亏，换弹也别扭。"},"use":{"en":"Best at close to mid range in short fights. It loads only 2 rounds per reload step, so a long reload mid-fight is deadly; top the mag up between fights. Community tier lists put it at C: fine as a cheap kit, not a pick for contested PvP. Tier IV's 24-round mag helps a lot, and repairs stay cheap through Tier III.","zh":"适合中近距离的短促交火。它每次只能装填2发，战斗中途换弹很危险，所以交火间隙就把弹匣补满。社区强度榜把它放在C档：作为低成本配装不错，但不适合高强度PvP。IV级的24发弹匣改善明显，III级以前维修也很便宜。"},"obtain":{"en":"Common in weapon crates and loot rooms; one guide points to the eastern sectors and red towers on Dam Battlegrounds and the Hydroponic Dome Complex. The Gunsmith L1 can craft it, and Picking Up The Pieces rewards a Rattler III.","zh":"武器箱和战利品房间里很常见；有攻略推荐大坝战场的东部区域和红色高塔，以及水培穹顶综合体。武器工作台1级即可制造，任务“积少成多”还会奖励一把响尾蛇 III。"},"amplified":{"en":"Amplified Rattler (unlocked via the Gunsmith, Research Station and an Amplification Module) offers More Reload, Drum Mag (+40 rounds, but more recoil and slower aim) and Incendiary Rounds (burn damage over time). Players mostly rate Drum Mag first, More Reload as the safe pick, and Incendiary the least. Repairs need Amplified Fragments: 7 at the base, 35 for the full tree.","zh":"增强型“响尾蛇”需要武器工作台、研究站和增强模块解锁，可选高效装填、弹鼓弹匣（+40发，但后坐力更大、瞄准更慢）和燃烧弹（持续灼烧）。玩家最看好弹鼓弹匣，高效装填求稳，燃烧弹评价最低。维修要消耗增强碎片：基础款7个，满配树35个。"},"tips":[{"en":"The 2.0 patch notes list no Rattler changes; the last known buff was in 1.7.0 (base mag 10 to 12).","zh":"2.0更新日志没有响尾蛇的改动；已知最近一次加强在1.7.0（基础弹匣由10增至12）。"},{"en":"Spare Rattler IIIs are better recycled than sold: they return Mechanical Components and Simple Gun Parts, worth more than the 5000 coin sale.","zh":"多余的“响尾蛇” III回收能得到机械元件和简易枪械零件，比卖5000钱币更划算。"},{"en":"Amplified Rattlers drop to 10% durability if you die, so budget for fragments before you bring the 35-fragment build.","zh":"增强型“响尾蛇”在你死亡后耐久会掉到10%，带满配款出战前先算好碎片够不够修。"}],"sources":["https://arcraiders.wiki/wiki/Rattler","https://nerdschalk.com/arc-raiders-rattler-assault-rifle-loot-craft-and-upgrades-guide/","https://www.dexerto.com/wikis/arc-raiders/weapon-tier-list-pvp-arc-raiders","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/","https://powerupgaming.co.uk/2026/10/09/arc-raiders-frozen-trail-best-amplified-weapon-paths/","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://insider-gaming.com/complete-arc-raiders-frozen-trail-2-0-update-patch-notes/"],"version":"2.0"},"tempest":{"verdict":{"en":"One of the best all-round assault rifles for PvP, but the blueprint is a grind and repairs use pricey parts.","zh":"PvP表现最好的突击步枪之一，但蓝图难刷，维修材料也不便宜。"},"use":{"en":"Stable, full-auto and usable at almost any range, which is why tier lists rate it S in PvP and B in PvE. Each upgrade cuts recoil and reload time substantially, so Tier IV is where it really shines. It hits for modest damage per bullet, so it is no heavy ARC killer.","zh":"稳定、全自动，几乎任何距离都能用，因此强度榜给PvP评S、PvE评B。每次升级都明显降低后坐力和换弹时间，IV级才是完全体。单发伤害一般，不适合当对付ARC的主力。"},"obtain":{"en":"Learn the Tempest Blueprint, then craft at Gunsmith L3. It is a random drop from weapon cases, raider caches and security lockers; guides suggest Buried City night raids or First Wave Caches during a Hurricane condition (older tips, check current events).","zh":"先学会风暴蓝图，再到武器工作台3级制造。蓝图是武器箱、掠袭者储物箱和安保柜里的随机掉落；有攻略推荐掩埋废城夜间突袭，或飓风条件下的头波物资箱（较早的建议，请以当前活动为准）。"},"tips":[{"en":"Repairs get dear at Tier IV (5 Advanced Mechanical Components and 4 Medium Gun Parts), so only bring IV when you plan to fight.","zh":"IV级维修要5个高级机械元件和4个中型枪械零件，打算认真交战时再带。"},{"en":"Recycling returns exactly what a repair costs, so a worn spare is never wasted.","zh":"回收所得与一次维修的材料相当，用旧的备用枪也不亏。"},{"en":"No Tempest balance changes appear in the 2.0 patch notes.","zh":"2.0更新日志里没有风暴的改动。"}],"sources":["https://arcraiders.wiki/wiki/Tempest","https://www.dexerto.com/wikis/arc-raiders/weapons/assault-rifle/tempest/","https://www.dexerto.com/wikis/arc-raiders/weapon-tier-list-pvp-arc-raiders","https://allthings.how/arc-raiders-tempest-blueprint-location-where-it-drops-and-what-to-farm/","https://nerdschalk.com/arc-raiders-tempest-assault-rifle-location-and-unlock-guide/","https://insider-gaming.com/complete-arc-raiders-frozen-trail-2-0-update-patch-notes/"],"version":"2.0"},"torrente":{"verdict":{"en":"A close-range bullet hose with a huge mag; fun and good for PvE, but handling and accuracy keep it out of serious PvP.","zh":"近距离的大弹匣火力泼洒枪；PvE好用，但操控和精度限制了PvP。"},"use":{"en":"Fire crouched, since it is only accurate then, and stay within close quarters. Players report it shreds raiders at short range but has slow pull-out and aim speed. Rated C in PvP and B in PvE. It eats Medium Ammo fast, so bring plenty or let a squadmate carry it.","zh":"只有蹲下时才准，请蹲射并保持近距离作战。玩家反映它在近处能迅速撕碎对手，但拔枪和开镜都慢。PvP评C，PvE评B。它很耗中型弹药，要多带，或交给队友使用。"},"obtain":{"en":"Craft it at Gunsmith L2 after learning the blueprint; Tian Wen also sells Tier I for 21000 coins (limit 1). Guides name blueprint spots at Marano Station, South Swamp Outpost, Pale Apartments, Testing Annex and Water Treatment Complex.","zh":"学会蓝图后在武器工作台2级制造；天玟也出售I级，售价21000钱币（限购1）。攻略提到的蓝图地点有马拉诺站、南沼泽前哨、苍白公寓、测试附楼和水处理综合体。"},"tips":[{"en":"Repairs are cheap (1 Advanced Mechanical Component and 1 Medium Gun Part at Tier I), but ammo is the real cost.","zh":"维修便宜（I级只要1个高级机械元件和1个中型枪械零件），真正花钱的是弹药。"},{"en":"Tier IV's 45% faster reload matters, since a 90-round mag still empties quickly.","zh":"IV级换弹快45%很值，90发弹匣也很快打空。"},{"en":"A suppressor will not fully silence it. No 2.0 balance changes are listed.","zh":"消音器无法完全消除它的枪声。2.0没有列出平衡改动。"}],"sources":["https://arcraiders.wiki/wiki/Torrente","https://www.dexerto.com/wikis/arc-raiders/weapons/lmg/torrente/","https://www.shacknews.com/article/147982/the-best-weapons-in-arc-raiders","https://nerdschalk.com/your-guide-to-the-torrente-gun-in-arc-raiders-location-crafting-and-usage/","https://insider-gaming.com/complete-arc-raiders-frozen-trail-2-0-update-patch-notes/"],"version":"2.0"},"aphelion":{"verdict":{"en":"A strong mid-range energy burst rifle for PvP and armored ARC, but it drinks ammo and the Amplified versions are brutal to repair.","zh":"中距离能量连发步枪，PvP和打装甲ARC都强，但费弹，增强型修理极贵。"},"use":{"en":"Fires two-round bursts with Strong ARC armor penetration, good stability and long falloff range. Players compare it to the Il Toro: Toro kills in about two bursts at its best range, Aphelion needs about three, but Aphelion holds up better at distance. Play patiently, fire aimed bursts instead of spraying, and bring spare Energy Clips. A vertical grip tightens the pair of shots. It is also a respected anti-ARC pick.","zh":"两连发，对ARC护甲穿透强，稳定性好、有效距离远。玩家常拿它和“公牛”比：“公牛”最佳距离约两个连发击杀，“远日点”约要三个，但远距离更稳。别扫射，打瞄准的点射，多带能量弹匣。竖握把能让两发更集中；打ARC也很好用。"},"obtain":{"en":"No trader sells it. You need the Aphelion blueprint, which drops from the Matriarch (the drop was moved to Stella Montis in patch 1.7.0, so check there first), then craft it at Gunsmith level 3 with a Matriarch Reactor. The quest Furtive Meetings also rewards one.","zh":"商人不卖。需要“远日点”蓝图，来自“族母”（1.7.0起蓝图掉落改到星辰山，先去那里找），再在武器工作台3级用“族母”反应堆制作。任务“秘密集会”也会奖励一把。"},"amplified":{"en":"Amplified is the Mk. V route: Bigger Mag, Charged Burst (hold to charge), Increased Burst (a refined Charged Burst) and Incendiary Rounds (extra burn damage). Guides suggest taking all four, but I found no hands-on player verdicts yet. Every perk stacks repair cost: the plain Amplified needs 22 Amplified Fragments to repair, the full build 61.","zh":"增强型是Mk. V路线：扩容弹匣、蓄力连发（按住蓄力）、强化连发（蓄力连发的进阶版）和燃烧弹（附加灼烧伤害）。攻略建议四个全点，但目前还没找到玩家实测评价。每加一个词条修理费都上涨：基础增强型22个增强碎片，全词条要61个。"},"tips":[{"en":"Ammo use is the real cost: kills take extra bursts, so carry more clips than you would for a Toro.","zh":"真正的成本是耗弹：击杀要多打几个连发，弹匣要比带“托罗”时多备。"},{"en":"Don't send a full Amplified build into a risky raid: repair is 61 Amplified Fragments, while recycling returns only 35.","zh":"别带全词条增强型冒险：修理要61个增强碎片，回收才返35个。"},{"en":"The base rifle can't be upgraded through tiers; the Amplified path starts from it directly.","zh":"基础款无法升阶，增强型直接从它升级。"}],"sources":["https://arcraiders.wiki/wiki/Aphelion","https://nerdschalk.com/everything-changed-for-aphelion-in-arc-raiders-is-aphelion-finally-in-the-good-meta/","https://insider-gaming.com/where-to-find-aphelion-arc-raiders-guide-blueprint/","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://www.dexerto.com/wikis/arc-raiders/weapons/battle-rifle/aphelion"],"version":"2.0"},"ferro":{"verdict":{"en":"Cheap, hard-hitting single-shot rifle that is the best budget answer to ARC armor, but the one-round reload punishes misses in close fights.","zh":"便宜的单发重炮，是对付ARC护甲的最佳平价选择，但近战打偏就要挨打。"},"use":{"en":"Break-action, one round per reload, Heavy Ammo, Strong ARC penetration and a 2.5x headshot multiplier. Use it from distance on armored ARC and for opportunistic headshots on players; PvP ceiling is lower than pricier rifles and guides disagree (S to B tier). Always pair it with a fast backup like the Stitcher and drop the Ferro if someone rushes you.","zh":"折枪式，每发都要装填，用重型弹药，ARC护甲穿透强，爆头倍率2.5x。适合远距离打装甲ARC、对玩家找机会爆头；PvP上限不如昂贵步枪，各攻略评价从S到B不一。务必带“钉机”之类的速射副武器，被贴脸就别用“生铁”。"},"obtain":{"en":"Craft Ferro I at a Workbench with Gunsmith level 1 for a handful of Metal and Rubber Parts, or buy it from Tian Wen. Ferro IV comes from the quest The Right Tool, and the Free Loadout can include one.","zh":"在工作台（武器工作台1级）用少量金属零件和橡胶零件制作生铁 I，或向天玟购买。生铁 IV是任务“正确工具”的奖励，免费装备也可能带一把。"},"tips":[{"en":"Upgrades are cheap (mostly Metal Parts), and each tier cuts reload time, which matters most for this gun. Ferro IV cuts it by 39%.","zh":"升级便宜（主要是金属零件），每阶都缩短装填时间，这对它最关键。生铁 IV缩短39%。"},{"en":"A compensator tightens shots; a silencer helps if you don't want to draw ARC attention.","zh":"补偿器能让弹着更集中；不想引来ARC时可加消音器。"},{"en":"Repair is cheap at every tier, so it is a low-risk loadout when you don't want to lose a good gun.","zh":"各阶修理都便宜，不想亏好枪时是低风险之选。"}],"sources":["https://arcraiders.wiki/wiki/Ferro","https://www.shacknews.com/article/147982/the-best-weapons-in-arc-raiders","https://mein-mmo.de/en/arc-raiders-die-besten-waffen,1534763/","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://arcraiders.wiki/wiki/Compensator_II"],"version":"2.0"},"renegade":{"verdict":{"en":"Accurate lever-action rifle for medium to long range: great against players and flyers, weak against heavy armor and up close.","zh":"精准的杠杆步枪，中远距离打玩家和飞行ARC很强，打重甲和贴身战较弱。"},"use":{"en":"Medium Ammo, 8-round magazine, high headshot damage and pinpoint accuracy when standing or crouched. Players like it at 50-100 m, and it can shoot thrusters off Wasps and handle small ARC like Pops. Moderate armor penetration means it struggles on Bastions, and close-range weapons such as the Vulcano beat it. A Silencer II or better keeps shots quiet; a 2x marksman sight suits its range.","zh":"中型弹药，弹匣8发，爆头伤害高，站立或蹲下时极精准。玩家常在50到100米使用，可以打掉黄蜂的推进器，也能处理“爆爆”等小型ARC。护甲穿透一般，打“堡垒”吃力，近距离会被“火山”这类武器压制。消音器 II以上能保持静音，2倍瞄准镜很适合它的射程。"},"obtain":{"en":"Buy Renegade I from Tian Wen (one per day, 21,000 coins) or craft it at Gunsmith level 3. The quests Wires Crossed and Back on Top each reward one. If you want it cheap, take the quest copies.","zh":"向天玟购买叛逆 I（每日限1把，21000钱币），或在武器工作台3级制作。任务“线路交错”和“重占上风”各奖励一把，想省钱就靠任务拿。"},"amplified":{"en":"Amplified needs the Mk. III module, Gunsmith and Research Station level 4, and the Renegade at tier IV. Choices are More Reload (loads more rounds per reload) and Scoped (adds a scope). Guides rate Scoped highly for clearing flyers and long-range PvP and list both together as the recommended path, but it is the pricier one: 33 Amplified Fragments to repair.","zh":"增强需要Mk. III模块、武器工作台和研究站4级，且叛逆升到IV。可选高效装填（每次装填多装子弹）和加装瞄准镜。攻略称瞄准镜适合清飞行ARC和远程PvP，并推荐两个都选，但修理要33个增强碎片，花费最高。"},"tips":[{"en":"Tier upgrades are cheap (1 Advanced Mechanical Component plus 2 Medium Gun Parts each) and add up to 75% fire rate, so upgrade before you amplify.","zh":"升阶便宜（每阶1个高级机械元件加2个中型枪械零件），最高加75%射速，先升满再考虑增强。"},{"en":"Renegade IV repair costs 3 Advanced Mechanical Components plus 3 Medium Gun Parts; an Amplified one with no perks is much cheaper (13 fragments) than the full build.","zh":"叛逆 IV修理要3个高级机械元件和3个中型枪械零件；不选词条的增强型修理仅13个碎片，比全词条便宜得多。"},{"en":"Perk values come partly from preview builds, so check the in-game stats before committing.","zh":"词条数值部分来自测试版，投入前先看游戏内数据。"}],"sources":["https://arcraiders.wiki/wiki/Renegade","https://nerdschalk.com/arc-raiders-renegade-battle-rifle-stats-upgrades-farming/","https://www.shacknews.com/article/147982/the-best-weapons-in-arc-raiders","https://powerupgaming.co.uk/2026/10/09/arc-raiders-frozen-trail-best-amplified-weapon-paths/","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/"],"version":"2.0"},"burletta":{"verdict":{"en":"A cheap, accurate light-ammo sidearm for finishing raiders, but weak against ARC and rated only a niche PvP pick.","zh":"便宜准头好的轻型弹药副武器，适合补刀玩家，打ARC乏力。"},"use":{"en":"Fast semi-auto clicking with a 12-round mag makes it a decent backup for close fights against raiders. Against ARC its armor penetration is very weak, so bring a real primary for machines. PvE guides call it fine for light farming runs; PvP tier lists put it around C-tier. Players favor an extended light mag and a Muzzle Brake II to keep follow-up shots on target.","zh":"半自动连点配12发弹匣，近距离对付玩家的副武器够用。ARC护甲穿透极弱，对付机器要另带主武器。PvE攻略认为适合轻量搜刮，PvP排行多把它放在C档。玩家常配扩容轻型弹匣和枪口制退器 II，让连射更稳。"},"obtain":{"en":"Learn the blueprint (Burletta I is the Industrial Espionage reward), then craft at Gunsmith level 1. Tian Wen sells it for 8,700 coins, 3 a day, which is steep next to the cheap craft. It also turns up in ordinary loot. Burletta III is the Snap and Salvage reward.","zh":"学会蓝图后在武器工作台 1 级制作（“工业间谍”任务奖励布尔莱塔 I）。天玟每天限购 3 把、要价 8700 钱币，比自己制作贵得多。普通战利品里也能捡到。布尔莱塔 III 是“拍照并拆解回收”的奖励。"},"amplified":{"en":"Unlocking needs the Outpost, Gunsmith 4 and Research Station 4, plus a Mk. II module. Burst Fire (then Increased Burst) is the safe pick: players say it has almost no downside. Full-Auto trades headshot damage and recoil control for fire rate, and some players found it out-DPSed by a plain Bobcat. Sprint Shooting is an optional add-on.","zh":"解锁需要哨站、武器工作台 4 级、研究站 4 级和 Mk. II 模块。玩家最推荐连发模式（再升强化连发），几乎没有副作用。全自动以爆头伤害和后坐力控制换射速，有玩家测出伤害输出还不如普通“山猫”。冲刺射击可按需追加。"},"tips":[{"en":"Amplified repairs scale hard: plain Burst needs 21 Amplified Fragments, the full Burst + Increased Burst + Sprint Shooting build 41. Pick perks you will actually use.","zh":"增强版修理开销很大：只选连发模式需 21 个增强碎片，连发 + 强化连发 + 冲刺射击要 41 个，只选真正用得上的。"},{"en":"Crafting I is cheap and upgrades cost mostly Mechanical Components, so the Tian Wen price is not worth paying.","zh":"制作 I 阶便宜，升级主要吃机械元件，不值得花钱找天玟买。"}],"sources":["https://arcraiders.wiki/wiki/Burletta","https://nerdschalk.com/your-guide-to-the-burletta-pistol-in-arc-raiders-location-crafting-and-usage/","https://www.dexerto.com/wikis/arc-raiders/weapon-tier-list-pvp-arc-raiders","https://games.gg/arc-raiders/guides/arc-raiders-all-weapon-amplifications/","https://powerupgaming.co.uk/2026/10/09/arc-raiders-frozen-trail-best-amplified-weapon-paths/","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"hairpin":{"verdict":{"en":"A silenced stealth sidearm that is dirt cheap to run, but clumsy in a real fight and ranked bottom-tier for PvP.","zh":"自带消音、成本极低的潜行副武器，正面对枪很吃力，PvP 垫底。"},"use":{"en":"The slide-action cycling slows follow-up shots, and ARC armor penetration is very weak, so treat it as a quiet loot-run gun that will not wake the map. One tier list calls it D-tier for PvP. It has no muzzle or grip slot, only a light magazine mod.","zh":"拉栓式击发让连射很慢，对ARC的护甲穿透极弱，更适合安静搜刮、不惊动周围。有排行把它列为 PvP 的 D 档。它没有枪口和握把槽位，只能装轻型弹匣。"},"obtain":{"en":"The cheapest gun to start with: craft Hairpin I at a Workbench or Gunsmith from Metal Parts and Plastic Parts. Tian Wen also sells it, and weapon crates on Blue Gate, Dam Battlegrounds and The Spaceport can hold one. It is the one Common weapon not in a free loadout.","zh":"入门成本最低：在工作台或武器工作台用金属零件和塑料零件制作发夹 I。天玟也出售，蓝门、大坝战场、太空港的武器箱里可能刷出。它是唯一不在免费装备包里的普通品质武器。"},"amplified":{"en":"Needs the Outpost, Gunsmith 4, Research Station 4 and a Mk. I module. Semi-Auto (+150% fire rate, worse headshots and spread) with Sprint Shooting is the aggressive pick; a preview squad running it was dangerous up close. Tracker Rounds reveal a hit target for 5 seconds, and Incendiary adds burn damage; those two are exclusive.","zh":"解锁需要哨站、武器工作台 4 级、研究站 4 级和 Mk. I 模块。半自动（射速 +150%，爆头与散布变差）搭配冲刺射击是激进路线，预览时有小队用它近战很危险。追踪弹可让命中目标暴露 5 秒，燃烧弹增加灼烧伤害，两者互斥。"},"tips":[{"en":"Do not pour materials into tiers II to IV for fighting; the gun stays weak against ARC. Upgrade only if you love the silent playstyle.","zh":"别为了战斗往 II 到 IV 阶投入材料，打ARC依然乏力；只有爱潜行玩法才值得升级。"},{"en":"Amplified repairs are the real cost: Semi-Auto + Sprint Shooting needs 27 Amplified Fragments, more than a Hairpin ever earns back.","zh":"增强版的修理才是大头：半自动 + 冲刺射击需 27 个增强碎片，远超“发夹”的价值。"}],"sources":["https://arcraiders.wiki/wiki/Hairpin","https://nerdschalk.com/arc-raiders-hairpin-pistol-location-crafting-and-usage-guide/","https://www.dexerto.com/wikis/arc-raiders/weapon-tier-list-pvp-arc-raiders","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://games.gg/arc-raiders/guides/arc-raiders-all-weapon-amplifications/","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/"],"version":"2.0"},"venator":{"verdict":{"en":"A top-rated PvP pistol thanks to Twin Shot, though only a mid pick for PvE and not amplifiable in 2.0.","zh":"双发射击让它成为 PvP 顶级手枪，PvE 表现一般。"},"use":{"en":"Each trigger pull fires two projectiles but uses one round, so it hits hard at close to medium range with Medium Ammo. The wiki rates it S-tier for PvP and B-tier for PvE; Moderate armor penetration keeps it behind real ARC killers. Most players run it as a sidearm with an extended medium mag and a grip or brake for recoil.","zh":"每次扣扳机射出两发弹丸却只耗一发弹药，用中型弹药在近中距离火力凶猛。社区维基给 PvP 评 S、PvE 评 B；护甲穿透为中等，打ARC不如专业武器。多数玩家当副武器用，配扩容中型弹匣和握把或制退器压后坐力。"},"obtain":{"en":"No fixed spawn and no trader sells it: you need the blueprint, then Gunsmith level 2. It drops from weapon crates and Raider Caches; guides point to Dam Battlegrounds crate routes and locked or breachable rooms, and night raids raise rare blueprint odds. Protect the blueprint in a safe pocket.","zh":"没有固定刷新点，商人也不卖：需要蓝图并有武器工作台 2 级。可从武器箱和奇袭者箱获得；攻略推荐大坝战场的武器箱路线、上锁或可破拆的房间，夜间突袭稀有蓝图概率更高。把蓝图放进安全口袋。"},"tips":[{"en":"It was nerfed in patch 1.3.0 (smaller fire-rate bonuses from upgrades), so tips from before that are stale. It was later nerfed again for damage and headshots per the wiki history.","zh":"1.3.0 版本削弱过（升级带来的射速加成变小），更早的攻略已过时；维基记录还显示其伤害和爆头倍率也被下调。"},{"en":"IV repair costs 3 Advanced Mechanical Components, and the gun sells for 17,000. Fine for a main sidearm, wasteful to leave a worn one in the bag.","zh":"IV 阶修理要 3 个高级机械元件，而售价为 17000；当主副武器可以，磨损的别留在背包。"}],"sources":["https://arcraiders.wiki/wiki/Venator","https://www.dexerto.com/wikis/arc-raiders/venator","https://www.gosugamers.net/entertainment/news/77629-arc-raiders-patch-nerfs-venator-and-improves-raider-dens-to-display-more-ducks","https://allthings.how/arc-raiders-venator-blueprint-locations-and-best-farming-routes/","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"anvil":{"verdict":{"en":"A heavy-hitting hand cannon with strong ARC penetration, but slow handling and costly Heavy Ammo.","zh":"重型手炮，对ARC穿透强，但手感迟缓，重型弹药不便宜。"},"use":{"en":"One accurate shot does the work at medium range, and Strong armor penetration makes it a real ARC answer. Close up it feels clunky because of the low fire rate. Top PvP tier lists rank it S. Players mostly mount a Compensator III for accuracy at range, or a silencer if they want to keep aggro down.","zh":"中距离一发准确命中就能解决问题，强穿透让它成为对付ARC的可靠选择。近距离因射速低显得笨重。PvP 排行里排 S 档。玩家多装补偿器 III 提升远距准度，想少引怪则换消音器。"},"obtain":{"en":"2.0 raised it to Rare, and Tian Wen no longer sells it; it now rotates through the weekly Nomadic Envoy. Otherwise find the blueprint, mainly in Raider Caches and weapon boxes on any map, then craft at Gunsmith level 2. A Rising Tide and Communication Hideout reward Anvil II and III.","zh":"2.0 把它提升为稀有，天玟不再出售，改入每周游牧使团轮换。否则需要找蓝图，任何地图的奇袭者箱和武器箱最常出，之后在武器工作台 2 级制作。“涨潮”和“通讯隐蔽处”分别奖励铁砧 II 和 III。"},"amplified":{"en":"Needs a Mk. III module on top of the usual Outpost, Gunsmith 4 and Research Station 4. X-Rounds adds explosive damage that is rated for armor and raiders; guides call it the PvE pick but note a lower headshot multiplier. Anvil Splitter, once a tech mod, now breaks each bullet into 4 weaker pellets.","zh":"除哨站、武器工作台 4 级、研究站 4 级外还需 Mk. III 模块。爆裂弹带来爆炸伤害，对护甲和玩家都有加成，攻略视为 PvE 首选，但爆头倍率降低。铁砧分流器原是科技模组，现在让每发子弹分成 4 枚弱化弹丸。"},"tips":[{"en":"Repairs on the Amplified version cost 13 Amplified Fragments (X-Rounds 21, Splitter 23), so keep a plain Anvil IV for routine runs.","zh":"增强版修理需 13 个增强碎片（爆裂弹 21、分裂弹 23），日常出战带普通铁砧 IV 更划算。"},{"en":"Old Anvil Splitter mods no longer drop; recycle leftovers into Amplified Fragments to cover repairs.","zh":"旧的铁砧分流器模组不再掉落，剩下的可回收成增强碎片，用来修理。"}],"sources":["https://arcraiders.wiki/wiki/Anvil","https://www.shacknews.com/article/147878/where-to-get-the-anvil-blueprint-in-arc-raiders","https://insider-gaming.com/complete-arc-raiders-frozen-trail-2-0-update-patch-notes/","https://www.keengamer.com/articles/guides/arc-raiders-frozen-trail-2-0-patch-notes-all-changes/","https://powerupgaming.co.uk/2026/10/09/arc-raiders-frozen-trail-best-amplified-weapon-paths/","https://www.dexerto.com/wikis/arc-raiders/weapon-tier-list-pvp-arc-raiders","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"dolabra":{"verdict":{"en":"A strong close-range energy shotgun, but the blueprint is a grind and every Energy Clip costs real money.","zh":"近战很强的能量霰弹枪，但蓝图难刷，能量弹匣也很烧钱。"},"use":{"en":"Two modes: hipfire is a wide short-range cone that clears grouped ARC, ADS is a tight beam that reaches far further. Players rate the ADS beam very highly against Vaporizers and Shredders and in close PvP, where it strips a heavy shield in two hits. It uses its own Energy Clips, so you can't share ammo with another gun. It cannot be upgraded and has no mod slots listed.","zh":"有两种模式：腰射是近距离的宽扇面，适合清成群 ARC；瞄准是更远的聚焦光束。玩家普遍认为聚焦光束打“汽化者”和“粉碎者”以及近距离 PvP 都很强，两下就能打穿重型护盾。它用独立的能量弹匣，不能和其他枪共用弹药，也无法升级。"},"obtain":{"en":"The blueprint is a random drop from breaching Assessors, and only while the Close Scrutiny map condition is active (hourly rotation on Dam, Buried City, Spaceport, Blue Gate; not Stella Montis). Each of an Assessor's three chambers is a separate roll. Crafting needs Gunsmith 3, and the Vaporizer Regulators come from the same event.","zh":"蓝图只会在“严密排查”地图条件下，从破门的评估者容器里随机掉落（大坝战场、掩埋废城、太空港、蓝门每小时轮换，星辰山没有）。每个评估者的三个舱室各算一次掉落。制作需要武器工作台 3 级，“汽化者”调节器也在同一活动中获得。"},"amplified":{"en":"There is no Amplified version. The only 2.0 change was a bug fix that lets it destroy the yellow weak points inside a Harvester; it was not nerfed.","zh":"没有增强型。2.0 对它只有一处修复：现在能打掉“收割者”内部的黄色弱点，并没有被削弱。"},"tips":[{"en":"Clips cost 3,000 coins from Tian Wen, or craft them from Advanced ARC Powercells and Batteries. Stock up before a Close Scrutiny run.","zh":"能量弹匣在天玟处 3000 钱币一个，也可用高级 ARC 电池和电池自制，严密排查前先备足。"},{"en":"Repairs cost 2 Magnetic Accelerators and a Shredder Gyro, the same parts you need to craft it, so don't run it at low durability.","zh":"修理需要 2 个磁力加速器和 1 个“粉碎者”陀螺仪，正是制作它的材料，别带着低耐久进局。"},{"en":"Recycling gives only 2 Magnetic Accelerators for a 27,500-coin item; sell it instead if you ever drop out of the build.","zh":"回收只能拿 2 个磁力加速器，而它能卖 27500 钱币，不用时直接卖掉更划算。"}],"sources":["https://arcraiders.wiki/wiki/Dolabra","https://www.keengamer.com/articles/guides/arc-raiders-guide-how-to-get-dolabra-blueprint/","https://8bittoast.com/arc-raiders-dolabra-shotgun/","https://arcraiders.com/news/frozen-trail-2-0-update"],"version":"2.0"},"il_toro":{"verdict":{"en":"Cheap, hard-hitting PvP shotgun for the early game, but weak against ARC armor, so carry a second gun.","zh":"便宜、近战伤害高的 PvP 霰弹枪，但打 ARC 装甲吃力，需要备一把副武器。"},"use":{"en":"Two or three body shots kill most raiders up close, and fully built it can down a medium-shield player in two shots within 7-8 m. Falloff is sharp and the pump reloads one shell at a time, so fight inside corners. Common mods are Shotgun Choke III, Extended Shotgun Mag III and a Lightweight Stock; recoil barely matters, so the grip is optional.","zh":"近距离两三发就能放倒大多数玩家，配满后在 7 到 8 米内两枪可打倒中等护盾的对手。衰减很厉害，换弹是逐发上膛，所以要贴近拐角作战。常见配件是霰弹枪收束器 III、霰弹扩容弹匣 III 和轻型枪托；后坐力影响不大，握把可选。"},"obtain":{"en":"Cheapest route is crafting at Gunsmith 1 once you have the blueprint. Tian Wen sells it for 15,000 coins (max 3), triple its sell value, so buy only if you lack the blueprint. Unexpected Initiative also rewards one.","zh":"最省钱的是拿到蓝图后在武器工作台 1 级自制。天玟 15000 钱币出售（限购 3 把），是售价的三倍，没蓝图时才买。任务“计划不如变化快”也会送一把。"},"amplified":{"en":"Unlock it through the Research Station project Solid-Core Casting Tech, then upgrade from Il Toro IV. Slug Rounds turns the pellets into one heavy slug with strong armor penetration, making it a mid-range gun for PvE and PvP; players rate it above More Reload, which only speeds reloading. Perks are permanent. Repairs cost 10/20/30 Amplified Fragments, so take only one perk unless you farm them.","zh":"在研究站完成“实心铸造技术”研究项目解锁，再用“公牛” IV 升级。独头弹把散弹变成一发重弹，对装甲穿透很强，能在中距离兼顾 PvE 和 PvP，玩家评价高于只加快装填的高效装填。强化一旦选定无法更改。修理要 10、20、30 个增强碎片，除非能大量刷碎片，否则只选一个强化。"},"tips":[{"en":"The nerf came in patch 1.20.0 (March): pellet damage, fire rate, spread, reload and falloff were all worsened. The 2.0 notes do not touch it.","zh":"削弱发生在 1.20.0（3 月）版本：伤害、射速、散布、装填和衰减都变差。2.0 没有再改它。"},{"en":"Il Toro IV repairs cost 5 Mechanical Components and 5 Simple Gun Parts, cheap enough to keep running it.","zh":"公牛 IV 修理只要 5 个机械元件和 5 个简易枪械零件，用起来不心疼。"},{"en":"Upgrading to IV needs one Heavy Gun Part plus four Mechanical Components at each of the last two steps.","zh":"升到 IV 的最后两步各需要 1 个重型枪械零件和若干机械元件。"}],"sources":["https://arcraiders.wiki/wiki/Il_Toro","https://frvr.com/blog/news/arc-raiders-1-20-0-patch-notes/","https://insider-gaming.com/arc-raiders-patch-nerf-il-toro-cut-down-energy/","https://www.dexerto.com/wikis/arc-raiders/il-toro-arc-raiders","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/","https://arcraiders.com/news/frozen-trail-2-0-update"],"version":"2.0"},"vulcano":{"verdict":{"en":"Fast semi-auto shotgun that rules close-range PvP, but is weak against ARC and eats expensive parts to repair.","zh":"近战 PvP 很强的半自动霰弹枪，打 ARC 乏力，修理耗材也贵。"},"use":{"en":"Tier lists put it at A in PvP and B in PvE. It deals big burst damage in tight spaces, but falloff is sharp and some players find it inconsistent unless fully upgraded and modded. Reload and fire rate improve noticeably at III and IV. Players pair it with Shotgun Choke III and Extended Shotgun Mag III; the magazine mod is the key fix. Bring another weapon for ARC.","zh":"排行榜里 PvP 为 A、PvE 为 B。狭窄空间里爆发很高，但衰减严重，没升满、没配好时有人觉得不稳定。III 和 IV 的装填与射速提升明显。玩家常配霰弹枪收束器 III 和霰弹扩容弹匣 III，扩容是最关键的补强。打 ARC 要另带武器。"},"obtain":{"en":"No trader sells it and no quest hands out the blueprint. One guide points to the Research building in Marano Park, Buried City, but the spawn is not confirmed; hidden raider caches can also hold blueprints. Crafting needs Gunsmith 3 plus an Exodus Module. The quest Into the Fray rewards Vulcano III.","zh":"商人不出售，任务也不送蓝图。有攻略提到掩埋废城马拉诺公园的研究楼，但并未证实，隐藏的突袭者储物点也可能出蓝图。制作需要武器工作台 3 级和一个离巢模块。任务“投入战斗”奖励火山 III。"},"amplified":{"en":"There is no Amplified version of the Vulcano.","zh":"火山没有增强型。"},"tips":[{"en":"Repairs cost Advanced Mechanical Components and Heavy Gun Parts, 4 of each at tier IV. That is steep, so don't take it into raids you expect to be long.","zh":"修理要高级机械元件和重型枪械零件，IV 阶各 4 个，开销不小，别带进预计会打很久的局。"},{"en":"Recycling a IV returns 4 Advanced Mechanical Components and 5 Heavy Gun Parts, more than most players spend upgrading it.","zh":"回收 IV 能拿回 4 个高级机械元件和 5 个重型枪械零件，不想用时回收不亏。"},{"en":"No 2.0 change to the Vulcano appears in the official notes.","zh":"官方 2.0 更新说明里没有火山的改动。"}],"sources":["https://arcraiders.wiki/wiki/Vulcano","https://www.dexerto.com/wikis/arc-raiders/weapons/shotgun/vulcano/","https://nerdschalk.com/arc-raiders-vulcano-shotgun-location-and-unlock-guide/","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/","https://arcraiders.com/news/frozen-trail-2-0-update"],"version":"2.0"},"bobcat":{"verdict":{"en":"A close-range PvP spray gun that only works once fully upgraded; against armored ARC it is close to useless.","zh":"近距离PvP喷子，升满才好用；打有装甲的ARC基本没用。"},"use":{"en":"Players rate it A-tier for PvP and C-tier for PvE. The ARC armor penetration is Very Weak, so keep it for raiders and small ARC like Fireballs and Snitches. At tier I the spread is wild: tier IV cuts dispersion and horizontal recoil by 45%, and the usual build adds Vertical Grip III and Extended Light Mag III, with Compensator III or Muzzle Brake II on the muzzle.","zh":"玩家把它评为PvP的A级、PvE的C级。对ARC装甲穿透“极弱”，只适合打玩家和火球、告密者这类小型ARC。一阶散布很大，四阶散布和横向后坐力降低45%，常见配置是垂直握把 III 加轻型扩容弹匣 III，枪口用补偿器 III 或枪口制退器 II。"},"obtain":{"en":"Not sold by traders. Craft it at Gunsmith level 3 after finding the blueprint, which comes from weapon crates and other high-value loot zones; guides call it hard to find. Bobcat IV is also a reward in the Trophy Display project.","zh":"商人不卖。找到蓝图后在武器工作台3级制作，蓝图多见于武器箱等高价值搜刮点，攻略普遍说不好找。山猫 IV 也是“战利品展示架”项目的奖励。"},"tips":[{"en":"Repair at tier IV costs 5 Advanced Mechanical Components and 4 Light Gun Parts, and it sells for 27000. Do not run it every raid.","zh":"四阶修理要5个高级机械元件和4个轻型枪械零件，而整枪才卖27000，别每局都带。"},{"en":"20 rounds in a fast gun burns Light Ammo quickly, so bring extra magazines.","zh":"20发弹匣打得很快，轻型弹药消耗大，多带备弹。"},{"en":"Craft it only to upgrade it: the base gun is the weakest version.","zh":"制作它就是为了升级，基础版是最弱的。"}],"sources":["https://arcraiders.wiki/wiki/Bobcat","https://nerdschalk.com/arc-raiders-bobcat-location-crafting-and-usage-guide/","https://www.dexerto.com/wikis/arc-raiders/arc-raiders-bobcat","https://finalboss.io/game/arc-raiders/weapon/bobcat","https://www.keengamer.com/articles/guides/arc-raiders-complete-attachment-guide-for-every-weapon/"],"version":"2.0"},"canto":{"verdict":{"en":"The best all-round SMG of the four: strong in PvP and decent on ARC plating, but the Amplified upgrade is very pricey to repair.","zh":"四把里最全面的冲锋枪，PvP强、打ARC装甲也尚可；增强版修理很贵。"},"use":{"en":"Medium Ammo and Moderate armor penetration make it the only one here that works on ARC as well as raiders. Dexerto rates it A in PvP and C in PvE; one guide says it can break a raider shield in under 0.9 seconds. The weak point is recoil on long sprays, so fire in bursts and fit grips and recoil mods.","zh":"用中型弹药，护甲穿透为中等，是这几把里唯一对玩家和ARC都能用的。有攻略站评为PvP A级、PvE C级；有攻略称不到0.9秒就能打穿一层奇袭者护盾。弱点是持续扫射后坐力大，建议点射并配握把和稳定类配件。"},"obtain":{"en":"The blueprint is a random drop. Most reliable: First Wave Raider Caches during the Hurricane condition, or Weapon Cases from the Close Scrutiny operation. Canto I is also a reward from the quests Collision Course and Empathetic Prototypes. Crafting needs Gunsmith level 3.","zh":"蓝图随机掉落。较稳的来源是“飓风”条件下的第一波奇袭者储物箱，或“严密排查”行动里的武器箱。颂歌 I 也是任务“碰撞航线”和“共情原型机”的奖励。制作需要武器工作台3级。"},"amplified":{"en":"Three perks: Carbine Conversion (steadier and more accurate), Incendiary Rounds (extra burn damage over time) and Sprint Shooting (fire while sprinting). I found no player ranking; Carbine is the safe pick for PvP. Mixing two perks makes repair cost 31 Amplified Fragments.","zh":"三种强化：卡宾改装（更稳更准）、燃烧弹（附加持续灼烧伤害）、冲刺射击（可边跑边开火）。没找到玩家的明确排名，打PvP选卡宾改装最稳。两个强化叠加后修理要31个增强碎片。"},"tips":[{"en":"Repair costs: plain Amplified Canto 13 Amplified Fragments, one perk 21 to 23, two perks 31. It only sells for 20800, so think hard before running it.","zh":"修理费：“增强型颂歌”基础款13个增强碎片，单强化21到23个，双强化31个，而整枪只卖20800，出战前三思。"},{"en":"Canto IV is the base for the Amplified upgrade, so a fully upgraded Canto is not wasted.","zh":"颂歌 IV 是增强型的升级底子，升满不会白费。"}],"sources":["https://arcraiders.wiki/wiki/Canto","https://players.com.ua/en/news/where-to-find-the-canto-smg-blueprint-in-arc-raiders/","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/","https://www.dexerto.com/wikis/arc-raiders/weapons/submachine-gun/canto/"],"version":"2.0"},"stitcher":{"verdict":{"en":"A cheap starter SMG: fine up close early on, but weak armor penetration and low fire rate make it a gun to outgrow.","zh":"便宜的入门冲锋枪，前期近战够用；穿甲弱、射速低，迟早要换。"},"use":{"en":"Dexerto puts it at B-tier PvP and D-tier PvE. It hits fairly hard for an SMG but fires slowly and is hard to control, and it does almost nothing to armored ARC. Prioritize recoil and reload upgrades, and carry a second weapon with better penetration. Patch 1.17 nerfed its headshot multiplier and damage; I found no 2.0 changes.","zh":"有攻略站评为PvP B级、PvE D级。单发伤害对冲锋枪来说不错，但射速慢、难控制，对有装甲的ARC几乎无效。优先升级后坐力和换弹，再带一把穿透更好的副武器。1.17版削弱过爆头倍率和伤害，2.0没找到改动。"},"obtain":{"en":"Buy it from Tian Wen, craft it at the Workbench or Gunsmith level 1 (no blueprint noted), or find it in weapon containers near Raider Hatch sites. Stitcher II is a reward for The Right Tool; free loadouts may include it.","zh":"可向天玟购买，在工作台或武器工作台1级制作，也能在奇袭者暗门附近的武器容器里捡到。钉机 II 是“正确工具”的任务奖励，免费装备也可能带一把。"},"tips":[{"en":"Upgrades and repairs use ordinary Metal and Rubber Parts at low tiers, so keeping it running is cheap compared with the others.","zh":"低阶升级和修理用普通金属零件和橡胶零件，比其他几把便宜得多。"},{"en":"At tier IV repair switches to Mechanical Components and Simple Gun Parts; a tier IV sells for 5000, so do not over-invest.","zh":"四阶修理改用机械元件和简易枪械零件，整枪只卖5000，不值得投入太多。"}],"sources":["https://arcraiders.wiki/wiki/Stitcher","https://nerdschalk.com/arc-raiders-stitcher-smg-comprehensive-guide/","https://www.dexerto.com/wikis/arc-raiders/weapons/submachine-gun/stitcher/"],"version":"2.0"},"bantam":{"verdict":{"en":"A budget Heavy Ammo revolver that hits hard and pierces ARC armor, but it is inaccurate, short ranged and has no mod slots.","zh":"预算款重型弹药左轮，伤害高、穿甲好，但不准、射程短，还不能装配件。"},"use":{"en":"New in 2.0 and the cheaper stand-in for the Anvil, which was bumped to rare. Reviews call it strong against both raiders and ARC at close range, with poor accuracy and hard hip-fire recoil. Aim for the first shots; the 8-round cylinder does not forgive misses. Best as a sidearm or a beginner loadout.","zh":"2.0新增，是升为稀有的铁砧的平价替代品。评测称近距离对玩家和ARC都很强，但精度差、腰射后坐力难控。第一发要瞄准，8发弹巢容不下乱打。适合作副武器或新手配置。"},"obtain":{"en":"Buy Bantam I from Tian Wen (limit 3), claim it at tier 4 of the Frozen Trail Reward Pass, or loot it and its blueprint in containers. Listed spots include Hospital on Buried City and Almatera Station on Pendola Pass.","zh":"可向天玟购买小钢炮 I（限购3把），霜痕小径奖励通行证4级领取，或在容器里搜到本体和蓝图。搜刮点包括掩埋废城的医院和彭多拉山口的阿尔玛特拉站。"},"tips":[{"en":"Repair and upgrade cost are Mechanical Components and Simple Gun Parts only, cheap next to the other guns here.","zh":"升级和修理只用机械元件和简易枪械零件，比这一批其他枪便宜。"},{"en":"No attachments can be fitted, so plan your loadout around its short range.","zh":"不能装配件，配装要围绕它的短射程来定。"}],"sources":["https://arcraiders.wiki/wiki/Bantam","https://games.gg/arc-raiders/guides/arc-raiders-how-to-get-bantam/","https://beebom.com/how-to-get-bantam-in-arc-raiders/","https://www.keengamer.com/articles/guides/arc-raiders-frozen-trail-2-0-patch-notes-all-changes/"],"version":"2.0"},"stiletto":{"verdict":{"en":"A cheap, accurate semi-auto for raider fights, but light ammo makes it a poor ARC killer.","zh":"便宜好用的半自动步枪，打玩家不错，打ARC乏力。"},"use":{"en":"Treat it as a budget PvP rifle: high accuracy and low early recoil reward paced single shots, and spread opens up if you dump the magazine. It reloads by swapping a full magazine, so it recovers faster than the Renegade. Against ARC its Weak armor penetration means you burn light ammo for almost no score on armored machines. Fine on light targets only.","zh":"当作低成本的PvP步枪：精度高、初始后坐力小，点射最舒服，扫射会明显散布。换整个弹匣的装填比“叛逆”快。弱穿甲意味着打装甲ARC基本是白费轻型弹药，只适合打轻甲目标。"},"obtain":{"en":"Blueprint is a random container drop on every map (guides list e.g. Dam Hydroponic Dome Complex, Buried City Hospital, Pendola Pass Almatera Station). The quest When Everything Falls gives one copy, and Ermal sells a finished Stiletto IV for a barter. Reward Pass tier 8 also gives a Stiletto I.","zh":"蓝图在各地图的容器中随机掉落（如大坝水培穹顶、掩埋废城医院、彭多拉山口）。任务“万物崩塌之时”送一把，商人Ermal可用以物易物换成品细剑 IV，通行证8级也给一把细剑 I。"},"amplified":{"en":"No Amplified version: Stiletto is not in the first 2.0 Amplification pool.","zh":"没有增强型：细剑不在2.0首批增强武器之列。"},"tips":[{"en":"Upgrades are cheap (Gunsmith 1, basic parts) and add fire rate, reload speed and magazine size; going straight to IV is worth it if you like it.","zh":"武器工作台 1 级升级，材料便宜，提升射速、装填速度和弹匣容量，喜欢就直接升到 IV。"},{"en":"Repairs use only basic parts, so it is a good gun to risk in low-stakes raids.","zh":"维修只用基础零件，适合带去低风险对局。"},{"en":"Bring a heavier weapon for ARC; do not rely on this one.","zh":"打ARC另带重火力，别指望它。"}],"sources":["https://arcraiders.wiki/wiki/Stiletto","https://beebom.com/how-to-get-stiletto-in-arc-raiders/","https://games.gg/arc-raiders/guides/arc-raiders-how-to-get-stiletto/","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/"],"version":"2.0"},"jupiter":{"verdict":{"en":"The best ARC-killing sniper in the game, but a Harvester-grade grind to get and slow to handle.","zh":"最强的ARC狙击，但获取要打“收割者”，操作偏慢。"},"use":{"en":"The railgun pierces ARC armor and everything in its line, with near-instant shots and no drop, so one core shot kills most small ARC and big ones fall cheaply. Rated S in PvE and A in PvP: top headshot damage, but long-range headshots are hard, and a miss with only 5 shots and slow handling leaves you exposed up close. Carry a sidearm.","zh":"磁轨弹丸可穿透ARC装甲并贯穿路径上所有目标，几乎瞬发、无下坠；打核心一发即可击杀多数小型ARC，大型ARC也很划算。PvE评S、PvP评A：爆头伤害最高，但远距离难命中，仅5发且操作慢，近身落空会很危险，记得带副武器。"},"obtain":{"en":"Blueprint comes from the Harvester event on Dam Battlegrounds and The Spaceport, from the final containers (some guides say the Queen core). Learn it, then craft at Gunsmith 3 with a Queen Reactor. The Trophy Display project also rewards a finished one.","zh":"蓝图来自大坝战场和太空港的“收割者”事件，出自最终容器（有攻略称也可从“女王”核心获得）。学会后在武器工作台3级用“女王”反应堆制作。战利品展示架项目也奖励成品。"},"amplified":{"en":"Perks: Bigger Mag, Scoped, Ergonomic Bolt (cycle bolt while aiming). One guide recommends taking all three. Unlock needs the Research Station: Top Mounted Optics Retrofittings (Snitch Scanners, Pilgrim's Peak) and Action Economy. Repairs are heavy: 22 to 47 Amplified Fragments.","zh":"增强项：扩容弹匣、加装瞄准镜、人体工学枪栓（瞄准时可拉栓）。有攻略建议三个全选。解锁需研究站：顶置光学瞄具改装（朝圣峰的“告密者”扫描仪）与操作效率。维修很贵：22至47个增强碎片。"},"tips":[{"en":"The base gun repairs for 2 Magnetic Accelerators and 1 Complex Gun Parts, cheap for its power; the Amplified version repairs in Amplified Fragments only.","zh":"基础版维修只要2个磁力加速器和1个复杂枪械零件，相对威力很划算；增强型只能用增强碎片维修。"},{"en":"Amplification is permanent on that gun, so pick perks before spending.","zh":"增强一旦施加就固定在该枪上，选之前想清楚。"},{"en":"Uses Energy Clips, not common ammo; stock up.","zh":"使用能量弹匣，要提前备足。"}],"sources":["https://arcraiders.wiki/wiki/Jupiter","https://www.dexerto.com/wikis/arc-raiders/weapons/sniper-rifle/jupiter","https://nerdschalk.com/arc-raiders-jupiter-blueprint-location-unlock-guide/","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/","https://www.keengamer.com/articles/guides/arc-raiders-all-15-amplified-weapons-how-to-unlock/"],"version":"2.0"},"osprey":{"verdict":{"en":"A solid mid-tier bolt-action for ARC hunting; fine in PvP only if you land your shots.","zh":"打ARC的稳妥栓动狙，PvP要枪枪命中才好用。"},"use":{"en":"Rated S in PvE but only B in PvP: slow bolt and reload punish misses. Medium ammo is easier to find than heavy, and moderate armor penetration is fine for most ARC, though not heavy armor. The scope is always on, which hurts up close. Tier upgrades cut bolt and reload time, so IV matters.","zh":"PvE评S，PvP仅B：拉栓和装填慢，失手代价大。中型弹药比重型更好找，中等穿甲对多数ARC够用，但打重甲吃力。瞄准镜常开，近战不便。升级会缩短拉栓和装填时间，IV 差别明显。"},"obtain":{"en":"Blueprint drops from weapon cases, e.g. around the Training Annex on Dam Battlegrounds and Buried City. The quests Exploring Pendola Pass and Boarding The Frigate give one copy. Tian Wen sells it for coins at a high price.","zh":"蓝图从武器箱掉落，如大坝战场训练楼附近和掩埋废城。任务“探索彭多拉山口”可得一把。天玟出售，但价格很高。"},"amplified":{"en":"Perks: Anti-Weak Point (more weak-spot damage, less on armor; the PvE pick), Ergonomic Bolt, Tracker Rounds (reveals a hit target for 5s). Needs Action Economy and Targeted Component Trial research. Repairs are costly: up to 34 Amplified Fragments.","zh":"增强项：弱点专攻（弱点伤害更高、装甲伤害更低，PvE首选）、人体工学枪栓、追踪弹（命中后显示目标5秒）。需研究操作效率与靶向部件试验。维修昂贵：最高34个增强碎片。"},"tips":[{"en":"Repair on the base tiers is cheap; the Amplified version's fragment bill is the real cost.","zh":"基础档维修便宜，增强型的碎片开销才是大头。"},{"en":"For heavy ARC armor, a stronger-penetration gun is better.","zh":"面对重甲ARC，换穿甲更强的枪更好。"}],"sources":["https://arcraiders.wiki/wiki/Osprey","https://www.dexerto.com/wikis/arc-raiders/weapons/sniper-rifle/osprey/","https://nerdschalk.com/arc-raiders-osprey-i-sniper-rifle-locations-where-to-find-and-unlock-it/","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/"],"version":"2.0"},"equalizer":{"verdict":{"en":"A beam rifle built to melt armored ARC and bosses; players find it disappointing against other raiders.","zh":"专打装甲 ARC 和首领的光束步枪，对人表现一般。"},"use":{"en":"Treat it as a PvE weapon: the 50-round Energy Clip magazine lets you hold the beam on a Bastion, Rocketeer or the Queen without reloading. Guides call it weak against players, with heavy weight, low mobility and no suppression, so it suits corridors and fixed positions. Against the Queen, fire and retreat.","zh":"当作 PvE 武器用：50 发能量弹匣可以持续照射“堡垒”“火箭手”乃至女王而不用换弹。多篇攻略认为它对人偏弱：太重、机动差、没有压制力，适合走廊和固定点位。打女王时边打边撤。"},"obtain":{"en":"Not sold. The blueprint comes from the Harvester event puzzle on Dam Battlegrounds or The Spaceport, where reward containers hold either the Equalizer or Jupiter blueprint. You also need a Queen Reactor, which drops from the Queen during Harvester events. Duplicate blueprints sell for 5,000 coins.","zh":"商人不卖。蓝图来自大坝战场或太空港的“收割者”事件解谜，奖励箱里是“制裁者”或“木星”的蓝图。制作还需要“女王”反应堆，只在“收割者”事件中击败女王掉落。重复蓝图可卖 5,000 钱币。"},"amplified":{"en":"Players favor Ramping Damage plus Bigger Mag for ARC and boss DPS, since damage grows the longer the beam stays on target. Anti-Weak Point trades armor damage for weak-point damage and only pays off once armor is stripped. The wiki data shows the stacked variants cost far more Amplified Fragments to repair.","zh":"玩家推荐“渐增伤害”加“扩容弹匣”，用来打 ARC 和首领，光束照得越久伤害越高。“弱点专攻”牺牲护甲伤害换弱点伤害，要先打掉护甲才划算。叠加多个增强的版本修理要耗费更多增强碎片。"},"tips":[{"en":"Repair is cheap for the base gun, but the Amplified versions need 22 to 54 Amplified Fragments, which is a lot per raid.","zh":"基础版修理便宜，增强版要 22 至 54 个增强碎片，每局都修很肉疼。"},{"en":"The base Equalizer cannot be upgraded through tiers; the only step up is the Amplified route.","zh":"基础“制裁者”没有等级升级，唯一的进阶是增强路线。"},{"en":"Bring Energy Clips in bulk; they now have a daily trader purchase limit in 2.0.","zh":"多备能量弹；2.0 起商人处能量弹有每日购买上限。"}],"sources":["https://arcraiders.wiki/wiki/Equalizer","https://nerdschalk.com/arc-raiders-equalizer-blueprint-location-unlock-guide/","https://www.dexerto.com/wikis/arc-raiders/weapons/special/equalizer","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/","https://www.keengamer.com/articles/guides/arc-raiders-frozen-trail-2-0-patch-notes-all-changes/"],"version":"2.0"},"hullcracker":{"verdict":{"en":"The big-ARC killer, but a bad PvP pick and expensive to feed.","zh":"对付大型 ARC 的利器，但打人很差，烧钱也快。"},"use":{"en":"Its grenades only explode on ARC, so it does nothing special against raiders and you lose most duels carrying it. Against Bastions, Rocketeers, Bombardiers, the Matriarch and the Queen it is very strong, and players praise it in Buried City. It is overkill on small ARC, where cheaper options like Blaze grenades are better value.","zh":"榴弹只会在 ARC 身上爆炸，对人没有优势，带它打人多半会输。对付“堡垒”“火箭手”“投弹手”、族母和女王时很强，玩家尤其推荐在掩埋废城使用。打小型 ARC 是浪费，用燃烧榴弹之类更划算。"},"obtain":{"en":"Craft it at the Gunsmith with the blueprint. In 2.0 Tian Wen no longer sells it directly; it moved to the weekly Nomadic Envoy rotation, so check each reset. The Tier I weapon is also a reward for the quest Disrupting the Frigate.","zh":"用蓝图在武器工作台制作。2.0 中天玟不再直接出售，改为每周“游牧使团”轮换，每次重置后可以去看看。I 级也是任务“干扰护卫者”的奖励。"},"amplified":{"en":"Mag Reload speeds up reloading the five-round pump magazine. Incendiary Rounds add burn damage over time (about +5 per second) and suit long boss fights. Combining both is the strongest but needs 35 Amplified Fragments per repair, so the single-perk versions are easier to afford.","zh":"“快速装弹”加快五发弹匣的装填。“燃烧弹”给目标附加持续灼烧（约每秒 +5），适合长时间打首领。两者叠加最强，但修一次要 35 个增强碎片，单增强版更省。"},"tips":[{"en":"Ammo is the real cost: launcher ammo prices rose after a damage nerf, so each shot is expensive. Only bring it when you plan to hunt big ARC.","zh":"真正的开销是弹药：伤害削弱后发射器弹药价格上涨，每发都很贵。只在计划猎杀大型 ARC 时再带。"},{"en":"Launcher Ammo now has a daily purchase limit at traders in 2.0, so stock up before a long session.","zh":"2.0 起发射器弹药每日限购，长时间游玩前先囤货。"},{"en":"Tier IV repair costs 4 Advanced Mechanical Components and 4 Heavy Gun Parts; upgrading to IV is cheap, so it is worth finishing the tiers.","zh":"IV 级修理要 4 个高级机械元件和 4 个重型枪械零件；升级到 IV 花费不高，值得升满。"}],"sources":["https://arcraiders.wiki/wiki/Hullcracker","https://www.iggm.com/news/arc-raiders-hullcracker-is-it-still-meta-after-damage-nerf","https://www.dexerto.com/wikis/arc-raiders/weapons/special/equalizer","https://www.keengamer.com/articles/guides/arc-raiders-frozen-trail-2-0-patch-notes-all-changes/","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/"],"version":"2.0"},"rascal":{"verdict":{"en":"A light, cheap single-shot anti-ARC launcher: a fine backup, not a main weapon.","zh":"轻便廉价的单发反 ARC 榴弹枪，适合当副武器，不适合当主力。"},"use":{"en":"It fires one grenade per reload, so every miss hurts. Use it from cover at close to medium range, since the grenade drops heavily at distance. Players use it against Wasps, Hornets, Shredders, Bombardiers and Bastions, but find it awkward against small ARC and swarms. Like the Hullcracker, it does nothing special to raiders.","zh":"每次装填只有一发，打偏就亏。适合在掩体后中近距离使用，远距离弹道下坠严重。玩家用它对付黄蜂、大黄蜂、粉碎者、投弹手和堡垒，但打小型 ARC 和群怪很别扭。与“裂甲者”一样，对人没有特殊效果。"},"obtain":{"en":"It can drop as loot, unlike the Hullcracker. Reported blueprint sources are Hurricane caches, Raider Caches, Security Breach cabinets, locked key rooms and the weekly Nomadic Envoy stock. Tian Wen sells it for a steep price, and Boarding the Frigate rewards a Rascal I.","zh":"可以当战利品掉落，这点比“裂甲者”方便。蓝图常见来源有飓风补给箱、奇袭者箱、安防突破柜、钥匙房和每周“游牧使团”库存。天玟标价很高，任务“登上护卫者”奖励一把“无赖” I。"},"amplified":{"en":"Sprint Shooting lets you fire while running, and High Velocity flattens the arc so the single shot lands more often. Incendiary Rounds add burn damage. Repair costs climb fast: up to 41 Amplified Fragments for the triple-perk version.","zh":"“冲刺射击”可以边跑边开火，“高速弹丸”让弹道更平，单发更容易命中。“燃烧弹”增加灼烧伤害。修理费涨得快，三项叠加最高要 41 个增强碎片。"},"tips":[{"en":"Upgrades to IV are cheap, and IV cuts reload time by 20 percent, which matters most for a one-shot gun.","zh":"升到 IV 花费不高，装填时间缩短 20%，对单发枪最关键。"},{"en":"Rascal repair is much cheaper than a Hullcracker; keep the Hullcracker for bosses and use this for routine armored ARC.","zh":"“无赖”修理远比“裂甲者”便宜；首领留给“裂甲者”，日常装甲 ARC 用它。"},{"en":"Check the Nomadic Envoy after each weekly reset; the Rascal is not guaranteed in stock.","zh":"每周重置后去看看“游牧使团”，不保证有“无赖”。"}],"sources":["https://arcraiders.wiki/wiki/Rascal","https://www.keengamer.com/articles/guides/arc-raiders-how-to-get-rascal-blueprint/","https://arcraidershub.com/guides/rascal-blueprint-guide","https://www.destructoid.com/all-weapon-amplifications-in-arc-raiders-and-how-they-work/"],"version":"2.0"}};
